#[derive(Debug, Clone, Deserialize, Default)]
pub struct PokedexData {
    #[serde(default)]
    pub pokemon: HashMap<String, PokemonEntry>,
    #[serde(default)]
    pub moves: HashMap<String, MoveDetail>,
}

impl PokedexData {
    pub fn load_from_file(path: &str) -> anyhow::Result<Self> {
        let file = std::fs::File::open(path)?;
        let reader = std::io::BufReader::new(file);
        let mut data: PokedexData = serde_json::from_reader(reader)?;

        // Assign canonical power to authentic fixed-damage and dynamic damage moves that have null/0 power in pokedex.json
        for (slug, m) in data.moves.iter_mut() {
            if m.p.unwrap_or(0) == 0 && !m.c.eq_ignore_ascii_case("status") {
                match slug.as_str() {
                    "dragon-rage" => m.p = Some(40),
                    "sonic-boom" => m.p = Some(20),
                    "seismic-toss" | "night-shade" | "psywave" | "super-fang" | "endeavor" | "natures-madness" | "ruination" | "low-kick" | "grass-knot" => m.p = Some(50),
                    "heavy-slam" | "heat-crash" | "electro-ball" | "flail" | "reversal" | "final-gambit" => m.p = Some(60),
                    "magnitude" | "return" | "frustration" => m.p = Some(70),
                    _ => {}
                }
            }
        }

        // Remove status moves and any 0-power / null-power moves completely from the bot
        data.moves.retain(|_, m| !m.c.eq_ignore_ascii_case("status") && m.p.unwrap_or(0) > 0);

        // Ensure every Pokémon's move pool contains only valid moves from the moves dictionary
        for pkmn in data.pokemon.values_mut() {
            pkmn.moves.retain(|m| data.moves.contains_key(&m.n));
        }

        Ok(data)
    }

    pub fn get_pokemon_by_id(&self, id: u32) -> Option<&PokemonEntry> {
        let lookup_id = crate::evolution::get_base_species_id_for_chibi(id);
        self.pokemon.values().find(|p| p.id == lookup_id)
    }

    pub fn get_by_id(&self, id: u32) -> Option<&PokemonEntry> {
        self.get_pokemon_by_id(id)
    }

    pub fn get_by_name(&self, name: &str) -> Option<&PokemonEntry> {
        self.get_pokemon_by_name(name)
    }

    pub fn get_pokemon_by_name(&self, name: &str) -> Option<&PokemonEntry> {
        let trimmed = name.trim();
        let target = trimmed
            .strip_prefix("chibi ")
            .or_else(|| trimmed.strip_prefix("Chibi "))
            .or_else(|| trimmed.strip_prefix("CHIBI "))
            .unwrap_or(trimmed)
            .trim();

        let slug = target.to_lowercase().replace(' ', "-");
        if let Some(p) = self.pokemon.get(&slug) {
            return Some(p);
        }
        let lower = target.to_lowercase();
        if let Some(p) = self.pokemon.get(&lower) {
            return Some(p);
        }
        let clean = target.to_lowercase();
        self.pokemon.values().find(|p| {
            p.name.eq_ignore_ascii_case(target)
                || p.name.to_lowercase().replace('-', " ") == clean
                || p.name.to_lowercase().replace('-', "") == clean.replace(' ', "")
        })
    }

    pub fn get_ordered_pokedex_entries(&self) -> Vec<&PokemonEntry> {
        let mut base_list: Vec<&PokemonEntry> = self
            .pokemon
            .values()
            .filter(|p| (1..=1025).contains(&p.id))
            .collect();
        base_list.sort_by_key(|p| p.id);

        let mut form_list: Vec<&PokemonEntry> = self
            .pokemon
            .values()
            .filter(|p| {
                p.id > 1025
                    && !p.name.contains("-mega")
                    && !p.name.contains("-gmax")
                    && !p.name.contains("-cap")
                    && !p.name.contains("-star")
                    && !p.name.contains("-cosplay")
                    && !p.name.contains("-belle")
                    && !p.name.contains("-libre")
                    && !p.name.contains("-phd")
            })
            .collect();
        form_list.sort_by_key(|p| p.id);

        let mut ordered: Vec<&PokemonEntry> = Vec::with_capacity(1250);
        for base in base_list {
            let base_name = base.name.to_lowercase();
            ordered.push(base);
            for form in &form_list {
                let form_name = form.name.to_lowercase();
                if form_name.starts_with(&format!("{}-", base_name)) {
                    ordered.push(form);
                }
            }
        }

        let mut mega_list: Vec<&PokemonEntry> = self
            .pokemon
            .values()
            .filter(|p| p.id > 1025 && p.name.contains("-mega"))
            .collect();
        mega_list.sort_by_key(|p| p.id);
        ordered.extend(mega_list);

        ordered
    }

    pub fn get_move(&self, key_or_name: &str) -> Option<&MoveDetail> {
        let slug = key_or_name.to_lowercase().replace(' ', "-");
        if let Some(m) = self.moves.get(&slug) {
            return Some(m);
        }
        if let Some(m) = self.moves.get(key_or_name) {
            return Some(m);
        }
        self.moves
            .values()
            .find(|m| m.name.eq_ignore_ascii_case(key_or_name))
    }

    pub fn get_level_up_moves(&self, pokemon_id: u32, level: u32) -> Vec<&MoveDetail> {
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return Vec::new();
        };

        let mut learned: Vec<(&str, u32, u32)> = Vec::new(); // (move_slug, level_learned, power)
        for m in &pkmn.moves {
            if m.m == "level-up" && m.l <= level {
                if let Some(detail) = self.moves.get(&m.n) {
                    if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                        continue;
                    }
                    let p = detail.p.unwrap_or(0);
                    if p > 0 && !learned.iter().any(|(n, _, _)| *n == m.n.as_str()) {
                        learned.push((m.n.as_str(), m.l, p));
                    }
                }
            }
        }

        // If a form/mega has empty moves, inherit from base species
        if learned.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                for m in &base_pkmn.moves {
                    if m.m == "level-up" && m.l <= level {
                        if let Some(detail) = self.moves.get(&m.n) {
                            if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                                continue;
                            }
                            let p = detail.p.unwrap_or(0);
                            if p > 0 && !learned.iter().any(|(n, _, _)| *n == m.n.as_str()) {
                                learned.push((m.n.as_str(), m.l, p));
                            }
                        }
                    }
                }
            }
        }

        // If fewer than 4 damaging moves found, check pre-evolution moves (e.g. stone evolutions)
        if learned.len() < 4 {
            let mut curr_pre = crate::evolution::get_pre_evolution(pokemon_id);
            let mut depth = 0;
            while let Some(pre_id) = curr_pre {
                if depth >= 3 {
                    break;
                }
                depth += 1;
                if let Some(pre_pkmn) = self.get_pokemon_by_id(pre_id) {
                    for m in &pre_pkmn.moves {
                        if m.m == "level-up" && m.l <= level {
                            if let Some(detail) = self.moves.get(&m.n) {
                                if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                                    continue;
                                }
                                let p = detail.p.unwrap_or(0);
                                if p > 0 && !learned.iter().any(|(n, _, _)| *n == m.n.as_str()) {
                                    learned.push((m.n.as_str(), m.l, p));
                                }
                            }
                        }
                    }
                }
                if learned.len() >= 4 {
                    break;
                }
                curr_pre = crate::evolution::get_pre_evolution(pre_id);
            }
        }

        // Select top moves: primary sort by power descending (high-power moves first),
        // secondary sort by level learned descending
        learned.sort_by(|a, b| {
            b.2.cmp(&a.2)
                .then_with(|| b.1.cmp(&a.1))
        });

        // Take up to 4 highest-power moves
        let mut top4: Vec<(&str, u32, u32)> = learned.into_iter().take(4).collect();

        // Sort the chosen top 4 moves by level learned ascending (preserving starter ordering)
        top4.sort_by(|a, b| {
            a.1.cmp(&b.1)
                .then_with(|| b.2.cmp(&a.2))
        });

        top4
            .into_iter()
            .filter_map(|(name, _, _)| self.moves.get(name))
            .collect()
    }

    pub fn get_moves_learned_between_levels(
        &self,
        pokemon_id: u32,
        old_level: u32,
        new_level: u32,
    ) -> Vec<&MoveDetail> {
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return Vec::new();
        };

        let mut candidate_moves: Vec<(&str, u32)> = Vec::new();
        for m in &pkmn.moves {
            if m.m == "level-up" && ((m.l > old_level && m.l <= new_level) || (old_level == 0 && m.l == 0)) {
                if let Some(detail) = self.moves.get(&m.n) {
                    if !detail.c.eq_ignore_ascii_case("status") && detail.p.unwrap_or(0) > 0 {
                        if !candidate_moves.iter().any(|(n, _)| *n == m.n.as_str()) {
                            candidate_moves.push((m.n.as_str(), m.l));
                        }
                    }
                }
            }
        }

        // If a form/mega has empty moves, inherit from base species
        if candidate_moves.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                for m in &base_pkmn.moves {
                    if m.m == "level-up" && ((m.l > old_level && m.l <= new_level) || (old_level == 0 && m.l == 0)) {
                        if let Some(detail) = self.moves.get(&m.n) {
                            if !detail.c.eq_ignore_ascii_case("status") && detail.p.unwrap_or(0) > 0 {
                                if !candidate_moves.iter().any(|(n, _)| *n == m.n.as_str()) {
                                    candidate_moves.push((m.n.as_str(), m.l));
                                }
                            }
                        }
                    }
                }
            }
        }

        // If candidate_moves is still empty, check pre-evolution (e.g. stone evolutions like Arcanine, Raichu)
        if candidate_moves.is_empty() {
            let mut curr_pre = crate::evolution::get_pre_evolution(pokemon_id);
            let mut depth = 0;
            while let Some(pre_id) = curr_pre {
                if depth >= 3 {
                    break;
                }
                depth += 1;
                if let Some(pre_pkmn) = self.get_pokemon_by_id(pre_id) {
                    for m in &pre_pkmn.moves {
                        if m.m == "level-up" && ((m.l > old_level && m.l <= new_level) || (old_level == 0 && m.l == 0)) {
                            if let Some(detail) = self.moves.get(&m.n) {
                                if !detail.c.eq_ignore_ascii_case("status") && detail.p.unwrap_or(0) > 0 {
                                    if !candidate_moves.iter().any(|(n, _)| *n == m.n.as_str()) {
                                        candidate_moves.push((m.n.as_str(), m.l));
                                    }
                                }
                            }
                        }
                    }
                }
                if !candidate_moves.is_empty() {
                    break;
                }
                curr_pre = crate::evolution::get_pre_evolution(pre_id);
            }
        }

        candidate_moves.sort_by_key(|(_, lvl)| *lvl);

        candidate_moves
            .into_iter()
            .filter_map(|(name, _)| self.moves.get(name))
            .collect()
    }

    /// Returns all moves available to relearn for a Pokémon, including:
    /// - Level-up moves of the current species unlocked up to `level` (or level 0)
    /// - Level-up moves of all pre-evolution species in the evolution chain unlocked up to `level` (or level 0)
    /// - Any explicitly stored moves in `stored_relearn`
    /// Strictly excludes currently known moves, 0-power moves, and status moves.
    pub fn get_relearnable_moves(
        &self,
        pokemon_id: u32,
        level: u32,
        current_moves: &[Option<String>],
        stored_relearn: &str,
    ) -> Vec<&MoveDetail> {
        let known: Vec<String> = current_moves
            .iter()
            .flatten()
            .map(|s| s.trim().to_lowercase())
            .collect();

        let mut move_names: Vec<String> = Vec::new();

        // 1. Gather all species in the evolutionary chain (current species + all pre-evolutions)
        let mut chain_ids = vec![pokemon_id];
        let mut curr_pre = crate::evolution::get_pre_evolution(pokemon_id);
        let mut depth = 0;
        while let Some(pre_id) = curr_pre {
            if depth >= 5 {
                break;
            }
            depth += 1;
            chain_ids.push(pre_id);
            curr_pre = crate::evolution::get_pre_evolution(pre_id);
        }

        // 2. Collect level-up moves for each species in the chain up to current level (or level 0)
        for &sp_id in &chain_ids {
            if let Some(pkmn) = self.get_pokemon_by_id(sp_id) {
                for m in &pkmn.moves {
                    if m.m == "level-up" && (m.l <= level || m.l == 0) {
                        if let Some(detail) = self.moves.get(&m.n).or_else(|| self.get_move(&m.n)) {
                            if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                                continue;
                            }
                            if !move_names.iter().any(|n| n.eq_ignore_ascii_case(&m.n)) {
                                move_names.push(m.n.clone());
                            }
                        }
                    }
                }
            }
        }

        // 3. Collect any explicitly stored relearn moves (e.g. from previous training/tutors/alts)
        for part in stored_relearn.split(',') {
            let trimmed = part.trim();
            if !trimmed.is_empty() {
                if let Some(detail) = self.moves.get(trimmed).or_else(|| self.get_move(trimmed)) {
                    if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                        continue;
                    }
                    if !move_names.iter().any(|n| n.eq_ignore_ascii_case(trimmed)) {
                        move_names.push(trimmed.to_string());
                    }
                }
            }
        }

        // 4. Resolve MoveDetails, strictly filtering out 0-power / null-power / status moves and currently known moves
        let mut relearnable: Vec<&MoveDetail> = Vec::new();
        for name in &move_names {
            if let Some(detail) = self.moves.get(name).or_else(|| self.get_move(name)) {
                // Must have power > 0 and not be a status move
                if detail.c.eq_ignore_ascii_case("status") || detail.p.unwrap_or(0) == 0 {
                    continue;
                }
                // Must not already be known by the Pokémon
                if known.contains(&detail.name.to_lowercase()) || known.contains(&name.to_lowercase()) {
                    continue;
                }
                if !relearnable.iter().any(|m| m.name.eq_ignore_ascii_case(&detail.name)) {
                    relearnable.push(detail);
                }
            }
        }

        // Sort moves by power descending, then name ascending
        relearnable.sort_by(|a, b| {
            b.p.unwrap_or(0)
                .cmp(&a.p.unwrap_or(0))
                .then_with(|| a.name.cmp(&b.name))
        });

        relearnable
    }

    /// Returns all moves that this Pokémon can learn via Technical Machine (TM).
    /// Strictly filters for learn method `m == "machine"` and excludes all Move Tutors.
    pub fn get_tm_moves(&self, pokemon_id: u32) -> Vec<&MoveDetail> {
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return Vec::new();
        };

        let mut learned: Vec<&str> = Vec::new();
        for m in &pkmn.moves {
            if m.m == "machine" && self.moves.contains_key(&m.n) && !learned.contains(&m.n.as_str()) {
                learned.push(m.n.as_str());
            }
        }

        // If a form/mega has empty moves, inherit from base species
        if learned.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                for m in &base_pkmn.moves {
                    if m.m == "machine" && self.moves.contains_key(&m.n) && !learned.contains(&m.n.as_str()) {
                        learned.push(m.n.as_str());
                    }
                }
            }
        }

        learned
            .into_iter()
            .filter_map(|name| self.moves.get(name))
            .collect()
    }

    /// Returns all moves that this Pokémon can learn via Move Tutor.
    /// Strictly filters for learn method `m == "tutor"`.
    pub fn get_tutor_moves(&self, pokemon_id: u32) -> Vec<&MoveDetail> {
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return Vec::new();
        };

        let mut learned: Vec<&str> = Vec::new();
        for m in &pkmn.moves {
            if m.m == "tutor" && self.moves.contains_key(&m.n) && !learned.contains(&m.n.as_str()) {
                learned.push(m.n.as_str());
            }
        }

        // If a form/mega has empty moves, inherit from base species
        if learned.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                for m in &base_pkmn.moves {
                    if m.m == "tutor" && self.moves.contains_key(&m.n) && !learned.contains(&m.n.as_str()) {
                        learned.push(m.n.as_str());
                    }
                }
            }
        }

        learned
            .into_iter()
            .filter_map(|name| self.moves.get(name))
            .collect()
    }

    /// Checks whether a Pokémon species can learn a specific move via TM (machine).
    pub fn can_learn_tm(&self, pokemon_id: u32, move_name: &str) -> bool {
        let clean = move_name.to_lowercase().replace(' ', "-");
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return false;
        };
        let directly = pkmn.moves.iter().any(|m| (m.m == "machine" || m.m == "tutor") && (m.n.eq_ignore_ascii_case(&clean) || m.n.eq_ignore_ascii_case(move_name)));
        if directly {
            return true;
        }
        if pkmn.moves.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                return base_pkmn.moves.iter().any(|m| (m.m == "machine" || m.m == "tutor") && (m.n.eq_ignore_ascii_case(&clean) || m.n.eq_ignore_ascii_case(move_name)));
            }
        }
        false
    }

    /// Checks whether a Pokémon species can learn a specific move via Move Tutor.
    pub fn can_learn_tutor(&self, pokemon_id: u32, move_name: &str) -> bool {
        let clean = move_name.to_lowercase().replace(' ', "-");
        let Some(pkmn) = self.get_pokemon_by_id(pokemon_id) else {
            return false;
        };
        let is_in_tutor_catalog = get_tutor_by_name(move_name).is_some();
        let directly = pkmn.moves.iter().any(|m| {
            let name_match = m.n.eq_ignore_ascii_case(&clean) || m.n.eq_ignore_ascii_case(move_name);
            name_match && (m.m == "tutor" || (is_in_tutor_catalog && m.m == "machine"))
        });
        if directly {
            return true;
        }
        if pkmn.moves.is_empty() && pokemon_id > 1025 {
            let base_name = pkmn.name.split('-').next().unwrap_or(&pkmn.name);
            if let Some(base_pkmn) = self.get_pokemon_by_name(base_name) {
                return base_pkmn.moves.iter().any(|m| {
                    let name_match = m.n.eq_ignore_ascii_case(&clean) || m.n.eq_ignore_ascii_case(move_name);
                    name_match && (m.m == "tutor" || (is_in_tutor_catalog && m.m == "machine"))
                });
            }
        }
        false
    }

    pub fn select_wild_pokemon(&self, region: &str) -> Option<(&PokemonEntry, bool)> {
        let mut rng = rand::thread_rng();

        // Shiny roll: 1 in 4096
        let is_shiny = rng.gen_range(0..4096) == 0;

        // Spawn tiers:
        // - Legendary / Mythical / Paradox / Ultra Beasts: Very rarely (1% -> 1 in 100)
        // - Non-Legendary & Pseudo-Legendary: Normally (99%)
        let is_legendary_roll = rng.gen_range(0..100) == 0;

        let mut candidates: Vec<&PokemonEntry> = if is_legendary_roll {
            self.pokemon
                .values()
                .filter(|p| {
                    is_pokemon_native_to_region(p, region)
                        && get_pokemon_spawn_tier(p) == Some(SpawnTier::LegendarySpecial)
                })
                .collect()
        } else {
            Vec::new()
        };

        // If not a legendary roll, or if the region has no native legendaries,
        // pick normally from native non-legendary and pseudo-legendary Pokémon
        if candidates.is_empty() {
            candidates = self
                .pokemon
                .values()
                .filter(|p| {
                    is_pokemon_native_to_region(p, region)
                        && matches!(
                            get_pokemon_spawn_tier(p),
                            Some(SpawnTier::NonLegendary) | Some(SpawnTier::PseudoLegendary)
                        )
                })
                .collect();
        }

        // Fallbacks if rolled tier is empty for this region
        if candidates.is_empty() {
            candidates = self
                .pokemon
                .values()
                .filter(|p| is_pokemon_native_to_region(p, region) && get_pokemon_spawn_tier(p).is_some())
                .collect();
        }

        if candidates.is_empty() {
            // Ultimate fallback to Kanto normal Pokémon
            candidates = self
                .pokemon
                .values()
                .filter(|p| {
                    is_pokemon_native_to_region(p, "kanto")
                        && matches!(
                            get_pokemon_spawn_tier(p),
                            Some(SpawnTier::NonLegendary) | Some(SpawnTier::PseudoLegendary)
                        )
                })
                .collect();
        }

        let selected = candidates.choose(&mut rng).copied()?;
        Some((selected, is_shiny))
    }

    pub fn select_evtrain_pokemon<'a>(&'a self, region: &str, stat: &str) -> Option<(&'a PokemonEntry, bool)> {
        let mut rng = rand::thread_rng();
        let is_shiny = rng.gen_range(0..4096) == 0;

        let target_stat = stat.to_lowercase();
        let target_region = region.trim().to_lowercase();

        // 1. Regional non-legendary candidates yielding this stat
        let mut candidates: Vec<&PokemonEntry> = self
            .pokemon
            .values()
            .filter(|p| {
                is_pokemon_native_to_region(p, &target_region)
                    && !p.is_legendary.unwrap_or(false)
                    && !p.is_mythical.unwrap_or(false)
                    && !is_disallowed_form(&p.name)
                    && get_pokemon_ev_yield_stat(p, &target_stat) > 0
            })
            .collect();

        // 2. Regional any candidates yielding this stat
        if candidates.is_empty() {
            candidates = self
                .pokemon
                .values()
                .filter(|p| {
                    is_pokemon_native_to_region(p, &target_region)
                        && !is_disallowed_form(&p.name)
                        && get_pokemon_ev_yield_stat(p, &target_stat) > 0
                })
                .collect();
        }

        // 3. Fallback to Kanto non-legendary yielding this stat
        if candidates.is_empty() {
            candidates = self
                .pokemon
                .values()
                .filter(|p| {
                    is_pokemon_native_to_region(p, "kanto")
                        && !p.is_legendary.unwrap_or(false)
                        && !p.is_mythical.unwrap_or(false)
                        && !is_disallowed_form(&p.name)
                        && get_pokemon_ev_yield_stat(p, &target_stat) > 0
                })
                .collect();
        }

        // 4. Fallback to any non-legendary yielding this stat across all regions
        if candidates.is_empty() {
            candidates = self
                .pokemon
                .values()
                .filter(|p| {
                    !p.is_legendary.unwrap_or(false)
                        && !p.is_mythical.unwrap_or(false)
                        && !is_disallowed_form(&p.name)
                        && get_pokemon_ev_yield_stat(p, &target_stat) > 0
                })
                .collect();
        }

        let selected = candidates.choose(&mut rng).copied()?;
        Some((selected, is_shiny))
    }
}

pub fn get_pokemon_ev_yield_stat(p: &PokemonEntry, stat: &str) -> i32 {
    let stat_norm = stat.trim().to_lowercase();
    // 1. Check ev_yields map
    if !p.ev_yields.is_empty() {
        for (key, &val) in &p.ev_yields {
            let k_norm = match key.to_lowercase().as_str() {
                "hp" => "hp",
                "attack" | "atk" => "atk",
                "defense" | "def" => "def",
                "special attack" | "special-attack" | "sp.atk" | "sp. attack" | "spa" => "spa",
                "special defense" | "special-defense" | "sp.def" | "sp. defense" | "spd" => "spd",
                "speed" | "spe" => "spe",
                _ => "",
            };
            if k_norm == stat_norm && val > 0 {
                return val as i32;
            }
        }
    }

    // 2. Check ev_yield string (e.g. "1 Speed", "2 Sp.Atk", "1 Def, 1 Sp.Def")
    if let Some(raw) = &p.ev_yield {
        let trimmed = raw.trim();
        if !trimmed.is_empty() && !trimmed.eq_ignore_ascii_case("none") {
            for raw_part in trimmed.split(',') {
                let part = raw_part.trim();
                let mut tokens = part.split_whitespace();
                if let (Some(num_str), Some(stat_str)) = (tokens.next(), tokens.next()) {
                    let s_norm = match stat_str.to_lowercase().as_str() {
                        "hp" => "hp",
                        "attack" | "atk" => "atk",
                        "defense" | "def" => "def",
                        "special-attack" | "special attack" | "sp.atk" | "spa" => "spa",
                        "special-defense" | "special defense" | "sp.def" | "spd" => "spd",
                        "speed" | "spe" => "spe",
                        _ => "",
                    };
                    if s_norm == stat_norm {
                        let num = num_str.trim_start_matches('+').parse::<i32>().unwrap_or(1);
                        if num > 0 {
                            return num;
                        }
                    }
                }
            }
        }
    }

    0
}

