#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvolutionStage {
    Base,        // Stage 1 unevolved: 1..=30
    Middle,      // Stage 2 in 3-stage chain: 15..=40
    Final3,      // Stage 3 in 3-stage chain (Charizard): 30..=80
    Final2,      // Stage 2 in 2-stage chain (Raticate, Gyarados): 25..=75
    SingleStage, // Single stage (Lapras, Heracross, Tauros): 25..=70
    Legendary,   // Legendary / Mythical / Paradox / Ultra Beast: 50..=80
}

