pub fn get_pokemon_evolution_stage(p: &PokemonEntry) -> EvolutionStage {
    if get_pokemon_spawn_tier(p) == Some(SpawnTier::LegendarySpecial) {
        return EvolutionStage::Legendary;
    }

    if (1..=1025).contains(&p.id) {
        return match SPECIES_EVO_STAGE[p.id as usize] {
            1 => EvolutionStage::Base,
            2 => EvolutionStage::Middle,
            3 => EvolutionStage::Final3,
            4 => EvolutionStage::Final2,
            _ => EvolutionStage::SingleStage,
        };
    }

    // Regional forms and special forms (ID > 1025)
    let n = p.name.to_lowercase();
    if n.contains("sliggoo-hisui") || n.contains("linoone-galar") || n.contains("mr-mime-galar") {
        EvolutionStage::Middle
    } else if n.contains("goodra-hisui") {
        EvolutionStage::Final3
    } else if n.contains("corsola-galar")
        || n.contains("qwilfish-hisui")
        || n.contains("sneasel-hisui")
        || n.contains("wooper-paldea")
        || n.contains("yamask-galar")
        || n.contains("farfetchd-galar")
    {
        EvolutionStage::Base
    } else {
        let base_name = n.split('-').next().unwrap_or(&n);
        match base_name {
            "rattata" | "sandshrew" | "vulpix" | "diglett" | "meowth" | "geodude" | "grimer"
            | "ponyta" | "slowpoke" | "zigzagoon" | "darumaka" | "growlithe" | "voltorb"
            | "zorua" => EvolutionStage::Base,
            "graveler" => EvolutionStage::Middle,
            "raticate" | "sandslash" | "ninetales" | "dugtrio" | "persian" | "muk"
            | "exeggutor" | "marowak" | "rapidash" | "slowbro" | "weezing" | "slowking"
            | "arcanine" | "electrode" | "lilligant" | "zoroark" | "braviary" | "avalugg" => {
                EvolutionStage::Final2
            }
            "raichu" | "golem" | "typhlosion" | "samurott" | "decidueye" => EvolutionStage::Final3,
            _ => EvolutionStage::SingleStage,
        }
    }
}

pub fn calculate_wild_level_range(
    stage: EvolutionStage,
    player_level: u32,
) -> (u32, u32) {
    let p_lvl = player_level.clamp(1, 100);

    let (base_min, base_max) = match stage {
        EvolutionStage::Base => (1, 30),
        EvolutionStage::Middle => (15, 40),
        EvolutionStage::Final3 => (30, 80),
        EvolutionStage::Final2 => (25, 75),
        EvolutionStage::SingleStage => (25, 70),
        EvolutionStage::Legendary => (50, 80),
    };

    // Upper limit based on player level (+ small margin of 3 levels, capped at 80)
    let player_ceiling = (p_lvl + 3).min(80);

    // Max level cannot exceed player ceiling or base_max
    let max_lvl = base_max.min(player_ceiling).max(1);

    // Min level: if player is lower level than base_min, scale min down to match low player level
    let player_floor = p_lvl.saturating_sub(3).max(1);
    let min_lvl = base_min.min(player_floor).min(max_lvl).max(1);

    (min_lvl, max_lvl)
}

pub fn generate_wild_pokemon_level(p: &PokemonEntry, player_level: u32) -> u32 {
    let mut rng = rand::thread_rng();
    let stage = get_pokemon_evolution_stage(p);
    let (min_lvl, max_lvl) = calculate_wild_level_range(stage, player_level);
    if min_lvl >= max_lvl {
        max_lvl
    } else {
        rng.gen_range(min_lvl..=max_lvl)
    }
}

pub async fn get_user_player_level(pool: &SqlitePool, user_id: u64) -> u32 {
    let max_lvl_opt: Option<i32> = sqlx::query_scalar(
        "SELECT MAX(level) FROM pokemons WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(pool)
    .await
    .ok()
    .flatten();

    let trainer_lvl_opt: Option<i32> = sqlx::query_scalar(
        "SELECT trainer_level FROM users WHERE id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(pool)
    .await
    .ok()
    .flatten();

    let max_poke_lvl = max_lvl_opt.unwrap_or(5).max(1) as u32;
    let trainer_rank = trainer_lvl_opt.unwrap_or(0).max(0) as u32;

    max_poke_lvl.max(trainer_rank * 10).max(5)
}

pub fn is_disallowed_form(name: &str) -> bool {
    let n = name.to_lowercase();
    n.contains("-mega")
        || n.contains("gigantamax")
        || n.contains("-gmax")
        || n.contains("-totem")
        || n.contains("-cap")
        || n.contains("-starter")
        || n.contains("-cosplay")
        || n.contains("-rock-star")
        || n.contains("-belle")
        || n.contains("-pop-star")
        || n.contains("-phd")
        || n.contains("-libre")
}

pub fn get_pokemon_spawn_tier(p: &PokemonEntry) -> Option<SpawnTier> {
    if is_disallowed_form(&p.name) {
        return None;
    }

    let n = p.name.to_lowercase();

    if PSEUDO_LEGENDARY_IDS.contains(&p.id) || n.contains("sliggoo-hisui") || n.contains("goodra-hisui") {
        return Some(SpawnTier::PseudoLegendary);
    }

    if p.is_legendary.unwrap_or(false)
        || p.is_mythical.unwrap_or(false)
        || ULTRA_BEAST_IDS.contains(&p.id)
        || PARADOX_IDS.contains(&p.id)
        || p.id == 772
        || p.id == 773
        || (n.ends_with("-galar") && (p.id == 144 || p.id == 145 || p.id == 146 || p.id == 10169 || p.id == 10170 || p.id == 10171))
    {
        return Some(SpawnTier::LegendarySpecial);
    }

    Some(SpawnTier::NonLegendary)
}

pub fn get_pokemon_native_region(p: &PokemonEntry) -> &'static str {
    let name_lower = p.name.to_lowercase();
    if name_lower.ends_with("-alola") {
        return "alola";
    }
    if name_lower.ends_with("-galar") {
        return "galar";
    }
    if name_lower.ends_with("-hisui") {
        return "sinnoh";
    }
    if name_lower.contains("-paldea") {
        return "paldea";
    }

    if (1..=1025).contains(&p.id) {
        return match p.id {
            1..=151 => "kanto",
            152..=251 => "johto",
            252..=386 => "hoenn",
            387..=493 => "sinnoh",
            494..=649 => "unova",
            650..=721 => "kalos",
            722..=809 => "alola",
            810..=905 => "galar",
            906..=1025 => "paldea",
            _ => "kanto",
        };
    }

    match p.region.as_deref().unwrap_or("").to_lowercase().as_str() {
        "kanto" => "kanto",
        "johto" => "johto",
        "hoenn" => "hoenn",
        "sinnoh" => "sinnoh",
        "unova" => "unova",
        "kalos" => "kalos",
        "alola" => "alola",
        "galar" => "galar",
        "paldea" => "paldea",
        _ => "kanto",
    }
}

pub fn is_pokemon_native_to_region(p: &PokemonEntry, region: &str) -> bool {
    if is_disallowed_form(&p.name) {
        return false;
    }
    let target = region.trim().to_lowercase();
    get_pokemon_native_region(p) == target
}

