pub fn escape_html(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
    }
}

fn damerau_levenshtein_distance(s1: &str, s2: &str) -> usize {
    let s1: Vec<char> = s1.chars().collect();
    let s2: Vec<char> = s2.chars().collect();
    let len1 = s1.len();
    let len2 = s2.len();

    if len1 == 0 {
        return len2;
    }
    if len2 == 0 {
        return len1;
    }

    let mut d = vec![vec![0; len2 + 1]; len1 + 1];

    for i in 0..=len1 {
        d[i][0] = i;
    }
    for j in 0..=len2 {
        d[0][j] = j;
    }

    for i in 1..=len1 {
        for j in 1..=len2 {
            let cost = if s1[i - 1] == s2[j - 1] { 0 } else { 1 };
            d[i][j] = (d[i - 1][j] + 1)
                .min(d[i][j - 1] + 1)
                .min(d[i - 1][j - 1] + cost);

            if i > 1 && j > 1 && s1[i - 1] == s2[j - 2] && s1[i - 2] == s2[j - 1] {
                d[i][j] = d[i][j].min(d[i - 2][j - 2] + 1);
            }
        }
    }

    d[len1][len2]
}

pub fn format_pokemon_name(raw: &str) -> String {
    if raw.eq_ignore_ascii_case("ho-oh") {
        return "Ho-Oh".to_string();
    }
    if raw.eq_ignore_ascii_case("porygon-z") {
        return "Porygon-Z".to_string();
    }
    if raw.eq_ignore_ascii_case("jangmo-o") {
        return "Jangmo-o".to_string();
    }
    if raw.eq_ignore_ascii_case("hakamo-o") {
        return "Hakamo-o".to_string();
    }
    if raw.eq_ignore_ascii_case("kommo-o") {
        return "Kommo-o".to_string();
    }
    raw.split('-')
        .map(|part| {
            if part.eq_ignore_ascii_case("mr") {
                "Mr.".to_string()
            } else if part.eq_ignore_ascii_case("jr") {
                "Jr.".to_string()
            } else {
                capitalize(part)
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

pub fn format_ev_yield_text(p: &PokemonEntry) -> String {
    const STAT_ORDER: &[(&str, &str)] = &[
        ("HP", "HP"),
        ("Attack", "Attack"),
        ("Defense", "Defense"),
        ("Special Attack", "Sp. Attack"),
        ("Special Defense", "Sp. Defense"),
        ("Speed", "Speed"),
    ];

    let mut parts = Vec::new();
    if !p.ev_yields.is_empty() {
        for (key, display_name) in STAT_ORDER {
            if let Some(&val) = p.ev_yields.get(*key) {
                if val > 0 {
                    parts.push(format!("+{} {}", val, display_name));
                }
            }
        }
    }

    if parts.is_empty() {
        if let Some(ev) = &p.ev_yield {
            let trimmed = ev.trim();
            if !trimmed.is_empty() && !trimmed.eq_ignore_ascii_case("none") {
                for raw_part in trimmed.split(',') {
                    let part = raw_part.trim();
                    let mut tokens = part.split_whitespace();
                    if let (Some(num), Some(stat)) = (tokens.next(), tokens.next()) {
                        let stat_clean = match stat.to_lowercase().as_str() {
                            "sp.atk" | "spa" | "special-attack" => "Sp. Attack",
                            "sp.def" | "spd" | "special-defense" => "Sp. Defense",
                            "atk" | "attack" => "Attack",
                            "def" | "defense" => "Defense",
                            "spe" | "speed" => "Speed",
                            "hp" => "HP",
                            _ => stat,
                        };
                        parts.push(format!("+{} {}", num.trim_start_matches('+'), stat_clean));
                    } else if !part.is_empty() {
                        parts.push(part.to_string());
                    }
                }
            }
        }
    }

    if parts.is_empty() {
        "Yields: None".to_string()
    } else {
        format!("Yields: {}", parts.join(", "))
    }
}

pub fn format_evtrain_yield_display(p: &PokemonEntry, stat: &str) -> String {
    let stat_name = match stat.to_lowercase().as_str() {
        "hp" => "HP",
        "atk" => "Attack",
        "def" => "Defense",
        "spa" => "Sp. Atk",
        "spd" => "Sp. Def",
        "spe" => "Speed",
        _ => stat,
    };
    let yield_amt = get_pokemon_ev_yield_stat(p, stat);
    if yield_amt > 0 {
        format!("{} {}", yield_amt, stat_name)
    } else if let Some(raw) = &p.ev_yield {
        raw.trim().to_string()
    } else {
        format!("1 {}", stat_name)
    }
}

pub fn format_evtrain_hunt_caption(
    name: &str,
    level: u32,
    is_shiny: bool,
    already_caught: bool,
    hunts_used: i32,
    max_hunts: i32,
    ev_yield_text: &str,
) -> String {
    let formatted_name = format_pokemon_name(name);
    let shiny_prefix = if is_shiny {
        format!("{} <b>", SHINY_EMOJI)
    } else {
        "<b>".to_string()
    };
    let star_suffix = if already_caught {
        format!(" {}", CAUGHT_STAR_EMOJI)
    } else {
        String::new()
    };

    format!(
        "A wild {}{}</b> (Lv. {}) has appeared{}\n\n/hunt limit: {}/{}\nEV Yield: {}",
        shiny_prefix,
        formatted_name,
        level,
        star_suffix,
        hunts_used,
        max_hunts,
        ev_yield_text
    )
}

pub fn find_closest_pokemon_name(query: &str, pokedex: &PokedexData) -> Option<String> {
    let q = query.trim().to_lowercase();
    if q.is_empty() {
        return None;
    }

    let q_len = q.chars().count();
    let max_dist = match q_len {
        0..=3 => 1,
        4..=5 => 2,
        6..=8 => 3,
        _ => 4,
    };

    let mut best_match: Option<(&PokemonEntry, usize)> = None;

    for entry in pokedex.pokemon.values() {
        let name_lower = entry.name.to_lowercase();
        let dist = damerau_levenshtein_distance(&q, &name_lower);

        let effective_dist = if name_lower.starts_with(&q) && q_len >= 3 {
            dist.min(1)
        } else {
            dist
        };

        if effective_dist <= max_dist {
            let is_base = entry.id <= 1025;
            let is_better = match best_match {
                None => true,
                Some((best_entry, best_dist)) => {
                    if effective_dist < best_dist {
                        true
                    } else if effective_dist == best_dist {
                        let best_is_base = best_entry.id <= 1025;
                        if is_base && !best_is_base {
                            true
                        } else if is_base == best_is_base {
                            let best_diff = (best_entry.name.len() as isize - q_len as isize).abs();
                            let curr_diff = (entry.name.len() as isize - q_len as isize).abs();
                            if curr_diff < best_diff {
                                true
                            } else if curr_diff == best_diff {
                                entry.id < best_entry.id
                            } else {
                                false
                            }
                        } else {
                            false
                        }
                    } else {
                        false
                    }
                }
            };

            if is_better {
                best_match = Some((entry, effective_dist));
            }
        }
    }

    best_match.map(|(entry, _)| format_pokemon_name(&entry.name))
}

fn format_disambiguation_list(
    rows: &[SqliteRow],
    prompt: &str,
    callback_prefix: &str,
    pokedex: &PokedexData,
    display_option: DisplayOption,
) -> (String, InlineKeyboardMarkup) {
    let mut lines = Vec::new();
    let mut buttons = Vec::new();

    let max_items = 20;
    let slice = if rows.len() > max_items {
        &rows[..max_items]
    } else {
        rows
    };

    for (idx, row) in slice.iter().enumerate() {
        let num = idx + 1;
        let id: i64 = row.get("id");
        let rec = PokemonDbRecord::from_row(row);
        let formatted_name = format_pokemon_name(&rec.nickname);

        let pokemon_id: i64 = row.try_get("pokemon_id").unwrap_or(0);
        let is_chibi = crate::evolution::is_chibi_id(pokemon_id as u32)
            || rec.nickname.to_lowercase().starts_with("chibi ");
        let chibi_prefix = if is_chibi {
            format!("{} ", crate::emoji::get_chibi_emoji(true))
        } else {
            String::new()
        };

        let is_egg = rec.is_hatched || rec.nickname.trim().eq_ignore_ascii_case("egg");
        let name_str = if rec.is_shiny {
            if is_egg {
                format!("{}{} {} <b>{}</b>", chibi_prefix, crate::emoji::get_shiny_emoji(true), crate::emoji::get_egg_emoji(true), escape_html(&formatted_name))
            } else {
                format!("{}{} <b>{}</b>", chibi_prefix, crate::emoji::get_shiny_emoji(true), escape_html(&formatted_name))
            }
        } else if is_egg {
            format!("{}{} <b>{}</b>", chibi_prefix, crate::emoji::get_egg_emoji(true), escape_html(&formatted_name))
        } else if is_chibi {
            format!("{}<b>{}</b>", chibi_prefix, escape_html(&formatted_name))
        } else {
            escape_html(&formatted_name)
        };

        let detail_opt = if display_option == DisplayOption::None {
            None
        } else {
            format_mypokemon_item_detail(&rec, pokedex, display_option)
                .or_else(|| Some(rec.nature.clone()))
        };

        let line_content = match detail_opt {
            Some(d) => format!("{}. {} - {}", num, name_str, d),
            None => format!("{}. {}", num, name_str),
        };

        lines.push(line_content);
        buttons.push(InlineKeyboardButton::callback(
            format!("{}", num),
            format!("{}{}", callback_prefix, id),
        ));
    }

    let text = format!("{}\n\n{}", lines.join("\n"), prompt);

    let keyboard_rows: Vec<Vec<InlineKeyboardButton>> = buttons
        .chunks(4)
        .map(|chunk| chunk.to_vec())
        .collect();

    (text, InlineKeyboardMarkup::new(keyboard_rows))
}

pub static SPECIES_ID_TO_NAME_MAP: std::sync::LazyLock<HashMap<u32, String>> = std::sync::LazyLock::new(|| {
    let mut map = HashMap::new();
    if let Ok(file) = std::fs::File::open("pokedex.json") {
        let reader = std::io::BufReader::new(file);
        if let Ok(val) = serde_json::from_reader::<_, serde_json::Value>(reader) {
            if let Some(pk_map) = val.get("pokemon").and_then(|p| p.as_object()) {
                for (_, entry) in pk_map {
                    if let (Some(id), Some(name)) = (
                        entry.get("id").and_then(|i| i.as_u64()),
                        entry.get("name").and_then(|n| n.as_str()),
                    ) {
                        map.insert(id as u32, name.to_string());
                    }
                }
            }
        }
    }
    map
});

pub static CHIBI_ASSET_MAP: std::sync::LazyLock<HashMap<String, String>> = std::sync::LazyLock::new(|| {
    let mut map = HashMap::new();
    if let Ok(entries) = std::fs::read_dir("assets/chibi_assets") {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
                    if ext.eq_ignore_ascii_case("jpg") || ext.eq_ignore_ascii_case("png") {
                        if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                            let p_str = path.to_string_lossy().replace('\\', "/");
                            let lower = stem.to_lowercase();
                            map.insert(lower.clone(), p_str.clone());
                            let norm = lower.replace(" (", "-").replace(')', "").replace(' ', "-");
                            map.insert(norm.clone(), p_str.clone());

                            // Forme aliases: "deoxys (attack forme)" -> "deoxys-attack", "giratina (origin forme)" -> "giratina-origin"
                            if norm.contains("-forme") || norm.contains("forme") {
                                let no_forme = norm.replace("-forme", "").replace("forme", "");
                                map.insert(no_forme, p_str.clone());
                            }

                            // Mega prefix alias: "mega venusaur" -> "venusaur-mega"
                            if lower.starts_with("mega ") {
                                let after = lower.trim_start_matches("mega ").trim().replace(' ', "-");
                                map.insert(format!("{}-mega", after), p_str.clone());
                            }

                            // Mega X / Y suffix aliases: "charizard x" -> "charizard-mega-x"
                            if lower.ends_with(" x") || norm.ends_with("-x") {
                                let base = lower.strip_suffix(" x").unwrap_or(&lower).trim().replace(' ', "-");
                                map.insert(format!("{}-mega-x", base), p_str.clone());
                            }
                            if lower.ends_with(" y") || norm.ends_with("-y") {
                                let base = lower.strip_suffix(" y").unwrap_or(&lower).trim().replace(' ', "-");
                                map.insert(format!("{}-mega-y", base), p_str.clone());
                            }
                        }
                    }
                }
            }
        }
    }
    map
});

pub fn get_chibi_artwork_path(pokemon_id: u32) -> Option<String> {
    if !crate::evolution::is_chibi_id(pokemon_id) {
        return None;
    }
    let base_id = crate::evolution::get_base_species_id_for_chibi(pokemon_id);

    // 1. Direct ID file check (e.g. assets/chibi_assets/25.png)
    let id_jpg = format!("assets/chibi_assets/{}.jpg", base_id);
    if std::path::Path::new(&id_jpg).exists() {
        return Some(id_jpg);
    }
    let id_png = format!("assets/chibi_assets/{}.png", base_id);
    if std::path::Path::new(&id_png).exists() {
        return Some(id_png);
    }

    // 2. Direct string ID lookup in cache
    if let Some(p) = CHIBI_ASSET_MAP.get(&base_id.to_string()) {
        return Some(p.clone());
    }

    // 3. Species name lookup
    if let Some(species_name) = SPECIES_ID_TO_NAME_MAP.get(&base_id) {
        let lower = species_name.to_lowercase();
        if let Some(p) = CHIBI_ASSET_MAP.get(&lower) {
            return Some(p.clone());
        }
        let norm = lower.replace(" (", "-").replace(')', "").replace(' ', "-");
        if let Some(p) = CHIBI_ASSET_MAP.get(&norm) {
            return Some(p.clone());
        }
        let first_part = lower.split('-').next().unwrap_or(&lower);
        if let Some(p) = CHIBI_ASSET_MAP.get(first_part) {
            return Some(p.clone());
        }
    }

    None
}

pub fn get_pokemon_artwork_path(pokemon_id: u32, is_shiny: bool) -> String {
    let is_chibi = crate::evolution::is_chibi_id(pokemon_id);
    let base_id = crate::evolution::get_base_species_id_for_chibi(pokemon_id);

    // Chibi artwork is ONLY for Chibi Pokémon
    if is_chibi {
        if let Some(chibi_path) = get_chibi_artwork_path(pokemon_id) {
            return chibi_path;
        }
        // Fallback to official artwork if chibi image file does not exist
    }

    if is_shiny {
        let shiny_path = format!("assets/pokemon_shiny/{}.png", pokemon_id);
        if std::path::Path::new(&shiny_path).exists() {
            return shiny_path;
        }
        let base_shiny_path = format!("assets/pokemon_shiny/{}.png", base_id);
        if std::path::Path::new(&base_shiny_path).exists() {
            return base_shiny_path;
        }
    }

    let normal_path = format!("assets/pokemon/{}.png", pokemon_id);
    if std::path::Path::new(&normal_path).exists() {
        return normal_path;
    }
    format!("assets/pokemon/{}.png", base_id)
}

async fn fetch_matching_owned_pokemons(
    pool: &SqlitePool,
    user_id: u64,
    query: &str,
    pokedex: &PokedexData,
) -> Result<Vec<SqliteRow>, sqlx::Error> {
    let trimmed = query.trim();
    let (is_shiny_filter, search_query) = if let Some(rest) = trimmed
        .strip_prefix("shiny ")
        .or_else(|| trimmed.strip_prefix("Shiny "))
        .or_else(|| trimmed.strip_prefix("SHINY "))
    {
        (true, rest.trim())
    } else {
        (false, trimmed)
    };

    let (is_chibi_filter, search_query) = if let Some(rest) = search_query
        .strip_prefix("chibi ")
        .or_else(|| search_query.strip_prefix("Chibi "))
        .or_else(|| search_query.strip_prefix("CHIBI "))
    {
        (true, rest.trim())
    } else {
        (false, search_query)
    };

    let rows = if let Ok(num) = search_query.parse::<i64>() {
        let sql = if is_shiny_filter {
            "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                    iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                    ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                    boosted_ivs
             FROM pokemons WHERE user_id = ? AND is_shiny = 1 AND (id = ? OR pokemon_id = ?) ORDER BY id ASC"
        } else {
            "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                    iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                    ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                    boosted_ivs
             FROM pokemons WHERE user_id = ? AND (id = ? OR pokemon_id = ?) ORDER BY id ASC"
        };
        sqlx::query(sql)
            .bind(user_id as i64)
            .bind(num)
            .bind(num)
            .fetch_all(pool)
            .await?
    } else {
        let pokedex_entry = pokedex.get_pokemon_by_name(search_query);
        let target_pokedex_id = pokedex_entry.map(|p| p.id as i64).unwrap_or(-1);
        let target_chibi_id = if target_pokedex_id > 0 {
            crate::evolution::get_chibi_id_for_base(target_pokedex_id as u32) as i64
        } else {
            -1
        };

        let sql = if is_chibi_filter {
            if is_shiny_filter {
                "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                        iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                        ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                        boosted_ivs
                 FROM pokemons WHERE user_id = ? AND is_shiny = 1 AND pokemon_id >= 20000 AND (
                     LOWER(nickname) = LOWER(?)
                     OR LOWER(nickname) LIKE LOWER(?) || ' [%'
                     OR LOWER(nickname) LIKE LOWER(?) || ' %'
                     OR LOWER(nickname) = LOWER(?)
                     OR pokemon_id = ?
                 ) ORDER BY id ASC"
            } else {
                "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                        iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                        ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                        boosted_ivs
                 FROM pokemons WHERE user_id = ? AND pokemon_id >= 20000 AND (
                     LOWER(nickname) = LOWER(?)
                     OR LOWER(nickname) LIKE LOWER(?) || ' [%'
                     OR LOWER(nickname) LIKE LOWER(?) || ' %'
                     OR LOWER(nickname) = LOWER(?)
                     OR pokemon_id = ?
                 ) ORDER BY id ASC"
            }
        } else {
            if is_shiny_filter {
                "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                        iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                        ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                        boosted_ivs
                 FROM pokemons WHERE user_id = ? AND is_shiny = 1 AND (
                     LOWER(nickname) = LOWER(?)
                     OR LOWER(nickname) LIKE LOWER(?) || ' [%'
                     OR LOWER(nickname) LIKE LOWER(?) || ' %'
                     OR LOWER(nickname) = LOWER(?)
                     OR pokemon_id = ?
                     OR pokemon_id = ?
                 ) ORDER BY id ASC"
            } else {
                "SELECT id, pokemon_id, nickname, level, nature, experience, is_starter, is_shiny, is_hatched,
                        iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                        ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                        boosted_ivs
                 FROM pokemons WHERE user_id = ? AND (
                     LOWER(nickname) = LOWER(?)
                     OR LOWER(nickname) LIKE LOWER(?) || ' [%'
                     OR LOWER(nickname) LIKE LOWER(?) || ' %'
                     OR LOWER(nickname) = LOWER(?)
                     OR pokemon_id = ?
                     OR pokemon_id = ?
                 ) ORDER BY id ASC"
            }
        };

        let chibi_prefixed = format!("chibi {}", search_query);
        let mut q = sqlx::query(sql)
            .bind(user_id as i64)
            .bind(search_query)
            .bind(search_query)
            .bind(search_query)
            .bind(&chibi_prefixed);

        if is_chibi_filter {
            q = q.bind(target_chibi_id);
        } else {
            q = q.bind(target_pokedex_id).bind(target_chibi_id);
        }

        q.fetch_all(pool).await?
    };

    if rows.len() > 1 {
        let (sort_option, sort_direction) = get_user_sort_settings(pool, user_id).await;
        let mut paired: Vec<(SqliteRow, PokemonDbRecord)> = rows
            .into_iter()
            .map(|r| {
                let rec = PokemonDbRecord::from_row(&r);
                (r, rec)
            })
            .collect();

        paired.sort_by(|(_, a), (_, b)| {
            let key_a = get_sort_key(a, pokedex, sort_option);
            let key_b = get_sort_key(b, pokedex, sort_option);
            match sort_direction {
                SortDirection::Ascending => key_a.cmp(&key_b).then_with(|| a.id.cmp(&b.id)),
                SortDirection::Descending => key_b.cmp(&key_a).then_with(|| a.id.cmp(&b.id)),
            }
        });

        Ok(paired.into_iter().map(|(r, _)| r).collect())
    } else {
        Ok(rows)
    }
}

fn generate_starter_ivs() -> (i32, i32, i32, i32, i32, i32) {
    let mut rng = rand::thread_rng();
    loop {
        let hp = rng.gen_range(0..=31i32);
        let atk = rng.gen_range(0..=31i32);
        let def = rng.gen_range(0..=31i32);
        let spa = rng.gen_range(0..=31i32);
        let spd = rng.gen_range(0..=31i32);
        let spe = rng.gen_range(0..=31i32);
        let total = hp + atk + def + spa + spd + spe;
        if total > 90 && total < 120 {
            return (hp, atk, def, spa, spd, spe);
        }
    }
}

/// Distributes target_sum across 6 stats with per-stat bounds [min_stat, max_stat].
/// Guarantees sum(ivs) == target_sum (clamped to bounds) with varied, natural distribution.
pub fn distribute_iv_sum<R: Rng>(
    target_sum: i32,
    min_stat: i32,
    max_stat: i32,
    rng: &mut R,
) -> (i32, i32, i32, i32, i32, i32) {
    let n = 6;
    let clamped_target = target_sum.clamp(n * min_stat, n * max_stat);
    let mut ivs = [min_stat; 6];
    let mut remaining = clamped_target - (n * min_stat);

    while remaining > 0 {
        let eligible: Vec<usize> = (0..6).filter(|&i| ivs[i] < max_stat).collect();
        if eligible.is_empty() {
            break;
        }
        let &idx = eligible.choose(rng).unwrap();
        let max_add = (max_stat - ivs[idx]).min(remaining);
        let chunk = rng.gen_range(1..=max_add.min(6));
        ivs[idx] += chunk;
        remaining -= chunk;
    }

    (ivs[0], ivs[1], ivs[2], ivs[3], ivs[4], ivs[5])
}

pub fn get_iv_tier(total_iv: i32) -> &'static str {
    match total_iv {
        0..=100 => "0-100",
        101..=120 => "101-120",
        121..=150 => "121-150",
        151..=169 => "151-169",
        170..=186 => "170-186",
        _ => "Unknown",
    }
}

/// Generates IVs for wild hunt encounters based on the exact user distribution:
/// - 0-100: 28.0%
/// - 101-120: 50.0%
/// - 121-150: 21.5%
/// - 151-169: 0.5%
/// - 170-186: 0.00001%
///
/// Floor guarantees:
/// - Legendary / Mythical / Ultra Beast: strictly never lower than 100 total IVs.
/// - Pseudo-Legendary: strictly never lower than 90 total IVs.
/// - Shiny Pokémon: at least one 31 IV.
pub fn generate_wild_hunt_ivs_with_rng<R: Rng>(
    pokemon: Option<&PokemonEntry>,
    is_shiny: bool,
    rng: &mut R,
) -> (i32, i32, i32, i32, i32, i32) {
    let roll: f64 = rng.gen_range(0.0..1.0);

    let mut target_sum = if roll < 0.280 {
        rng.gen_range(0..=100)
    } else if roll < 0.780 {
        rng.gen_range(101..=120)
    } else if roll < 0.9949999 {
        rng.gen_range(121..=150)
    } else if roll < 0.9999999 {
        rng.gen_range(151..=169)
    } else {
        rng.gen_range(170..=186)
    };

    // Floor guarantees for Legendary and Pseudo-Legendary species
    if let Some(p) = pokemon {
        let tier = get_pokemon_spawn_tier(p);
        if tier == Some(SpawnTier::LegendarySpecial) {
            if target_sum < 100 {
                target_sum = rng.gen_range(100..=120);
            }
        } else if tier == Some(SpawnTier::PseudoLegendary) {
            if target_sum < 90 {
                target_sum = rng.gen_range(90..=120);
            }
        }
    }

    let (hp, atk, def, spa, spd, spe) = distribute_iv_sum(target_sum, 0, 31, rng);
    let mut ivs = [hp, atk, def, spa, spd, spe];

    // Shiny guarantee: at least one 31 IV
    if is_shiny && !ivs.contains(&31) {
        let shiny_idx = rng.gen_range(0..6);
        ivs[shiny_idx] = 31;
    }

    (ivs[0], ivs[1], ivs[2], ivs[3], ivs[4], ivs[5])
}

pub fn generate_wild_hunt_ivs(
    pokemon: Option<&PokemonEntry>,
    is_shiny: bool,
) -> (i32, i32, i32, i32, i32, i32) {
    let mut rng = rand::thread_rng();
    generate_wild_hunt_ivs_with_rng(pokemon, is_shiny, &mut rng)
}

/// Generates IVs for Safari Zone encounters based on the exact user distribution:
/// - 0-100: 0%
/// - 101-120: 69.44%
/// - 121-150: 29.86%
/// - 151-169: 0.69%
/// - 170-186: 0.000014%
///
/// Floor guarantees:
/// - Safari floor: strictly never lower than 100 total IVs.
/// - Shiny Pokémon: at least one 31 IV.
pub fn generate_safari_ivs_with_rng<R: Rng>(
    pokemon: Option<&PokemonEntry>,
    is_shiny: bool,
    rng: &mut R,
) -> (i32, i32, i32, i32, i32, i32) {
    let roll: f64 = rng.gen_range(0.0..1.0);

    // Normalized weights across tiers >= 100 (sum = 72.0)
    let p_120 = 50.0 / 72.0;                      // ~69.44%
    let p_150 = (50.0 + 21.49999) / 72.0;         // ~99.30% (29.86% in 121..=150)
    let p_170 = (50.0 + 21.49999 + 0.5) / 72.0;   // ~99.99% (0.69% in 151..=169)
    // Remainder >= p_170 is 0.00001 / 72.0 (~0.000014% in 170..=186)

    let mut target_sum = if roll < p_120 {
        rng.gen_range(101..=120)
    } else if roll < p_150 {
        rng.gen_range(121..=150)
    } else if roll < p_170 {
        rng.gen_range(151..=169)
    } else {
        rng.gen_range(170..=186)
    };

    // Safari floor guarantee: strictly never lower than 100 total IVs
    if target_sum < 100 {
        target_sum = rng.gen_range(100..=120);
    }

    if let Some(p) = pokemon {
        let tier = get_pokemon_spawn_tier(p);
        if tier == Some(SpawnTier::LegendarySpecial) && target_sum < 100 {
            target_sum = rng.gen_range(100..=120);
        }
    }

    let (hp, atk, def, spa, spd, spe) = distribute_iv_sum(target_sum, 0, 31, rng);
    let mut ivs = [hp, atk, def, spa, spd, spe];

    // Shiny guarantee: at least one 31 IV
    if is_shiny && !ivs.contains(&31) {
        let shiny_idx = rng.gen_range(0..6);
        ivs[shiny_idx] = 31;
    }

    (ivs[0], ivs[1], ivs[2], ivs[3], ivs[4], ivs[5])
}

pub fn generate_safari_ivs(
    pokemon: Option<&PokemonEntry>,
    is_shiny: bool,
) -> (i32, i32, i32, i32, i32, i32) {
    let mut rng = rand::thread_rng();
    generate_safari_ivs_with_rng(pokemon, is_shiny, &mut rng)
}

fn type_emoji(t: &str) -> String {
    let (id, fallback) = match t.to_lowercase().as_str() {
        "ground" => ("6122668629990319764", "🏜️"),
        "ice" => ("6120931706561111199", "❄️"),
        "normal" => ("6120921634862800671", "🔘"),
        "poison" => ("6120510391744208596", "☠️"),
        "psychic" => ("6120626703753552440", "🔮"),
        "rock" => ("6123197808615891197", "🪨"),
        "steel" => ("6120534877352763496", "⚙️"),
        "water" => ("6122856740967950386", "💧"),
        "bug" => ("6122889240985478227", "🐛"),
        "dark" => ("6120930220502426354", "🌑"),
        "dragon" => ("6120513333796807923", "🐉"),
        "electric" => ("6120423087943984078", "⚡"),
        "fairy" => ("6120623229125009484", "✨"),
        "fighting" => ("6122836039225581659", "🥊"),
        "fire" => ("6122676369521385632", "🔥"),
        "flying" => ("6122860864136553639", "🦅"),
        "ghost" => ("6120875811856721604", "👻"),
        "grass" => ("6120509726024277548", "🌿"),
        _ => return String::new(),
    };
    format!(r#"<tg-emoji emoji-id="{}">{}</tg-emoji>"#, id, fallback)
}

pub fn format_type_with_emoji(t: &str) -> String {
    let cap = capitalize(t);
    let emoji = type_emoji(t);
    if emoji.is_empty() {
        cap
    } else {
        format!("{} {}", cap, emoji)
    }
}

fn format_types(types: &[String]) -> String {
    let mut parts = Vec::new();
    for t in types {
        let cap = capitalize(t);
        let emoji = type_emoji(t);
        if emoji.is_empty() {
            parts.push(cap);
        } else {
            parts.push(format!("{} {}", cap, emoji));
        }
    }
    format!("Types: [{} ]", parts.join(" / "))
}

