#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PokedexTab {
    About,
    BaseStats,
    EvYields,
}

pub fn build_pokedex_keyboard(pokemon_id: u32, current_tab: PokedexTab) -> InlineKeyboardMarkup {
    let all_buttons = [
        (PokedexTab::About, "About", format!("pdex_abt_{}", pokemon_id)),
        (PokedexTab::BaseStats, "Base stats", format!("pdex_bst_{}", pokemon_id)),
        (PokedexTab::EvYields, "EV yields", format!("pdex_ev_{}", pokemon_id)),
    ];

    let row: Vec<InlineKeyboardButton> = all_buttons
        .iter()
        .filter(|(tab, _, _)| *tab != current_tab)
        .map(|(_, label, data)| InlineKeyboardButton::callback(*label, data.clone()))
        .collect();

    InlineKeyboardMarkup::new(vec![row])
}

pub fn get_catch_probability(catch_rate: u32) -> &'static str {
    match catch_rate {
        0..=30 => "Very Low",
        31..=75 => "Low",
        76..=150 => "Medium",
        151..=220 => "High",
        _ => "Very High",
    }
}

pub fn get_pokemon_growth_rate(id: u32, p: &PokemonEntry) -> &'static str {
    if p.is_legendary == Some(true) || p.is_mythical == Some(true) {
        return "Slow";
    }

    match id {
        // Starters (Gen 1 to 9)
        1..=9 | 152..=160 | 252..=260 | 387..=395 | 495..=503 | 650..=658 | 722..=730 | 810..=818 | 906..=914 => "Medium Slow",
        // Pseudo-Legendaries
        147..=149 | 246..=248 | 371..=376 | 443..=445 | 633..=635 | 704..=706 | 782..=784 | 885..=887 | 996..=998 => "Slow",
        // Slow group
        58 | 59 | 90 | 91 | 129 | 130 | 131 | 142 | 143 | 320 | 321 | 369 | 446 => "Slow",
        // Erratic group
        290..=292 | 313 | 314 | 335 | 336 | 345..=350 | 366..=368 | 408..=411 | 456 | 457 => "Erratic",
        // Fluctuating group
        285 | 286 | 296 | 297 | 316 | 317 | 341 | 342 | 425 | 426 => "Fluctuating",
        // Fast group
        35 | 36 | 39 | 40 | 113 | 173..=177 | 183 | 184 | 190 | 200 | 209 | 210 | 222 | 225 | 235 | 241 | 242
        | 298 | 300 | 301 | 303 | 307 | 308 | 315 | 325 | 326 | 333 | 334 | 358 | 370 | 406 | 407 | 417
        | 424 | 427 | 428 | 429 | 431 | 432 | 433 | 440 | 441 | 531 | 546..=549 | 587 | 594 | 702 | 703 | 707
        | 742 | 743 | 761..=764 | 771 | 777 | 778 | 864 | 876 | 877 | 921..=927 | 957..=959 => "Fast",
        // Medium Slow group (Pidgey, Nidoran, Oddish, Poliwag, Abra, Machop, Bellsprout, Geodude, Gastly, Onix, etc.)
        16..=18 | 29..=34 | 43..=45 | 60..=71 | 74..=76 | 92..=95 | 111 | 112 | 116 | 117 | 137 | 151
        | 179..=181 | 186..=189 | 194 | 195 | 208 | 230 | 233 | 280..=282 | 287..=289 | 304..=306 | 328..=330
        | 363..=365 | 396..=398 | 403..=405 | 464 | 474 | 475 | 524..=526 | 532..=537 | 540..=545 | 577..=579
        | 582..=584 | 599..=604 | 607..=612 | 661..=663 | 669..=671 | 679..=681 | 821..=823 => "Medium Slow",
        // Default for remaining standard Pokemon
        _ => "Medium Fast",
    }
}

pub fn get_pokemon_regions_found(p: &PokemonEntry) -> Vec<&'static str> {
    let name_lower = p.name.to_lowercase();
    if name_lower.ends_with("-alola") {
        return vec!["Alola"];
    }
    if name_lower.ends_with("-galar") {
        return vec!["Galar"];
    }
    if name_lower.ends_with("-hisui") {
        return vec!["Sinnoh"];
    }
    if name_lower.contains("-paldea") {
        return vec!["Paldea"];
    }

    match p.id {
        // Gen 1 Starters (Bulbasaur, Charmander, Squirtle lines)
        1..=9 => vec!["Kanto", "Johto", "Kalos", "Galar", "Paldea"],
        // Pikachu / Raichu
        25 | 26 => vec!["Kanto", "Johto", "Hoenn", "Sinnoh", "Kalos", "Alola", "Galar", "Paldea"],
        // Gen 2 Starters (Chikorita, Cyndaquil, Totodile)
        152..=160 => vec!["Johto", "Hoenn", "Sinnoh", "Alola", "Paldea"],
        // Gen 3 Starters (Treecko, Torchic, Mudkip)
        252..=260 => vec!["Hoenn", "Sinnoh", "Kalos", "Galar", "Paldea"],
        // Gen 4 Starters (Turtwig, Chimchar, Piplup)
        387..=395 => vec!["Sinnoh", "Unova", "Paldea"],
        // Gen 5 Starters (Snivy, Tepig, Oshawott)
        495..=503 => vec!["Unova", "Alola", "Paldea"],
        // Gen 6 Starters (Chespin, Fennekin, Froakie)
        650..=658 => vec!["Kalos", "Paldea"],
        // Gen 7 Starters (Rowlet, Litten, Popplio)
        722..=730 => vec!["Alola", "Galar", "Paldea"],
        // Gen 8 Starters (Grookey, Scorbunny, Sobble)
        810..=818 => vec!["Galar", "Paldea"],
        // Gen 9 Starters (Sprigatito, Fuecoco, Quaxly)
        906..=914 => vec!["Paldea"],
        // Common cross-region Pokemon
        129 | 130 => vec!["Kanto", "Johto", "Hoenn", "Sinnoh", "Unova", "Kalos", "Alola", "Galar", "Paldea"],
        41 | 42 | 169 => vec!["Kanto", "Johto", "Hoenn", "Sinnoh", "Unova", "Kalos", "Alola", "Galar"],
        54 | 55 => vec!["Kanto", "Johto", "Hoenn", "Sinnoh", "Unova", "Kalos", "Alola", "Galar", "Paldea"],
        _ => {
            let native = capitalize(get_pokemon_native_region(p));
            if let Some(r) = find_region(&native) {
                vec![r.name]
            } else {
                vec!["Kanto"]
            }
        }
    }
}

pub fn format_pokedex_about_caption(entry: &PokemonEntry) -> String {
    let name = format_pokemon_name(&entry.name);
    let types_str = entry
        .types
        .iter()
        .map(|t| format_type_with_emoji(t))
        .collect::<Vec<_>>()
        .join(" / ");
    let catch_prob = get_catch_probability(entry.catch_rate.unwrap_or(45));
    let growth_rate = get_pokemon_growth_rate(entry.id, entry);
    let regions = get_pokemon_regions_found(entry);

    format!(
        "Pokedex No. {}\nName: {}\nTypes: [{}]\nCatch probability: {}\nGrowth rate: {}\nRegions found: [{}]",
        entry.id,
        name,
        types_str,
        catch_prob,
        growth_rate,
        regions.join(", ")
    )
}

pub fn format_pokedex_stats_caption(entry: &PokemonEntry) -> String {
    format!(
        "<b>HP:</b> {}\n<b>Attack:</b> {}\n<b>Defense:</b> {}\n<b>Sp. Attack:</b> {}\n<b>Sp. Defense:</b> {}\n<b>Speed:</b> {}",
        entry.stats.hp,
        entry.stats.attack,
        entry.stats.defense,
        entry.stats.special_attack,
        entry.stats.special_defense,
        entry.stats.speed
    )
}

pub fn format_pokedex_ev_caption(p: &PokemonEntry) -> String {
    const STAT_ORDER: &[(&str, &str)] = &[
        ("HP", "HP"),
        ("Attack", "Attack"),
        ("Defense", "Defense"),
        ("Special Attack", "Sp. Attack"),
        ("Special Defense", "Sp. Defense"),
        ("Speed", "Speed"),
    ];

    let mut parts = Vec::new();
    if !p.ev_yields.is_empty() {
        for (key, display_name) in STAT_ORDER {
            if let Some(&val) = p.ev_yields.get(*key) {
                if val > 0 {
                    parts.push(format!("{}: +{}", display_name, val));
                }
            }
        }
    }

    if parts.is_empty() {
        if let Some(ev) = &p.ev_yield {
            let trimmed = ev.trim();
            if !trimmed.is_empty() && !trimmed.eq_ignore_ascii_case("none") {
                for raw_part in trimmed.split(',') {
                    let part = raw_part.trim();
                    let mut tokens = part.split_whitespace();
                    if let (Some(num), Some(stat)) = (tokens.next(), tokens.next()) {
                        let stat_clean = match stat.to_lowercase().as_str() {
                            "sp.atk" | "spa" | "special-attack" => "Sp. Attack",
                            "sp.def" | "spd" | "special-defense" => "Sp. Defense",
                            "atk" | "attack" => "Attack",
                            "def" | "defense" => "Defense",
                            "spe" | "speed" => "Speed",
                            "hp" => "HP",
                            _ => stat,
                        };
                        parts.push(format!("{}: +{}", stat_clean, num));
                    }
                }
            }
        }
    }

    if parts.is_empty() {
        "None: +0".to_string()
    } else {
        parts.join("\n")
    }
}

fn format_release_confirmation(
    level: i32,
    name: &str,
    nature: &str,
    total_ivs: i32,
    total_evs: i32,
) -> String {
    format!(
        "Are you sure you want to release your Lv. {} <b>{}</b>?\nNature: {}, Total IVs: {}, Total EVs: {}",
        level,
        escape_html(name),
        escape_html(nature),
        total_ivs,
        total_evs
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegionInfo {
    pub id: u32,
    pub name: &'static str,
    pub required_level: u32,
}

pub const ALL_REGIONS: &[RegionInfo] = &[
    RegionInfo { id: 1, name: "Kanto", required_level: 0 },
    RegionInfo { id: 2, name: "Johto", required_level: 1 },
    RegionInfo { id: 3, name: "Hoenn", required_level: 2 },
    RegionInfo { id: 4, name: "Sinnoh", required_level: 3 },
    RegionInfo { id: 5, name: "Unova", required_level: 4 },
    RegionInfo { id: 6, name: "Kalos", required_level: 5 },
    RegionInfo { id: 7, name: "Alola", required_level: 6 },
    RegionInfo { id: 8, name: "Galar", required_level: 7 },
    RegionInfo { id: 9, name: "Paldea", required_level: 8 },
];

pub fn get_unlocked_regions_for_level(level: u32) -> Vec<&'static str> {
    ALL_REGIONS
        .iter()
        .filter(|r| r.required_level <= level)
        .map(|r| r.name)
        .collect()
}

pub fn get_unlocked_regions_csv_for_level(level: u32) -> String {
    get_unlocked_regions_for_level(level).join(",")
}

pub fn find_region(query: &str) -> Option<&'static RegionInfo> {
    let q = query.trim();
    if let Ok(id) = q.parse::<u32>() {
        ALL_REGIONS.iter().find(|r| r.id == id)
    } else {
        ALL_REGIONS.iter().find(|r| r.name.eq_ignore_ascii_case(q))
    }
}

fn format_travel_message(current_region: &str, unlocked_regions: &str) -> String {
    let unlocked_set: Vec<&str> = unlocked_regions
        .split(',')
        .map(|r| r.trim())
        .collect();

    let mut list = Vec::new();
    for region in ALL_REGIONS {
        if unlocked_set.iter().any(|r| r.eq_ignore_ascii_case(region.name)) {
            list.push(format!("{}. {}", region.id, region.name));
        }
    }
    if list.is_empty() {
        list.push("1. Kanto".to_string());
    }

    let list_text = list.join("\n");
    format!(
        "Which region would you like to travel to?\n\n{}\n\nRank up to unlock more regions\n\nCurrent region: <b>{}</b>",
        list_text,
        escape_html(current_region)
    )
}

fn travel_keyboard(unlocked_regions: &str) -> InlineKeyboardMarkup {
    let unlocked_set: Vec<&str> = unlocked_regions
        .split(',')
        .map(|r| r.trim())
        .collect();

    let mut buttons = Vec::new();
    for region in ALL_REGIONS {
        if unlocked_set.iter().any(|r| r.eq_ignore_ascii_case(region.name)) {
            buttons.push(InlineKeyboardButton::callback(
                region.id.to_string(),
                format!("travel_{}", region.id),
            ));
        }
    }
    if buttons.is_empty() {
        buttons.push(InlineKeyboardButton::callback("1", "travel_1"));
    }

    let rows: Vec<Vec<InlineKeyboardButton>> = if buttons.len() <= 4 {
        vec![buttons]
    } else {
        buttons.chunks(3).map(|c| c.to_vec()).collect()
    };
    InlineKeyboardMarkup::new(rows)
}

