pub fn get_safari_roster(region: &str) -> &'static [&'static str] {
    match region.to_ascii_lowercase().as_str() {
        "kanto" => SAFARI_KANTO,
        "hoenn" => SAFARI_HOENN,
        "sinnoh" => SAFARI_SINNOH,
        "galar" => SAFARI_GALAR,
        "kalos" => SAFARI_KALOS,
        "hisui" => SAFARI_HISUI,
        "johto" => SAFARI_JOHTO,
        "unova" => SAFARI_UNOVA,
        "alola" => SAFARI_ALOLA,
        "paldea" => SAFARI_PALDEA,
        _ => SAFARI_KANTO,
    }
}

pub fn get_random_safari_pokemon(region: &str) -> &'static str {
    let roster = get_safari_roster(region);
    let mut rng = rand::thread_rng();
    roster[rng.gen_range(0..roster.len())]
}

fn nature_modifier(nature: &str, stat_name: &str) -> f64 {
    let (increased, decreased) = match nature.to_lowercase().as_str() {
        "lonely" => (Some("atk"), Some("def")),
        "brave" => (Some("atk"), Some("spe")),
        "adamant" => (Some("atk"), Some("spa")),
        "naughty" => (Some("atk"), Some("spd")),

        "bold" => (Some("def"), Some("atk")),
        "relaxed" => (Some("def"), Some("spe")),
        "impish" => (Some("def"), Some("spa")),
        "lax" => (Some("def"), Some("spd")),

        "timid" => (Some("spe"), Some("atk")),
        "hasty" => (Some("spe"), Some("def")),
        "jolly" => (Some("spe"), Some("spa")),
        "naive" => (Some("spe"), Some("spd")),

        "modest" => (Some("spa"), Some("atk")),
        "mild" => (Some("spa"), Some("def")),
        "quiet" => (Some("spa"), Some("spe")),
        "rash" => (Some("spa"), Some("spd")),

        "calm" => (Some("spd"), Some("atk")),
        "gentle" => (Some("spd"), Some("def")),
        "sassy" => (Some("spd"), Some("spe")),
        "careful" => (Some("spd"), Some("spa")),

        _ => (None, None),
    };

    if increased == Some(stat_name) {
        1.1
    } else if decreased == Some(stat_name) {
        0.9
    } else {
        1.0
    }
}

pub fn calc_stat(base: u32, iv: i32, ev: i32, level: i32, modifier: f64) -> (i32, &'static str) {
    let raw = (((2 * base as i32 + iv + ev / 4) * level) / 100) + 5;
    let final_val = (raw as f64 * modifier).floor() as i32;
    let suffix = if modifier > 1.05 {
        " (+)"
    } else if modifier < 0.95 {
        " (-)"
    } else {
        ""
    };
    (final_val, suffix)
}

pub fn calc_hp(base: u32, iv: i32, ev: i32, level: i32) -> i32 {
    if base == 1 {
        return 1;
    }
    (((2 * base as i32 + iv + ev / 4) * level) / 100) + level + 10
}

fn format_battle_stats_caption(
    base: &BaseStats,
    level: i32,
    nature: &str,
    iv_hp: i32,
    iv_atk: i32,
    iv_def: i32,
    iv_spa: i32,
    iv_spd: i32,
    iv_spe: i32,
    ev_hp: i32,
    ev_atk: i32,
    ev_def: i32,
    ev_spa: i32,
    ev_spd: i32,
    ev_spe: i32,
) -> String {
    let hp = calc_hp(base.hp, iv_hp, ev_hp, level);
    let (atk, atk_sfx) = calc_stat(base.attack, iv_atk, ev_atk, level, nature_modifier(nature, "atk"));
    let (def, def_sfx) = calc_stat(base.defense, iv_def, ev_def, level, nature_modifier(nature, "def"));
    let (spa, spa_sfx) = calc_stat(base.special_attack, iv_spa, ev_spa, level, nature_modifier(nature, "spa"));
    let (spd, spd_sfx) = calc_stat(base.special_defense, iv_spd, ev_spd, level, nature_modifier(nature, "spd"));
    let (spe, spe_sfx) = calc_stat(base.speed, iv_spe, ev_spe, level, nature_modifier(nature, "spe"));

    format!(
        "<b>HP:</b> {}\n<b>Attack:</b> {}{}\n<b>Defense:</b> {}{}\n<b>Sp. Attack:</b> {}{}\n<b>Sp. Defense:</b> {}{}\n<b>Speed:</b> {}{}",
        hp, atk, atk_sfx, def, def_sfx, spa, spa_sfx, spd, spd_sfx, spe, spe_sfx
    )
}

pub fn format_move_entry(m: &MoveDetail) -> String {
    let emoji = type_emoji(&m.t);
    let cap_type = capitalize(&m.t);
    let type_tag = if emoji.is_empty() {
        format!("[{}]", cap_type)
    } else {
        format!("[{} {}]", cap_type, emoji)
    };

    let power_val = m
        .p
        .filter(|&p| p > 0)
        .map(|p| p.to_string())
        .unwrap_or_else(|| "--".to_string());
    let acc_val = m
        .a
        .filter(|&a| a > 0)
        .map(|a| a.to_string())
        .unwrap_or_else(|| "--".to_string());
    let cat_str = if m.c.is_empty() {
        "Physical".to_string()
    } else {
        capitalize(&m.c)
    };

    format!(
        "<b>{} {}</b>\nPower: {}, Accuracy: {} ({})",
        escape_html(&m.name),
        type_tag,
        power_val,
        acc_val,
        cat_str
    )
}

pub fn format_battle_move_entry(m: &MoveDetail, _user_id: u64) -> String {
    let emoji = type_emoji(&m.t);
    let cap_type = capitalize(&m.t);
    let type_tag = if emoji.is_empty() {
        format!("[ {} ]", cap_type)
    } else {
        format!("[ {} {} ]", cap_type, emoji)
    };

    let power_val = m
        .p
        .filter(|&p| p > 0)
        .map(|p| p.to_string())
        .unwrap_or_else(|| "--".to_string());
    let acc_val = m
        .a
        .filter(|&a| a > 0)
        .map(|a| a.to_string())
        .unwrap_or_else(|| "--".to_string());
    let cat_str = if m.c.is_empty() {
        "Physical".to_string()
    } else {
        capitalize(&m.c)
    };

    format!(
        "<b>• {} {}</b>\n<b><i>Power:</i></b> <code>{}</code> | <b><i>Accuracy:</i></b> <code>{}</code> | ({})",
        escape_html(&m.name),
        type_tag,
        power_val,
        acc_val,
        cat_str
    )
}

fn format_moves_caption(moves: &[&MoveDetail]) -> String {
    if moves.is_empty() {
        return "No moves learned yet.".to_string();
    }

    let mut lines = Vec::new();
    for m in moves {
        lines.push(format_move_entry(m));
    }

    lines.join("\n")
}

#[derive(Debug, Clone)]
pub struct BattlePokemon {
    pub db_id: Option<i64>,
    pub id: u32,
    pub name: String,
    pub nickname: String,
    pub level: u32,
    pub types: Vec<String>,
    pub nature: String,
    pub base_stats: BaseStats,
    pub iv_hp: i32,
    pub iv_atk: i32,
    pub iv_def: i32,
    pub iv_spa: i32,
    pub iv_spd: i32,
    pub iv_spe: i32,
    pub ev_hp: i32,
    pub ev_atk: i32,
    pub ev_def: i32,
    pub ev_spa: i32,
    pub ev_spd: i32,
    pub ev_spe: i32,
    pub max_hp: i32,
    pub current_hp: i32,
    pub moves: Vec<MoveDetail>,
    pub is_shiny: bool,
    pub catch_rate: u32,
    pub base_experience: u32,
    pub is_burned: bool,
}

impl BattlePokemon {
    pub fn is_giratina(&self) -> bool {
        self.id == 487 || self.id == 10007 || self.name.to_lowercase().contains("giratina") || self.nickname.to_lowercase().contains("giratina")
    }

    pub fn is_dialga(&self) -> bool {
        self.id == 483 || self.id == 10245 || self.name.to_lowercase().contains("dialga") || self.nickname.to_lowercase().contains("dialga")
    }

    pub fn is_palkia(&self) -> bool {
        self.id == 484 || self.id == 10246 || self.name.to_lowercase().contains("palkia") || self.nickname.to_lowercase().contains("palkia")
    }

    pub fn get_atk(&self) -> i32 {
        calc_stat(self.base_stats.attack, self.iv_atk, self.ev_atk, self.level as i32, nature_modifier(&self.nature, "atk")).0.max(1)
    }

    pub fn get_def(&self) -> i32 {
        calc_stat(self.base_stats.defense, self.iv_def, self.ev_def, self.level as i32, nature_modifier(&self.nature, "def")).0.max(1)
    }

    pub fn get_spa(&self) -> i32 {
        calc_stat(self.base_stats.special_attack, self.iv_spa, self.ev_spa, self.level as i32, nature_modifier(&self.nature, "spa")).0.max(1)
    }

    pub fn get_spd(&self) -> i32 {
        calc_stat(self.base_stats.special_defense, self.iv_spd, self.ev_spd, self.level as i32, nature_modifier(&self.nature, "spd")).0.max(1)
    }

    pub fn get_spe(&self) -> i32 {
        let base = calc_stat(self.base_stats.speed, self.iv_spe, self.ev_spe, self.level as i32, nature_modifier(&self.nature, "spe")).0.max(1);
        if self.is_dialga() {
            // Dialga Ability: Time Acceleration (+50% Speed)
            ((base as f64) * 1.5).round() as i32
        } else {
            base
        }
    }

    pub fn get_effective_spe_against(&self, opponent: &BattlePokemon) -> i32 {
        let base_spe = self.get_spe();
        if opponent.is_dialga() && !self.is_dialga() {
            // Dialga Ability: Time Stop (-50% Opponent Speed while Dialga is active)
            ((base_spe as f64) * 0.5).round().max(1.0) as i32
        } else {
            base_spe
        }
    }
}

