fn get_single_type_effectiveness(atk_type: &str, def_type: &str) -> f64 {
    let atk = atk_type.trim().to_lowercase();
    let def = def_type.trim().to_lowercase();

    match atk.as_str() {
        "normal" => match def.as_str() {
            "rock" | "steel" => 0.5,
            "ghost" => 0.0,
            _ => 1.0,
        },
        "fire" => match def.as_str() {
            "grass" | "ice" | "bug" | "steel" => 2.0,
            "fire" | "water" | "rock" | "dragon" => 0.5,
            _ => 1.0,
        },
        "water" => match def.as_str() {
            "fire" | "ground" | "rock" => 2.0,
            "water" | "grass" | "dragon" => 0.5,
            _ => 1.0,
        },
        "electric" => match def.as_str() {
            "water" | "flying" => 2.0,
            "electric" | "grass" | "dragon" => 0.5,
            "ground" => 0.0,
            _ => 1.0,
        },
        "grass" => match def.as_str() {
            "water" | "ground" | "rock" => 2.0,
            "fire" | "grass" | "poison" | "flying" | "bug" | "dragon" | "steel" => 0.5,
            _ => 1.0,
        },
        "ice" => match def.as_str() {
            "grass" | "ground" | "flying" | "dragon" => 2.0,
            "fire" | "water" | "ice" | "steel" => 0.5,
            _ => 1.0,
        },
        "fighting" => match def.as_str() {
            "normal" | "ice" | "rock" | "dark" | "steel" => 2.0,
            "poison" | "flying" | "psychic" | "bug" | "fairy" => 0.5,
            "ghost" => 0.0,
            _ => 1.0,
        },
        "poison" => match def.as_str() {
            "grass" | "fairy" => 2.0,
            "poison" | "ground" | "rock" | "ghost" => 0.5,
            "steel" => 0.0,
            _ => 1.0,
        },
        "ground" => match def.as_str() {
            "fire" | "electric" | "poison" | "rock" | "steel" => 2.0,
            "grass" | "bug" => 0.5,
            "flying" => 0.0,
            _ => 1.0,
        },
        "flying" => match def.as_str() {
            "grass" | "fighting" | "bug" => 2.0,
            "electric" | "rock" | "steel" => 0.5,
            _ => 1.0,
        },
        "psychic" => match def.as_str() {
            "fighting" | "poison" => 2.0,
            "psychic" | "steel" => 0.5,
            "dark" => 0.0,
            _ => 1.0,
        },
        "bug" => match def.as_str() {
            "grass" | "psychic" | "dark" => 2.0,
            "fire" | "fighting" | "poison" | "flying" | "ghost" | "steel" | "fairy" => 0.5,
            _ => 1.0,
        },
        "rock" => match def.as_str() {
            "fire" | "ice" | "flying" | "bug" => 2.0,
            "fighting" | "ground" | "steel" => 0.5,
            _ => 1.0,
        },
        "ghost" => match def.as_str() {
            "psychic" | "ghost" => 2.0,
            "dark" => 0.5,
            "normal" => 0.0,
            _ => 1.0,
        },
        "dragon" => match def.as_str() {
            "dragon" => 2.0,
            "steel" => 0.5,
            "fairy" => 0.0,
            _ => 1.0,
        },
        "steel" => match def.as_str() {
            "ice" | "rock" | "fairy" => 2.0,
            "fire" | "water" | "electric" | "steel" => 0.5,
            _ => 1.0,
        },
        "dark" => match def.as_str() {
            "psychic" | "ghost" => 2.0,
            "fighting" | "dark" | "fairy" => 0.5,
            _ => 1.0,
        },
        "fairy" => match def.as_str() {
            "fighting" | "dragon" | "dark" => 2.0,
            "fire" | "poison" | "steel" => 0.5,
            _ => 1.0,
        },
        _ => 1.0,
    }
}

fn get_type_effectiveness(atk_type: &str, def_types: &[String]) -> f64 {
    let mut mult = 1.0;
    for def in def_types {
        mult *= get_single_type_effectiveness(atk_type, def);
    }
    mult
}

