#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MultiHitKind {
    Fixed(u32),
    TwoToFive,
}

pub fn get_multi_hit_kind(slug: &str) -> Option<MultiHitKind> {
    match slug {
        "doublekick" | "dualchop" | "geargrind" | "bonemerang" | "dragondarts"
        | "twineedle" | "doublehit" | "twinbeam" | "tachyoncutter" => Some(MultiHitKind::Fixed(2)),
        "triplekick" | "tripleaxel" => Some(MultiHitKind::Fixed(3)),
        "bulletseed" | "iciclespear" | "rockblast" | "tailslap" | "pinmissile"
        | "armthrust" | "bonerush" | "furyswipes" | "doubleslap" | "spikecannon"
        | "cometpunch" | "barrage" | "scaleshot" | "watershuriken" => Some(MultiHitKind::TwoToFive),
        _ => None,
    }
}

pub fn get_fixed_damage(
    attacker: &BattlePokemon,
    slug: &str,
    defender: &BattlePokemon,
) -> Option<i32> {
    match slug {
        "dragonrage" => Some(40),
        "sonicboom" => Some(20),
        "seismictoss" | "nightshade" => Some(attacker.level.max(1) as i32),
        "superfang" | "naturesmadness" | "ruination" => {
            Some((defender.current_hp / 2).max(1))
        }
        "endeavor" => {
            if defender.current_hp > attacker.current_hp {
                Some(defender.current_hp - attacker.current_hp)
            } else {
                Some(0)
            }
        }
        "finalgambit" => Some(attacker.current_hp.max(1)),
        "psywave" => {
            let mut rng = rand::thread_rng();
            let min_dmg = (attacker.level as i32) / 2;
            let max_dmg = (attacker.level as i32 * 3) / 2;
            Some(rng.gen_range(min_dmg.max(1)..=max_dmg.max(1)))
        }
        _ => None,
    }
}

pub fn get_dynamic_move_power(
    attacker: &BattlePokemon,
    move_detail: &MoveDetail,
    slug: &str,
    defender: &BattlePokemon,
    atk_spe: i32,
    def_spe: i32,
) -> i32 {
    let base = move_detail.p.unwrap_or(40) as i32;
    match slug {
        "waterspout" | "eruption" => {
            let max_hp = attacker.max_hp.max(1);
            let cur_hp = attacker.current_hp.max(0);
            ((150 * cur_hp) / max_hp).clamp(1, 150)
        }
        "flail" | "reversal" => {
            let max_hp = attacker.max_hp.max(1);
            let cur_hp = attacker.current_hp.max(0);
            let ratio = (48 * cur_hp) / max_hp;
            if ratio < 2 {
                200
            } else if ratio < 5 {
                150
            } else if ratio < 10 {
                100
            } else if ratio < 17 {
                80
            } else if ratio < 33 {
                40
            } else {
                20
            }
        }
        "gyroball" => {
            let user_spe = atk_spe.max(1);
            let target_spe = def_spe.max(1);
            ((25 * target_spe) / user_spe + 1).clamp(1, 150)
        }
        "electroball" => {
            let user_spe = atk_spe.max(1);
            let target_spe = def_spe.max(1);
            let ratio = user_spe as f64 / target_spe as f64;
            if ratio >= 4.0 {
                150
            } else if ratio >= 3.0 {
                120
            } else if ratio >= 2.0 {
                80
            } else if ratio >= 1.0 {
                60
            } else {
                40
            }
        }
        "acrobatics" => 110,
        "brine" => {
            if defender.current_hp * 2 <= defender.max_hp {
                130
            } else {
                65
            }
        }
        _ => base,
    }
}

pub fn get_attack_and_defense_stats(
    attacker: &BattlePokemon,
    move_detail: &MoveDetail,
    slug: &str,
    defender: &BattlePokemon,
) -> (i32, i32) {
    let is_special = move_detail.c.eq_ignore_ascii_case("special");

    if is_special {
        let atk = attacker.get_spa();
        let def = if slug == "psyshock" || slug == "psystrike" || slug == "secretsword" {
            defender.get_def()
        } else {
            defender.get_spd()
        };
        (atk, def)
    } else {
        let def = defender.get_def();
        let atk = if slug == "bodypress" {
            attacker.get_def()
        } else if slug == "foulplay" {
            defender.get_atk()
        } else {
            attacker.get_atk()
        };
        (atk, def)
    }
}

pub fn calc_single_hit_damage(
    attacker: &BattlePokemon,
    defender: &BattlePokemon,
    move_detail: &MoveDetail,
    power: i32,
    atk_stat: i32,
    def_stat: i32,
    is_crit: bool,
    is_stab: bool,
    type_mult: f64,
    random_roll: u32,
) -> i32 {
    if type_mult == 0.0 || power <= 0 {
        return 0;
    }

    let level = attacker.level.max(1) as f64;

    // 1. Level Factor = ((2 * Level) / 5) + 2
    let level_factor = ((2.0 * level) / 5.0) + 2.0;

    // 2. Base Damage = (((Level Factor * Move Power * (Attack / Defense)) / 50) + 2)
    let a_over_d = atk_stat as f64 / (def_stat.max(1) as f64);
    let base_damage = ((level_factor * (power as f64) * a_over_d) / 50.0) + 2.0;

    // 3. Multipliers & Modifiers
    let stab_mult = if is_stab { 1.5 } else { 1.0 };
    let crit_mult = if is_crit { 1.5 } else { 1.0 };
    let burn_mult = if attacker.is_burned && move_detail.c.eq_ignore_ascii_case("physical") {
        0.5
    } else {
        1.0
    };
    let antimatter_mult = if defender.is_giratina() {
        // Giratina Ability: Anti-Matter Dominion (Takes only 50% incoming damage from all attacks)
        0.5
    } else {
        1.0
    };
    let palkia_rift_mult = if attacker.is_palkia() {
        // Palkia Ability: Dimensional Rift (Palkia's attacks deal 1.5x damage)
        1.5
    } else {
        1.0
    };
    let r = (random_roll.clamp(85, 100) as f64) / 100.0;

    let modifiers = stab_mult * crit_mult * type_mult * burn_mult * antimatter_mult * palkia_rift_mult;

    // 4. Final Damage = floor(Base Damage * Modifiers * R)
    let final_damage = (base_damage * modifiers * r).floor() as i32;

    // If the attack connects and is not immune (type_multiplier > 0), the minimum damage is 1.
    final_damage.max(1)
}

pub fn calculate_authentic_damage_exact(
    attacker: &BattlePokemon,
    move_detail: &MoveDetail,
    defender: &BattlePokemon,
    crit_override: Option<bool>,
    random_factor_override: Option<u32>,
) -> (i32, bool, f64) {
    let slug = normalize_move_name(&move_detail.name);

    if move_detail.c.eq_ignore_ascii_case("status") {
        return (0, false, 1.0);
    }

    let mut type_mult = get_type_effectiveness(&move_detail.t, &defender.types);
    if attacker.is_palkia() && type_mult < 1.0 {
        // Palkia Ability: Spatial Distortion
        // All attacks ignore type-based damage reductions and immunities (resisted/immune targets take 1.5x damage).
        type_mult = 1.5;
    }

    if type_mult == 0.0 {
        return (0, false, 0.0);
    }

    if let Some(fixed) = get_fixed_damage(attacker, &slug, defender) {
        let fixed_dmg = if defender.is_giratina() {
            // Giratina Ability: Anti-Matter Dominion (Takes only 50% incoming damage)
            (fixed / 2).max(1)
        } else {
            fixed
        };
        return (fixed_dmg.max(0), false, type_mult);
    }

    let atk_spe = attacker.get_effective_spe_against(defender);
    let def_spe = defender.get_effective_spe_against(attacker);

    let power = get_dynamic_move_power(attacker, move_detail, &slug, defender, atk_spe, def_spe);
    if power <= 0 {
        return (0, false, type_mult);
    }

    let (attack_stat, defense_stat) = get_attack_and_defense_stats(attacker, move_detail, &slug, defender);
    let is_stab = attacker.types.iter().any(|t| t.eq_ignore_ascii_case(&move_detail.t));

    let roll_crit = || -> bool {
        if let Some(c) = crit_override {
            return c;
        }
        let mut rng = rand::thread_rng();
        if is_always_crit_move(&slug) {
            true
        } else if is_high_crit_move(&slug) {
            rng.gen_range(0..8) == 0
        } else {
            // Gen 9 standard: 1 in 16 (6.25%) baseline chance
            rng.gen_range(0..16) == 0
        }
    };

    let roll_rand = || -> u32 {
        if let Some(r) = random_factor_override {
            r.clamp(85, 100)
        } else {
            let mut rng = rand::thread_rng();
            rng.gen_range(85..=100)
        }
    };

    // Single Hit Resolution: All multi-hit moves strike once per turn for snappy Telegram message pacing.
    let is_crit = roll_crit();
    let rand_val = roll_rand();
    let dmg = calc_single_hit_damage(
        attacker,
        defender,
        move_detail,
        power,
        attack_stat,
        defense_stat,
        is_crit,
        is_stab,
        type_mult,
        rand_val,
    );
    (dmg, is_crit, type_mult)
}

pub fn check_move_miss(move_detail: &MoveDetail) -> bool {
    let slug = normalize_move_name(&move_detail.name);
    if matches!(
        slug.as_str(),
        "swift"
            | "aerialace"
            | "aurasphere"
            | "faintattack"
            | "feintattack"
            | "magicalleaf"
            | "shockwave"
            | "magnetbomb"
            | "clearsmog"
            | "disarmingvoice"
    ) {
        return false;
    }

    let acc = match move_detail.a {
        Some(a) if a > 0 => a,
        _ => return false,
    };

    if acc >= 100 {
        return false;
    }

    let roll = rand::thread_rng().gen_range(1..=100);
    roll > acc
}

pub fn check_move_miss_with_roll(move_detail: &MoveDetail, roll: u32) -> bool {
    let slug = normalize_move_name(&move_detail.name);
    if matches!(
        slug.as_str(),
        "swift"
            | "aerialace"
            | "aurasphere"
            | "faintattack"
            | "feintattack"
            | "magicalleaf"
            | "shockwave"
            | "magnetbomb"
            | "clearsmog"
            | "disarmingvoice"
    ) {
        return false;
    }

    let acc = match move_detail.a {
        Some(a) if a > 0 => a,
        _ => return false,
    };

    if acc >= 100 {
        return false;
    }

    let r = roll.clamp(1, 100);
    r > acc
}

pub fn check_move_miss_against(move_detail: &MoveDetail, defender: &BattlePokemon) -> bool {
    let mut rng = rand::thread_rng();
    if defender.is_giratina() && rng.gen_bool(0.5) {
        // Giratina Ability: Shadow Realm (Every move targeting Giratina has a 50% chance to miss into the Shadow Realm)
        return true;
    }
    check_move_miss(move_detail)
}

pub fn check_move_miss_against_with_roll(
    move_detail: &MoveDetail,
    defender: &BattlePokemon,
    roll: u32,
    shadow_realm_miss: bool,
) -> bool {
    if defender.is_giratina() && shadow_realm_miss {
        return true;
    }
    check_move_miss_with_roll(move_detail, roll)
}

pub fn calc_battle_damage(
    attacker: &BattlePokemon,
    move_detail: &MoveDetail,
    defender: &BattlePokemon,
) -> (i32, bool, f64) {
    calculate_authentic_damage_exact(attacker, move_detail, defender, None, None)
}

pub fn determine_wild_battle_turn_order(
    player_spe: i32,
    wild_spe: i32,
    tie_breaker_player_wins: bool,
) -> bool {
    if player_spe > wild_spe {
        true
    } else if wild_spe > player_spe {
        false
    } else {
        tie_breaker_player_wins
    }
}

pub fn get_move_priority(move_name: &str) -> i32 {
    let slug = normalize_move_name(move_name);
    match slug.as_str() {
        "helpinghand" => 5,
        "protect" | "detect" | "kingsshield" | "spikyshield" | "banefulbunker"
        | "obstruct" | "silktrap" | "endure" | "magiccoat" => 4,
        "fakeout" | "quickguard" | "wideguard" | "craftyshield" => 3,
        "extremespeed" | "firstimpression" | "feint" | "followme" | "ragepowder" | "allyswitch" => 2,
        "accelerock" | "aquajet" | "babydolleyes" | "bulletpunch" | "iceshard"
        | "machpunch" | "quickattack" | "shadowsneak" | "suckerpunch" | "vacuumwave"
        | "watershuriken" | "bide" | "iondeluge" | "grassyglide" => 1,
        "vitalthrow" => -1,
        "focuspunch" => -3,
        "avalanche" | "revenge" => -4,
        "counter" | "mirrorcoat" => -5,
        "roar" | "whirlwind" | "dragontail" | "circlethrow" | "teleport" => -6,
        "trickroom" => -7,
        _ => 0,
    }
}

pub fn determine_battle_turn_order(
    player_spe: i32,
    wild_spe: i32,
    player_prio: i32,
    wild_prio: i32,
    tie_breaker_player_wins: bool,
) -> bool {
    if player_prio > wild_prio {
        true
    } else if wild_prio > player_prio {
        false
    } else {
        determine_wild_battle_turn_order(player_spe, wild_spe, tie_breaker_player_wins)
    }
}

pub fn select_smart_gym_leader_move(
    leader_pkmn: &BattlePokemon,
    player_pkmn: &BattlePokemon,
) -> MoveDetail {
    if leader_pkmn.moves.is_empty() {
        return MoveDetail {
            name: "Tackle".to_string(),
            t: "Normal".to_string(),
            c: "Physical".to_string(),
            p: Some(40),
            a: Some(100),
            pp: Some(35),
            d: String::new(),
        };
    }
    if leader_pkmn.moves.len() == 1 {
        return leader_pkmn.moves[0].clone();
    }

    let player_spe = player_pkmn.get_effective_spe_against(leader_pkmn);
    let leader_spe = leader_pkmn.get_effective_spe_against(player_pkmn);
    let player_is_faster = player_spe > leader_spe;

    // Check for lethal knockout moves
    let mut lethal_moves: Vec<(&MoveDetail, i32, f64, i32, u32)> = Vec::new();
    for m in &leader_pkmn.moves {
        let (raw_dmg, _, eff) = calc_battle_damage(leader_pkmn, m, player_pkmn);
        let prio = get_move_priority(&m.name);
        let acc = m.a.unwrap_or(100);
        if raw_dmg >= player_pkmn.current_hp && eff > 0.0 {
            lethal_moves.push((m, raw_dmg, eff, prio, acc));
        }
    }

    if !lethal_moves.is_empty() {
        // If player is faster, priority KO guarantees first strike victory
        if player_is_faster {
            if let Some(&(prio_m, _, _, _, _)) = lethal_moves.iter().filter(|(_, _, _, prio, _)| *prio > 0).max_by_key(|(_, _, eff, prio, acc)| (*prio, (*eff * 10.0) as i32, *acc)) {
                return prio_m.clone();
            }
        }
        // Prefer highest accuracy, then super-effective, then damage
        lethal_moves.sort_by(|a, b| {
            b.4.cmp(&a.4)
                .then_with(|| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal))
                .then_with(|| b.1.cmp(&a.1))
        });
        return lethal_moves[0].0.clone();
    }

    // Master AI Rule: "he can play only super effective moves etc."
    // If the leader has super-effective moves against the player, ONLY pick from those moves!
    let super_effective_moves: Vec<&MoveDetail> = leader_pkmn
        .moves
        .iter()
        .filter(|m| {
            let (_, _, eff) = calc_battle_damage(leader_pkmn, m, player_pkmn);
            eff >= 2.0
        })
        .collect();

    let candidate_pool: Vec<&MoveDetail> = if !super_effective_moves.is_empty() {
        super_effective_moves
    } else {
        // Filter out immune / 0x moves if any damaging moves exist
        let non_immune_moves: Vec<&MoveDetail> = leader_pkmn
            .moves
            .iter()
            .filter(|m| {
                let (_, _, eff) = calc_battle_damage(leader_pkmn, m, player_pkmn);
                eff > 0.0
            })
            .collect();
        if !non_immune_moves.is_empty() {
            non_immune_moves
        } else {
            leader_pkmn.moves.iter().collect()
        }
    };

    let mut best_move = candidate_pool[0].clone();
    let mut best_score = -999999.0;

    for &m in &candidate_pool {
        let (raw_dmg, _, eff) = calc_battle_damage(leader_pkmn, m, player_pkmn);
        let dmg = raw_dmg.max(0) as f64;
        let acc = m.a.unwrap_or(100).clamp(1, 100) as f64 / 100.0;
        let prio = get_move_priority(&m.name);

        let mut score = dmg * eff;

        // STAB preference
        if leader_pkmn.types.iter().any(|t| t.eq_ignore_ascii_case(&m.t)) {
            score *= 1.25;
        }

        // Accuracy factor
        score *= acc;

        // Priority factor if player is faster
        if prio > 0 && player_is_faster {
            score += 35.0;
        }

        if score > best_score {
            best_score = score;
            best_move = m.clone();
        } else if (score - best_score).abs() < 0.001 {
            if m.p.unwrap_or(0) > best_move.p.unwrap_or(0) {
                best_move = m.clone();
            }
        }
    }

    best_move
}

pub fn select_smart_gym_leader_counter_index(
    remaining_team: &[BattlePokemon],
    player_pkmn: &BattlePokemon,
) -> usize {
    if remaining_team.is_empty() {
        return 0;
    }

    let mut best_idx = 0;
    let mut best_score = -999999.0;

    for (idx, candidate) in remaining_team.iter().enumerate() {
        if candidate.current_hp <= 0 {
            continue;
        }

        let mut score = 0.0;

        // Defensive evaluation
        for ptype in &player_pkmn.types {
            let mult = get_type_effectiveness(ptype, &candidate.types);
            if mult == 0.0 {
                score += 120.0;
            } else if mult <= 0.5 {
                score += 60.0;
            } else if mult >= 4.0 {
                score -= 160.0;
            } else if mult >= 2.0 {
                score -= 80.0;
            }
        }

        // Offensive evaluation
        let mut max_move_rating: f64 = 0.0;
        for m in &candidate.moves {
            let (raw_dmg, _, eff) = calc_battle_damage(candidate, m, player_pkmn);
            if eff >= 4.0 {
                max_move_rating = max_move_rating.max(200.0 + raw_dmg as f64);
            } else if eff >= 2.0 {
                max_move_rating = max_move_rating.max(120.0 + raw_dmg as f64);
            } else if eff == 1.0 {
                max_move_rating = max_move_rating.max(raw_dmg as f64);
            }
        }
        score += max_move_rating;

        // Speed advantage
        if candidate.get_effective_spe_against(player_pkmn) > player_pkmn.get_effective_spe_against(candidate) {
            score += 40.0;
        }

        // HP ratio
        let hp_ratio = candidate.current_hp as f64 / candidate.max_hp.max(1) as f64;
        score += hp_ratio * 30.0;

        if score > best_score {
            best_score = score;
            best_idx = idx;
        }
    }

    best_idx
}

pub fn evaluate_gym_leader_tactical_switch(
    active_leader_pkmn: &BattlePokemon,
    player_pkmn: &BattlePokemon,
    remaining_team: &[BattlePokemon],
    turns_since_switch: usize,
) -> Option<usize> {
    if remaining_team.is_empty() {
        return None;
    }

    let has_conscious = remaining_team.iter().any(|p| p.current_hp > 0);
    if !has_conscious {
        return None;
    }

    // Never switch if the active Pokémon can score an immediate lethal KO this turn!
    let can_ko_player = active_leader_pkmn.moves.iter().any(|m| {
        let (dmg, _, eff) = calc_battle_damage(active_leader_pkmn, m, player_pkmn);
        dmg >= player_pkmn.current_hp && eff > 0.0
    });
    if can_ko_player {
        return None;
    }

    let is_critical_4x_weak = player_pkmn.types.iter().any(|ptype| {
        get_type_effectiveness(ptype, &active_leader_pkmn.types) >= 4.0
    });

    // Check minimum switch cooldown: at least 2 turns to prevent switch spamming
    if turns_since_switch < 2 {
        return None;
    }

    let player_super_effective = player_pkmn.types.iter().any(|ptype| {
        get_type_effectiveness(ptype, &active_leader_pkmn.types) >= 2.0
    });

    let leader_has_super_effective = active_leader_pkmn.moves.iter().any(|m| {
        let (_, _, eff) = calc_battle_damage(active_leader_pkmn, m, player_pkmn);
        eff >= 2.0
    });

    let active_moves_all_resisted = active_leader_pkmn.moves.iter().all(|m| {
        let (_, _, eff) = calc_battle_damage(active_leader_pkmn, m, player_pkmn);
        eff <= 0.5
    });

    // Master AI considers switching if:
    // 1. Player deals super-effective damage and leader has no super-effective counter
    // 2. Active leader's moves are completely resisted/immune
    let needs_switch = (player_super_effective && !leader_has_super_effective) || active_moves_all_resisted || is_critical_4x_weak;
    if !needs_switch {
        return None;
    }

    let candidate_idx = select_smart_gym_leader_counter_index(remaining_team, player_pkmn);
    let candidate = &remaining_team[candidate_idx];
    if candidate.current_hp <= 0 {
        return None;
    }

    let candidate_weak = player_pkmn.types.iter().any(|ptype| {
        get_type_effectiveness(ptype, &candidate.types) >= 2.0
    });
    if candidate_weak {
        return None;
    }

    let candidate_resists = player_pkmn.types.iter().any(|ptype| {
        get_type_effectiveness(ptype, &candidate.types) <= 0.5
    });
    let candidate_offensive = candidate.moves.iter().any(|m| {
        let (_, _, eff) = calc_battle_damage(candidate, m, player_pkmn);
        eff >= 2.0
    });

    if candidate_resists || candidate_offensive || is_critical_4x_weak {
        Some(candidate_idx)
    } else {
        None
    }
}

fn format_action_log(
    attacker_name: &str,
    move_name: &str,
    dmg: i32,
    is_crit: bool,
    type_mult: f64,
    _is_wild: bool,
) -> String {
    let mut eff_lines = Vec::new();
    if is_crit {
        eff_lines.push("<i>Critical hit!</i>");
    }
    if type_mult >= 2.0 {
        eff_lines.push("<i>It's super effective!</i>");
    } else if type_mult == 0.0 {
        eff_lines.push("<i>It has no effect.</i>");
    } else if type_mult <= 0.5 {
        eff_lines.push("<i>It's not very effective...</i>");
    } else {
        eff_lines.push("<i>It's effective.</i>");
    }

    let eff_str = eff_lines.join("\n");
    format!("{} used <b>{}</b>.\n{}\nDeal {} damage.", attacker_name, move_name, eff_str, dmg)
}

fn format_miss_log(attacker_name: &str, move_name: &str) -> String {
    format!("{} used <b>{}</b>.\n{}'s attack missed.", attacker_name, move_name, attacker_name)
}

pub fn calculate_wild_kill_pd(level: u32) -> i64 {
    let pd = ((level * 12 + 79) / 80) as i64;
    pd.clamp(1, 12)
}

fn format_wild_faint_screen(attack_logs: &[String], wild_name: &str, is_shiny: bool, pd_gain: i64) -> String {
    let shiny_prefix = if is_shiny {
        format!("{} ", SHINY_EMOJI)
    } else {
        String::new()
    };
    let logs = attack_logs.join("\n\n");
    if pd_gain > 0 {
        format!(
            "{}\n\nThe wild {}{} fainted.\n\n+{} 💵",
            logs,
            shiny_prefix,
            wild_name,
            pd_gain
        )
    } else {
        format!(
            "{}\n\nThe wild {}{} fainted.",
            logs,
            shiny_prefix,
            wild_name
        )
    }
}

fn format_player_faint_screen(attack_logs: &[String], player_name: &str) -> String {
    let logs = attack_logs.join("\n\n");
    format!(
        "{}\n\n{} fainted.",
        logs,
        player_name
    )
}

pub fn format_player_faint_prompt(attack_logs: &[String], player_name: &str) -> String {
    let logs = attack_logs.join("\n\n");
    format!(
        "{}\n\n{} fainted. Choose your next Pokémon:",
        logs,
        player_name
    )
}

pub async fn get_user_active_team(pool: &SqlitePool, user_id: u64) -> usize {
    let row = sqlx::query("SELECT active_team FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(pool)
        .await
        .ok()
        .flatten();

    let team: i64 = row.and_then(|r| r.try_get("active_team").ok()).unwrap_or(1);
    if (1..=6).contains(&team) {
        team as usize
    } else {
        1
    }
}

pub async fn process_player_pokemon_faint(
    pool: &SqlitePool,
    battle: &mut ActiveBattle,
    owner_id: u64,
) -> (bool, usize, Vec<usize>) {
    if let Some(db_id) = battle.player_pokemon.db_id {
        if !battle.fainted_pokemon_ids.contains(&db_id) {
            battle.fainted_pokemon_ids.push(db_id);
        }
        battle.team_hp.insert(db_id, 0);
    }
    battle.player_pokemon.current_hp = 0;

    let active_team_num = get_user_active_team(pool, owner_id).await;
    let mut team_rows = sqlx::query(
        "SELECT p.id
         FROM user_teams t
         JOIN pokemons p ON t.pokemon_db_id = p.id
         WHERE t.user_id = ? AND t.team_num = ?
         ORDER BY t.slot ASC"
    )
    .bind(owner_id as i64)
    .bind(active_team_num as i64)
    .fetch_all(pool)
    .await
    .unwrap_or_default();

    if team_rows.is_empty() {
        team_rows = sqlx::query(
            "SELECT id FROM pokemons WHERE user_id = ? ORDER BY id ASC LIMIT 6"
        )
        .bind(owner_id as i64)
        .fetch_all(pool)
        .await
        .unwrap_or_default();
    }

    let team_count = team_rows.len();
    let mut fainted_indices = Vec::new();
    let mut has_alive = false;

    for (idx, r) in team_rows.iter().enumerate() {
        let db_id: i64 = r.get("id");
        if battle.fainted_pokemon_ids.contains(&db_id) {
            fainted_indices.push(idx);
        } else {
            has_alive = true;
        }
    }

    battle.fainted_team_indices = fainted_indices.clone();
    (has_alive, team_count, fainted_indices)
}

fn format_hp_bar(current: i32, max: i32, total_blocks: usize, _user_id: u64) -> String {
    let max = max.max(1);
    let current = current.clamp(0, max);
    let ratio = current as f64 / max as f64;
    let mut filled = (ratio * total_blocks as f64).round() as usize;
    if current > 0 && filled == 0 {
        filled = 1;
    }
    filled = filled.min(total_blocks);
    let empty = total_blocks - filled;

    let filled_str = "█".repeat(filled);
    let empty_str = "░".repeat(empty);

    format!("<code>{}{}</code>", filled_str, empty_str)
}

fn format_battle_screen(
    header_text: &str,
    wild_pokemon: &BattlePokemon,
    player_pokemon: &BattlePokemon,
    trainer_name: &str,
    trainer_id: u64,
) -> String {
    let wild_name = format_pokemon_name(&wild_pokemon.name);
    let wild_types_str = wild_pokemon
        .types
        .iter()
        .map(|t| format_type_with_emoji(t))
        .collect::<Vec<_>>()
        .join(" / ");

    let wild_header = if wild_pokemon.is_shiny {
        format!("Wild {} <b>{}</b> [{}]", SHINY_EMOJI, wild_name, wild_types_str)
    } else {
        format!("Wild <b>{}</b> [{}]", wild_name, wild_types_str)
    };

    let wild_hp_line = format!(
        "Lv. {} • HP <code>{}/{}</code>",
        wild_pokemon.level,
        wild_pokemon.current_hp.max(0),
        wild_pokemon.max_hp
    );
    let wild_hp_bar = format_hp_bar(wild_pokemon.current_hp, wild_pokemon.max_hp, 10, trainer_id);

    let player_name = format_pokemon_name(&player_pokemon.name);

    let player_types_str = player_pokemon
        .types
        .iter()
        .map(|t| format_type_with_emoji(t))
        .collect::<Vec<_>>()
        .join(" / ");

    let player_header = format!("<b>{}</b> [{}]", player_name, player_types_str);
    let player_hp_line = format!(
        "Lv. {} • HP <code>{}/{}</code>",
        player_pokemon.level,
        player_pokemon.current_hp.max(0),
        player_pokemon.max_hp
    );
    let player_hp_bar = format_hp_bar(player_pokemon.current_hp, player_pokemon.max_hp, 10, trainer_id);

    let mut move_lines = Vec::new();
    for m in &player_pokemon.moves {
        move_lines.push(format_battle_move_entry(m, trainer_id));
    }

    let moves_str = move_lines.join("\n");

    format!(
        "{}\n\n{}\n{}\n{}\n\nCurrent turn: <a href=\"tg://user?id={}\">{}</a>\n{}\n{}\n{}\n\n{}",
        header_text,
        wild_header,
        wild_hp_line,
        wild_hp_bar,
        trainer_id,
        escape_html(trainer_name),
        player_header,
        player_hp_line,
        player_hp_bar,
        moves_str
    )
}

pub fn format_gym_battle_screen(
    header_text: &str,
    leader_name: &str,
    leader_pokemon: &BattlePokemon,
    player_pokemon: &BattlePokemon,
    trainer_name: &str,
    trainer_id: u64,
) -> String {
    let leader_pkmn_name = format_pokemon_name(&leader_pokemon.name);
    let leader_types_str = leader_pokemon
        .types
        .iter()
        .map(|t| format_type_with_emoji(t))
        .collect::<Vec<_>>()
        .join(" / ");

    let leader_header = format!("Gym Leader {}'s <b>{}</b> [{}]", leader_name, leader_pkmn_name, leader_types_str);

    let leader_hp_line = format!(
        "Lv. {} • HP <code>{}/{}</code>",
        leader_pokemon.level,
        leader_pokemon.current_hp.max(0),
        leader_pokemon.max_hp
    );
    let leader_hp_bar = format_hp_bar(leader_pokemon.current_hp, leader_pokemon.max_hp, 10, trainer_id);

    let player_name = format_pokemon_name(&player_pokemon.name);

    let player_types_str = player_pokemon
        .types
        .iter()
        .map(|t| format_type_with_emoji(t))
        .collect::<Vec<_>>()
        .join(" / ");

    let player_header = format!("<b>{}</b> [{}]", player_name, player_types_str);
    let player_hp_line = format!(
        "Lv. {} • HP <code>{}/{}</code>",
        player_pokemon.level,
        player_pokemon.current_hp.max(0),
        player_pokemon.max_hp
    );
    let player_hp_bar = format_hp_bar(player_pokemon.current_hp, player_pokemon.max_hp, 10, trainer_id);

    let mut move_lines = Vec::new();
    for m in &player_pokemon.moves {
        move_lines.push(format_battle_move_entry(m, trainer_id));
    }

    let moves_str = move_lines.join("\n");

    format!(
        "{}\n\n{}\n{}\n{}\n\nCurrent turn: <a href=\"tg://user?id={}\">{}</a>\n{}\n{}\n{}\n\n{}",
        header_text,
        leader_header,
        leader_hp_line,
        leader_hp_bar,
        trainer_id,
        escape_html(trainer_name),
        player_header,
        player_hp_line,
        player_hp_bar,
        moves_str
    )
}

pub fn build_gym_battle_keyboard(owner_id: u64, moves: &[MoveDetail]) -> InlineKeyboardMarkup {
    let mut keyboard_rows = Vec::new();

    let mut move_row = Vec::new();
    for (idx, m) in moves.iter().enumerate() {
        move_row.push(InlineKeyboardButton::callback(
            &m.name,
            format!("btl_mv:{}:{}", owner_id, idx),
        ));
        if move_row.len() == 2 {
            keyboard_rows.push(move_row);
            move_row = Vec::new();
        }
    }
    if !move_row.is_empty() {
        keyboard_rows.push(move_row);
    }

    keyboard_rows.push(vec![
        InlineKeyboardButton::callback("Run", format!("btl_run:{}", owner_id)),
        InlineKeyboardButton::callback("Pokemons", format!("btl_team:{}", owner_id)),
    ]);

    InlineKeyboardMarkup::new(keyboard_rows)
}

#[allow(dead_code)]
fn build_battle_keyboard(owner_id: u64, moves: &[MoveDetail]) -> InlineKeyboardMarkup {
    build_battle_keyboard_opts(owner_id, moves, false)
}

fn build_battle_keyboard_opts(owner_id: u64, moves: &[MoveDetail], is_evtrain: bool) -> InlineKeyboardMarkup {
    let mut keyboard_rows = Vec::new();

    let mut move_row = Vec::new();
    for (idx, m) in moves.iter().enumerate() {
        move_row.push(InlineKeyboardButton::callback(
            &m.name,
            format!("btl_mv:{}:{}", owner_id, idx),
        ));
        if move_row.len() == 2 {
            keyboard_rows.push(move_row);
            move_row = Vec::new();
        }
    }
    if !move_row.is_empty() {
        keyboard_rows.push(move_row);
    }

    if is_evtrain {
        keyboard_rows.push(vec![
            InlineKeyboardButton::callback("Run", format!("btl_run:{}", owner_id)),
            InlineKeyboardButton::callback("Pokemons", format!("btl_team:{}", owner_id)),
        ]);
    } else {
        keyboard_rows.push(vec![
            InlineKeyboardButton::callback("Poke Ball", format!("btl_ball:{}", owner_id)),
            InlineKeyboardButton::callback("Run", format!("btl_run:{}", owner_id)),
            InlineKeyboardButton::callback("Pokemons", format!("btl_team:{}", owner_id)),
        ]);
    }

    InlineKeyboardMarkup::new(keyboard_rows)
}

pub fn build_battle_team_keyboard(owner_id: u64, team_count: usize, fainted_indices: &[usize]) -> InlineKeyboardMarkup {
    build_battle_team_keyboard_internal(owner_id, team_count, fainted_indices, true)
}

pub fn build_battle_faint_team_keyboard(owner_id: u64, team_count: usize, fainted_indices: &[usize]) -> InlineKeyboardMarkup {
    build_battle_team_keyboard_internal(owner_id, team_count, fainted_indices, false)
}

fn build_battle_team_keyboard_internal(
    owner_id: u64,
    team_count: usize,
    fainted_indices: &[usize],
    include_back: bool,
) -> InlineKeyboardMarkup {
    let mut keyboard_rows = Vec::new();

    let is_available = |idx: usize| -> bool {
        idx < team_count && !fainted_indices.contains(&idx)
    };

    let mut row1 = Vec::new();
    if is_available(0) {
        row1.push(InlineKeyboardButton::callback("1", format!("btl_sw:{}:0", owner_id)));
    } else {
        row1.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    if is_available(1) {
        row1.push(InlineKeyboardButton::callback("2", format!("btl_sw:{}:1", owner_id)));
    } else {
        row1.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    keyboard_rows.push(row1);

    let mut row2 = Vec::new();
    if is_available(2) {
        row2.push(InlineKeyboardButton::callback("3", format!("btl_sw:{}:2", owner_id)));
    } else {
        row2.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    if is_available(3) {
        row2.push(InlineKeyboardButton::callback("4", format!("btl_sw:{}:3", owner_id)));
    } else {
        row2.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    keyboard_rows.push(row2);

    let mut row3 = Vec::new();
    if is_available(4) {
        row3.push(InlineKeyboardButton::callback("5", format!("btl_sw:{}:4", owner_id)));
    } else {
        row3.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    if is_available(5) {
        row3.push(InlineKeyboardButton::callback("6", format!("btl_sw:{}:5", owner_id)));
    } else {
        row3.push(InlineKeyboardButton::callback("\u{2800}", "noop"));
    }
    keyboard_rows.push(row3);

    keyboard_rows.push(vec![InlineKeyboardButton::callback(
        "View Team",
        format!("btl_vteam:{}", owner_id),
    )]);

    if include_back {
        keyboard_rows.push(vec![InlineKeyboardButton::callback(
            "Back",
            format!("btl_back:{}", owner_id),
        )]);
    }

    InlineKeyboardMarkup::new(keyboard_rows)
}

