#[derive(Debug, PartialEq, Eq)]
pub struct BerryResult {
    pub ev_loss: i32,
    pub berries_used: i64,
}

pub fn calculate_berry_application(
    current_stat_ev: i32,
    user_berries: i64,
    multiplier: u32,
) -> Result<BerryResult, &'static str> {
    if user_berries <= 0 {
        return Err("You don't have any berries left!");
    }
    if current_stat_ev <= 0 {
        return Err("This stat is already at 0 EVs!");
    }

    let desired_berries = (multiplier as i64).min(user_berries);
    if desired_berries <= 0 {
        return Err("You don't have enough berries!");
    }

    let potential_ev_loss = (desired_berries as i32) * 10;
    let ev_loss = potential_ev_loss.min(current_stat_ev);

    if ev_loss <= 0 {
        return Err("No EVs could be removed!");
    }

    let berries_used = ((ev_loss + 9) / 10) as i64;
    Ok(BerryResult {
        ev_loss,
        berries_used,
    })
}

