pub const CANDY_CUSTOM_EMOJI_ID: &str = "5427163461689833807";
pub const CANDY_EMOJI: &str = r#"<tg-emoji emoji-id="5427163461689833807">🍬</tg-emoji>"#;

#[derive(Debug, PartialEq, Eq)]
pub struct CandyResult {
    pub old_level: i32,
    pub new_level: i32,
    pub candies_used: i64,
}

pub fn calculate_candy_application(
    current_level: i32,
    user_candies: i64,
    multiplier: u32,
) -> Result<CandyResult, &'static str> {
    if user_candies <= 0 {
        return Err("You don't have enough Rare Candies!");
    }
    if current_level >= 100 {
        return Err("This Pokémon is already at the maximum level (Lv. 100)!");
    }

    let desired_candies = (multiplier as i64).min(user_candies);
    if desired_candies <= 0 {
        return Err("You don't have enough Rare Candies!");
    }

    let max_gain = (100 - current_level) as i64;
    let candies_used = desired_candies.min(max_gain);
    if candies_used <= 0 {
        return Err("This Pokémon is already at the maximum level (Lv. 100)!");
    }

    let new_level = current_level + candies_used as i32;

    Ok(CandyResult {
        old_level: current_level,
        new_level,
        candies_used,
    })
}

pub fn format_candy_screen(
    display_name: &str,
    old_level: i32,
    new_level: i32,
    candies_used: i64,
    learned_moves: &[String],
) -> String {
    let mut text = format!(
        "You gave {} {} to {}\nLv. {} -> Lv. {}",
        candies_used,
        CANDY_EMOJI,
        display_name,
        old_level,
        new_level
    );
    for m in learned_moves {
        text.push_str(&format!("\n{} learned {}", display_name, m));
    }
    text
}

pub fn format_teach_prompt_text(
    display_name: &str,
    level: i32,
    move_detail: &MoveDetail,
) -> String {
    format!(
        "Lv. {} {} wants to learn <b>{}</b> but already knows 4 moves. Should a move be forgotten to make space for <b>{}</b>?\n\n<b>{} [{}]</b>\nPower: {}, Accuracy: {} ({})\n\nYou will have 10 minutes to decide",
        level,
        escape_html(display_name),
        escape_html(&move_detail.name),
        escape_html(&move_detail.name),
        escape_html(&move_detail.name),
        format_type_with_emoji(&move_detail.t),
        move_detail.p.unwrap_or(0),
        move_detail.a.unwrap_or(100),
        capitalize(&move_detail.c)
    )
}

