pub fn get_tm_by_number(num: u32) -> Option<&'static ShopTm> {
    TM_CATALOG.iter().find(|t| t.number == num)
}

pub fn get_tm_by_name(name: &str) -> Option<&'static ShopTm> {
    let clean = name.to_lowercase().replace(['-', ' '], "");
    TM_CATALOG.iter().find(|t| {
        t.name.to_lowercase().replace(['-', ' '], "") == clean
            || format!("tm{}", t.number) == clean
            || format!("{}", t.number) == clean
    })
}

pub fn default_shop_tms() -> Vec<&'static ShopTm> {
    vec![
        get_tm_by_number(45).unwrap(),
        get_tm_by_number(46).unwrap(),
        get_tm_by_number(95).unwrap(),
        get_tm_by_number(219).unwrap(),
        get_tm_by_number(54).unwrap(),
    ]
}

