pub fn get_tutor_by_number(num: u32) -> Option<&'static TutorMove> {
    TUTOR_CATALOG.iter().find(|t| t.number == num)
}

pub fn get_tutor_by_name(name: &str) -> Option<&'static TutorMove> {
    let clean = name.to_lowercase().replace(['-', ' '], "");
    TUTOR_CATALOG.iter().find(|t| {
        t.name.to_lowercase().replace(['-', ' '], "") == clean
            || format!("tutor{}", t.number) == clean
            || format!("{}", t.number) == clean
    })
}

pub fn is_tutor_move(name: &str) -> bool {
    let clean = name.to_lowercase().replace(['-', ' '], "");
    TUTOR_CATALOG.iter().any(|t| t.name.to_lowercase().replace(['-', ' '], "") == clean)
}

pub fn is_tutor_item_or_move(item_str: &str) -> bool {
    let clean = item_str.trim().to_lowercase();
    let clean_up = clean.to_uppercase();
    if clean_up.starts_with("TUTOR") || clean_up.contains("TUTOR") {
        return true;
    }
    is_tutor_move(&clean)
}

pub fn format_number(n: i64) -> String {
    let s = n.abs().to_string();
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for (i, &ch) in chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(ch);
    }
    if n < 0 {
        format!("-{}", result)
    } else {
        result
    }
}

