pub fn format_pokestore_tms(balance: i64, tms: &[&ShopTm], refresh_str: &str) -> String {
    let tms_hdr = crate::emoji::get_tms_emoji(true);
    let mut lines = Vec::new();
    lines.push(format!(r#"<blockquote>{} <u><b>TECHNICAL MACHINES</b></u></blockquote>"#, tms_hdr));
    lines.push(String::new());
    lines.push(format!("• Balance ▸ {} 💵", format_number(balance)));
    lines.push(String::new());

    let pure_tms: Vec<&&ShopTm> = tms.iter().filter(|tm| !is_tutor_move(tm.name)).collect();
    for (i, tm) in pure_tms.iter().enumerate() {
        let type_emoji_str = type_emoji(tm.move_type);
        lines.push(format!(
            "{}) TM #{} : {} [{} {}]",
            i + 1,
            tm.number,
            tm.name,
            type_emoji_str,
            capitalize(tm.move_type)
        ));
        lines.push(format!(
            "  ╰ {} • Pwr: {} | Acc: {} • {} 💵",
            tm.category,
            tm.pwr,
            tm.acc,
            format_number(tm.price)
        ));
        if i + 1 < pure_tms.len() {
            lines.push(String::new());
        }
    }

    lines.push(String::new());
    lines.push(format!(r#"<blockquote>{} TM Shop will refresh in: {}</blockquote>"#, tms_hdr, refresh_str));

    lines.join("\n")
}

