#[derive(Debug, PartialEq, Eq, Clone)]
pub enum BuyItemTarget {
    RegularBall,
    GreatBall,
    UltraBall,
    RepeatBall,
    NestBall,
    DuskBall,
    OmniRing,
    EggIncubator,
    RareCandy,
    Berry,
    Vitamin,
    Boost,
    Tm(u32),
}

pub fn format_buy_usage() -> &'static str {
    "Usage: /buy <item> [amount]"
}

pub fn parse_buy_input(input: &str) -> Result<(BuyItemTarget, i64), String> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(format_buy_usage().to_string());
    }

    let lower = trimmed.to_lowercase();
    let normalized_full = lower.replace('#', "").replace('-', " ");
    if normalized_full.starts_with("tutor") {
        return Err("Move Tutors cannot be purchased in the TM Shop.".to_string());
    }
    if normalized_full.starts_with("tm") {
        let rest = normalized_full.trim_start_matches("tm").trim();
        let tm_tokens: Vec<&str> = rest.split_whitespace().collect();
        if let Some(first) = tm_tokens.first() {
            if let Ok(num) = first.parse::<u32>() {
                let qty = if tm_tokens.len() > 1 {
                    tm_tokens[1].parse::<i64>().unwrap_or(1).max(1)
                } else {
                    1
                };
                return Ok((BuyItemTarget::Tm(num), qty));
            }
        }
    }

    let tokens: Vec<&str> = trimmed.split_whitespace().collect();
    let (item_tokens, qty) = if tokens.len() > 1 {
        if let Ok(q) = tokens.last().unwrap().parse::<i64>() {
            if q <= 0 {
                return Err("Quantity must be greater than 0.".to_string());
            }
            (&tokens[..tokens.len() - 1], q)
        } else {
            (&tokens[..], 1)
        }
    } else {
        (&tokens[..], 1)
    };

    let item_str = item_tokens.join(" ").to_lowercase();
    let normalized = item_str.replace('#', "").replace('-', " ");

    if is_tutor_item_or_move(&normalized) {
        return Err("Move Tutors cannot be purchased in the TM Shop.".to_string());
    }

    match normalized.as_str() {
        "regular ball" | "regular" | "pokeball" | "poke ball" | "poke" => Ok((BuyItemTarget::RegularBall, qty)),
        "great ball" | "great" => Ok((BuyItemTarget::GreatBall, qty)),
        "ultra ball" | "ultra" => Ok((BuyItemTarget::UltraBall, qty)),
        "repeat ball" | "repeat" => Ok((BuyItemTarget::RepeatBall, qty)),
        "nest ball" | "nest" => Ok((BuyItemTarget::NestBall, qty)),
        "dusk ball" | "dusk" => Ok((BuyItemTarget::DuskBall, qty)),
        "omni ring" | "omni" | "omni_ring" => Ok((BuyItemTarget::OmniRing, qty)),
        "egg incubator" | "incubator" | "egg_incubator" => Ok((BuyItemTarget::EggIncubator, qty)),
        "rare candy" | "candy" | "candies" | "rare_candy" => Ok((BuyItemTarget::RareCandy, qty)),
        "berry" | "berries" => Ok((BuyItemTarget::Berry, qty)),
        "vitamin" | "vitamins" => Ok((BuyItemTarget::Vitamin, qty)),
        "boost" | "boosts" => Ok((BuyItemTarget::Boost, qty)),
        _ => Err(format!("Unknown item '<b>{}</b>'. Use /pokestore to see available items.", escape_html(&item_str))),
    }
}

pub async fn get_user_pokedollars(pool: &SqlitePool, user_id: u64) -> i64 {
    sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(pool)
        .await
        .unwrap_or(None)
        .unwrap_or(0)
}

pub async fn get_or_create_user_tm_shop(
    pool: &SqlitePool,
    user_id: u64,
) -> Result<(Vec<&'static ShopTm>, String), sqlx::Error> {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;

    let row = sqlx::query(
        "SELECT tm_1, tm_2, tm_3, tm_4, tm_5, expires_at FROM user_tm_shop WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(pool)
    .await?;

    let (tm_ids, expires_at) = match row {
        Some(r) => {
            let exp: i64 = r.get("expires_at");
            if now >= exp {
                let new_ids: Vec<u32> = {
                    let mut rng = rand::thread_rng();
                    let mut all: Vec<u32> = TM_CATALOG.iter().map(|t| t.number).collect();
                    all.shuffle(&mut rng);
                    all.into_iter().take(5).collect()
                };
                let new_exp = now + 3 * 86400;

                let _ = sqlx::query(
                    "UPDATE user_tm_shop SET tm_1 = ?, tm_2 = ?, tm_3 = ?, tm_4 = ?, tm_5 = ?, expires_at = ? WHERE user_id = ?"
                )
                .bind(new_ids[0] as i64)
                .bind(new_ids[1] as i64)
                .bind(new_ids[2] as i64)
                .bind(new_ids[3] as i64)
                .bind(new_ids[4] as i64)
                .bind(new_exp)
                .bind(user_id as i64)
                .execute(pool)
                .await;

                (new_ids, new_exp)
            } else {
                let ids = vec![
                    r.get::<i64, _>("tm_1") as u32,
                    r.get::<i64, _>("tm_2") as u32,
                    r.get::<i64, _>("tm_3") as u32,
                    r.get::<i64, _>("tm_4") as u32,
                    r.get::<i64, _>("tm_5") as u32,
                ];
                (ids, exp)
            }
        }
        None => {
            let default_ids = vec![45, 46, 95, 219, 54];
            let new_exp = now + 3 * 86400;
            let _ = sqlx::query(
                "INSERT INTO user_tm_shop (user_id, tm_1, tm_2, tm_3, tm_4, tm_5, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
            )
            .bind(user_id as i64)
            .bind(default_ids[0] as i64)
            .bind(default_ids[1] as i64)
            .bind(default_ids[2] as i64)
            .bind(default_ids[3] as i64)
            .bind(default_ids[4] as i64)
            .bind(new_exp)
            .execute(pool)
            .await;

            (default_ids, new_exp)
        }
    };

    let remaining = (expires_at - now).max(0);
    let days = (remaining + 86399) / 86400;
    let refresh_str = if days > 1 {
        format!("{} days", days)
    } else if days == 1 {
        "1 day".to_string()
    } else {
        "< 1 day".to_string()
    };

    let tms: Vec<&'static ShopTm> = tm_ids
        .into_iter()
        .filter_map(get_tm_by_number)
        .collect();

    Ok((tms, refresh_str))
}

pub async fn refresh_user_tm_shop(
    pool: &SqlitePool,
    user_id: u64,
) -> anyhow::Result<(Vec<&'static ShopTm>, String, i64)> {
    let balance = get_user_pokedollars(pool, user_id).await;
    if balance < 2000 {
        return Err(anyhow::anyhow!("You need 2,000 PokéDollars to refresh the TM shop!"));
    }

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;
    let new_exp = now + 3 * 86400;

    let new_ids: Vec<u32> = {
        let mut rng = rand::thread_rng();
        let mut all: Vec<u32> = TM_CATALOG.iter().map(|t| t.number).collect();
        all.shuffle(&mut rng);
        all.into_iter().take(5).collect()
    };

    sqlx::query("UPDATE users SET pokedollars = pokedollars - 2000 WHERE id = ?")
        .bind(user_id as i64)
        .execute(pool)
        .await?;

    sqlx::query(
        "INSERT INTO user_tm_shop (user_id, tm_1, tm_2, tm_3, tm_4, tm_5, expires_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(user_id) DO UPDATE SET tm_1 = excluded.tm_1, tm_2 = excluded.tm_2, tm_3 = excluded.tm_3, tm_4 = excluded.tm_4, tm_5 = excluded.tm_5, expires_at = excluded.expires_at"
    )
    .bind(user_id as i64)
    .bind(new_ids[0] as i64)
    .bind(new_ids[1] as i64)
    .bind(new_ids[2] as i64)
    .bind(new_ids[3] as i64)
    .bind(new_ids[4] as i64)
    .bind(new_exp)
    .execute(pool)
    .await?;

    let new_balance = balance - 2000;
    let tms: Vec<&'static ShopTm> = new_ids.into_iter().filter_map(get_tm_by_number).collect();
    Ok((tms, "3 days".to_string(), new_balance))
}

pub async fn buy_tm(
    pool: &SqlitePool,
    user_id: u64,
    tm_num: u32,
) -> anyhow::Result<(&'static ShopTm, i64)> {
    let tm = get_tm_by_number(tm_num)
        .ok_or_else(|| anyhow::anyhow!("TM #{} not found!", tm_num))?;

    let already_owned: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM user_tms WHERE user_id = ? AND tm_number = ? AND quantity > 0)"
    )
    .bind(user_id as i64)
    .bind(tm_num as i64)
    .fetch_one(pool)
    .await
    .unwrap_or(false);

    if already_owned {
        return Err(anyhow::anyhow!("You already own TM #{} ({})! TMs can only be purchased once.", tm.number, tm.name));
    }

    let balance = get_user_pokedollars(pool, user_id).await;
    if balance < tm.price {
        return Err(anyhow::anyhow!("You don't have enough PokéDollars!"));
    }

    sqlx::query("UPDATE users SET pokedollars = pokedollars - ? WHERE id = ?")
        .bind(tm.price)
        .bind(user_id as i64)
        .execute(pool)
        .await?;

    sqlx::query(
        "INSERT INTO user_tms (user_id, tm_number, move_name, quantity)
         VALUES (?, ?, ?, 1)
         ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = 1"
    )
    .bind(user_id as i64)
    .bind(tm.number as i64)
    .bind(tm.name)
    .execute(pool)
    .await?;

    let new_balance = balance - tm.price;
    Ok((tm, new_balance))
}

pub async fn execute_buy_command(
    pool: &SqlitePool,
    user_id: u64,
    input: &str,
) -> Result<String, String> {
    let (target, qty) = parse_buy_input(input)?;

    let (item_name, price, col_name) = match target {
        BuyItemTarget::RegularBall => ("Regular Ball", 10i64, Some("ball_regular")),
        BuyItemTarget::GreatBall => ("Great Ball", 20i64, Some("ball_great")),
        BuyItemTarget::UltraBall => ("Ultra Ball", 25i64, Some("ball_ultra")),
        BuyItemTarget::RepeatBall => ("Repeat Ball", 25i64, Some("ball_repeat")),
        BuyItemTarget::NestBall => ("Nest Ball", 15i64, Some("ball_nest")),
        BuyItemTarget::DuskBall => ("Dusk Ball", 35i64, Some("ball_dusk")),
        BuyItemTarget::OmniRing => ("Omni Ring", 5000i64, Some("omni_ring")),
        BuyItemTarget::EggIncubator => ("Egg Incubator", 5000i64, Some("egg_incubator")),
        BuyItemTarget::RareCandy => ("Rare Candy", 50i64, Some("candies")),
        BuyItemTarget::Berry => ("Berry", 25i64, Some("berries")),
        BuyItemTarget::Vitamin => ("Vitamin", 25i64, Some("vitamins")),
        BuyItemTarget::Boost => ("Boost", 500i64, Some("boosts")),
        BuyItemTarget::Tm(num) => {
            let tm = get_tm_by_number(num)
                .ok_or_else(|| format!("TM #{} is not available in the Mart.", num))?;
            if qty > 1 {
                return Err("TMs can only be purchased once.".to_string());
            }

            let already_owned: bool = sqlx::query_scalar(
                "SELECT EXISTS(SELECT 1 FROM user_tms WHERE user_id = ? AND tm_number = ? AND quantity > 0)"
            )
            .bind(user_id as i64)
            .bind(num as i64)
            .fetch_one(pool)
            .await
            .unwrap_or(false);

            if already_owned {
                return Err(format!("You already own TM #{} ({})! TMs can only be purchased once.", tm.number, tm.name));
            }

            let total_cost = tm.price;
            let balance = get_user_pokedollars(pool, user_id).await;
            if balance < total_cost {
                return Err(format!(
                    "You need <b>{} 💵</b> to buy TM #{} ({}), but only have <b>{} 💵</b>.",
                    format_number(total_cost),
                    tm.number,
                    tm.name,
                    format_number(balance)
                ));
            }

            let _ = sqlx::query("UPDATE users SET pokedollars = pokedollars - ? WHERE id = ?")
                .bind(total_cost)
                .bind(user_id as i64)
                .execute(pool)
                .await;

            let _ = sqlx::query(
                "INSERT INTO user_tms (user_id, tm_number, move_name, quantity)
                 VALUES (?, ?, ?, 1)
                 ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = 1"
            )
            .bind(user_id as i64)
            .bind(tm.number as i64)
            .bind(tm.name)
            .execute(pool)
            .await;

            let tm_emoji = crate::emoji::get_tms_emoji(true);
            return Ok(format!(
                "Purchased {} <b>TM #{} ({})</b> for <b>{} 💵</b>!",
                tm_emoji,
                tm.number,
                tm.name,
                format_number(total_cost),
            ));
        }
    };

    let col = col_name.unwrap();
    let total_cost = price * qty;
    let balance = get_user_pokedollars(pool, user_id).await;

    if balance < total_cost {
        return Err(format!(
            "You need <b>{} 💵</b> to buy {}x {}, but only have <b>{} 💵</b>.",
            format_number(total_cost),
            qty,
            item_name,
            format_number(balance)
        ));
    }

    let query_str = format!(
        "UPDATE users SET pokedollars = pokedollars - ?, {} = {} + ? WHERE id = ?",
        col, col
    );
    let _ = sqlx::query(&query_str)
        .bind(total_cost)
        .bind(qty)
        .bind(user_id as i64)
        .execute(pool)
        .await;

    let item_emoji = match target {
        BuyItemTarget::RegularBall => ball_emoji("regular"),
        BuyItemTarget::GreatBall => ball_emoji("great"),
        BuyItemTarget::UltraBall => ball_emoji("ultra"),
        BuyItemTarget::RepeatBall => ball_emoji("repeat"),
        BuyItemTarget::NestBall => ball_emoji("nest"),
        BuyItemTarget::DuskBall => ball_emoji("dusk"),
        BuyItemTarget::OmniRing => crate::emoji::get_omni_ring_emoji(true).to_string(),
        BuyItemTarget::EggIncubator => crate::emoji::get_incubator_emoji(true).to_string(),
        BuyItemTarget::RareCandy => CANDY_EMOJI.to_string(),
        BuyItemTarget::Berry => BERRY_EMOJI.to_string(),
        BuyItemTarget::Vitamin => VITAMIN_JAR_EMOJI.to_string(),
        BuyItemTarget::Boost => BOOST_EMOJI.to_string(),
        BuyItemTarget::Tm(_) => crate::emoji::get_tms_emoji(true).to_string(),
    };

    Ok(format!(
        "Purchased {} <b>{}x {}</b> for <b>{} 💵</b>!",
        item_emoji,
        qty,
        item_name,
        format_number(total_cost),
    ))
}

pub fn is_admin(user_id: u64) -> bool {
    let Ok(admin_ids_str) = std::env::var("ADMIN_IDS") else {
        return false;
    };
    admin_ids_str
        .split(',')
        .any(|id_str| id_str.trim().parse::<u64>().map(|id| id == user_id).unwrap_or(false))
}

pub fn parse_agive_input(input: &str) -> Result<(String, i64), String> {
    let parts: Vec<&str> = input.split_whitespace().collect();
    if parts.len() < 2 {
        return Err("<b>Usage:</b> <code>/agive &lt;username&gt; &lt;pd_amount&gt;</code>".to_string());
    }
    let username = parts[0].trim().trim_start_matches('@').to_string();
    if username.is_empty() {
        return Err("<b>Usage:</b> <code>/agive &lt;username&gt; &lt;pd_amount&gt;</code>".to_string());
    }

    let pd_str = parts[1].replace(',', "");
    let amount: i64 = match pd_str.parse() {
        Ok(val) if val > 0 => val,
        _ => return Err("Invalid amount. Please provide a positive amount of PokéDollars to give.".to_string()),
    };

    Ok((username, amount))
}

pub async fn find_user_by_username_or_id(
    pool: &SqlitePool,
    query: &str,
) -> Result<Option<(u64, Option<String>, String, i64)>, sqlx::Error> {
    let clean_q = query.trim().trim_start_matches('@');
    if clean_q.is_empty() {
        return Ok(None);
    }

    let row = if let Ok(numeric_id) = clean_q.parse::<i64>() {
        sqlx::query(
            "SELECT id, username, first_name, pokedollars FROM users WHERE id = ? OR LOWER(username) = LOWER(?) LIMIT 1"
        )
        .bind(numeric_id)
        .bind(clean_q)
        .fetch_optional(pool)
        .await?
    } else {
        sqlx::query(
            "SELECT id, username, first_name, pokedollars FROM users WHERE LOWER(username) = LOWER(?) LIMIT 1"
        )
        .bind(clean_q)
        .fetch_optional(pool)
        .await?
    };

    if let Some(r) = row {
        let id: i64 = r.try_get("id").unwrap_or(0);
        let username: Option<String> = r.try_get("username").ok();
        let first_name: String = r.try_get("first_name").unwrap_or_else(|_| "Trainer".to_string());
        let pokedollars: i64 = r.try_get("pokedollars").unwrap_or(0);
        Ok(Some((id as u64, username, first_name, pokedollars)))
    } else {
        Ok(None)
    }
}

pub async fn execute_agive_command(
    pool: &SqlitePool,
    admin_id: u64,
    input: &str,
) -> Result<String, String> {
    if !is_admin(admin_id) {
        return Err("<b>Access Denied:</b> You do not have administrator permissions to use this command.".to_string());
    }

    let (target_query, amount) = parse_agive_input(input)?;

    let user_opt = find_user_by_username_or_id(pool, &target_query)
        .await
        .map_err(|e| format!("Database error: {}", e))?;

    let (target_id, target_uname, target_name, old_bal) = match user_opt {
        Some(u) => u,
        None => {
            return Err(format!(
                "User @<b>{}</b> was not found in the database. Ensure they have started the bot.",
                escape_html(&target_query)
            ));
        }
    };

    sqlx::query("UPDATE users SET pokedollars = pokedollars + ? WHERE id = ?")
        .bind(amount)
        .bind(target_id as i64)
        .execute(pool)
        .await
        .map_err(|e| format!("Failed to update PokéDollars: {}", e))?;

    let new_bal = old_bal + amount;
    let currency = crate::emoji::get_currency_emoji(true);
    let display_tag = match target_uname {
        Some(ref u) => format!("@{}", escape_html(u)),
        None => format!("<b>{}</b>", escape_html(&target_name)),
    };

    Ok(format!(
r#"<blockquote>{} <b>PokéDollars Granted!</b></blockquote>

Successfully gave <b>{} {}</b> to {}.

<b>Previous Balance:</b> {} {}
<b>New Balance:</b> {} {}"#,
        currency,
        format_number(amount),
        currency,
        display_tag,
        format_number(old_bal),
        currency,
        format_number(new_bal),
        currency
    ))
}

