pub fn is_valid_key_item(name: &str) -> bool {
    let lower = name.to_lowercase();
    if lower.contains("egg")
        || lower.contains("ball")
        || lower.contains("plate")
        || lower.contains("memory")
        || lower.contains("drive")
        || lower.contains("core")
        || lower.contains("crystal")
        || (lower.contains("stone") && !ALL_MEGA_STONES.iter().any(|&s| s.eq_ignore_ascii_case(name)))
        || lower == "leftovers"
        || lower.starts_with("rusted ")
    {
        return false;
    }

    ALL_MEGA_STONES.iter().any(|&s| s.eq_ignore_ascii_case(name))
        || name.eq_ignore_ascii_case("Red Orb")
        || name.eq_ignore_ascii_case("Blue Orb")
        || name.eq_ignore_ascii_case("Jade Orb")
        || name.eq_ignore_ascii_case("Omni Ring")
        || name.ends_with(" Z")
}

