pub fn format_myinventory_tutors_page(
    tutors: &[(u32, String, i64)],
    current_page: usize,
    total_pages: usize,
) -> String {
    let tutor_hdr = crate::emoji::get_tutors_emoji(true);
    if tutors.is_empty() {
        format!(
r#"<blockquote>{} <b>Your Move Tutors:</b></blockquote>

You do not own any Move Tutors yet."#,
            tutor_hdr
        )
    } else {
        let mut lines = Vec::new();
        lines.push(format!(
            r#"<blockquote>{} <b>Your Move Tutors (Page {}/{}):</b></blockquote>"#,
            tutor_hdr, current_page, total_pages
        ));
        lines.push(String::new());
        for (num, name, qty) in tutors {
            if *qty > 1 {
                lines.push(format!("• /TUTOR{} - {} (x{})", num, name, qty));
            } else {
                lines.push(format!("• /TUTOR{} - {}", num, name));
            }
        }
        lines.join("\n")
    }
}

