pub async fn get_user_inventory_summary(pool: &SqlitePool, user_id: u64) -> (i64, i64, i64) {
    let row = sqlx::query("SELECT omni_ring, egg_incubator, pokedollars FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(pool)
        .await;
    if let Ok(Some(r)) = row {
        (
            r.try_get::<i64, _>("omni_ring").unwrap_or(0),
            r.try_get::<i64, _>("egg_incubator").unwrap_or(0),
            r.try_get::<i64, _>("pokedollars").unwrap_or(0),
        )
    } else {
        (0, 0, 0)
    }
}

pub async fn get_user_pokeballs(pool: &SqlitePool, user_id: u64) -> (i64, i64, i64, i64, i64, i64, i64) {
    let row = sqlx::query(
        "SELECT ball_regular, ball_great, ball_ultra, ball_repeat, ball_nest, ball_dusk, ball_master FROM users WHERE id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(pool)
    .await;
    if let Ok(Some(r)) = row {
        (
            r.try_get::<i64, _>("ball_regular").unwrap_or(100),
            r.try_get::<i64, _>("ball_great").unwrap_or(50),
            r.try_get::<i64, _>("ball_ultra").unwrap_or(30),
            r.try_get::<i64, _>("ball_repeat").unwrap_or(20),
            r.try_get::<i64, _>("ball_nest").unwrap_or(0),
            r.try_get::<i64, _>("ball_dusk").unwrap_or(20),
            r.try_get::<i64, _>("ball_master").unwrap_or(5),
        )
    } else {
        (100, 50, 30, 20, 0, 20, 5)
    }
}

pub async fn get_user_owned_tms(pool: &SqlitePool, user_id: u64) -> Vec<(u32, String, i64)> {
    let rows = sqlx::query(
        "SELECT tm_number, move_name, quantity FROM user_tms WHERE user_id = ? AND quantity > 0 ORDER BY tm_number ASC"
    )
    .bind(user_id as i64)
    .fetch_all(pool)
    .await;
    if let Ok(r_list) = rows {
        r_list
            .into_iter()
            .map(|r| {
                let num: i64 = r.try_get("tm_number").unwrap_or(0);
                let name: String = r.try_get("move_name").unwrap_or_default();
                let qty: i64 = r.try_get("quantity").unwrap_or(0);
                (num as u32, name, qty)
            })
            .collect()
    } else {
        Vec::new()
    }
}

