pub fn roll_hunt_drops<R: rand::Rng>(
    rng: &mut R,
    pokedex: &PokedexData,
    region: &str,
) -> Vec<HuntDrop> {
    let mut drops = Vec::new();

    // 1. Egg drop: 1 in 1,000 (0.1000%)
    if rng.gen_range(0..EGG_DROP_RATE) == 0 {
        let mut candidates: Vec<&PokemonEntry> = pokedex
            .pokemon
            .values()
            .filter(|p| {
                p.id <= 1025
                    && !is_disallowed_form(&p.name)
                    && get_pokemon_spawn_tier(p) != Some(SpawnTier::LegendarySpecial)
                    && crate::evolution::get_pre_evolution(p.id).is_none()
                    && is_pokemon_native_to_region(p, region)
            })
            .collect();

        if candidates.is_empty() {
            candidates = pokedex
                .pokemon
                .values()
                .filter(|p| {
                    p.id <= 1025
                        && !is_disallowed_form(&p.name)
                        && get_pokemon_spawn_tier(p) != Some(SpawnTier::LegendarySpecial)
                        && crate::evolution::get_pre_evolution(p.id).is_none()
                })
                .collect();
        }

        if candidates.is_empty() {
            candidates = pokedex
                .pokemon
                .values()
                .filter(|p| {
                    p.id <= 1025
                        && !is_disallowed_form(&p.name)
                        && get_pokemon_spawn_tier(p) != Some(SpawnTier::LegendarySpecial)
                })
                .collect();
        }

        if !candidates.is_empty() {
            let idx = rng.gen_range(0..candidates.len());
            let chosen = candidates[idx];
            drops.push(HuntDrop::Egg {
                pokemon_id: chosen.id,
                pokemon_name: chosen.name.clone(),
            });
        }
    }

    // 2. Mega stone drop: 1 in 8,192 (~0.0122%)
    if rng.gen_range(0..MEGA_STONE_DROP_RATE) == 0 {
        let idx = rng.gen_range(0..ALL_MEGA_STONES.len());
        drops.push(HuntDrop::MegaStone(ALL_MEGA_STONES[idx].to_string()));
    }

    // 3. TM drop: 1 in 1,543 (~0.0648%)
    if rng.gen_range(0..TM_DROP_RATE) == 0 {
        let idx = rng.gen_range(0..TM_CATALOG.len());
        let tm = &TM_CATALOG[idx];
        drops.push(HuntDrop::Tm {
            number: tm.number,
            move_name: tm.name.to_string(),
        });
    }

    // 4. Tutor drop: 1 in 2,354 (~0.0425%)
    if rng.gen_range(0..TUTOR_DROP_RATE) == 0 {
        let idx = rng.gen_range(0..TUTOR_CATALOG.len());
        let tutor = &TUTOR_CATALOG[idx];
        drops.push(HuntDrop::Tutor {
            number: tutor.number,
            move_name: tutor.name.to_string(),
        });
    }

    drops
}

pub async fn save_hunt_drops(
    pool: &SqlitePool,
    user_id: u64,
    drops: &[HuntDrop],
) -> anyhow::Result<()> {
    for drop in drops {
        match drop {
            HuntDrop::Egg { pokemon_id, .. } => {
                let incubator_owned: i64 = sqlx::query_scalar("SELECT egg_incubator FROM users WHERE id = ?")
                    .bind(user_id as i64)
                    .fetch_one(pool)
                    .await
                    .unwrap_or(0);

                let is_inc_already: i64 = sqlx::query_scalar(
                    "SELECT COUNT(*) FROM user_eggs WHERE user_id = ? AND is_incubating = 1"
                )
                .bind(user_id as i64)
                .fetch_one(pool)
                .await
                .unwrap_or(0);

                let start_incubating = if incubator_owned > 0 && is_inc_already == 0 { 1 } else { 0 };

                let _ = sqlx::query(
                    "INSERT INTO user_eggs (user_id, pokemon_id, steps_remaining, is_incubating) VALUES (?, ?, 50, ?)"
                )
                .bind(user_id as i64)
                .bind(*pokemon_id as i64)
                .bind(start_incubating)
                .execute(pool)
                .await;
            }
            HuntDrop::MegaStone(stone) => {
                let _ = sqlx::query(
                    "INSERT INTO user_key_items (user_id, item_name, quantity) VALUES (?, ?, 1)
                     ON CONFLICT(user_id, item_name) DO UPDATE SET quantity = quantity + 1"
                )
                .bind(user_id as i64)
                .bind(stone)
                .execute(pool)
                .await;
            }
            HuntDrop::Tm { number, move_name } => {
                let _ = sqlx::query(
                    "INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (?, ?, ?, 1)
                     ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = 1"
                )
                .bind(user_id as i64)
                .bind(*number as i64)
                .bind(move_name)
                .execute(pool)
                .await;
            }
            HuntDrop::Tutor { number, move_name } => {
                let _ = sqlx::query(
                    "INSERT INTO user_tutors (user_id, tutor_number, move_name, quantity) VALUES (?, ?, ?, 1)
                     ON CONFLICT(user_id, tutor_number) DO UPDATE SET quantity = quantity + 1"
                )
                .bind(user_id as i64)
                .bind(*number as i64)
                .bind(move_name)
                .execute(pool)
                .await;
            }
        }
    }
    Ok(())
}

pub async fn process_egg_step_on_hunt(
    pool: &SqlitePool,
    pokedex: &PokedexData,
    user_id: u64,
) -> Option<HatchedPokemon> {
    let egg_incubator: i64 = sqlx::query_scalar("SELECT egg_incubator FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_one(pool)
        .await
        .unwrap_or(0);

    if egg_incubator <= 0 {
        return None;
    }

    let incubating_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM user_eggs WHERE user_id = ? AND is_incubating = 1",
    )
    .bind(user_id as i64)
    .fetch_one(pool)
    .await
    .unwrap_or(0);

    if incubating_count == 0 {
        let _ = sqlx::query(
            "UPDATE user_eggs SET is_incubating = 1 WHERE id = (
                SELECT id FROM user_eggs WHERE user_id = ? AND is_incubating = 0 ORDER BY id ASC LIMIT 1
            )",
        )
        .bind(user_id as i64)
        .execute(pool)
        .await;
    }

    let incubating = get_user_incubating_egg(pool, user_id).await?;
    let new_steps = (incubating.steps_remaining - 1).max(0);

    let _ = sqlx::query("UPDATE user_eggs SET steps_remaining = ? WHERE id = ?")
        .bind(new_steps)
        .bind(incubating.id)
        .execute(pool)
        .await;

    if new_steps <= 0 {
        let _ = sqlx::query("DELETE FROM user_eggs WHERE id = ?")
            .bind(incubating.id)
            .execute(pool)
            .await;

        let pkmn_entry = pokedex.get_pokemon_by_id(incubating.pokemon_id);
        let name = pkmn_entry.map(|p| p.name.clone()).unwrap_or_else(|| "Mystery".to_string());

        let (nature, iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe) = {
            let mut rng = rand::thread_rng();
            (
                NATURES[rng.gen_range(0..NATURES.len())],
                rng.gen_range(0..=31),
                rng.gen_range(0..=31),
                rng.gen_range(0..=31),
                rng.gen_range(0..=31),
                rng.gen_range(0..=31),
                rng.gen_range(0..=31),
            )
        };
        let level = 5u32;
        let growth_rate = pokedex
            .get_pokemon_by_id(incubating.pokemon_id)
            .map(|p| get_pokemon_growth_rate(incubating.pokemon_id, p))
            .unwrap_or("Medium Fast");
        let exp = calculate_pokemon_exp_at_level(growth_rate, level as i32);

        let moves = pokedex.get_level_up_moves(incubating.pokemon_id, level);
        let m1 = moves.get(0).map(|m| m.name.clone());
        let m2 = moves.get(1).map(|m| m.name.clone());
        let m3 = moves.get(2).map(|m| m.name.clone());
        let m4 = moves.get(3).map(|m| m.name.clone());

        let insert_res = sqlx::query(
            "INSERT INTO pokemons (user_id, pokemon_id, nickname, level, nature,
                                   iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                                   ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                                   experience, move_1, move_2, move_3, move_4, is_starter, is_shiny, is_hatched)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, 0, 0, 0, ?, ?, ?, ?, ?, 0, 0, 1)",
        )
        .bind(user_id as i64)
        .bind(incubating.pokemon_id as i64)
        .bind(&name)
        .bind(level as i32)
        .bind(nature)
        .bind(iv_hp)
        .bind(iv_atk)
        .bind(iv_def)
        .bind(iv_spa)
        .bind(iv_spd)
        .bind(iv_spe)
        .bind(exp as i64)
        .bind(m1)
        .bind(m2)
        .bind(m3)
        .bind(m4)
        .execute(pool)
        .await;

        let db_id = insert_res.map(|r| r.last_insert_rowid()).unwrap_or(0);

        let _ = sqlx::query(
            "UPDATE users SET
                pokemons_caught = pokemons_caught + 1,
                pokemon_obtained = (SELECT COUNT(DISTINCT pokemon_id) FROM pokemons WHERE user_id = ?)
             WHERE id = ?",
        )
        .bind(user_id as i64)
        .bind(user_id as i64)
        .execute(pool)
        .await;

        let _ = sqlx::query(
            "INSERT OR IGNORE INTO user_seen_pokemon (user_id, pokemon_id) VALUES (?, ?)",
        )
        .bind(user_id as i64)
        .bind(incubating.pokemon_id as i64)
        .execute(pool)
        .await;

        let _ = sqlx::query(
            "UPDATE user_eggs SET is_incubating = 1 WHERE id = (
                SELECT id FROM user_eggs WHERE user_id = ? AND is_incubating = 0 ORDER BY id ASC LIMIT 1
            )",
        )
        .bind(user_id as i64)
        .execute(pool)
        .await;

        Some(HatchedPokemon {
            db_id,
            pokemon_id: incubating.pokemon_id,
            name,
        })
    } else {
        None
    }
}

pub fn format_hunt_caption(
    name: &str,
    level: u32,
    is_shiny: bool,
    already_caught: bool,
) -> String {
    let formatted_name = format_pokemon_name(name);
    let shiny_prefix = if is_shiny {
        format!("{} <b>", SHINY_EMOJI)
    } else {
        "<b>".to_string()
    };
    let star_suffix = if already_caught {
        format!(" {}", CAUGHT_STAR_EMOJI)
    } else {
        String::new()
    };

    format!(
        "A wild {}{}</b> (Lv. {}) has appeared!{}",
        shiny_prefix,
        formatted_name,
        level,
        star_suffix
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CatchResult {
    BrokeFree(usize),
    Caught,
}

pub fn calculate_catch_result_with_rolls(
    catch_rate: u32,
    current_hp: i32,
    max_hp: i32,
    ball_type: &str,
    ball_mult: f64,
    rolls: [f64; 4],
) -> CatchResult {
    if ball_type == "master" {
        return CatchResult::Caught;
    }

    let c_rate = catch_rate.max(3) as f64;
    let m_hp = max_hp.max(1) as f64;
    let cur_hp = (current_hp.max(0) as f64).min(m_hp);

    let a = (((3.0 * m_hp - 2.0 * cur_hp) * c_rate * ball_mult) / (3.0 * m_hp)).max(1.0);
    if a >= 255.0 {
        return CatchResult::Caught;
    }

    let p = (a / 255.0).clamp(0.001, 0.999).powf(0.25);

    if rolls[0] >= p {
        return CatchResult::BrokeFree(1);
    }
    if rolls[1] >= p {
        return CatchResult::BrokeFree(2);
    }
    if rolls[2] >= p {
        return CatchResult::BrokeFree(3);
    }
    if rolls[3] >= p {
        return CatchResult::BrokeFree(3);
    }

    CatchResult::Caught
}

pub fn calculate_catch_result(
    catch_rate: u32,
    current_hp: i32,
    max_hp: i32,
    ball_type: &str,
    ball_mult: f64,
) -> CatchResult {
    let mut rng = rand::thread_rng();
    let rolls = [
        rng.gen::<f64>(),
        rng.gen::<f64>(),
        rng.gen::<f64>(),
        rng.gen::<f64>(),
    ];
    calculate_catch_result_with_rolls(catch_rate, current_hp, max_hp, ball_type, ball_mult, rolls)
}

