pub fn is_valid_nickname(nick: &str) -> bool {
    let trimmed = nick.trim();
    if trimmed.is_empty() || trimmed.len() > 20 {
        return false;
    }
    trimmed.chars().all(|c| c.is_alphanumeric())
}

