#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MyPokemonItem {
    pub nickname: String,
    pub nature: String,
    pub is_shiny: bool,
    pub is_hatched: bool,
    pub is_chibi: bool,
    pub detail: Option<String>,
}

pub fn format_mypokemon_text(
    items: &[MyPokemonItem],
    page: usize,
    page_size: usize,
    total: usize,
    sort_option: SortOption,
    sort_direction: SortDirection,
    display_option: DisplayOption,
    show_numbering: bool,
) -> String {
    let start_idx = (page - 1) * page_size + 1;
    let mut lines = Vec::new();

    for (i, item) in items.iter().enumerate() {
        let idx = start_idx + i;
        let formatted_name = format_pokemon_name(&item.nickname);
        let is_egg = item.is_hatched || item.nickname.trim().eq_ignore_ascii_case("egg");
        let is_chibi = item.is_chibi || item.nickname.to_lowercase().starts_with("chibi ");
        let chibi_prefix = if is_chibi {
            format!("{} ", CHIBI_EMOJI)
        } else {
            String::new()
        };
        let name_display = if item.is_shiny {
            if is_egg {
                format!("{}{} {} <b>{}</b>", chibi_prefix, SHINY_EMOJI, crate::emoji::get_egg_emoji(true), escape_html(&formatted_name))
            } else {
                format!("{}{} <b>{}</b>", chibi_prefix, SHINY_EMOJI, escape_html(&formatted_name))
            }
        } else if is_egg {
            format!("{}{} <b>{}</b>", chibi_prefix, crate::emoji::get_egg_emoji(true), escape_html(&formatted_name))
        } else {
            format!("{}<b>{}</b>", chibi_prefix, escape_html(&formatted_name))
        };

        let detail_opt = if display_option == DisplayOption::None {
            None
        } else {
            item.detail.as_deref().or(Some(&item.nature))
        };

        let line_content = match detail_opt {
            Some(d) => format!("{} - {}", name_display, escape_html(d)),
            None => name_display,
        };

        if show_numbering {
            lines.push(format!("{}. {}", idx, line_content));
        } else {
            lines.push(line_content);
        }
    }

    format!(
        "{}\n\nTotal Pokemon: {}\n/sort by: {} {}\n/display: {}\n/pagesize: {}",
        lines.join("\n"),
        total,
        sort_option.display_name(),
        sort_direction.arrow(),
        display_option.display_name(),
        page_size
    )
}

pub fn build_mypokemon_keyboard(
    owner_id: u64,
    current_page: usize,
    total_pages: usize,
) -> InlineKeyboardMarkup {
    let prev_page = if current_page > 1 { current_page - 1 } else { 1 };
    let next_page = if current_page < total_pages { current_page + 1 } else { total_pages };

    let row1 = vec![
        InlineKeyboardButton::callback("←", format!("mypkmn:{}:{}", owner_id, prev_page)),
        InlineKeyboardButton::callback(format!("{}/{}", current_page, total_pages), "noop"),
        InlineKeyboardButton::callback("→", format!("mypkmn:{}:{}", owner_id, next_page)),
    ];

    let mut rows = vec![row1];

    if total_pages >= 5 {
        let minus_5 = current_page.saturating_sub(5).max(1);
        let plus_5 = (current_page + 5).min(total_pages);
        rows.push(vec![
            InlineKeyboardButton::callback("(-5) ←", format!("mypkmn:{}:{}", owner_id, minus_5)),
            InlineKeyboardButton::callback("→ (+5)", format!("mypkmn:{}:{}", owner_id, plus_5)),
        ]);
    }

    if total_pages >= 10 {
        let minus_10 = current_page.saturating_sub(10).max(1);
        let plus_10 = (current_page + 10).min(total_pages);
        rows.push(vec![
            InlineKeyboardButton::callback("(-10) ←", format!("mypkmn:{}:{}", owner_id, minus_10)),
            InlineKeyboardButton::callback("→ (+10)", format!("mypkmn:{}:{}", owner_id, plus_10)),
        ]);
    }

    if total_pages >= 20 {
        let minus_20 = current_page.saturating_sub(20).max(1);
        let plus_20 = (current_page + 20).min(total_pages);
        rows.push(vec![
            InlineKeyboardButton::callback("(-20) ←", format!("mypkmn:{}:{}", owner_id, minus_20)),
            InlineKeyboardButton::callback("→ (+20)", format!("mypkmn:{}:{}", owner_id, plus_20)),
        ]);
    }

    if total_pages >= 30 {
        let minus_30 = current_page.saturating_sub(30).max(1);
        let plus_30 = (current_page + 30).min(total_pages);
        rows.push(vec![
            InlineKeyboardButton::callback("(-30) ←", format!("mypkmn:{}:{}", owner_id, minus_30)),
            InlineKeyboardButton::callback("→ (+30)", format!("mypkmn:{}:{}", owner_id, plus_30)),
        ]);
    }

    InlineKeyboardMarkup::new(rows)
}

