pub fn format_viewshiny_text(
    items: &[MyPokemonItem],
    page: usize,
    page_size: usize,
    total: usize,
    total_pages: usize,
    sort_option: SortOption,
    sort_direction: SortDirection,
    display_option: DisplayOption,
    show_numbering: bool,
) -> String {
    let start_idx = (page - 1) * page_size + 1;
    let mut lines = Vec::new();

    for (i, item) in items.iter().enumerate() {
        let idx = start_idx + i;
        let formatted_name = format_pokemon_name(&item.nickname);
        let is_egg = item.is_hatched || item.nickname.trim().eq_ignore_ascii_case("egg");
        let is_chibi = item.is_chibi || item.nickname.to_lowercase().starts_with("chibi ");
        let chibi_prefix = if is_chibi {
            format!("{} ", CHIBI_EMOJI)
        } else {
            String::new()
        };
        let shiny_icon = crate::emoji::get_shiny_emoji(true);
        let name_display = if is_egg {
            format!("{}{} {} <b>{}</b>", chibi_prefix, shiny_icon, crate::emoji::get_egg_emoji(true), escape_html(&formatted_name))
        } else {
            format!("{}{} <b>{}</b>", chibi_prefix, shiny_icon, escape_html(&formatted_name))
        };

        let detail_opt = if display_option == DisplayOption::None {
            None
        } else {
            item.detail.as_deref().or(Some(&item.nature))
        };

        let line_content = match detail_opt {
            Some(d) => format!("{} - {}", name_display, escape_html(d)),
            None => name_display,
        };

        if show_numbering {
            lines.push(format!("{}. {}", idx, line_content));
        } else {
            lines.push(line_content);
        }
    }

    let sort_arrow = match sort_direction {
        SortDirection::Ascending => "▲",
        SortDirection::Descending => "▼",
    };

    format!(
        "<blockquote>{} <b>Your Shiny Pokémon:</b></blockquote>\n\n{}\n\n<b>Total:</b> {} | <b>Page:</b> {}/{}\n<b>Sort:</b> {} {} | <b>Display:</b> {}",
        crate::emoji::get_shiny_emoji(true),
        lines.join("\n"),
        total,
        page,
        total_pages,
        sort_option.display_name(),
        sort_arrow,
        display_option.display_name()
    )
}

