pub fn format_pokedexall_text(
    entries: &[&PokemonEntry],
    start_number: usize,
    caught_set: &HashSet<u32>,
    seen_set: &HashSet<u32>,
) -> String {
    let mut lines = Vec::with_capacity(entries.len());
    for (idx, p) in entries.iter().enumerate() {
        let num = start_number + idx;
        let is_caught = caught_set.contains(&p.id);
        let is_seen = is_caught || seen_set.contains(&p.id);

        if is_caught {
            lines.push(format!("{}. {} ☆", num, format_pokemon_name(&p.name)));
        } else if is_seen {
            lines.push(format!("{}. {}", num, format_pokemon_name(&p.name)));
        } else {
            lines.push(format!("{}. ???", num));
        }
    }
    lines.join("\n")
}

pub async fn get_pokedexall_page_data(
    pool: &SqlitePool,
    pokedex: &PokedexData,
    user_id: u64,
    target_page: usize,
) -> Result<Option<(String, InlineKeyboardMarkup, usize, usize)>, sqlx::Error> {
    let all_entries = pokedex.get_ordered_pokedex_entries();
    let total_entries = all_entries.len();
    if total_entries == 0 {
        return Ok(None);
    }

    let total_pages = (total_entries + POKEDEXALL_PAGE_SIZE - 1) / POKEDEXALL_PAGE_SIZE;
    let clamped_page = target_page.clamp(1, total_pages);

    let caught_rows: Vec<i64> = sqlx::query_scalar(
        "SELECT DISTINCT pokemon_id FROM pokemons WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_all(pool)
    .await?;
    let caught_set: HashSet<u32> = caught_rows.into_iter().map(|id| id as u32).collect();

    let seen_rows: Vec<i64> = sqlx::query_scalar(
        "SELECT DISTINCT pokemon_id FROM user_seen_pokemon WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_all(pool)
    .await?;
    let seen_set: HashSet<u32> = seen_rows.into_iter().map(|id| id as u32).collect();

    let start_idx = (clamped_page - 1) * POKEDEXALL_PAGE_SIZE;
    let end_idx = (start_idx + POKEDEXALL_PAGE_SIZE).min(total_entries);
    let page_entries = &all_entries[start_idx..end_idx];
    let start_number = start_idx + 1;

    let text = format_pokedexall_text(page_entries, start_number, &caught_set, &seen_set);
    let kb = build_pokedexall_keyboard(user_id, clamped_page, total_pages);

    Ok(Some((text, kb, clamped_page, total_pages)))
}

