#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum SortOption {
    OrderCaught = 1,
    PokedexNumber = 2,
    Level = 3,
    IvPoints = 4,
    EvPoints = 5,
    Name = 6,
    Nature = 7,
    Type = 8,
    CatchRate = 9,
    HpPoints = 10,
    AttackPoints = 11,
    DefensePoints = 12,
    SpAttackPoints = 13,
    SpDefensePoints = 14,
    SpeedPoints = 15,
    TotalStatsPoints = 16,
}

impl SortOption {
    pub const ALL: [SortOption; 16] = [
        SortOption::OrderCaught,
        SortOption::PokedexNumber,
        SortOption::Level,
        SortOption::IvPoints,
        SortOption::EvPoints,
        SortOption::Name,
        SortOption::Nature,
        SortOption::Type,
        SortOption::CatchRate,
        SortOption::HpPoints,
        SortOption::AttackPoints,
        SortOption::DefensePoints,
        SortOption::SpAttackPoints,
        SortOption::SpDefensePoints,
        SortOption::SpeedPoints,
        SortOption::TotalStatsPoints,
    ];

    pub fn from_number(n: u8) -> Option<Self> {
        match n {
            1 => Some(SortOption::OrderCaught),
            2 => Some(SortOption::PokedexNumber),
            3 => Some(SortOption::Level),
            4 => Some(SortOption::IvPoints),
            5 => Some(SortOption::EvPoints),
            6 => Some(SortOption::Name),
            7 => Some(SortOption::Nature),
            8 => Some(SortOption::Type),
            9 => Some(SortOption::CatchRate),
            10 => Some(SortOption::HpPoints),
            11 => Some(SortOption::AttackPoints),
            12 => Some(SortOption::DefensePoints),
            13 => Some(SortOption::SpAttackPoints),
            14 => Some(SortOption::SpDefensePoints),
            15 => Some(SortOption::SpeedPoints),
            16 => Some(SortOption::TotalStatsPoints),
            _ => None,
        }
    }

    pub fn from_str(s: &str) -> Option<Self> {
        let clean = s.trim().to_lowercase().replace(['.', '_', '-'], " ");
        let words: Vec<&str> = clean.split_whitespace().collect();
        let joined = words.join(" ");

        if let Ok(num) = joined.parse::<u8>() {
            return Self::from_number(num);
        }

        match joined.as_str() {
            "order" | "order caught" | "caught" | "date" | "time" | "id" => Some(SortOption::OrderCaught),
            "pokedex" | "pokedex number" | "dex" | "num" | "number" => Some(SortOption::PokedexNumber),
            "level" | "lvl" => Some(SortOption::Level),
            "iv" | "ivs" | "iv points" => Some(SortOption::IvPoints),
            "ev" | "evs" | "ev points" => Some(SortOption::EvPoints),
            "name" | "pokemon" | "alphabetical" => Some(SortOption::Name),
            "nature" => Some(SortOption::Nature),
            "type" => Some(SortOption::Type),
            "catch rate" | "rate" | "catch" => Some(SortOption::CatchRate),
            "hp" | "hp points" => Some(SortOption::HpPoints),
            "attack" | "attack points" | "atk" => Some(SortOption::AttackPoints),
            "defense" | "defense points" | "def" => Some(SortOption::DefensePoints),
            "sp attack" | "sp attack points" | "spa" | "special attack" => Some(SortOption::SpAttackPoints),
            "sp defense" | "sp defense points" | "spd" | "special defense" => Some(SortOption::SpDefensePoints),
            "speed" | "speed points" | "spe" => Some(SortOption::SpeedPoints),
            "total" | "total stats" | "total stats points" | "stats" | "stat" | "bst" => Some(SortOption::TotalStatsPoints),
            _ => None,
        }
    }

    pub fn display_name(&self) -> &'static str {
        match self {
            SortOption::OrderCaught => "Order caught",
            SortOption::PokedexNumber => "Pokedex number",
            SortOption::Level => "Level",
            SortOption::IvPoints => "IV points",
            SortOption::EvPoints => "EV points",
            SortOption::Name => "Name",
            SortOption::Nature => "Nature",
            SortOption::Type => "Type",
            SortOption::CatchRate => "Catch rate",
            SortOption::HpPoints => "HP points",
            SortOption::AttackPoints => "Attack points",
            SortOption::DefensePoints => "Defense points",
            SortOption::SpAttackPoints => "Sp. Attack points",
            SortOption::SpDefensePoints => "Sp. Defense points",
            SortOption::SpeedPoints => "Speed points",
            SortOption::TotalStatsPoints => "Total stats points",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortDirection {
    Ascending,
    Descending,
}

impl SortDirection {
    pub fn display_name(&self) -> &'static str {
        match self {
            SortDirection::Ascending => "Ascending",
            SortDirection::Descending => "Descending",
        }
    }

    pub fn arrow(&self) -> &'static str {
        match self {
            SortDirection::Ascending => "↑",
            SortDirection::Descending => "↓",
        }
    }

    pub fn toggle(&self) -> Self {
        match self {
            SortDirection::Ascending => SortDirection::Descending,
            SortDirection::Descending => SortDirection::Ascending,
        }
    }

    pub fn from_str(s: &str) -> Option<Self> {
        match s.trim().to_lowercase().as_str() {
            "asc" | "ascending" | "up" | "↑" => Some(SortDirection::Ascending),
            "desc" | "descending" | "down" | "↓" => Some(SortDirection::Descending),
            _ => None,
        }
    }
}

