async fn handle_text_message(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    pending_nicknames: PendingNicknames,
    working_teams: WorkingTeams,
    pending_team_actions: PendingTeamActions,
) -> ResponseResult<()> {
    let Some(user) = msg.from.as_ref() else {
        return Ok(());
    };
    let user_id = user.id.0;

    let pending_team_opt = {
        let lock = pending_team_actions.read().await;
        lock.get(&user_id).cloned()
    };

    if let Some(pending_team) = pending_team_opt {
        let Some(text) = msg.text() else {
            return Ok(());
        };
        let input = text.trim();

        if input.eq_ignore_ascii_case("/cancel") {
            pending_team_actions.write().await.remove(&user_id);
            bot.send_message(msg.chat.id, "Add Pokémon cancelled.")
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            return Ok(());
        }

        let mut matched_db_id: Option<(i64, String)> = None;

        if let Ok(num) = input.parse::<i64>() {
            let row = sqlx::query(
                "SELECT id, nickname FROM pokemons WHERE user_id = ? AND pokemon_id = ? ORDER BY id ASC LIMIT 1"
            )
            .bind(user_id as i64)
            .bind(num)
            .fetch_optional(&*pool)
            .await
            .ok()
            .flatten();

            if let Some(r) = row {
                let id: i64 = r.get("id");
                let nick: String = r.get("nickname");
                matched_db_id = Some((id, nick));
            } else {
                let all_owned = sqlx::query(
                    "SELECT id, nickname FROM pokemons WHERE user_id = ? ORDER BY id ASC"
                )
                .bind(user_id as i64)
                .fetch_all(&*pool)
                .await
                .unwrap_or_default();

                if num >= 1 && (num as usize) <= all_owned.len() {
                    let r = &all_owned[(num - 1) as usize];
                    let id: i64 = r.get("id");
                    let nick: String = r.get("nickname");
                    matched_db_id = Some((id, nick));
                } else {
                    let by_id = sqlx::query(
                        "SELECT id, nickname FROM pokemons WHERE user_id = ? AND id = ?"
                    )
                    .bind(user_id as i64)
                    .bind(num)
                    .fetch_optional(&*pool)
                    .await
                    .ok()
                    .flatten();
                    if let Some(r) = by_id {
                        let id: i64 = r.get("id");
                        let nick: String = r.get("nickname");
                        matched_db_id = Some((id, nick));
                    }
                }
            }
        } else {
            let rows = match fetch_matching_owned_pokemons(&pool, user_id, input, &pokedex).await {
                Ok(r) => r,
                Err(e) => {
                    tracing::warn!("Error fetching owned pokemons for team add: {}", e);
                    Vec::new()
                }
            };

            if rows.len() == 1 {
                let r = &rows[0];
                let id: i64 = r.get("id");
                let nick: String = r.get("nickname");
                matched_db_id = Some((id, nick));
            } else if rows.len() > 1 {
                let (display_option, _) = get_user_display_settings(&pool, user_id).await;
                let (prompt, kb) = format_disambiguation_list(
                    &rows,
                    "Add which pokemon?",
                    &format!("team_add_sel_{}:", pending_team.editor_message_id),
                    &pokedex,
                    display_option,
                );
                bot.send_message(msg.chat.id, prompt)
                    .parse_mode(ParseMode::Html)
                    .reply_markup(kb)
                    .reply_parameters(ReplyParameters::new(msg.id))
                    .await?;
                return Ok(());
            }
        }

        match matched_db_id {
            Some((db_id, nick)) => {
                let mut wt = working_teams.write().await;
                let team = wt.entry(user_id).or_default();
                if team.contains(&db_id) {
                    bot.send_message(
                        msg.chat.id,
                        format!("<b>{}</b> is already in your team!", escape_html(&format_pokemon_name(&nick))),
                    )
                    .parse_mode(ParseMode::Html)
                    .reply_parameters(ReplyParameters::new(msg.id))
                    .await?;
                    return Ok(());
                }
                if team.len() >= 6 {
                    bot.send_message(
                        msg.chat.id,
                        "Your team is already full! Remove a Pokémon first.",
                    )
                    .reply_parameters(ReplyParameters::new(msg.id))
                    .await?;
                    return Ok(());
                }

                team.push(db_id);
                let current_team = team.clone();
                drop(wt);

                pending_team_actions.write().await.remove(&user_id);

                let names = get_pokemon_names_for_ids(&pool, user_id, &current_team, &pokedex).await;
                let slot_lines = format_slots_lines(&names);
                let text = format_team_editor_text(&slot_lines);
                let kb = build_team_editor_keyboard(user_id);
                let _ = safe_edit_text(&bot, ChatId(pending_team.chat_id), MessageId(pending_team.editor_message_id), text, kb).await;

                bot.send_message(
                    msg.chat.id,
                    format!("Added <b>{}</b> to team editor.", escape_html(&format_pokemon_name(&nick))),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }
            None => {
                bot.send_message(
                    msg.chat.id,
                    format!("You do not have a Pokémon matching '<b>{}</b>'.\nPlease try again or send /cancel to cancel:", escape_html(input)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .reply_markup(ForceReply::new())
                .await?;
                return Ok(());
            }
        }
    }

    let raw_text_opt = msg.text().map(|s| s.to_string());
    if let Some(text) = raw_text_opt {
        let trimmed = text.trim();
        let lower = trimmed.to_lowercase();
        let cmd_token = lower.split_whitespace().next().unwrap_or("");
        let base_cmd = cmd_token.split('@').next().unwrap_or("");
        if base_cmd == "/tms" {
            let _ = handle_tm(bot, msg, pool, String::new()).await;
            return Ok(());
        } else if base_cmd == "/tutors" {
            let _ = handle_tutor(bot, msg, pool, String::new()).await;
            return Ok(());
        } else if base_cmd.starts_with("/tm") && base_cmd[3..].chars().all(|c| c.is_ascii_digit()) && base_cmd.len() > 3 {
            let num_str = base_cmd[3..].to_string();
            let _ = handle_tm(bot, msg, pool, num_str).await;
            return Ok(());
        } else if base_cmd.starts_with("/tutor") && base_cmd[6..].chars().all(|c| c.is_ascii_digit()) && base_cmd.len() > 6 {
            let num_str = base_cmd[6..].to_string();
            let _ = handle_tutor(bot, msg, pool, num_str).await;
            return Ok(());
        }
    }

    let pending_opt = {
        let lock = pending_nicknames.read().await;
        lock.get(&user_id).cloned()
    };

    let Some(pending) = pending_opt else {
        return Ok(());
    };

    let Some(text) = msg.text() else {
        return Ok(());
    };

    let proposed_nick = text.trim();

    if proposed_nick.eq_ignore_ascii_case("/cancel") {
        pending_nicknames.write().await.remove(&user_id);
        bot.send_message(msg.chat.id, "Nickname change cancelled.")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    if !is_valid_nickname(proposed_nick) {
        bot.send_message(
            msg.chat.id,
            "Nicknames can contain letters and numbers only (max 20 characters).\nPlease type a valid nickname:",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .reply_markup(ForceReply::new())
        .await?;
        return Ok(());
    }

    let update_res = sqlx::query(
        "UPDATE pokemons SET nickname = ? WHERE id = ? AND user_id = ?"
    )
    .bind(proposed_nick)
    .bind(pending.pokemon_db_id)
    .bind(user_id as i64)
    .execute(&*pool)
    .await;

    match update_res {
        Ok(_) => {
            pending_nicknames.write().await.remove(&user_id);
            bot.send_message(
                msg.chat.id,
                format!(
                    "Nickname successfully changed to <b>{}</b>!",
                    escape_html(proposed_nick)
                ),
            )
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        }
        Err(e) => {
            tracing::error!("Failed to update nickname in database: {}", e);
            bot.send_message(
                msg.chat.id,
                "Failed to update nickname due to a database error. Please try again later.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        }
    }

    Ok(())
}

async fn handle_travel(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    target: String,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    if is_user_in_battle(user_id).await {
        bot.send_message(msg.chat.id, "You can't travel while battling")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    // Ensure user row exists with defaults
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let user_row = sqlx::query("SELECT current_region, unlocked_regions, trainer_level FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let (current_region, unlocked_regions) = if let Ok(Some(row)) = user_row {
        let cr: String = row
            .try_get("current_region")
            .unwrap_or_else(|_| "Kanto".to_string());
        let ur: String = row
            .try_get("unlocked_regions")
            .unwrap_or_else(|_| "Kanto".to_string());
        let t_lvl: i32 = row
            .try_get("trainer_level")
            .unwrap_or(0);
        let level_csv = get_unlocked_regions_csv_for_level(t_lvl.max(0) as u32);
        let mut set: Vec<String> = ur.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
        let mut changed = false;
        for reg in level_csv.split(',') {
            if !set.iter().any(|r| r.eq_ignore_ascii_case(reg)) {
                set.push(reg.to_string());
                changed = true;
            }
        }
        let final_ur = if changed {
            let merged = set.join(",");
            let _ = sqlx::query("UPDATE users SET unlocked_regions = ? WHERE id = ?")
                .bind(&merged)
                .bind(user_id as i64)
                .execute(&*pool)
                .await;
            merged
        } else {
            ur
        };
        (cr, final_ur)
    } else {
        ("Kanto".to_string(), "Kanto".to_string())
    };

    let target_trim = target.trim();
    if target_trim.is_empty() {
        let text = format_travel_message(&current_region, &unlocked_regions);
        let keyboard = travel_keyboard(&unlocked_regions);

        bot.send_message(msg.chat.id, text)
            .parse_mode(ParseMode::Html)
            .reply_markup(keyboard)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    // Direct travel argument, e.g. /travel kanto, /travel 1, /travel hoenn, /travel 3, etc.
    let dest_region = match find_region(target_trim) {
        Some(r) => r,
        None => {
            let available_list = ALL_REGIONS
                .iter()
                .map(|r| format!("{}. {}", r.id, r.name))
                .collect::<Vec<_>>()
                .join("\n");
            bot.send_message(
                msg.chat.id,
                format!("Unknown region. Available regions:\n{}", available_list),
            )
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    };
    let dest = dest_region.name;

    if dest == current_region {
        bot.send_message(
            msg.chat.id,
            format!("You are already in <b>{}</b>!", dest),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let is_unlocked = unlocked_regions
        .split(',')
        .any(|r| r.trim().eq_ignore_ascii_case(dest));

    if !is_unlocked {
        bot.send_message(
            msg.chat.id,
            format!("Rank up to unlock {}!", dest),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let _ = sqlx::query("UPDATE users SET current_region = ? WHERE id = ?")
        .bind(dest)
        .bind(user_id as i64)
        .execute(&*pool)
        .await;

    bot.send_message(
        msg.chat.id,
        format!("You have traveled to <b>{}</b>!", dest),
    )
    .parse_mode(ParseMode::Html)
    .reply_parameters(ReplyParameters::new(msg.id))
    .await?;

    Ok(())
}

async fn handle_safari(bot: Bot, msg: Message) -> ResponseResult<()> {
    if !msg.chat.is_private() {
        let kb = build_dm_redirect_kb("safari", "Safari in DM");
        bot.send_message(msg.chat.id, "You can only play Safari in DMs")
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let user_id = msg.from.as_ref().map(|u| u.id.0).unwrap_or(0);
    if is_user_in_battle(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while battling")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_challenge(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while in a challenge")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_trade(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while trading")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let text = "Hunt for rare Pokémon in the Safari Zone\n\n\
<u>Instructions</u>\n\
• /travel to the Region where you want to play the Safari Game.\n\
• You will be given 45 Safari Balls (×2 catch rate multiplier) to catch Pokémon with. No other Poké Balls will be allowed.\n\
• You will have a 150 /hunt limit.\n\
• You cannot battle any of the wild Pokémon, you must only throw Safari Balls.\n\
• When you run out of Safari Balls, you will automatically be kicked out of the Safari Zone.\n\
• When you reach the /hunt limit, you will automatically be kicked out of the Safari Zone.\n\n\
Entry fee: 150 💵\n\
/enter to enter the Safari Zone\n\
/exit to manually exit the Safari Zone\n\n\
Note: if you choose to exit the Safari Zone, you will not be given a refund, and you cannot keep any Safari Balls.\n\
Max 1 play per day.\n\
<b>You are not guaranteed to capture a Pokémon in the Safari Zone.</b>";

    bot.send_message(msg.chat.id, text)
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

async fn handle_enter(bot: Bot, msg: Message, pool: Arc<SqlitePool>) -> ResponseResult<()> {
    if !msg.chat.is_private() {
        let kb = build_dm_redirect_kb("safari", "Safari in DM");
        bot.send_message(msg.chat.id, "You can only play Safari in DMs")
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    if is_user_in_battle(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while battling")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_challenge(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while in a challenge")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_trade(user_id).await {
        bot.send_message(msg.chat.id, "You can't safari while trading")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username.as_deref())
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let safari_status: Option<(i32, String)> = sqlx::query_as(
        "SELECT is_active, last_played_date FROM user_safari WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await
    .unwrap_or(None);

    let today = chrono::Utc::now().format("%Y-%m-%d").to_string();

    let is_evtrain_active: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM user_evtrain WHERE user_id = ? AND is_active = 1)"
    )
    .bind(user_id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(false);

    if is_evtrain_active {
        bot.send_message(
            msg.chat.id,
            "You are currently EV Training! Use /exit to leave before entering the Safari Zone.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if let Some((is_active, last_played_date)) = &safari_status {
        if *is_active == 1 {
            bot.send_message(
                msg.chat.id,
                "You are already in the Safari Zone! Use /hunt to find Pokémon or /exit to leave.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }

        if last_played_date == &today {
            bot.send_message(
                msg.chat.id,
                "Max 1 play per day. You have already entered the Safari Zone today. Come back tomorrow!",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    }

    let pokedollars: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_one(&*pool)
        .await
        .unwrap_or(0);

    if pokedollars < 150 {
        bot.send_message(
            msg.chat.id,
            "You do not have enough PokéDollars! Entry fee is 150 💵.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let _ = sqlx::query("UPDATE users SET pokedollars = pokedollars - 150 WHERE id = ?")
        .bind(user_id as i64)
        .execute(&*pool)
        .await;

    let current_region: String = sqlx::query_scalar("SELECT current_region FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| "Kanto".to_string());

    let _ = sqlx::query(
        "INSERT INTO user_safari (user_id, is_active, balls_remaining, hunts_used, region, last_played_date)
         VALUES (?, 1, 45, 0, ?, ?)
         ON CONFLICT(user_id) DO UPDATE SET
            is_active = 1,
            balls_remaining = 45,
            hunts_used = 0,
            region = excluded.region,
            last_played_date = excluded.last_played_date",
    )
    .bind(user_id as i64)
    .bind(&current_region)
    .bind(&today)
    .execute(&*pool)
    .await;

    let text = format!(
        "Welcome to the <b>{}</b> Safari Zone\nEntry fee deducted: 150 💵\n\nBegin your /hunt for rare Pokémon",
        escape_html(&current_region)
    );

    bot.send_message(msg.chat.id, text)
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

async fn handle_exit(bot: Bot, msg: Message, pool: Arc<SqlitePool>) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    let is_evtrain: Option<i32> = sqlx::query_scalar(
        "SELECT is_active FROM user_evtrain WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await
    .unwrap_or(None);

    if is_evtrain == Some(1) {
        let _ = sqlx::query("UPDATE user_evtrain SET is_active = 0 WHERE user_id = ?")
            .bind(user_id as i64)
            .execute(&*pool)
            .await;

        bot.send_message(msg.chat.id, "You have left EV Training.")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let is_active: Option<i32> = sqlx::query_scalar(
        "SELECT is_active FROM user_safari WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await
    .unwrap_or(None);

    if is_active != Some(1) {
        bot.send_message(msg.chat.id, "You are not currently in the Safari Zone or EV Training.")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let _ = sqlx::query("UPDATE user_safari SET is_active = 0, balls_remaining = 0 WHERE user_id = ?")
        .bind(user_id as i64)
        .execute(&*pool)
        .await;

    bot.send_message(
        msg.chat.id,
        "You have left the Safari Zone. Any remaining Safari Balls were returned.",
    )
    .reply_parameters(ReplyParameters::new(msg.id))
    .await?;

    Ok(())
}

pub async fn clear_user_stuck_states(
    pool: &SqlitePool,
    user_id: u64,
    battles: &BattleSessions,
    challenges: &ChallengeSessions,
    trades: &TradeSessions,
    pending_nicknames: &PendingNicknames,
    working_teams: &WorkingTeams,
    pending_team_actions: &PendingTeamActions,
    card_sessions: &CardSessions,
) {
    if user_id == 0 {
        return;
    }

    // 1. In-memory wild battle & gym battle session
    battles.write().await.remove(&user_id);

    // 2. In-memory challenge / PvP session
    challenges.write().await.retain(|_, ch| {
        ch.challenger_id != user_id && ch.opponent_id != Some(user_id)
    });

    // 3. In-memory trade session
    trades.write().await.retain(|_, tr| {
        tr.sender_id != user_id && tr.target_id != user_id
    });

    // 4. In-memory pending nicknames, team editing, and team actions
    pending_nicknames.write().await.remove(&user_id);
    working_teams.write().await.remove(&user_id);
    pending_team_actions.write().await.remove(&user_id);

    // 5. In-memory trainer card customization session
    card_sessions.write().await.remove(&user_id);

    // 6. Database states: safari, evtrain & active hunt
    let _ = sqlx::query("UPDATE user_safari SET is_active = 0, balls_remaining = 0 WHERE user_id = ?")
        .bind(user_id as i64)
        .execute(pool)
        .await;

    let _ = sqlx::query("UPDATE user_evtrain SET is_active = 0 WHERE user_id = ?")
        .bind(user_id as i64)
        .execute(pool)
        .await;

    let _ = sqlx::query("DELETE FROM active_hunts WHERE user_id = ?")
        .bind(user_id as i64)
        .execute(pool)
        .await;
}

async fn handle_cexit(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    battles: BattleSessions,
    trades: TradeSessions,
    pending_nicknames: PendingNicknames,
    working_teams: WorkingTeams,
) -> ResponseResult<()> {
    let user_id = msg.from.as_ref().map(|u| u.id.0).unwrap_or(0);
    if user_id == 0 {
        return Ok(());
    }

    let challenges = get_challenges();
    let card_sessions = get_card_sessions();
    let pending_team_actions = get_pending_team_actions();

    clear_user_stuck_states(
        &pool,
        user_id,
        &battles,
        &challenges,
        &trades,
        &pending_nicknames,
        &working_teams,
        &pending_team_actions,
        &card_sessions,
    )
    .await;

    bot.send_message(msg.chat.id, "Exited successfully!")
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

