pub fn format_referrals_message(
    completed_count: i64,
    pending_count: i64,
    ref_link: Option<&str>,
) -> String {
    let link_section = if let Some(link) = ref_link {
        format!("\n\n<code>{}</code>", link)
    } else {
        String::new()
    };

    format!(
        "Total referrals: {}\n\nSend the link below to new players and receive a bonus of 100 💵 for every invited player that reaches <b>Rank 3</b>{}\n\nAlso:\n• After every 3 invites, you will receive a mix of different poke balls\n• After every 7 invites, you will receive a TM 💿 and 1000 💵\n• After every 12 invites, you will receive 1 Master Ball and 1 Key Item\n\n<i>Waiting to reach Rank 3: {}</i>",
        completed_count,
        link_section,
        pending_count
    )
}

pub fn build_referrals_initial_kb(user_id: u64) -> InlineKeyboardMarkup {
    InlineKeyboardMarkup::new(vec![vec![
        InlineKeyboardButton::callback("Generate my link", format!("gen_ref_link:{}", user_id)),
    ]])
}

pub fn build_referrals_generated_kb(user_id: u64, ref_link: &str) -> InlineKeyboardMarkup {
    let share_url_str = format!(
        "https://t.me/share/url?url={}&text=Join%20me%20on%20Ozone%20Pokemon!",
        ref_link
    );
    let share_button = if let Ok(u) = Url::parse(&share_url_str) {
        InlineKeyboardButton::url("Share link", u)
    } else {
        InlineKeyboardButton::callback("Share link", "noop")
    };

    InlineKeyboardMarkup::new(vec![
        vec![share_button],
        vec![InlineKeyboardButton::callback("Refresh", format!("ref_refresh:{}", user_id))],
    ])
}

async fn handle_referrals(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);
    if user_id == 0 {
        return Ok(());
    }

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    // Ensure user row exists so referrer is a valid registered player
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let completed_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ? AND status = 'completed'",
    )
    .bind(user_id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(0);

    let pending_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ? AND status = 'pending'",
    )
    .bind(user_id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(0);

    let message_text = format_referrals_message(completed_count, pending_count, None);
    let keyboard = build_referrals_initial_kb(user_id);

    bot.send_message(msg.chat.id, message_text)
        .parse_mode(ParseMode::Html)
        .reply_markup(keyboard)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

pub async fn register_referral_if_eligible(
    pool: &SqlitePool,
    referred_id: u64,
    referrer_id: u64,
    referred_username: Option<&str>,
    referred_first_name: &str,
) -> bool {
    // 1. Cannot refer self or invalid ID
    if referred_id == 0 || referrer_id == 0 || referred_id == referrer_id {
        return false;
    }

    // 2. Referrer must exist in users table
    let referrer_exists: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM users WHERE id = ?)",
    )
    .bind(referrer_id as i64)
    .fetch_one(pool)
    .await
    .unwrap_or(false);

    if !referrer_exists {
        return false;
    }

    // 3. User must not have already picked a starter
    let already_started: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM users WHERE id = ? AND starter_id IS NOT NULL)",
    )
    .bind(referred_id as i64)
    .fetch_one(pool)
    .await
    .unwrap_or(false);

    if already_started {
        return false;
    }

    // 4. User must not have already been referred
    let already_referred: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM referrals WHERE referred_id = ?)",
    )
    .bind(referred_id as i64)
    .fetch_one(pool)
    .await
    .unwrap_or(false);

    if already_referred {
        return false;
    }

    // 5. Insert pending referral
    let res = sqlx::query(
        "INSERT INTO referrals (referrer_id, referred_id, referred_username, referred_first_name, status)
         VALUES (?, ?, ?, ?, 'pending')
         ON CONFLICT(referred_id) DO NOTHING",
    )
    .bind(referrer_id as i64)
    .bind(referred_id as i64)
    .bind(referred_username)
    .bind(referred_first_name)
    .execute(pool)
    .await;

    matches!(res, Ok(r) if r.rows_affected() > 0)
}

pub async fn process_referral_rank_up(
    pool: &SqlitePool,
    referred_id: i64,
) -> Result<(), sqlx::Error> {
    // Check if table referrals exists first (avoids errors in partial in-memory test databases)
    let table_exists: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='referrals')",
    )
    .fetch_one(pool)
    .await
    .unwrap_or(false);

    if !table_exists {
        return Ok(());
    }

    let ref_row = sqlx::query(
        "SELECT referrer_id FROM referrals WHERE referred_id = ? AND status = 'pending'",
    )
    .bind(referred_id)
    .fetch_optional(pool)
    .await?;

    let Some(row) = ref_row else {
        return Ok(());
    };

    let referrer_id: i64 = row.get("referrer_id");

    // Mark referral as completed
    let update_res = sqlx::query(
        "UPDATE referrals SET status = 'completed' WHERE referred_id = ? AND status = 'pending'",
    )
    .bind(referred_id)
    .execute(pool)
    .await?;

    if update_res.rows_affected() == 0 {
        return Ok(());
    }

    // Award 100 PokeDollars to referrer
    let _ = sqlx::query(
        "UPDATE users SET pokedollars = pokedollars + 100 WHERE id = ?",
    )
    .bind(referrer_id)
    .execute(pool)
    .await;

    // Fetch total completed count
    let completed_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ? AND status = 'completed'",
    )
    .bind(referrer_id)
    .fetch_one(pool)
    .await
    .unwrap_or(0);

    if completed_count <= 0 {
        return Ok(());
    }

    let mut milestone_notes: Vec<&str> = Vec::new();

    // After every 3 invites, receive a mix of different poke balls
    if completed_count % 3 == 0 {
        let _ = sqlx::query(
            "UPDATE users SET ball_great = ball_great + 15, ball_ultra = ball_ultra + 10, ball_dusk = ball_dusk + 5, ball_repeat = ball_repeat + 5 WHERE id = ?",
        )
        .bind(referrer_id)
        .execute(pool)
        .await;
        milestone_notes.push("a mix of different poke balls");
    }

    // After every 7 invites, receive a TM and 1000 PokeDollars
    if completed_count % 7 == 0 {
        let _ = sqlx::query(
            "UPDATE users SET pokedollars = pokedollars + 1000 WHERE id = ?",
        )
        .bind(referrer_id)
        .execute(pool)
        .await;

        let selected_tm = {
            let mut rng = rand::thread_rng();
            TM_CATALOG.choose(&mut rng).cloned()
        };
        if let Some(tm) = selected_tm {
            let _ = sqlx::query(
                "INSERT INTO user_tms (user_id, tm_number, move_name, quantity)
                 VALUES (?, ?, ?, 1)
                 ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = quantity + 1",
            )
            .bind(referrer_id)
            .bind(tm.number as i64)
            .bind(tm.name)
            .execute(pool)
            .await;
        }
        milestone_notes.push("a TM 💿 and 1000 💵");
    }

    // After every 12 invites, receive 1 Master Ball and 1 Key Item
    if completed_count % 12 == 0 {
        let _ = sqlx::query(
            "UPDATE users SET ball_master = ball_master + 1 WHERE id = ?",
        )
        .bind(referrer_id)
        .execute(pool)
        .await;

        let selected_stone = {
            let mut rng = rand::thread_rng();
            DEFAULT_KEY_ITEMS.choose(&mut rng).map(|&(name, _)| name)
        };
        if let Some(stone_name) = selected_stone {
            let _ = sqlx::query(
                "INSERT INTO user_key_items (user_id, item_name, quantity)
                 VALUES (?, ?, 1)
                 ON CONFLICT(user_id, item_name) DO UPDATE SET quantity = quantity + 1",
            )
            .bind(referrer_id)
            .bind(stone_name)
            .execute(pool)
            .await;
        }
        milestone_notes.push("1 Master Ball and 1 Key Item");
    }

    // Notify referrer if bot instance is available
    if let Some(bot) = BOT_INSTANCE.get() {
        let bonus_detail = if milestone_notes.is_empty() {
            String::new()
        } else {
            format!("\n\nMilestone reward unlocked:\n• {}", milestone_notes.join("\n• "))
        };

        let notify_text = format!(
            "One of your invited trainers reached <b>Rank 3</b>! You received a bonus of 100 💵.{}",
            bonus_detail
        );
        let _ = bot
            .send_message(ChatId(referrer_id), notify_text)
            .parse_mode(ParseMode::Html)
            .await;
    }

    Ok(())
}

async fn handle_hstop(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
) -> ResponseResult<()> {
    let Some(from) = msg.from.as_ref() else {
        return Ok(());
    };
    let user_id = from.id.0;
    if !is_admin(user_id) {
        return Ok(());
    }

    if let Err(e) = halloween::stop_halloween_event(&pool).await {
        tracing::error!("Failed to stop halloween event: {}", e);
        let _ = bot.send_message(msg.chat.id, "Failed to stop Halloween event.").await;
        return Ok(());
    }

    let menu_commands = get_bot_menu_commands(false);
    if let Err(e) = bot.set_my_commands(menu_commands).await {
        tracing::warn!("Failed to update bot commands after stopping halloween: {}", e);
    }

    let _ = bot
        .send_message(
            msg.chat.id,
            "Halloween event stopped. Event commands and drops are disabled, and /halloween has been removed from the menu.",
        )
        .await;

    Ok(())
}

async fn handle_halloween(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
) -> ResponseResult<()> {
    if !halloween::is_halloween_enabled(&pool).await {
        return Ok(());
    }
    let Some(from) = msg.from.as_ref() else {
        return Ok(());
    };
    let user_id = from.id.0;
    let username = from.username.clone().unwrap_or_default();
    let first_name = from.first_name.clone();

    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username=excluded.username, first_name=excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(&username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let admin = is_admin(user_id);
    let (dashboard_text, dashboard_kb) = match halloween::build_halloween_dashboard(&pool, user_id, admin).await {
        Ok(res) => res,
        Err(e) => {
            tracing::error!("Failed to build halloween dashboard: {}", e);
            return Ok(());
        }
    };

    let gif_path = std::path::Path::new("assets/halloween.gif");
    let mut sent = false;
    if gif_path.exists() {
        if let Ok(_) = bot
            .send_animation(msg.chat.id, InputFile::file(gif_path))
            .caption(&dashboard_text)
            .parse_mode(ParseMode::Html)
            .reply_markup(dashboard_kb.clone())
            .await
        {
            sent = true;
        }
    }

    if !sent {
        let _ = bot
            .send_message(msg.chat.id, dashboard_text)
            .parse_mode(ParseMode::Html)
            .reply_markup(dashboard_kb)
            .await;
    }

    Ok(())
}

