async fn handle_gym(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
) -> ResponseResult<()> {
    let Some(from) = msg.from.as_ref() else {
        return Ok(());
    };
    let user_id = from.id.0 as i64;
    let username = from.username.clone().unwrap_or_default();
    let first_name = from.first_name.clone();

    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username=excluded.username, first_name=excluded.first_name",
    )
    .bind(user_id)
    .bind(&username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let photo_path = std::path::Path::new("assets/gym.jpg");
    let kb = build_gym_keyboard();
    let (globally_open, global_reason) = are_gyms_globally_open(&pool).await;
    let main_caption = if !globally_open {
        format!("{}\n\n<b>Notice:</b> {}", GYM_MAIN_CAPTION, escape_html(&global_reason))
    } else {
        GYM_MAIN_CAPTION.to_string()
    };

    if photo_path.exists() {
        bot.send_photo(msg.chat.id, InputFile::file(photo_path))
            .caption(main_caption)
            .parse_mode(ParseMode::Html)
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
    } else {
        bot.send_message(msg.chat.id, main_caption)
            .parse_mode(ParseMode::Html)
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
    }

    Ok(())
}

