pub fn format_gym_cities_caption(region_name: &str, gyms_beaten: i32) -> String {
    let cities = get_gym_cities_for_region(region_name);
    let lock_emoji = crate::emoji::get_locked_gym_emoji(true);
    let conquered_emoji = crate::emoji::get_conquered_emoji(true);

    let mut lines = Vec::new();
    lines.push("<blockquote>Which Gym will you step into? Choose your battlefield!</blockquote>\n".to_string());

    for (i, &city) in cities.iter().enumerate() {
        let gym_idx = i as i32;
        if gym_idx < gyms_beaten {
            lines.push(format!("• {} {}", city, conquered_emoji));
        } else if gym_idx == gyms_beaten {
            lines.push(format!("• {} [ Current ]", city));
        } else {
            lines.push(format!("• {} {}", city, lock_emoji));
        }
    }

    lines.join("\n")
}

