pub fn get_gym_photo_path(city_name: &str) -> String {
    let clean = city_name.to_lowercase().replace(' ', "_");
    let candidates = [
        format!("assets/gyms/{}.jpg", clean),
        format!("assets/gym_{}.jpg", clean),
        format!("assets/gyms/{}.png", clean),
        format!("assets/gym_{}.png", clean),
    ];
    for p in &candidates {
        if std::path::Path::new(p).exists() {
            return p.clone();
        }
    }
    "assets/gym.jpg".to_string()
}

