pub fn create_gym_pokemon_by_id(
    pokemon_id: u32,
    pokedex: &PokedexData,
) -> Option<BattlePokemon> {
    let entry = pokedex.get_pokemon_by_id(pokemon_id)?;

    // Exactly 186 IVs: 31 in each of the 6 stats (31 * 6 = 186)
    let iv_hp = 31;
    let iv_atk = 31;
    let iv_def = 31;
    let iv_spa = 31;
    let iv_spd = 31;
    let iv_spe = 31;

    // Exactly 510 EVs: competitive spread matching attacking style (252 + 252 + 6 = 510)
    let (nature, ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe) = if entry.stats.attack >= entry.stats.special_attack {
        let nature = if entry.stats.speed >= 70 { "Jolly" } else { "Adamant" };
        if entry.stats.speed >= 60 {
            (nature.to_string(), 6, 252, 0, 0, 0, 252)
        } else {
            (nature.to_string(), 252, 252, 6, 0, 0, 0)
        }
    } else {
        let nature = if entry.stats.speed >= 70 { "Timid" } else { "Modest" };
        if entry.stats.speed >= 60 {
            (nature.to_string(), 6, 0, 0, 252, 0, 252)
        } else {
            (nature.to_string(), 252, 0, 0, 252, 6, 0)
        }
    };

    let level = 100;
    let max_hp = calc_hp(entry.stats.hp, iv_hp, ev_hp, level as i32);

    let mut moves: Vec<MoveDetail> = pokedex
        .get_level_up_moves(pokemon_id, level)
        .into_iter()
        .cloned()
        .collect();

    if moves.is_empty() {
        moves.push(MoveDetail {
            name: "Tackle".to_string(),
            t: "Normal".to_string(),
            c: "Physical".to_string(),
            p: Some(40),
            a: Some(100),
            pp: Some(35),
            d: "A physical attack in which the user charges and slams into the target with its whole body.".to_string(),
        });
    }
    moves.truncate(4);

    Some(BattlePokemon {
        db_id: None,
        id: pokemon_id,
        name: entry.name.clone(),
        nickname: entry.name.clone(),
        level,
        types: entry.types.clone(),
        nature,
        base_stats: entry.stats.clone(),
        iv_hp,
        iv_atk,
        iv_def,
        iv_spa,
        iv_spd,
        iv_spe,
        ev_hp,
        ev_atk,
        ev_def,
        ev_spa,
        ev_spd,
        ev_spe,
        max_hp,
        current_hp: max_hp,
        moves,
        is_shiny: false,
        catch_rate: entry.catch_rate.unwrap_or(45),
        base_experience: entry.base_experience.unwrap_or(100),
        is_burned: false,
    })
}

pub fn create_gym_leader_battle_pokemon(
    leader: &GymLeaderInfo,
    pokedex: &PokedexData,
) -> Option<BattlePokemon> {
    create_gym_pokemon_by_id(leader.signature_pokemon_id, pokedex)
}

pub fn create_gym_leader_team(
    leader: &GymLeaderInfo,
    pokedex: &PokedexData,
) -> Vec<BattlePokemon> {
    let mut team = Vec::new();
    for &pid in leader.team_pokemon_ids {
        if let Some(pkmn) = create_gym_pokemon_by_id(pid, pokedex) {
            team.push(pkmn);
        }
    }
    if team.is_empty() {
        if let Some(pkmn) = create_gym_leader_battle_pokemon(leader, pokedex) {
            team.push(pkmn);
        }
    }
    team
}

pub fn format_gym_leader_caption(leader: &GymLeaderInfo) -> String {
    let type_emoji = crate::emoji::get_type_emoji(leader.poke_type, true);
    format!(
        "<blockquote><u>Gym Leader {}:</u>\n<i>\"{}\"</i></blockquote>\n\n<b>Gym Type:</b> <code>{}</code> {}\n<b>Challenge Fee:</b> <code>{}</code> PokéDollars 💵\n\nAre you sure you want to challenge <code>{}</code> ?",
        leader.name,
        leader.quote,
        leader.poke_type,
        type_emoji,
        leader.fee,
        leader.gym_name
    )
}

pub fn build_gym_leader_keyboard(region: &str, gym_num: usize) -> InlineKeyboardMarkup {
    let r = region.to_lowercase();
    InlineKeyboardMarkup::new(vec![
        vec![
            InlineKeyboardButton::callback("Rewards", format!("gym_act:rew:{}:{}", r, gym_num)),
            InlineKeyboardButton::callback("Rules", format!("gym_act:rules:{}:{}", r, gym_num)),
        ],
        vec![
            InlineKeyboardButton::callback("Battle", format!("gym_act:btl:{}:{}", r, gym_num)),
            InlineKeyboardButton::callback("Back", format!("gym_act:back:{}", r)),
        ],
    ])
}

