#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
pub struct GymRulesConfig {
    #[serde(default)]
    pub banned_types: Vec<String>,
    #[serde(default)]
    pub ban_legendaries: bool,
    #[serde(default)]
    pub ban_mythicals: bool,
    #[serde(default)]
    pub ban_ultra_beasts: bool,
    #[serde(default)]
    pub ban_paradox: bool,
    #[serde(default)]
    pub no_duplicates: bool,
    #[serde(default)]
    pub require_conscious: bool,
    #[serde(default)]
    pub max_level: Option<u32>,
}

impl GymRulesConfig {
    pub fn to_bullet_rules(&self) -> Vec<String> {
        let mut list = Vec::new();
        if !self.banned_types.is_empty() {
            let types_str = self.banned_types.join(", ");
            list.push(format!("• No {}-type Pokémon in your team!", types_str));
        }
        let mut specials = Vec::new();
        if self.ban_mythicals { specials.push("Mythical"); }
        if self.ban_legendaries { specials.push("Legendary"); }
        if self.ban_ultra_beasts { specials.push("Ultra Beast"); }
        if self.ban_paradox { specials.push("Paradox"); }
        if !specials.is_empty() {
            let specials_str = if specials.len() == 1 {
                specials[0].to_string()
            } else if specials.len() == 2 {
                format!("{} or {}", specials[0], specials[1])
            } else {
                let init = specials[..specials.len() - 1].join(", ");
                let last = specials[specials.len() - 1];
                format!("{}, or {}", init, last)
            };
            list.push(format!("• No {} Pokémon allowed!", specials_str));
        }
        if self.no_duplicates {
            list.push("• No duplicate Pokémon allowed!".to_string());
        }
        if self.require_conscious {
            list.push("• Active battle team must have at least 1 conscious Pokémon!".to_string());
        }
        if let Some(lvl) = self.max_level {
            list.push(format!("• Maximum Pokémon level allowed: Lv. {}!", lvl));
        }
        list
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
pub struct GymRewardsConfig {
    #[serde(default)]
    pub pokedollars: Option<i64>,
    #[serde(default)]
    pub badge: Option<String>,
    #[serde(default)]
    pub mega_stone: Option<String>,
    #[serde(default)]
    pub tm: Option<String>,
    #[serde(default)]
    pub egg: Option<String>,
}

impl GymRewardsConfig {
    pub fn to_bullet_rewards(&self, default_badge: &str, default_money: i64) -> Vec<String> {
        let mut list = Vec::new();
        let badge_name = self.badge.as_deref().unwrap_or(default_badge);
        if !badge_name.is_empty() {
            list.push(format!("• {}", badge_name));
        }
        let money = self.pokedollars.unwrap_or(default_money);
        if money > 0 {
            list.push(format!("• {} PokéDollars 💵", money));
        }
        if let Some(ref ms) = self.mega_stone {
            if !ms.is_empty() && ms != "none" {
                if ms == "random" {
                    list.push("• Random Mega Stone".to_string());
                } else {
                    list.push(format!("• {} (Mega Stone)", ms));
                }
            }
        }
        if let Some(ref tm_val) = self.tm {
            if !tm_val.is_empty() && tm_val != "none" {
                if tm_val == "random" {
                    list.push("• Random TM".to_string());
                } else if let Ok(num) = tm_val.parse::<u32>() {
                    if let Some(tm) = get_tm_by_number(num) {
                        list.push(format!("• TM #{} ({})", tm.number, tm.name));
                    } else {
                        list.push(format!("• TM #{}", num));
                    }
                } else {
                    list.push(format!("• TM {}", tm_val));
                }
            }
        }
        if let Some(ref egg_val) = self.egg {
            if !egg_val.is_empty() && egg_val != "none" {
                if egg_val == "random" {
                    list.push("• Random Pokémon Egg".to_string());
                } else if let Ok(id) = egg_val.parse::<u32>() {
                    list.push(format!("• Pokémon Egg (#{})", id));
                } else {
                    list.push(format!("• {} Egg", egg_val));
                }
            }
        }
        list
    }

    pub fn to_bullet_rewards_with_pokedex(&self, default_badge: &str, default_money: i64, pokedex: &PokedexData) -> Vec<String> {
        let mut list = Vec::new();
        let badge_name = self.badge.as_deref().unwrap_or(default_badge);
        if !badge_name.is_empty() {
            list.push(format!("• {}", badge_name));
        }
        let money = self.pokedollars.unwrap_or(default_money);
        if money > 0 {
            list.push(format!("• {} PokéDollars 💵", money));
        }
        if let Some(ref ms) = self.mega_stone {
            if !ms.is_empty() && ms != "none" {
                if ms == "random" {
                    list.push("• Random Mega Stone".to_string());
                } else {
                    list.push(format!("• {} (Mega Stone)", ms));
                }
            }
        }
        if let Some(ref tm_val) = self.tm {
            if !tm_val.is_empty() && tm_val != "none" {
                if tm_val == "random" {
                    list.push("• Random TM".to_string());
                } else if let Ok(num) = tm_val.parse::<u32>() {
                    if let Some(tm) = get_tm_by_number(num) {
                        list.push(format!("• TM #{} ({})", tm.number, tm.name));
                    } else {
                        list.push(format!("• TM #{}", num));
                    }
                } else {
                    list.push(format!("• TM {}", tm_val));
                }
            }
        }
        if let Some(ref egg_val) = self.egg {
            if !egg_val.is_empty() && egg_val != "none" {
                if egg_val == "random" {
                    list.push("• Random Pokémon Egg".to_string());
                } else if let Ok(id) = egg_val.parse::<u32>() {
                    let name = pokedex.get_pokemon_by_id(id).map(|p| format_pokemon_name(&p.name)).unwrap_or_else(|| format!("#{}", id));
                    list.push(format!("• {} Egg", name));
                } else {
                    list.push(format!("• {} Egg", egg_val));
                }
            }
        }
        list
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
pub struct RedeemRewardsConfig {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pokedollars: Option<i64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tm: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tutor: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub egg: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mega_stone: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pokemon: Option<RedeemPokemonConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
pub struct RedeemPokemonConfig {
    #[serde(default = "default_pokemon_mode")]
    pub mode: String, // "specific" or "random"
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pokemon_id: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>, // "all", "non_legendary", "legendary", "mythical", "ultra_beast", "paradox"
    #[serde(default = "default_redeem_level")]
    pub level: u32,
    #[serde(default)]
    pub is_shiny: bool,
}

fn default_pokemon_mode() -> String {
    "random".to_string()
}

fn default_redeem_level() -> u32 {
    50
}

impl RedeemRewardsConfig {
    pub fn to_summary_string(&self, pokedex: &PokedexData) -> String {
        let mut parts = Vec::new();
        if let Some(pd) = self.pokedollars {
            if pd > 0 {
                parts.push(format!("💵 {} PokéDollars", pd));
            }
        }
        if let Some(ref tm) = self.tm {
            if !tm.is_empty() && tm != "none" {
                if tm.eq_ignore_ascii_case("random") {
                    parts.push("Random TM".to_string());
                } else if let Ok(num) = tm.parse::<u32>() {
                    if let Some(t) = get_tm_by_number(num) {
                        parts.push(format!("TM #{} ({})", t.number, t.name));
                    } else {
                        parts.push(format!("TM #{}", num));
                    }
                } else {
                    parts.push(format!("TM {}", tm));
                }
            }
        }
        if let Some(ref tut) = self.tutor {
            if !tut.is_empty() && tut != "none" {
                if tut.eq_ignore_ascii_case("random") {
                    parts.push("Random Move Tutor".to_string());
                } else if let Ok(num) = tut.parse::<u32>() {
                    if let Some(t) = TUTOR_CATALOG.iter().find(|x| x.number == num) {
                        parts.push(format!("Tutor #{} ({})", t.number, t.name));
                    } else {
                        parts.push(format!("Tutor #{}", num));
                    }
                } else {
                    parts.push(format!("Tutor {}", tut));
                }
            }
        }
        if let Some(ref egg) = self.egg {
            if !egg.is_empty() && egg != "none" {
                if egg.eq_ignore_ascii_case("random") {
                    parts.push("Random Pokémon Egg".to_string());
                } else if let Ok(id) = egg.parse::<u32>() {
                    let name = pokedex.get_pokemon_by_id(id).map(|p| format_pokemon_name(&p.name)).unwrap_or_else(|| format!("#{}", id));
                    parts.push(format!("{} Egg", name));
                } else {
                    parts.push(format!("{} Egg", egg));
                }
            }
        }
        if let Some(ref ms) = self.mega_stone {
            if !ms.is_empty() && ms != "none" {
                if ms.eq_ignore_ascii_case("random") {
                    parts.push("Random Mega Stone".to_string());
                } else {
                    parts.push(ms.clone());
                }
            }
        }
        if let Some(ref p) = self.pokemon {
            if p.mode != "none" {
                if p.mode == "specific" {
                    if let Some(id) = p.pokemon_id {
                        let name = pokedex.get_pokemon_by_id(id).map(|pk| format_pokemon_name(&pk.name)).unwrap_or_else(|| format!("#{}", id));
                        let shiny = if p.is_shiny { " (Shiny)" } else { "" };
                        parts.push(format!("{} Lv. {}{}", name, p.level, shiny));
                    }
                } else {
                    let cat_label = match p.category.as_deref().unwrap_or("all") {
                        "legendary" => "Legendary",
                        "mythical" => "Mythical",
                        "ultra_beast" => "Ultra Beast",
                        "paradox" => "Paradox",
                        "non_legendary" => "Non-Legendary",
                        _ => "Random",
                    };
                    let shiny = if p.is_shiny { " (Shiny)" } else { "" };
                    parts.push(format!("{} Pokémon (Lv. {}){}", cat_label, p.level, shiny));
                }
            }
        }
        if parts.is_empty() {
            "No Rewards".to_string()
        } else {
            parts.join(", ")
        }
    }
}

pub fn validate_player_team_for_gym(
    team: &[BattlePokemon],
    rules: &GymRulesConfig,
    pokedex: &PokedexData,
) -> Result<(), String> {
    if team.is_empty() {
        return Err("Gym Rule Violation:\n• You do not have any Pokémon on your active battle team!".to_string());
    }

    let mut violations: Vec<String> = Vec::new();
    let mut seen_species: HashSet<u32> = HashSet::new();
    let mut has_conscious = false;

    for pkmn in team {
        let display_name = if !pkmn.nickname.is_empty() && pkmn.nickname != pkmn.name {
            format!("{} ({})", format_pokemon_name(&pkmn.nickname), format_pokemon_name(&pkmn.name))
        } else {
            format_pokemon_name(&pkmn.name)
        };

        if pkmn.current_hp > 0 || pkmn.max_hp > 0 {
            has_conscious = true;
        }

        // 1. Banned types
        if !rules.banned_types.is_empty() {
            for t in &pkmn.types {
                if rules.banned_types.iter().any(|b| b.eq_ignore_ascii_case(t)) {
                    violations.push(format!("• {} is a {}-type Pokémon, which is banned in this Gym!", display_name, t));
                    break;
                }
            }
        }

        // Look up pokedex entry for special categories
        if let Some(entry) = pokedex.get_pokemon_by_id(pkmn.id) {
            // 2. Legendary
            if rules.ban_legendaries && entry.is_legendary == Some(true) {
                violations.push(format!("• {} is a Legendary Pokémon, which is banned in this Gym!", display_name));
            }
            // 3. Mythical
            if rules.ban_mythicals && entry.is_mythical == Some(true) {
                violations.push(format!("• {} is a Mythical Pokémon, which is banned in this Gym!", display_name));
            }
            // 4. Ultra Beast
            if rules.ban_ultra_beasts && ULTRA_BEAST_IDS.contains(&pkmn.id) {
                violations.push(format!("• {} is an Ultra Beast Pokémon, which is banned in this Gym!", display_name));
            }
            // 5. Paradox
            if rules.ban_paradox && PARADOX_IDS.contains(&pkmn.id) {
                violations.push(format!("• {} is a Paradox Pokémon, which is banned in this Gym!", display_name));
            }
        }

        // 6. Duplicate species
        if rules.no_duplicates {
            if seen_species.contains(&pkmn.id) {
                violations.push(format!("• Duplicate Pokémon detected: you have multiple {} on your team!", format_pokemon_name(&pkmn.name)));
            } else {
                seen_species.insert(pkmn.id);
            }
        }

        // 7. Max level
        if let Some(max_lvl) = rules.max_level {
            if pkmn.level > max_lvl {
                violations.push(format!("• {} is Lv. {}, which exceeds the Gym level cap of Lv. {}!", display_name, pkmn.level, max_lvl));
            }
        }
    }

    // 8. Require conscious pokemon
    if rules.require_conscious && !has_conscious {
        violations.push("• Active battle team must have at least 1 conscious Pokémon!".to_string());
    }

    if violations.is_empty() {
        Ok(())
    } else {
        Err(format!("Gym Rule Violation:\n{}", violations.join("\n")))
    }
}

pub async fn award_gym_rewards(
    pool: &SqlitePool,
    user_id: u64,
    gym: &ActiveGymBattle,
    pokedex: &PokedexData,
) -> Vec<String> {
    let mut earned = Vec::new();

    // 1. Badge
    let badge_name = gym.rewards_config.badge.as_deref().unwrap_or(&gym.badge);
    if !badge_name.is_empty() {
        let _ = sqlx::query(
            "INSERT INTO user_key_items (user_id, item_name, quantity) VALUES (?, ?, 1)
             ON CONFLICT(user_id, item_name) DO UPDATE SET quantity = quantity + 1"
        )
        .bind(user_id as i64)
        .bind(badge_name)
        .execute(pool)
        .await;
        earned.push(format!("• <b>{}</b>", badge_name));
    }

    // 2. PokéDollars
    let prize_money = gym.rewards_config.pokedollars.unwrap_or(if gym.reward_money > 0 { gym.reward_money } else { gym.fee * 5 });
    if prize_money > 0 {
        let _ = sqlx::query("UPDATE users SET wins = wins + 1, pokedollars = pokedollars + ? WHERE id = ?")
            .bind(prize_money)
            .bind(user_id as i64)
            .execute(pool)
            .await;
        earned.push(format!("• 💵 <code>{} PokéDollars</code>", prize_money));
    } else {
        let _ = sqlx::query("UPDATE users SET wins = wins + 1 WHERE id = ?")
            .bind(user_id as i64)
            .execute(pool)
            .await;
    }

    // 3. Mega Stone
    if let Some(ref ms) = gym.rewards_config.mega_stone {
        if !ms.is_empty() && ms != "none" {
            let stone_name = if ms == "random" {
                let mut rng = rand::thread_rng();
                ALL_MEGA_STONES.choose(&mut rng).unwrap_or(&"Lucarionite").to_string()
            } else {
                ms.clone()
            };

            let _ = sqlx::query(
                "INSERT INTO user_key_items (user_id, item_name, quantity) VALUES (?, ?, 1)
                 ON CONFLICT(user_id, item_name) DO UPDATE SET quantity = quantity + 1"
            )
            .bind(user_id as i64)
            .bind(&stone_name)
            .execute(pool)
            .await;

            let ms_emoji = crate::emoji::get_item_emoji("megastone", true);
            earned.push(format!("• {} <code>{} (Mega Stone)</code>", ms_emoji, stone_name));
        }
    }

    // 4. TM
    if let Some(ref tm_val) = gym.rewards_config.tm {
        if !tm_val.is_empty() && tm_val != "none" {
            let tm_entry = if tm_val == "random" {
                let mut rng = rand::thread_rng();
                TM_CATALOG.choose(&mut rng).cloned()
            } else if let Ok(num) = tm_val.parse::<u32>() {
                get_tm_by_number(num).cloned()
            } else {
                get_tm_by_name(tm_val).cloned()
            };

            if let Some(tm) = tm_entry {
                let _ = sqlx::query(
                    "INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (?, ?, ?, 1)
                     ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = 1"
                )
                .bind(user_id as i64)
                .bind(tm.number as i64)
                .bind(tm.name)
                .execute(pool)
                .await;

                let tm_emoji = r#"<tg-emoji emoji-id="6192525164958196815">💿</tg-emoji>"#;
                earned.push(format!("• {} <code>TM #{} ({})</code>", tm_emoji, tm.number, tm.name));
            }
        }
    }

    // 5. Egg
    if let Some(ref egg_val) = gym.rewards_config.egg {
        if !egg_val.is_empty() && egg_val != "none" {
            let egg_pkmn_id: Option<u32> = if egg_val == "random" {
                let mut rng = rand::thread_rng();
                pokedex.pokemon.values().map(|p| p.id).collect::<Vec<_>>().choose(&mut rng).copied()
            } else if let Ok(id) = egg_val.parse::<u32>() {
                Some(id)
            } else {
                pokedex.get_pokemon_by_name(egg_val).map(|p| p.id)
            };

            if let Some(pkmn_id) = egg_pkmn_id {
                let incubator_owned: i64 = sqlx::query_scalar("SELECT egg_incubator FROM users WHERE id = ?")
                    .bind(user_id as i64)
                    .fetch_one(pool)
                    .await
                    .unwrap_or(0);

                let is_inc_already: i64 = sqlx::query_scalar(
                    "SELECT COUNT(*) FROM user_eggs WHERE user_id = ? AND is_incubating = 1"
                )
                .bind(user_id as i64)
                .fetch_one(pool)
                .await
                .unwrap_or(0);

                let start_incubating = if incubator_owned > 0 && is_inc_already == 0 { 1 } else { 0 };

                let _ = sqlx::query(
                    "INSERT INTO user_eggs (user_id, pokemon_id, steps_remaining, is_incubating) VALUES (?, ?, 50, ?)"
                )
                .bind(user_id as i64)
                .bind(pkmn_id as i64)
                .bind(start_incubating)
                .execute(pool)
                .await;

                let pkmn_name = pokedex.get_pokemon_by_id(pkmn_id).map(|p| format_pokemon_name(&p.name)).unwrap_or_else(|| "Pokémon".to_string());
                let egg_emoji = crate::emoji::get_egg_emoji(true);
                earned.push(format!("• {} <code>{} Egg</code>", egg_emoji, pkmn_name));
            }
        }
    }

    // 6. Record gym beaten in user_gyms
    let _ = sqlx::query(
        "INSERT INTO user_gyms (user_id, region, gyms_beaten) VALUES (?, ?, ?)
         ON CONFLICT(user_id, region) DO UPDATE SET gyms_beaten = MAX(gyms_beaten, excluded.gyms_beaten)"
    )
    .bind(user_id as i64)
    .bind(&gym.region)
    .bind(gym.gym_num as i32)
    .execute(pool)
    .await;

    earned
}

pub async fn award_redeem_rewards(
    pool: &SqlitePool,
    user_id: u64,
    config: &RedeemRewardsConfig,
    pokedex: &PokedexData,
) -> Vec<String> {
    let mut awarded = Vec::new();

    // 1. PokéDollars
    if let Some(pd) = config.pokedollars {
        if pd > 0 {
            let _ = sqlx::query("UPDATE users SET pokedollars = pokedollars + ? WHERE id = ?")
                .bind(pd)
                .bind(user_id as i64)
                .execute(pool)
                .await;
            awarded.push(format!("• 💵 <code>{} PokéDollars</code>", pd));
        }
    }

    // 2. TM
    if let Some(ref tm_val) = config.tm {
        if !tm_val.is_empty() && tm_val != "none" {
            let tm_entry = {
                if tm_val.eq_ignore_ascii_case("random") {
                    let mut rng = rand::thread_rng();
                    TM_CATALOG.choose(&mut rng).cloned()
                } else if let Ok(num) = tm_val.parse::<u32>() {
                    get_tm_by_number(num).cloned()
                } else {
                    get_tm_by_name(tm_val).cloned()
                }
            };

            if let Some(tm) = tm_entry {
                let _ = sqlx::query(
                    "INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (?, ?, ?, 1)
                     ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = quantity + 1"
                )
                .bind(user_id as i64)
                .bind(tm.number as i64)
                .bind(tm.name)
                .execute(pool)
                .await;

                let tm_emoji = r#"<tg-emoji emoji-id="6192525164958196815">💿</tg-emoji>"#;
                awarded.push(format!("• {} <code>TM #{} ({})</code>", tm_emoji, tm.number, tm.name));
            }
        }
    }

    // 3. Tutor
    if let Some(ref tut_val) = config.tutor {
        if !tut_val.is_empty() && tut_val != "none" {
            let tut_entry = {
                if tut_val.eq_ignore_ascii_case("random") {
                    let mut rng = rand::thread_rng();
                    TUTOR_CATALOG.choose(&mut rng).cloned()
                } else if let Ok(num) = tut_val.parse::<u32>() {
                    get_tutor_by_number(num).cloned()
                } else {
                    get_tutor_by_name(tut_val).cloned()
                }
            };

            if let Some(tut) = tut_entry {
                let _ = sqlx::query(
                    "INSERT INTO user_tutors (user_id, tutor_number, move_name, quantity) VALUES (?, ?, ?, 1)
                     ON CONFLICT(user_id, tutor_number) DO UPDATE SET quantity = quantity + 1"
                )
                .bind(user_id as i64)
                .bind(tut.number as i64)
                .bind(tut.name)
                .execute(pool)
                .await;

                let tutor_emoji = crate::emoji::get_tutors_emoji(true);
                awarded.push(format!("• {} <code>Move Tutor #{} ({})</code>", tutor_emoji, tut.number, tut.name));
            }
        }
    }

    // 4. Egg
    if let Some(ref egg_val) = config.egg {
        if !egg_val.is_empty() && egg_val != "none" {
            let egg_pkmn_id: Option<u32> = {
                if egg_val.eq_ignore_ascii_case("random") {
                    let mut rng = rand::thread_rng();
                    let valid_ids: Vec<u32> = pokedex.pokemon.values().map(|p| p.id).filter(|&id| id <= 1025).collect();
                    valid_ids.choose(&mut rng).copied()
                } else if let Ok(id) = egg_val.parse::<u32>() {
                    Some(id)
                } else {
                    pokedex.get_pokemon_by_name(egg_val).map(|p| p.id)
                }
            };

            if let Some(pkmn_id) = egg_pkmn_id {
                let incubator_owned: i64 = sqlx::query_scalar("SELECT egg_incubator FROM users WHERE id = ?")
                    .bind(user_id as i64)
                    .fetch_one(pool)
                    .await
                    .unwrap_or(0);

                let is_inc_already: i64 = sqlx::query_scalar(
                    "SELECT COUNT(*) FROM user_eggs WHERE user_id = ? AND is_incubating = 1"
                )
                .bind(user_id as i64)
                .fetch_one(pool)
                .await
                .unwrap_or(0);

                let start_incubating = if incubator_owned > 0 && is_inc_already == 0 { 1 } else { 0 };

                let _ = sqlx::query(
                    "INSERT INTO user_eggs (user_id, pokemon_id, steps_remaining, is_incubating) VALUES (?, ?, 50, ?)"
                )
                .bind(user_id as i64)
                .bind(pkmn_id as i64)
                .bind(start_incubating)
                .execute(pool)
                .await;

                let pkmn_name = pokedex.get_pokemon_by_id(pkmn_id).map(|p| format_pokemon_name(&p.name)).unwrap_or_else(|| "Pokémon".to_string());
                let egg_emoji = crate::emoji::get_egg_emoji(true);
                awarded.push(format!("• {} <code>{} Egg</code>", egg_emoji, pkmn_name));
            }
        }
    }

    // 5. Mega Stone
    if let Some(ref ms_val) = config.mega_stone {
        if !ms_val.is_empty() && ms_val != "none" {
            let stone_name = {
                if ms_val.eq_ignore_ascii_case("random") {
                    let mut rng = rand::thread_rng();
                    ALL_MEGA_STONES.choose(&mut rng).unwrap_or(&"Lucarionite").to_string()
                } else {
                    ms_val.clone()
                }
            };

            let _ = sqlx::query(
                "INSERT INTO user_key_items (user_id, item_name, quantity) VALUES (?, ?, 1)
                 ON CONFLICT(user_id, item_name) DO UPDATE SET quantity = quantity + 1"
            )
            .bind(user_id as i64)
            .bind(&stone_name)
            .execute(pool)
            .await;

            let ms_emoji = crate::emoji::get_item_emoji("megastone", true);
            awarded.push(format!("• {} <code>{} (Mega Stone)</code>", ms_emoji, stone_name));
        }
    }

    // 6. Pokémon
    if let Some(ref p_cfg) = config.pokemon {
        if p_cfg.mode != "none" {
            let chosen_id: Option<u32> = if p_cfg.mode == "specific" {
                p_cfg.pokemon_id
            } else {
                let mut rng = rand::thread_rng();
                let cat = p_cfg.category.as_deref().unwrap_or("all");
                let candidates: Vec<u32> = pokedex.pokemon.values().filter_map(|p| {
                    if p.id > 1025 {
                        return None;
                    }
                    let is_leg = p.is_legendary == Some(true);
                    let is_myth = p.is_mythical == Some(true);
                    let is_ub = ULTRA_BEAST_IDS.contains(&p.id);
                    let is_par = PARADOX_IDS.contains(&p.id);

                    let matches = match cat {
                        "legendary" => is_leg,
                        "mythical" => is_myth,
                        "ultra_beast" => is_ub,
                        "paradox" => is_par,
                        "non_legendary" => !is_leg && !is_myth && !is_ub && !is_par,
                        _ => true,
                    };

                    if matches { Some(p.id) } else { None }
                }).collect();

                candidates.choose(&mut rng).copied()
            };

            if let Some(target_id) = chosen_id {
                if let Some(pkmn_entry) = pokedex.get_pokemon_by_id(target_id) {
                    let level = p_cfg.level.clamp(1, 100);
                    let (nature, iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe) = {
                        let mut rng = rand::thread_rng();
                        (
                            NATURES.choose(&mut rng).copied().unwrap_or("Hardy"),
                            rng.gen_range(0..=31),
                            rng.gen_range(0..=31),
                            rng.gen_range(0..=31),
                            rng.gen_range(0..=31),
                            rng.gen_range(0..=31),
                            rng.gen_range(0..=31),
                        )
                    };

                    let growth_rate = get_pokemon_growth_rate(target_id, pkmn_entry);
                    let exp = calculate_pokemon_exp_at_level(growth_rate, level as i32);

                    let moves = pokedex.get_level_up_moves(target_id, level);
                    let m1 = moves.get(0).map(|m| m.name.clone());
                    let m2 = moves.get(1).map(|m| m.name.clone());
                    let m3 = moves.get(2).map(|m| m.name.clone());
                    let m4 = moves.get(3).map(|m| m.name.clone());

                    let is_shiny_int = if p_cfg.is_shiny { 1 } else { 0 };

                    let _ = sqlx::query(
                        "INSERT INTO pokemons (user_id, pokemon_id, nickname, level, nature,
                                               iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                                               ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                                               experience, move_1, move_2, move_3, move_4, is_starter, is_shiny)
                         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, 0, 0, 0, 0, ?, ?, ?, ?, ?, 0, ?)"
                    )
                    .bind(user_id as i64)
                    .bind(target_id as i64)
                    .bind(&pkmn_entry.name)
                    .bind(level as i32)
                    .bind(nature)
                    .bind(iv_hp)
                    .bind(iv_atk)
                    .bind(iv_def)
                    .bind(iv_spa)
                    .bind(iv_spd)
                    .bind(iv_spe)
                    .bind(exp)
                    .bind(m1)
                    .bind(m2)
                    .bind(m3)
                    .bind(m4)
                    .bind(is_shiny_int)
                    .execute(pool)
                    .await;

                    let pokeball_emoji = r#"<tg-emoji emoji-id="5425017773338164606">🔴</tg-emoji>"#;
                    let display_name = format_pokemon_name(&pkmn_entry.name);
                    let shiny_suffix = if p_cfg.is_shiny { " (Shiny)" } else { "" };
                    awarded.push(format!("• {} <code>{} Lv. {}{}</code>", pokeball_emoji, display_name, level, shiny_suffix));
                }
            }
        }
    }

    awarded
}

pub async fn handle_redeem(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    args: String,
) -> ResponseResult<()> {
    let Some(from) = msg.from.as_ref() else {
        return Ok(());
    };
    let user_id = from.id.0;

    let code_input = args.trim().to_uppercase();
    if code_input.is_empty() {
        bot.send_message(
            msg.chat.id,
            "Format: /redeem <code>\nExample: /redeem OZONE2026",
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if is_user_in_battle(user_id).await {
        bot.send_message(msg.chat.id, "You can't redeem codes while battling")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_trade(user_id).await {
        bot.send_message(msg.chat.id, "You can't redeem codes while trading")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }
    if is_user_in_any_challenge(user_id).await {
        bot.send_message(msg.chat.id, "You can't redeem codes while in a challenge")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let starter_row = sqlx::query("SELECT starter_id FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let has_starter = match &starter_row {
        Ok(Some(row)) => row.try_get::<i64, _>("starter_id").is_ok(),
        _ => false,
    };

    if !has_starter {
        bot.send_message(
            msg.chat.id,
            "Please pick your starter Pokémon first using /start!",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let code_row = sqlx::query(
        "SELECT id, code, description, rewards_json, max_uses, current_uses, max_per_user, expires_at, is_active
         FROM redeem_codes WHERE UPPER(code) = UPPER(?)"
    )
    .bind(&code_input)
    .fetch_optional(&*pool)
    .await;

    let row = match code_row {
        Ok(Some(r)) => r,
        Ok(None) => {
            bot.send_message(
                msg.chat.id,
                "Invalid redeem code. Please verify the code and try again.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
        Err(e) => {
            tracing::error!("Failed to fetch redeem code: {}", e);
            bot.send_message(
                msg.chat.id,
                "An error occurred while verifying the code. Please try again later.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    };

    let code_id: i64 = row.get("id");
    let canonical_code: String = row.get("code");
    let rewards_json: String = row.get("rewards_json");
    let max_uses: Option<i64> = row.get("max_uses");
    let current_uses: i64 = row.get("current_uses");
    let max_per_user: i64 = row.get("max_per_user");
    let expires_at: Option<String> = row.get("expires_at");
    let is_active: i64 = row.get("is_active");

    if is_active == 0 {
        bot.send_message(
            msg.chat.id,
            "This redeem code is no longer active.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if let Some(ref exp_str) = expires_at {
        if !exp_str.is_empty() {
            let now = chrono::Utc::now();
            let expired = if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(exp_str) {
                now >= dt
            } else if let Ok(naive) = chrono::NaiveDateTime::parse_from_str(exp_str, "%Y-%m-%d %H:%M:%S") {
                now.naive_utc() >= naive
            } else if let Ok(date) = chrono::NaiveDate::parse_from_str(exp_str, "%Y-%m-%d") {
                now.date_naive() > date
            } else {
                false
            };

            if expired {
                bot.send_message(
                    msg.chat.id,
                    "This redeem code has expired.",
                )
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }
        }
    }

    if let Some(max) = max_uses {
        if max > 0 && current_uses >= max {
            bot.send_message(
                msg.chat.id,
                "This redeem code has reached its maximum total uses.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    }

    let user_uses: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM user_redeemed_codes WHERE user_id = ? AND code_id = ?"
    )
    .bind(user_id as i64)
    .bind(code_id)
    .fetch_one(&*pool)
    .await
    .unwrap_or(0);

    if user_uses >= max_per_user {
        bot.send_message(
            msg.chat.id,
            "You have already redeemed this code!",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let rewards_cfg: RedeemRewardsConfig = serde_json::from_str(&rewards_json).unwrap_or_default();
    let mut awarded = award_redeem_rewards(&pool, user_id, &rewards_cfg, &pokedex).await;
    if awarded.is_empty() {
        awarded.push("• <code>No rewards configured for this code</code>".to_string());
    }

    let summary_for_history = awarded.join(", ");
    let _ = sqlx::query(
        "INSERT INTO user_redeemed_codes (user_id, code_id, code_text, rewards_summary) VALUES (?, ?, ?, ?)"
    )
    .bind(user_id as i64)
    .bind(code_id)
    .bind(&canonical_code)
    .bind(&summary_for_history)
    .execute(&*pool)
    .await;

    let _ = sqlx::query("UPDATE redeem_codes SET current_uses = current_uses + 1 WHERE id = ?")
        .bind(code_id)
        .execute(&*pool)
        .await;

    let text = format!(
        "Code <b>{}</b> redeemed successfully!\n\n<b>Rewards received:</b>\n{}",
        escape_html(&canonical_code),
        awarded.join("\n")
    );

    bot.send_message(msg.chat.id, text)
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

#[derive(Debug, Clone)]
pub struct DynamicGymConfig {
    pub region: String,
    pub gym_num: usize,
    pub is_open: bool,
    pub closed_reason: String,
    pub leader_name: String,
    pub city: String,
    pub gym_name: String,
    pub poke_type: String,
    pub fee: i64,
    pub quote: String,
    pub badge: String,
    pub rules_text: String,
    pub rewards_text: String,
    pub reward_money: i64,
    pub reward_badge: String,
    pub signature_pokemon_id: u32,
    pub team: Vec<CustomGymPokemon>,
    pub rules_json: String,
    pub rules_config: GymRulesConfig,
    pub rewards_json: String,
    pub rewards_config: GymRewardsConfig,
}

pub fn format_dynamic_gym_leader_caption(cfg: &DynamicGymConfig) -> String {
    let type_emoji = crate::emoji::get_type_emoji(&cfg.poke_type, true);
    format!(
        "<blockquote><u>Gym Leader {}:</u>\n<i>\"{}\"</i></blockquote>\n\n<b>Gym Type:</b> <code>{}</code> {}\n<b>Challenge Fee:</b> <code>{}</code> PokéDollars 💵\n\nAre you sure you want to challenge <code>{}</code> ?",
        escape_html(&cfg.leader_name),
        escape_html(&cfg.quote),
        escape_html(&cfg.poke_type),
        type_emoji,
        cfg.fee,
        escape_html(&cfg.gym_name)
    )
}

pub async fn are_gyms_globally_open(pool: &SqlitePool) -> (bool, String) {
    let row = sqlx::query("SELECT gyms_open, closed_reason FROM gym_global_settings WHERE id = 1")
        .fetch_optional(pool)
        .await
        .ok()
        .flatten();

    if let Some(row) = row {
        let gyms_open: i64 = row.try_get("gyms_open").unwrap_or(1);
        let closed_reason: String = row.try_get("closed_reason").unwrap_or_else(|_| "Gyms are temporarily closed by the Pokémon League.".to_string());
        (gyms_open != 0, closed_reason)
    } else {
        (true, "Gyms are temporarily closed by the Pokémon League.".to_string())
    }
}

pub async fn get_dynamic_gym_config(
    pool: &SqlitePool,
    region: &str,
    gym_num: usize,
    _pokedex: &PokedexData,
) -> Option<DynamicGymConfig> {
    let r_slug = region.to_lowercase();
    let row = sqlx::query(
        "SELECT is_open, closed_reason, leader_name, city, gym_name, poke_type, fee,
                quote, badge, rules_text, rewards_text, reward_money, reward_badge,
                signature_pokemon_id, team_json, rules_json, rewards_json
         FROM gym_configs
         WHERE LOWER(region) = ? AND gym_num = ?"
    )
    .bind(&r_slug)
    .bind(gym_num as i64)
    .fetch_optional(pool)
    .await
    .ok()
    .flatten();

    if let Some(row) = row {
        let is_open_int: i64 = row.try_get("is_open").unwrap_or(1);
        let closed_reason: String = row.try_get("closed_reason").unwrap_or_else(|_| "This Gym is currently closed.".to_string());
        let leader_name: String = row.try_get("leader_name").unwrap_or_else(|_| "Gym Leader".to_string());
        let city: String = row.try_get("city").unwrap_or_else(|_| "City".to_string());
        let gym_name: String = row.try_get("gym_name").unwrap_or_else(|_| "Gym".to_string());
        let poke_type: String = row.try_get("poke_type").unwrap_or_else(|_| "Normal".to_string());
        let fee: i64 = row.try_get("fee").unwrap_or(200);
        let quote: String = row.try_get("quote").unwrap_or_default();
        let badge: String = row.try_get("badge").unwrap_or_default();
        let rules_text: String = row.try_get("rules_text").unwrap_or_default();
        let rewards_text: String = row.try_get("rewards_text").unwrap_or_default();
        let reward_money: i64 = row.try_get("reward_money").unwrap_or(fee * 5);
        let reward_badge: String = row.try_get("reward_badge").unwrap_or_else(|_| badge.clone());
        let signature_pokemon_id: u32 = row.try_get::<i64, _>("signature_pokemon_id").unwrap_or(0) as u32;
        let team_json: String = row.try_get("team_json").unwrap_or_else(|_| "[]".to_string());
        let rules_json: String = row.try_get("rules_json").unwrap_or_else(|_| "{}".to_string());
        let rewards_json: String = row.try_get("rewards_json").unwrap_or_else(|_| "{}".to_string());

        let team: Vec<CustomGymPokemon> = serde_json::from_str(&team_json).unwrap_or_default();
        let rules_config: GymRulesConfig = serde_json::from_str(&rules_json).unwrap_or_default();
        let rewards_config: GymRewardsConfig = serde_json::from_str(&rewards_json).unwrap_or_default();

        Some(DynamicGymConfig {
            region: r_slug,
            gym_num,
            is_open: is_open_int != 0,
            closed_reason,
            leader_name,
            city,
            gym_name,
            poke_type,
            fee,
            quote,
            badge,
            rules_text,
            rewards_text,
            reward_money,
            reward_badge,
            signature_pokemon_id,
            team,
            rules_json,
            rules_config,
            rewards_json,
            rewards_config,
        })
    } else {
        let leader = get_gym_leader(&r_slug, gym_num)?;
        let rules_text = format!(
            "Gym Rules:\n• 6v6 Pokémon Battle against {}\n• Level 100 Anime Signature Pokémon Team\n• Perfect IVs (186) & Max EVs (510)\n• Defeat all 6 of the Gym Leader's Pokémon to earn the Gym Badge!",
            leader.name
        );
        let rewards_text = format!("Gym Rewards:\n• {}\n• {} PokéDollars", leader.badge, leader.fee * 5);

        Some(DynamicGymConfig {
            region: r_slug,
            gym_num,
            is_open: true,
            closed_reason: "This Gym is currently closed.".to_string(),
            leader_name: leader.name.to_string(),
            city: leader.city.to_string(),
            gym_name: leader.gym_name.to_string(),
            poke_type: leader.poke_type.to_string(),
            fee: leader.fee,
            quote: leader.quote.to_string(),
            badge: leader.badge.to_string(),
            rules_text,
            rewards_text,
            reward_money: leader.fee * 5,
            reward_badge: leader.badge.to_string(),
            signature_pokemon_id: leader.signature_pokemon_id,
            team: Vec::new(),
            rules_json: "{}".to_string(),
            rules_config: GymRulesConfig::default(),
            rewards_json: "{}".to_string(),
            rewards_config: GymRewardsConfig::default(),
        })
    }
}

pub fn build_battle_pokemon_from_custom(
    custom: &CustomGymPokemon,
    pokedex: &PokedexData,
) -> Option<BattlePokemon> {
    let entry = pokedex.get_pokemon_by_id(custom.pokemon_id)?;
    let level = custom.level.clamp(1, 100);

    let (iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe) = if let Some(ref ivs) = custom.ivs {
        (
            ivs.hp.clamp(0, 31),
            ivs.attack.clamp(0, 31),
            ivs.defense.clamp(0, 31),
            ivs.sp_attack.clamp(0, 31),
            ivs.sp_defense.clamp(0, 31),
            ivs.speed.clamp(0, 31),
        )
    } else {
        (31, 31, 31, 31, 31, 31)
    };

    let (ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe) = if let Some(ref evs) = custom.evs {
        (
            evs.hp.clamp(0, 252),
            evs.attack.clamp(0, 252),
            evs.defense.clamp(0, 252),
            evs.sp_attack.clamp(0, 252),
            evs.sp_defense.clamp(0, 252),
            evs.speed.clamp(0, 252),
        )
    } else {
        if entry.stats.attack >= entry.stats.special_attack {
            if entry.stats.speed >= 60 {
                (6, 252, 0, 0, 0, 252)
            } else {
                (252, 252, 6, 0, 0, 0)
            }
        } else {
            if entry.stats.speed >= 60 {
                (6, 0, 0, 252, 0, 252)
            } else {
                (252, 0, 0, 252, 6, 0)
            }
        }
    };

    let max_hp = calc_hp(entry.stats.hp, iv_hp, ev_hp, level as i32);

    let mut moves: Vec<MoveDetail> = Vec::new();
    for m in &custom.moves {
        if !m.name.trim().is_empty() {
            moves.push(MoveDetail {
                name: m.name.clone(),
                t: if m.r#type.is_empty() { "Normal".to_string() } else { capitalize(&m.r#type) },
                c: if m.category.is_empty() { "Physical".to_string() } else { capitalize(&m.category) },
                p: m.power.or(Some(80)),
                a: m.accuracy.or(Some(100)),
                pp: m.pp.or(Some(15)),
                d: String::new(),
            });
        }
    }

    if moves.is_empty() {
        moves = pokedex
            .get_level_up_moves(custom.pokemon_id, level)
            .into_iter()
            .cloned()
            .collect();
    }

    if moves.is_empty() {
        moves.push(MoveDetail {
            name: "Tackle".to_string(),
            t: "Normal".to_string(),
            c: "Physical".to_string(),
            p: Some(40),
            a: Some(100),
            pp: Some(35),
            d: "A physical attack in which the user charges and slams into the target with its whole body.".to_string(),
        });
    }

    Some(BattlePokemon {
        db_id: None,
        id: custom.pokemon_id,
        name: entry.name.clone(),
        nickname: if custom.name.is_empty() { entry.name.clone() } else { custom.name.clone() },
        level,
        types: entry.types.clone(),
        nature: custom.nature.clone(),
        base_stats: entry.stats.clone(),
        iv_hp,
        iv_atk,
        iv_def,
        iv_spa,
        iv_spd,
        iv_spe,
        ev_hp,
        ev_atk,
        ev_def,
        ev_spa,
        ev_spd,
        ev_spe,
        max_hp,
        current_hp: max_hp,
        moves,
        is_shiny: false,
        catch_rate: entry.catch_rate.unwrap_or(45),
        base_experience: entry.base_experience.unwrap_or(270),
        is_burned: false,
    })
}

pub fn create_dynamic_gym_leader_team(
    cfg: &DynamicGymConfig,
    pokedex: &PokedexData,
) -> Vec<BattlePokemon> {
    let mut team = Vec::new();
    let level_cap = cfg.rules_config.max_level.unwrap_or(0);
    for pkmn_cfg in &cfg.team {
        if let Some(mut pkmn) = build_battle_pokemon_from_custom(pkmn_cfg, pokedex) {
            if level_cap > 0 && pkmn.level > level_cap {
                pkmn.level = level_cap;
                if let Some(entry) = pokedex.get_pokemon_by_id(pkmn.id) {
                    pkmn.max_hp = calc_hp(entry.stats.hp, pkmn.iv_hp, pkmn.ev_hp, pkmn.level as i32);
                    pkmn.current_hp = pkmn.max_hp;
                }
            }
            team.push(pkmn);
        }
    }
    if team.is_empty() {
        if let Some(leader) = get_gym_leader(&cfg.region, cfg.gym_num) {
            let mut default_team = create_gym_leader_team(&leader, pokedex);
            if level_cap > 0 {
                for pkmn in &mut default_team {
                    if pkmn.level > level_cap {
                        pkmn.level = level_cap;
                        if let Some(entry) = pokedex.get_pokemon_by_id(pkmn.id) {
                            pkmn.max_hp = calc_hp(entry.stats.hp, pkmn.iv_hp, pkmn.ev_hp, pkmn.level as i32);
                            pkmn.current_hp = pkmn.max_hp;
                        }
                    }
                }
            }
            return default_team;
        }
    }
    team
}

async fn handle_gym_callback(
    bot: &Bot,
    q: &CallbackQuery,
    pool: &SqlitePool,
    pokedex: &PokedexData,
    battles: &BattleSessions,
    data: &str,
) -> ResponseResult<()> {
    let Some(ref msg) = q.message else {
        let _ = bot.answer_callback_query(q.id.clone()).await;
        return Ok(());
    };
    let chat_id = msg.chat().id;
    let message_id = msg.id();
    let user_id = q.from.id.0 as i64;

    if data == "gym_main" {
        let _ = bot.answer_callback_query(q.id.clone()).await;
        let (globally_open, global_reason) = are_gyms_globally_open(pool).await;
        let caption = if !globally_open {
            format!("{}\n\n<b>Notice:</b> {}", GYM_MAIN_CAPTION, escape_html(&global_reason))
        } else {
            GYM_MAIN_CAPTION.to_string()
        };
        let photo_path = "assets/gym.jpg";
        if std::path::Path::new(photo_path).exists() {
            let media = InputMedia::Photo(
                InputMediaPhoto::new(InputFile::file(std::path::Path::new(photo_path)))
                    .caption(caption.clone())
                    .parse_mode(ParseMode::Html),
            );
            let _ = bot
                .edit_message_media(chat_id, message_id, media)
                .reply_markup(build_gym_keyboard())
                .await;
        } else {
            safe_edit_caption(bot, chat_id, message_id, caption, build_gym_keyboard()).await?;
        }
        return Ok(());
    }

    if let Some(region_slug) = data.strip_prefix("gym_reg:") {
        let (globally_open, global_reason) = are_gyms_globally_open(pool).await;
        if !globally_open {
            let _ = bot
                .answer_callback_query(q.id.clone())
                .text(format!("Gym Battles are closed: {}", global_reason))
                .show_alert(true)
                .await;
            return Ok(());
        }

        let _ = bot.answer_callback_query(q.id.clone()).await;
        let region_name = match region_slug {
            "kanto" => "Kanto",
            "johto" => "Johto",
            "hoenn" => "Hoenn",
            "sinnoh" => "Sinnoh",
            other => other,
        };

        let gyms_beaten: i32 = sqlx::query_scalar(
            "SELECT gyms_beaten FROM user_gyms WHERE user_id = ? AND LOWER(region) = LOWER(?)"
        )
        .bind(user_id)
        .bind(region_name)
        .fetch_optional(pool)
        .await
        .unwrap_or(None)
        .unwrap_or(0);

        let caption = format_gym_cities_caption(region_name, gyms_beaten);
        let custom_kb = build_gym_cities_keyboard_json(region_slug);
        let fallback_kb = build_gym_cities_keyboard(region_slug);

        let photo_path = "assets/gym.jpg";
        if std::path::Path::new(photo_path).exists() {
            let media = InputMedia::Photo(
                InputMediaPhoto::new(InputFile::file(std::path::Path::new(photo_path)))
                    .caption(caption.clone())
                    .parse_mode(ParseMode::Html),
            );
            if bot.edit_message_media(chat_id, message_id, media).reply_markup(fallback_kb.clone()).await.is_err() {
                safe_edit_caption_with_json_fallback(bot, chat_id, message_id, caption, custom_kb, fallback_kb).await?;
            }
        } else {
            safe_edit_caption_with_json_fallback(bot, chat_id, message_id, caption, custom_kb, fallback_kb).await?;
        }
        return Ok(());
    }

    if let Some(rest) = data.strip_prefix("gym_city:") {
        let parts: Vec<&str> = rest.split(':').collect();
        if parts.len() == 2 {
            let region_slug = parts[0];
            let gym_num: usize = parts[1].parse().unwrap_or(1);
            let region_name = match region_slug {
                "kanto" => "Kanto",
                "johto" => "Johto",
                "hoenn" => "Hoenn",
                "sinnoh" => "Sinnoh",
                other => other,
            };

            let (globally_open, global_reason) = are_gyms_globally_open(pool).await;
            if !globally_open {
                let _ = bot
                    .answer_callback_query(q.id.clone())
                    .text(format!("Gym Battles are closed: {}", global_reason))
                    .show_alert(true)
                    .await;
                return Ok(());
            }

            let gyms_beaten: i32 = sqlx::query_scalar(
                "SELECT gyms_beaten FROM user_gyms WHERE user_id = ? AND LOWER(region) = LOWER(?)"
            )
            .bind(user_id)
            .bind(region_name)
            .fetch_optional(pool)
            .await
            .unwrap_or(None)
            .unwrap_or(0);

            let gym_idx = (gym_num as i32) - 1;
            if gym_idx > gyms_beaten {
                let _ = bot
                    .answer_callback_query(q.id.clone())
                    .text("This Gym is currently locked! Defeat the previous Gym first.")
                    .show_alert(true)
                    .await;
                return Ok(());
            }

            if let Some(cfg) = get_dynamic_gym_config(pool, region_name, gym_num, pokedex).await {
                if !cfg.is_open {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(format!("{}: {}", cfg.gym_name, cfg.closed_reason))
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                let _ = bot.answer_callback_query(q.id.clone()).await;
                let caption = format_dynamic_gym_leader_caption(&cfg);
                let kb = build_gym_leader_keyboard(region_slug, gym_num);

                let photo_path = get_gym_photo_path(&cfg.city);
                if std::path::Path::new(&photo_path).exists() {
                    let media = InputMedia::Photo(
                        InputMediaPhoto::new(InputFile::file(std::path::Path::new(&photo_path)))
                            .caption(caption.clone())
                            .parse_mode(ParseMode::Html),
                    );
                    if bot.edit_message_media(chat_id, message_id, media).reply_markup(kb.clone()).await.is_err() {
                        safe_edit_caption(bot, chat_id, message_id, caption, kb).await?;
                    }
                } else {
                    safe_edit_caption(bot, chat_id, message_id, caption, kb).await?;
                }
                return Ok(());
            }
        }
    }

    if let Some(rest) = data.strip_prefix("gym_act:") {
        let parts: Vec<&str> = rest.split(':').collect();
        if parts.is_empty() {
            let _ = bot.answer_callback_query(q.id.clone()).await;
            return Ok(());
        }

        match parts[0] {
            "back" => {
                let _ = bot.answer_callback_query(q.id.clone()).await;
                let region_slug = if parts.len() > 1 { parts[1] } else { "kanto" };
                let region_name = match region_slug {
                    "kanto" => "Kanto",
                    "johto" => "Johto",
                    "hoenn" => "Hoenn",
                    "sinnoh" => "Sinnoh",
                    other => other,
                };

                let gyms_beaten: i32 = sqlx::query_scalar(
                    "SELECT gyms_beaten FROM user_gyms WHERE user_id = ? AND LOWER(region) = LOWER(?)"
                )
                .bind(user_id)
                .bind(region_name)
                .fetch_optional(pool)
                .await
                .unwrap_or(None)
                .unwrap_or(0);

                let caption = format_gym_cities_caption(region_name, gyms_beaten);
                let custom_kb = build_gym_cities_keyboard_json(region_slug);
                let fallback_kb = build_gym_cities_keyboard(region_slug);

                let photo_path = "assets/gym.jpg";
                if std::path::Path::new(photo_path).exists() {
                    let media = InputMedia::Photo(
                        InputMediaPhoto::new(InputFile::file(std::path::Path::new(photo_path)))
                            .caption(caption.clone())
                            .parse_mode(ParseMode::Html),
                    );
                    if bot.edit_message_media(chat_id, message_id, media).reply_markup(fallback_kb.clone()).await.is_err() {
                        safe_edit_caption_with_json_fallback(bot, chat_id, message_id, caption, custom_kb, fallback_kb).await?;
                    }
                } else {
                    safe_edit_caption_with_json_fallback(bot, chat_id, message_id, caption, custom_kb, fallback_kb).await?;
                }
                return Ok(());
            }
            "rew" => {
                let region_slug = if parts.len() > 1 { parts[1] } else { "kanto" };
                let gym_num: usize = if parts.len() > 2 { parts[2].parse().unwrap_or(1) } else { 1 };
                let region_name = match region_slug {
                    "kanto" => "Kanto",
                    "johto" => "Johto",
                    "hoenn" => "Hoenn",
                    "sinnoh" => "Sinnoh",
                    other => other,
                };
                if let Some(cfg) = get_dynamic_gym_config(pool, region_name, gym_num, pokedex).await {
                    let bullets = cfg.rewards_config.to_bullet_rewards_with_pokedex(&cfg.reward_badge, cfg.reward_money, pokedex);
                    let reward_text = if !bullets.is_empty() {
                        format!("Gym Rewards:\n{}", bullets.join("\n"))
                    } else if !cfg.rewards_text.trim().is_empty() {
                        cfg.rewards_text
                    } else {
                        format!("Gym Rewards:\n• {}\n• {} PokéDollars 💵", cfg.reward_badge, cfg.reward_money)
                    };
                    let _ = bot.answer_callback_query(q.id.clone()).text(reward_text).show_alert(true).await;
                } else {
                    let _ = bot.answer_callback_query(q.id.clone()).await;
                }
                return Ok(());
            }
            "rules" => {
                let region_slug = if parts.len() > 1 { parts[1] } else { "kanto" };
                let gym_num: usize = if parts.len() > 2 { parts[2].parse().unwrap_or(1) } else { 1 };
                let region_name = match region_slug {
                    "kanto" => "Kanto",
                    "johto" => "Johto",
                    "hoenn" => "Hoenn",
                    "sinnoh" => "Sinnoh",
                    other => other,
                };
                if let Some(cfg) = get_dynamic_gym_config(pool, region_name, gym_num, pokedex).await {
                    let bullets = cfg.rules_config.to_bullet_rules();
                    let rules_text = if !bullets.is_empty() {
                        let mut all = bullets;
                        all.push(format!("• 6v6 Pokémon Battle against {}", cfg.leader_name));
                        all.push("• Level 100 Anime Signature Pokémon Team".to_string());
                        all.push("• Perfect IVs (186) & Max EVs (510)".to_string());
                        all.push("• Defeat all 6 of the Gym Leader's Pokémon to earn the Gym Badge!".to_string());
                        format!("Gym Rules:\n{}", all.join("\n"))
                    } else if !cfg.rules_text.trim().is_empty() {
                        cfg.rules_text
                    } else {
                        format!(
                            "Gym Rules:\n• 6v6 Pokémon Battle against {}\n• Level 100 Anime Signature Pokémon Team\n• Perfect IVs (186) & Max EVs (510)\n• Defeat all 6 of the Gym Leader's Pokémon to earn the Gym Badge!",
                            cfg.leader_name
                        )
                    };
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(rules_text)
                        .show_alert(true)
                        .await;
                } else {
                    let _ = bot.answer_callback_query(q.id.clone()).await;
                }
                return Ok(());
            }
            "btl" => {
                let region_slug = if parts.len() > 1 { parts[1] } else { "kanto" };
                let gym_num: usize = if parts.len() > 2 { parts[2].parse().unwrap_or(1) } else { 1 };
                let region_name = match region_slug {
                    "kanto" => "Kanto",
                    "johto" => "Johto",
                    "hoenn" => "Hoenn",
                    "sinnoh" => "Sinnoh",
                    other => other,
                };

                let (globally_open, global_reason) = are_gyms_globally_open(pool).await;
                if !globally_open {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(format!("Gym Battles are closed: {}", global_reason))
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                let Some(cfg) = get_dynamic_gym_config(pool, region_name, gym_num, pokedex).await else {
                    let _ = bot.answer_callback_query(q.id.clone()).await;
                    return Ok(());
                };

                if !cfg.is_open {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(format!("{}: {}", cfg.gym_name, cfg.closed_reason))
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                // Check if user already in battle
                if battles.read().await.contains_key(&(user_id as u64)) {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text("You are already in a battle! Finish or forfeit your active battle first.")
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                // Check fee
                let pokedollars = get_user_pokedollars(pool, user_id as u64).await;
                if pokedollars < cfg.fee {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(format!("You don't have enough PokéDollars! Entry fee is {} PokéDollars.", cfg.fee))
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                // Load player's active team (all members in active team or up to 6 from storage)
                let active_team_num = get_user_active_team(pool, user_id as u64).await;
                let mut team_rows = sqlx::query(
                    "SELECT p.id, p.pokemon_id, p.nickname, p.level, p.nature, p.experience,
                            p.iv_hp, p.iv_attack, p.iv_defense, p.iv_sp_attack, p.iv_sp_defense, p.iv_speed,
                            p.ev_hp, p.ev_attack, p.ev_defense, p.ev_sp_attack, p.ev_sp_defense, p.ev_speed,
                            p.move_1, p.move_2, p.move_3, p.move_4
                     FROM user_teams t
                     JOIN pokemons p ON t.pokemon_db_id = p.id
                     WHERE t.user_id = ? AND t.team_num = ?
                     ORDER BY t.slot ASC"
                )
                .bind(user_id)
                .bind(active_team_num as i64)
                .fetch_all(pool)
                .await
                .unwrap_or_default();

                if team_rows.is_empty() {
                    team_rows = sqlx::query(
                        "SELECT id, pokemon_id, nickname, level, nature, experience,
                                iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                                ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                                move_1, move_2, move_3, move_4
                         FROM pokemons WHERE user_id = ? ORDER BY id ASC LIMIT 6"
                    )
                    .bind(user_id)
                    .fetch_all(pool)
                    .await
                    .unwrap_or_default();
                }

                if team_rows.is_empty() {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text("You don't have any Pokémon to battle with! Choose one with /start.")
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                let mut player_team = Vec::new();
                for r in &team_rows {
                    if let Some(p) = parse_player_battle_pokemon(r, pokedex, pool).await {
                        player_team.push(p);
                    }
                }

                if player_team.is_empty() {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text("Error loading Pokémon data.")
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                // Strictly validate player's team against Gym battle rules
                if let Err(violation) = validate_player_team_for_gym(&player_team, &cfg.rules_config, pokedex) {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text(violation)
                        .show_alert(true)
                        .await;
                    return Ok(());
                }

                let player_pkmn = player_team.remove(0);

                let mut leader_team = create_dynamic_gym_leader_team(&cfg, pokedex);
                if leader_team.is_empty() {
                    let _ = bot
                        .answer_callback_query(q.id.clone())
                        .text("Error loading Gym Leader Pokémon data.")
                        .show_alert(true)
                        .await;
                    return Ok(());
                }
                let leader_pkmn = leader_team.remove(0);
                let remaining_team = leader_team;

                // Deduct entry fee
                let _ = sqlx::query("UPDATE users SET pokedollars = pokedollars - ? WHERE id = ?")
                    .bind(cfg.fee)
                    .bind(user_id)
                    .execute(pool)
                    .await;

                let _ = bot
                    .answer_callback_query(q.id.clone())
                    .text(format!("Battle against Gym Leader {} has begun!", cfg.leader_name))
                    .await;

                // Send battle as another (new) message
                let player_name = q.from.first_name.clone();
                let header = format!("Gym Leader {} challenges you to a battle!", cfg.leader_name);
                let battle_text = format_gym_battle_screen(
                    &header,
                    &cfg.leader_name,
                    &leader_pkmn,
                    &player_pkmn,
                    &player_name,
                    user_id as u64,
                );
                let battle_kb = build_gym_battle_keyboard(user_id as u64, &player_pkmn.moves);

                let sent_msg = bot
                    .send_message(chat_id, battle_text)
                    .parse_mode(ParseMode::Html)
                    .reply_markup(battle_kb)
                    .await?;

                let active_battle = ActiveBattle {
                    owner_id: user_id as u64,
                    chat_id,
                    message_id: sent_msg.id,
                    trainer_name: player_name,
                    player_pokemon: player_pkmn,
                    wild_pokemon: leader_pkmn,
                    turn_count: 0,
                    last_action: header,
                    fainted_pokemon_ids: Vec::new(),
                    fainted_team_indices: Vec::new(),
                    team_hp: HashMap::new(),
                    is_evtrain: false,
                    gym_info: Some(ActiveGymBattle {
                        region: region_name.to_string(),
                        gym_num,
                        leader_name: cfg.leader_name.clone(),
                        badge: cfg.reward_badge.clone(),
                        fee: cfg.fee,
                        reward_money: cfg.reward_money,
                        remaining_team,
                        rewards_config: cfg.rewards_config.clone(),
                        turns_since_switch: 2,
                    }),
                    last_activity: chrono::Utc::now(),
                };

                battles.write().await.insert(user_id as u64, active_battle);
                return Ok(());
            }
            _ => {}
        }
    }

    let _ = bot.answer_callback_query(q.id.clone()).await;
    Ok(())
}

async fn handle_evtrain(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    battles: BattleSessions,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username.as_deref())
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let starter_row = sqlx::query("SELECT starter_id FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let has_starter = match &starter_row {
        Ok(Some(row)) => row.try_get::<i64, _>("starter_id").is_ok(),
        _ => false,
    };

    if !has_starter {
        bot.send_message(
            msg.chat.id,
            "Please pick your starter Pokémon first using /start!",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if battles.read().await.contains_key(&user_id) {
        bot.send_message(
            msg.chat.id,
            "You are already in a battle! Finish or run from your current battle before entering EV Training.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let is_safari: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM user_safari WHERE user_id = ? AND is_active = 1)"
    )
    .bind(user_id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(false);

    if is_safari {
        bot.send_message(
            msg.chat.id,
            "You are currently in the Safari Zone! Use /exit to leave before entering EV Training.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let is_evtrain_active: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM user_evtrain WHERE user_id = ? AND is_active = 1)"
    )
    .bind(user_id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(false);

    if is_evtrain_active {
        bot.send_message(
            msg.chat.id,
            "You are already EV Training! Use /hunt to find Pokémon or /exit to leave.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let text = "Battle wild Pokémon to increase Effort Values (EVs)\n\n\
<u>Instructions</u>\n\
• /travel to the Region where you want to EV Train.\n\
• You cannot capture any of the wild Pokémon, you must only battle them.\n\
• You will not receive any Poké Dollars for defeating a wild Pokémon.\n\
• You will have a 50 /hunt limit before the EV Training session is finished.\n\n\
Entry fee: 50 💵";

    let keyboard = InlineKeyboardMarkup::new(vec![vec![
        InlineKeyboardButton::callback("Begin Training", format!("evtrain_begin:{}", user_id)),
    ]]);

    bot.send_message(msg.chat.id, text)
        .parse_mode(ParseMode::Html)
        .reply_markup(keyboard)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;

    Ok(())
}

pub async fn award_evs_to_pokemon(
    pool: &SqlitePool,
    pokemon_db_id: Option<i64>,
    wild_entry: &PokemonEntry,
) {
    let Some(db_id) = pokemon_db_id else { return; };
    let row = sqlx::query(
        "SELECT ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed
         FROM pokemons WHERE id = ?"
    )
    .bind(db_id)
    .fetch_optional(pool)
    .await;

    let Ok(Some(r)) = row else { return; };

    let mut ev_hp: i32 = r.try_get("ev_hp").unwrap_or(0);
    let mut ev_atk: i32 = r.try_get("ev_attack").unwrap_or(0);
    let mut ev_def: i32 = r.try_get("ev_defense").unwrap_or(0);
    let mut ev_spa: i32 = r.try_get("ev_sp_attack").unwrap_or(0);
    let mut ev_spd: i32 = r.try_get("ev_sp_defense").unwrap_or(0);
    let mut ev_spe: i32 = r.try_get("ev_speed").unwrap_or(0);

    let mut total_ev = ev_hp + ev_atk + ev_def + ev_spa + ev_spd + ev_spe;
    const MAX_TOTAL_EV: i32 = 510;
    const MAX_SINGLE_EV: i32 = 252;

    let gains = [
        ("hp", get_pokemon_ev_yield_stat(wild_entry, "hp")),
        ("atk", get_pokemon_ev_yield_stat(wild_entry, "atk")),
        ("def", get_pokemon_ev_yield_stat(wild_entry, "def")),
        ("spa", get_pokemon_ev_yield_stat(wild_entry, "spa")),
        ("spd", get_pokemon_ev_yield_stat(wild_entry, "spd")),
        ("spe", get_pokemon_ev_yield_stat(wild_entry, "spe")),
    ];

    for (stat, yield_val) in gains {
        if yield_val <= 0 {
            continue;
        }
        let (stat_ref, col) = match stat {
            "hp" => (&mut ev_hp, "ev_hp"),
            "atk" => (&mut ev_atk, "ev_attack"),
            "def" => (&mut ev_def, "ev_defense"),
            "spa" => (&mut ev_spa, "ev_sp_attack"),
            "spd" => (&mut ev_spd, "ev_sp_defense"),
            "spe" => (&mut ev_spe, "ev_speed"),
            _ => continue,
        };
        let room_in_stat = (MAX_SINGLE_EV - *stat_ref).max(0);
        let room_total = (MAX_TOTAL_EV - total_ev).max(0);
        let add = yield_val.min(room_in_stat).min(room_total);
        if add > 0 {
            *stat_ref += add;
            total_ev += add;
            let query = format!("UPDATE pokemons SET {} = ? WHERE id = ?", col);
            let _ = sqlx::query(&query).bind(*stat_ref).bind(db_id).execute(pool).await;
        }
    }
}

pub const MAX_TRAINER_LEVEL: i32 = 10_000_000;
pub const MAX_TRAINER_EXP: i64 = 1_099_999_900_000;

pub fn req_exp_for_rank(rank: i32) -> i32 {
    if rank < 0 || rank >= MAX_TRAINER_LEVEL {
        0
    } else {
        match rank {
            0 => 50_000,
            1 => 60_000,
            2 => 80_000,
            3 => 100_000,
            4 => 110_000,
            5 => 120_000,
            6 => 130_000,
            7 => 140_000,
            8 => 100_000,
            _ => 110_000,
        }
    }
}

pub fn cumulative_exp_for_rank(rank: i32) -> i64 {
    let r = rank.clamp(0, MAX_TRAINER_LEVEL);
    if r <= 10 {
        match r {
            0 => 0,
            1 => 50_000,
            2 => 110_000,
            3 => 190_000,
            4 => 290_000,
            5 => 400_000,
            6 => 520_000,
            7 => 650_000,
            8 => 790_000,
            9 => 890_000,
            10 => 1_000_000,
            _ => 0,
        }
    } else {
        1_000_000 + ((r - 10) as i64) * 110_000
    }
}

pub fn get_total_cumulative_exp(rank: i32, current_exp: i32) -> i64 {
    if rank >= MAX_TRAINER_LEVEL {
        return cumulative_exp_for_rank(MAX_TRAINER_LEVEL);
    }
    let base = cumulative_exp_for_rank(rank);
    (base + (current_exp.max(0) as i64)).min(cumulative_exp_for_rank(MAX_TRAINER_LEVEL))
}

pub fn calculate_to_next_rank_exp(rank: i32, exp: i32) -> i32 {
    if rank >= MAX_TRAINER_LEVEL {
        0
    } else {
        (req_exp_for_rank(rank) - exp.max(0)).max(0)
    }
}

pub fn format_commas<T: std::fmt::Display>(val: T) -> String {
    let s = val.to_string();
    let is_neg = s.starts_with('-');
    let digits = if is_neg { &s[1..] } else { &s[..] };
    let mut res = String::new();
    let len = digits.len();
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            res.push(',');
        }
        res.push(c);
    }
    if is_neg { format!("-{}", res) } else { res }
}

pub fn format_more_stats_message(
    wins: i32,
    losses: i32,
    pokeballs_used: i64,
    pokemon_caught: i64,
    pokemon_seen: i64,
    pokemon_obtained: i64,
) -> String {
    let wl_ratio = if losses > 0 {
        format!("{:.2}", wins as f64 / losses as f64)
    } else if wins > 0 {
        format!("{:.2}", wins as f64)
    } else {
        "0.00".to_string()
    };

    let catch_rate = if pokeballs_used > 0 {
        format!("{:.2}%", (pokemon_caught as f64 / pokeballs_used as f64) * 100.0)
    } else {
        "0.00%".to_string()
    };

    format!(
        "Win/Loss ratio: {}\n\
         Total poke balls used: {}\n\
         Total pokemon caught: {}\n\
         Catch success rate: {}\n\
         Pokemon seen: {} / 1025\n\
         Pokemon obtained ★: {} / 1025",
        wl_ratio,
        pokeballs_used,
        pokemon_caught,
        catch_rate,
        pokemon_seen,
        pokemon_obtained,
    )
}

#[derive(Debug, Clone, PartialEq)]
pub struct TrainerExpResult {
    pub old_rank: i32,
    pub new_rank: i32,
    pub leveled_up: bool,
    pub current_exp: i32,
    pub req_exp: i32,
    pub total_cumulative_exp: i64,
    pub newly_unlocked_regions: Vec<String>,
}

pub async fn add_trainer_exp(
    pool: &SqlitePool,
    user_id: i64,
    exp_gain: i32,
) -> Result<TrainerExpResult, sqlx::Error> {
    let row = sqlx::query(
        "SELECT trainer_level, trainer_exp, unlocked_regions FROM users WHERE id = ?"
    )
    .bind(user_id)
    .fetch_one(pool)
    .await?;

    let mut rank: i32 = row.try_get("trainer_level").unwrap_or(0);
    let mut exp: i32 = row.try_get("trainer_exp").unwrap_or(0);
    let unlocked_str: String = row.try_get("unlocked_regions").unwrap_or_else(|_| "Kanto".to_string());

    let old_rank = rank;
    let mut leveled_up = false;

    if rank < MAX_TRAINER_LEVEL && exp_gain > 0 {
        exp += exp_gain;
        while rank < MAX_TRAINER_LEVEL {
            let req = req_exp_for_rank(rank);
            if exp >= req {
                exp -= req;
                rank += 1;
                leveled_up = true;
            } else {
                break;
            }
        }
        if rank >= MAX_TRAINER_LEVEL {
            rank = MAX_TRAINER_LEVEL;
            exp = 0;
        }
    }

    let all_unlocked = get_unlocked_regions_for_level(rank.max(0) as u32);
    let mut current_unlocked_list: Vec<String> = unlocked_str
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect();

    let mut newly_unlocked = Vec::new();
    for r in &all_unlocked {
        if !current_unlocked_list.iter().any(|c| c.eq_ignore_ascii_case(r)) {
            newly_unlocked.push(r.to_string());
            current_unlocked_list.push(r.to_string());
        }
    }

    let new_unlocked_str = current_unlocked_list.join(",");

    sqlx::query(
        "UPDATE users SET trainer_level = ?, trainer_exp = ?, unlocked_regions = ? WHERE id = ?"
    )
    .bind(rank)
    .bind(exp)
    .bind(&new_unlocked_str)
    .bind(user_id)
    .execute(pool)
    .await?;

    if old_rank < 3 && rank >= 3 {
        let _ = process_referral_rank_up(pool, user_id).await;
    }

    let total_cumulative = get_total_cumulative_exp(rank, exp);
    let req = req_exp_for_rank(rank);

    Ok(TrainerExpResult {
        old_rank,
        new_rank: rank,
        leveled_up,
        current_exp: exp,
        req_exp: req,
        total_cumulative_exp: total_cumulative,
        newly_unlocked_regions: newly_unlocked,
    })
}

fn format_adventure_date(created_at: &str) -> String {
    let raw = created_at.trim();
    if raw.is_empty() {
        return chrono::Local::now().format("%b %d, %Y").to_string();
    }
    let clean = raw.split('.').next().unwrap_or(raw);
    if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(clean, "%Y-%m-%d %H:%M:%S") {
        return dt.format("%b %d, %Y").to_string();
    }
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(clean) {
        return dt.format("%b %d, %Y").to_string();
    }
    if let Ok(date) = chrono::NaiveDate::parse_from_str(clean, "%Y-%m-%d") {
        return date.format("%b %d, %Y").to_string();
    }
    chrono::Local::now().format("%b %d, %Y").to_string()
}

async fn generate_card_image(
    user_id: i64,
    rank: i32,
    exp: i64,
    to_next: i32,
    wins: i32,
    losses: i32,
    date: &str,
    avatar: &str,
    badges: i32,
    theme: &str,
    text_color: &str,
    output_path: &str,
) -> Result<(), String> {
    let python_candidates = [
        "C:\\Users\\kalaw\\OneDrive\\Desktop\\autohexa\\.venv\\Scripts\\python.exe",
        "py",
        "python",
        "python3",
        "C:\\Users\\kalaw\\AppData\\Local\\Programs\\Python\\Python314\\python.exe",
    ];

    let mut last_err = String::new();
    for py_bin in &python_candidates {
        let output = tokio::process::Command::new(py_bin)
            .arg("assets/generate_trainer_card.py")
            .arg("--user-id")
            .arg(user_id.to_string())
            .arg("--rank")
            .arg(rank.to_string())
            .arg("--exp")
            .arg(exp.to_string())
            .arg("--to-next")
            .arg(to_next.to_string())
            .arg("--wins")
            .arg(wins.to_string())
            .arg("--losses")
            .arg(losses.to_string())
            .arg("--date")
            .arg(date)
            .arg("--avatar")
            .arg(avatar)
            .arg("--badges")
            .arg(badges.to_string())
            .arg("--theme")
            .arg(theme)
            .arg("--text-color")
            .arg(text_color)
            .arg("--output")
            .arg(output_path)
            .output()
            .await;

        match output {
            Ok(out) if out.status.success() => return Ok(()),
            Ok(out) => {
                let stderr = String::from_utf8_lossy(&out.stderr);
                last_err = format!("Exit status: {} | {}", out.status, stderr);
            }
            Err(e) => last_err = format!("Failed to spawn {}: {}", py_bin, e),
        }
    }

    Err(last_err)
}

