pub fn resolve_theme_index(theme_str: &str) -> u32 {
    let s = theme_str.trim();
    if let Ok(num) = s.parse::<u32>() {
        if (1..=10).contains(&num) {
            return num;
        }
    }
    for (i, name) in CARD_THEME_NAMES.iter().enumerate() {
        if name.eq_ignore_ascii_case(s) {
            return (i + 1) as u32;
        }
    }
    10
}

pub fn resolve_text_color_index(color_str: &str) -> u32 {
    let s = color_str.trim();
    if let Ok(num) = s.parse::<u32>() {
        if (1..=20).contains(&num) {
            return num;
        }
    }
    for (i, name) in CARD_TEXT_COLOR_NAMES.iter().enumerate() {
        if name.eq_ignore_ascii_case(s) {
            return (i + 1) as u32;
        }
    }
    20
}

pub fn resolve_avatar_index(avatar_str: &str) -> u32 {
    let s = avatar_str.trim();
    if let Ok(num) = s.parse::<u32>() {
        if (1..=30).contains(&num) {
            return num;
        }
    }
    let lower = s.to_lowercase();
    let file_only = lower.trim_start_matches("assets/avatars/").trim_start_matches("assets\\avatars\\");
    for (i, file) in CARD_AVATAR_FILES.iter().enumerate() {
        if file.eq_ignore_ascii_case(file_only) || file.trim_end_matches(".png").eq_ignore_ascii_case(file_only.trim_end_matches(".png")) {
            return (i + 1) as u32;
        }
    }
    if lower.contains("captain") {
        return 28;
    }
    if lower.contains("drake") {
        return 27;
    }
    if lower.contains("trainer_boy") || lower.contains("trainer boy") {
        return 25;
    }
    if lower.contains("trainer_girl") || lower.contains("trainer girl") {
        return 26;
    }
    if lower.contains("brendan") {
        return 10;
    }
    28
}

