async fn safe_edit_media(
    bot: &Bot,
    chat_id: ChatId,
    message_id: MessageId,
    photo_path: &str,
    caption: String,
    keyboard: InlineKeyboardMarkup,
) -> ResponseResult<()> {
    let media = InputMedia::Photo(
        InputMediaPhoto::new(InputFile::file(std::path::Path::new(photo_path)))
            .caption(caption.clone())
            .parse_mode(ParseMode::Html),
    );
    let edit_res = bot
        .edit_message_media(chat_id, message_id, media)
        .reply_markup(keyboard.clone())
        .await;

    // Clean up temporary photo file to avoid accumulating unnecessary disk storage
    let _ = tokio::fs::remove_file(photo_path).await;

    if let Err(e) = edit_res {
        let s = e.to_string();
        if !s.contains("message is not modified") {
            tracing::warn!("Failed to edit message media: {}", s);
            let _ = safe_edit_caption(bot, chat_id, message_id, caption, keyboard).await;
        }
    }
    Ok(())
}

async fn handle_mystats(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    // Ensure user row exists with defaults
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    // Check if user has picked a starter
    let starter_row = sqlx::query("SELECT starter_id, created_at FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let has_starter = match &starter_row {
        Ok(Some(row)) => row.try_get::<i64, _>("starter_id").is_ok(),
        _ => false,
    };

    if !has_starter {
        bot.send_message(
            msg.chat.id,
            "Please pick your starter Pokémon first using /start!",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    // Retrieve stats
    let user_row = sqlx::query(
        "SELECT trainer_level, trainer_exp, wins, losses, badges_count, avatar, card_theme, card_text_color, created_at FROM users WHERE id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await;

    let (rank, exp, wins, losses, badges, avatar, theme, text_color, created_at_str) = if let Ok(Some(row)) = user_row {
        let r: i32 = row.try_get("trainer_level").unwrap_or(0);
        let e: i32 = row.try_get("trainer_exp").unwrap_or(0);
        let w: i32 = row.try_get("wins").unwrap_or(0);
        let l: i32 = row.try_get("losses").unwrap_or(0);
        let b: i32 = row.try_get("badges_count").unwrap_or(0);
        let a: String = row.try_get("avatar").unwrap_or_else(|_| "assets/avatars/captain.png".to_string());
        let t: String = row.try_get("card_theme").unwrap_or_else(|_| "Bronze Copper".to_string());
        let tc: String = row.try_get("card_text_color").unwrap_or_else(|_| "Bronze Gold".to_string());
        let c: String = row.try_get("created_at").unwrap_or_else(|_| "".to_string());
        (r, e, w, l, b, a, t, tc, c)
    } else {
        (0, 0, 0, 0, 0, "assets/avatars/captain.png".to_string(), "Bronze Copper".to_string(), "Bronze Gold".to_string(), "".to_string())
    };

    let date_str = format_adventure_date(&created_at_str);
    let to_next = calculate_to_next_rank_exp(rank, exp);
    let total_exp = get_total_cumulative_exp(rank, exp);

    let temp_dir = std::env::temp_dir().join("ozone_trainer_cards");
    let _ = tokio::fs::create_dir_all(&temp_dir).await;
    let card_file_path = temp_dir.join(format!("{}.png", user_id));
    let card_file_path_str = card_file_path.to_string_lossy().to_string();

    // Call Python Pillow script to generate the trainer card image
    if let Err(e) = generate_card_image(
        user_id as i64,
        rank,
        total_exp,
        to_next,
        wins,
        losses,
        &date_str,
        &avatar,
        badges,
        &theme,
        &text_color,
        &card_file_path_str,
    ).await {
        tracing::error!("Failed to generate trainer card: {}", e);
        bot.send_message(msg.chat.id, "Failed to generate your trainer card. Please try again later.")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let keyboard = InlineKeyboardMarkup::new(vec![vec![
        InlineKeyboardButton::callback("More Stats", format!("mystats_more:{}", user_id)),
    ]]);

    let send_res = bot.send_photo(msg.chat.id, InputFile::file(&card_file_path))
        .reply_markup(keyboard)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await;

    // Clean up temporary card image immediately after sending to free disk space
    let _ = tokio::fs::remove_file(&card_file_path).await;

    send_res?;

    Ok(())
}

