async fn handle_hunt(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    battles: BattleSessions,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    if !msg.chat.is_private() {
        let kb = build_dm_redirect_kb("hunt", "Hunt in DM");
        bot.send_message(msg.chat.id, "You can only hunt in DMs")
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    if battles.read().await.contains_key(&user_id) || is_user_in_battle(user_id).await {
        bot.send_message(
            msg.chat.id,
            "You can't hunt while battling",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if is_user_in_any_challenge(user_id).await {
        bot.send_message(
            msg.chat.id,
            "You can't hunt while in a challenge",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if is_user_in_any_trade(user_id).await {
        bot.send_message(
            msg.chat.id,
            "You can't hunt while trading",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    // Ensure user exists in database
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username.as_deref())
    .bind(&first_name)
    .execute(&*pool)
    .await;

    // Check if user has picked a starter
    let starter_row = sqlx::query("SELECT starter_id FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let has_starter = match &starter_row {
        Ok(Some(row)) => row.try_get::<i64, _>("starter_id").is_ok(),
        _ => false,
    };

    if !has_starter {
        bot.send_message(
            msg.chat.id,
            "Please pick your starter Pokémon first using /start!",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    // Check if user is in EV Training
    let evtrain_session: Option<(i32, String, i32, i32, String)> = sqlx::query_as(
        "SELECT is_active, stat, hunts_used, max_hunts, region FROM user_evtrain WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await
    .unwrap_or(None);

    if let Some((1, ev_stat, hunts_used, max_hunts, ev_region)) = evtrain_session {
        if hunts_used >= max_hunts {
            let _ = sqlx::query("UPDATE user_evtrain SET is_active = 0 WHERE user_id = ?")
                .bind(user_id as i64)
                .execute(&*pool)
                .await;
            bot.send_message(
                msg.chat.id,
                "You have reached the 50 /hunt limit! Your EV Training session has ended.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }

        let new_hunts_used = hunts_used + 1;
        let _ = sqlx::query("UPDATE user_evtrain SET hunts_used = hunts_used + 1 WHERE user_id = ?")
            .bind(user_id as i64)
            .execute(&*pool)
            .await;

        let (wild, is_shiny) = match pokedex.select_evtrain_pokemon(&ev_region, &ev_stat) {
            Some((p, s)) => (p, s),
            None => {
                bot.send_message(msg.chat.id, "No suitable Pokémon found for EV Training.")
                    .reply_parameters(ReplyParameters::new(msg.id))
                    .await?;
                return Ok(());
            }
        };

        let player_level = get_user_player_level(&pool, user_id).await;
        let level: u32 = generate_wild_pokemon_level(wild, player_level);

        let _ = sqlx::query("UPDATE users SET pokemon_seen = MIN(pokemon_seen + 1, 1025) WHERE id = ?")
            .bind(user_id as i64)
            .execute(&*pool)
            .await;
        let _ = sqlx::query("INSERT OR IGNORE INTO user_seen_pokemon (user_id, pokemon_id) VALUES (?, ?)")
            .bind(user_id as i64)
            .bind(wild.id as i64)
            .execute(&*pool)
            .await;

        let already_caught: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM pokemons WHERE user_id = ? AND pokemon_id = ?)"
        )
        .bind(user_id as i64)
        .bind(wild.id as i64)
        .fetch_one(&*pool)
        .await
        .unwrap_or(false);

        let hatched = process_egg_step_on_hunt(&pool, &pokedex, user_id).await;

        let caption = format_evtrain_hunt_caption(
            &wild.name,
            level,
            is_shiny,
            already_caught,
            new_hunts_used,
            max_hunts,
            &format_evtrain_yield_display(wild, &ev_stat),
        );

        let keyboard = InlineKeyboardMarkup::new(vec![vec![
            InlineKeyboardButton::callback(
                "Battle",
                format!("hunt_btl:{}:{}:{}:{}", user_id, wild.id, level, if is_shiny { 1 } else { 0 }),
            ),
        ]]);

        let photo_path = if is_shiny {
            let shiny_p = format!("assets/pokemon_shiny/{}.png", wild.id);
            if std::path::Path::new(&shiny_p).exists() {
                shiny_p
            } else {
                format!("assets/pokemon/{}.png", wild.id)
            }
        } else {
            format!("assets/pokemon/{}.png", wild.id)
        };

        let photo_file = std::path::Path::new(&photo_path);

        let sent_msg = if photo_file.exists() {
            bot.send_photo(msg.chat.id, InputFile::file(photo_file))
                .caption(caption)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?
        } else {
            bot.send_message(msg.chat.id, caption)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?
        };

        if let Some(hatched_pkmn) = hatched {
            let hatch_emoji = crate::emoji::get_hatched_egg_emoji(true);
            let hatch_text = format!(
                "{} Oh? Your Egg hatched into a <b>{}</b> (Lv. 5)!",
                hatch_emoji,
                format_pokemon_name(&hatched_pkmn.name)
            );
            let hatch_kb = build_caught_pokemon_keyboard(user_id, hatched_pkmn.db_id, hatched_pkmn.pokemon_id);
            let _ = bot.send_message(msg.chat.id, hatch_text)
                .parse_mode(ParseMode::Html)
                .reply_markup(hatch_kb)
                .await;
        }

        let prev_hunt = sqlx::query(
            "SELECT chat_id, message_id FROM active_hunts WHERE user_id = ?"
        )
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

        if let Ok(Some(row)) = prev_hunt {
            let old_chat_id: i64 = row.get("chat_id");
            let old_message_id: i64 = row.get("message_id");

            let _ = sqlx::query(
                "INSERT OR IGNORE INTO consumed_encounters (chat_id, message_id) VALUES (?, ?)"
            )
            .bind(old_chat_id)
            .bind(old_message_id)
            .execute(&*pool)
            .await;

            let _ = safe_edit_reply_markup(
                &bot,
                ChatId(old_chat_id),
                MessageId(old_message_id as i32),
                InlineKeyboardMarkup::default(),
            )
            .await;
        }

        let _ = sqlx::query(
            "INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, ?, ?)
             ON CONFLICT(user_id) DO UPDATE SET chat_id = excluded.chat_id, message_id = excluded.message_id"
        )
        .bind(user_id as i64)
        .bind(msg.chat.id.0)
        .bind(sent_msg.id.0 as i64)
        .execute(&*pool)
        .await;

        return Ok(());
    }

    // Check if user is in Safari Zone
    let safari_session: Option<(i32, i32, i32, String)> = sqlx::query_as(
        "SELECT is_active, balls_remaining, hunts_used, region FROM user_safari WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await
    .unwrap_or(None);

    if let Some((1, balls_remaining, hunts_used, safari_region)) = safari_session {
        if balls_remaining <= 0 {
            let _ = sqlx::query("UPDATE user_safari SET is_active = 0 WHERE user_id = ?")
                .bind(user_id as i64)
                .execute(&*pool)
                .await;
            bot.send_message(
                msg.chat.id,
                "You have run out of Safari Balls! You have been escorted out of the Safari Zone.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }

        if hunts_used >= 150 {
            let _ = sqlx::query("UPDATE user_safari SET is_active = 0 WHERE user_id = ?")
                .bind(user_id as i64)
                .execute(&*pool)
                .await;
            bot.send_message(
                msg.chat.id,
                "You have reached the 150 /hunt limit! You have been escorted out of the Safari Zone.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }

        let new_hunts_used = hunts_used + 1;
        let _ = sqlx::query("UPDATE user_safari SET hunts_used = hunts_used + 1 WHERE user_id = ?")
            .bind(user_id as i64)
            .execute(&*pool)
            .await;

        let wild_slug = get_random_safari_pokemon(&safari_region);
        let wild = match pokedex.get_pokemon_by_name(wild_slug) {
            Some(p) => p,
            None => {
                match pokedex.select_wild_pokemon(&safari_region) {
                    Some((p, _)) => p,
                    None => {
                        bot.send_message(msg.chat.id, "No wild Pokémon found in the Safari Zone.")
                            .reply_parameters(ReplyParameters::new(msg.id))
                            .await?;
                        return Ok(());
                    }
                }
            }
        };

        let player_level = get_user_player_level(&pool, user_id).await;
        let is_shiny = {
            let mut rng = rand::thread_rng();
            rng.gen_range(0..4096) == 0
        };
        let level: u32 = generate_wild_pokemon_level(wild, player_level);

        let _ = sqlx::query("UPDATE users SET pokemon_seen = MIN(pokemon_seen + 1, 1025) WHERE id = ?")
            .bind(user_id as i64)
            .execute(&*pool)
            .await;
        let _ = sqlx::query("INSERT OR IGNORE INTO user_seen_pokemon (user_id, pokemon_id) VALUES (?, ?)")
            .bind(user_id as i64)
            .bind(wild.id as i64)
            .execute(&*pool)
            .await;

        let already_caught: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM pokemons WHERE user_id = ? AND pokemon_id = ?)"
        )
        .bind(user_id as i64)
        .bind(wild.id as i64)
        .fetch_one(&*pool)
        .await
        .unwrap_or(false);

        let formatted_name = format_pokemon_name(&wild.name);
        let shiny_prefix = if is_shiny {
            format!("{} <b>", SHINY_EMOJI)
        } else {
            "<b>".to_string()
        };
        let star_suffix = if already_caught {
            format!(" {}", CAUGHT_STAR_EMOJI)
        } else {
            String::new()
        };

        let caption = format!(
            "A wild {}{}</b> (Lv. {}) has appeared{}\n\n/hunt limit: {}/150\nSafari Balls remaining: {}",
            shiny_prefix,
            formatted_name,
            level,
            star_suffix,
            new_hunts_used,
            balls_remaining
        );

        let keyboard = InlineKeyboardMarkup::new(vec![vec![
            InlineKeyboardButton::callback(
                "Catch",
                format!("safari_catch:{}:{}:{}:{}", user_id, wild.id, level, if is_shiny { 1 } else { 0 }),
            ),
            InlineKeyboardButton::callback("EV Yield", format!("hunt_ev:{}:{}", user_id, wild.id)),
        ]]);

        let photo_path = if is_shiny {
            let shiny_p = format!("assets/pokemon_shiny/{}.png", wild.id);
            if std::path::Path::new(&shiny_p).exists() {
                shiny_p
            } else {
                format!("assets/pokemon/{}.png", wild.id)
            }
        } else {
            format!("assets/pokemon/{}.png", wild.id)
        };

        let photo_file = std::path::Path::new(&photo_path);

        let sent_msg = if photo_file.exists() {
            bot.send_photo(msg.chat.id, InputFile::file(photo_file))
                .caption(caption)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?
        } else {
            bot.send_message(msg.chat.id, caption)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?
        };

        let prev_hunt = sqlx::query(
            "SELECT chat_id, message_id FROM active_hunts WHERE user_id = ?"
        )
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

        if let Ok(Some(row)) = prev_hunt {
            let old_chat_id: i64 = row.get("chat_id");
            let old_message_id: i64 = row.get("message_id");

            let _ = sqlx::query(
                "INSERT OR IGNORE INTO consumed_encounters (chat_id, message_id) VALUES (?, ?)"
            )
            .bind(old_chat_id)
            .bind(old_message_id)
            .execute(&*pool)
            .await;

            let _ = safe_edit_reply_markup(
                &bot,
                ChatId(old_chat_id),
                MessageId(old_message_id as i32),
                InlineKeyboardMarkup::default(),
            )
            .await;
        }

        let _ = sqlx::query(
            "INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, ?, ?)
             ON CONFLICT(user_id) DO UPDATE SET chat_id = excluded.chat_id, message_id = excluded.message_id"
        )
        .bind(user_id as i64)
        .bind(msg.chat.id.0)
        .bind(sent_msg.id.0 as i64)
        .execute(&*pool)
        .await;

        return Ok(());
    }

    // Retrieve user's current region
    let user_region_row = sqlx::query("SELECT current_region FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await;

    let region = match user_region_row {
        Ok(Some(row)) => row
            .try_get::<String, _>("current_region")
            .unwrap_or_else(|_| "Kanto".to_string()),
        _ => "Kanto".to_string(),
    };

    let (wild, is_shiny) = match pokedex.select_wild_pokemon(&region) {
        Some((p, s)) => (p, s),
        None => {
            bot.send_message(
                msg.chat.id,
                "No wild Pokémon found in this region. Try traveling with /travel!",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    };

    let player_level = get_user_player_level(&pool, user_id).await;
    let level: u32 = generate_wild_pokemon_level(wild, player_level);

    // Increment pokemon_seen in users table
    let _ = sqlx::query(
        "UPDATE users SET pokemon_seen = MIN(pokemon_seen + 1, 1025) WHERE id = ?"
    )
    .bind(user_id as i64)
    .execute(&*pool)
    .await;

    // Record seen pokemon in user_seen_pokemon
    let _ = sqlx::query(
        "INSERT OR IGNORE INTO user_seen_pokemon (user_id, pokemon_id) VALUES (?, ?)"
    )
    .bind(user_id as i64)
    .bind(wild.id as i64)
    .execute(&*pool)
    .await;

    // Check if user has already caught this pokemon at least once
    let already_caught: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM pokemons WHERE user_id = ? AND pokemon_id = ?)"
    )
    .bind(user_id as i64)
    .bind(wild.id as i64)
    .fetch_one(&*pool)
    .await
    .unwrap_or(false);

    let hatched = process_egg_step_on_hunt(&pool, &pokedex, user_id).await;

    let drops = {
        let mut rng = rand::thread_rng();
        roll_hunt_drops(&mut rng, &pokedex, &region)
    };
    if !drops.is_empty() {
        let _ = save_hunt_drops(&pool, user_id, &drops).await;
    }

    let mut caption = format_hunt_caption(&wild.name, level, is_shiny, already_caught);
    if !drops.is_empty() {
        let drops_text = format_hunt_drops_text(&drops);
        caption.push_str(&format!("\n\n{}", drops_text));
    }

    let keyboard = InlineKeyboardMarkup::new(vec![vec![
        InlineKeyboardButton::callback(
            "Battle",
            format!("hunt_btl:{}:{}:{}:{}", user_id, wild.id, level, if is_shiny { 1 } else { 0 }),
        ),
        InlineKeyboardButton::callback("EV Yield", format!("hunt_ev:{}:{}", user_id, wild.id)),
    ]]);

    let photo_path = if is_shiny {
        let shiny_p = format!("assets/pokemon_shiny/{}.png", wild.id);
        if std::path::Path::new(&shiny_p).exists() {
            shiny_p
        } else {
            format!("assets/pokemon/{}.png", wild.id)
        }
    } else {
        format!("assets/pokemon/{}.png", wild.id)
    };

    let photo_file = std::path::Path::new(&photo_path);

    let sent_msg = if photo_file.exists() {
        bot.send_photo(msg.chat.id, InputFile::file(photo_file))
            .caption(caption)
            .parse_mode(ParseMode::Html)
            .reply_markup(keyboard)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?
    } else {
        bot.send_message(msg.chat.id, caption)
            .parse_mode(ParseMode::Html)
            .reply_markup(keyboard)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?
    };

    if let Some(hatched_pkmn) = hatched {
        let hatch_emoji = crate::emoji::get_hatched_egg_emoji(true);
        let hatch_text = format!(
            "{} Oh? Your Egg hatched into a <b>{}</b> (Lv. 5)!",
            hatch_emoji,
            format_pokemon_name(&hatched_pkmn.name)
        );
        let hatch_kb = build_caught_pokemon_keyboard(user_id, hatched_pkmn.db_id, hatched_pkmn.pokemon_id);
        let _ = bot.send_message(msg.chat.id, hatch_text)
            .parse_mode(ParseMode::Html)
            .reply_markup(hatch_kb)
            .await;
    }

    // Invalidate previous active hunt for this user so old hunt will not work at all
    let prev_hunt = sqlx::query(
        "SELECT chat_id, message_id FROM active_hunts WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(&*pool)
    .await;

    if let Ok(Some(row)) = prev_hunt {
        let old_chat_id: i64 = row.get("chat_id");
        let old_message_id: i64 = row.get("message_id");

        let _ = sqlx::query(
            "INSERT OR IGNORE INTO consumed_encounters (chat_id, message_id) VALUES (?, ?)"
        )
        .bind(old_chat_id)
        .bind(old_message_id)
        .execute(&*pool)
        .await;

        let _ = safe_edit_reply_markup(
            &bot,
            ChatId(old_chat_id),
            MessageId(old_message_id as i32),
            InlineKeyboardMarkup::default(),
        )
        .await;
    }

    let _ = sqlx::query(
        "INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, ?, ?)
         ON CONFLICT(user_id) DO UPDATE SET chat_id = excluded.chat_id, message_id = excluded.message_id, created_at = CURRENT_TIMESTAMP"
    )
    .bind(user_id as i64)
    .bind(sent_msg.chat.id.0)
    .bind(sent_msg.id.0 as i64)
    .execute(&*pool)
    .await;

    Ok(())
}

async fn safe_edit_caption(
    bot: &Bot,
    chat_id: ChatId,
    message_id: MessageId,
    caption: String,
    keyboard: InlineKeyboardMarkup,
) -> ResponseResult<()> {
    if let Err(e) = bot
        .edit_message_caption(chat_id, message_id)
        .caption(caption.clone())
        .parse_mode(ParseMode::Html)
        .reply_markup(keyboard.clone())
        .await
    {
        let s = e.to_string();
        if s.contains("there is no caption in the message to edit") {
            let _ = bot
                .edit_message_text(chat_id, message_id, caption)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .await;
        } else if !s.contains("message is not modified") {
            tracing::warn!("Failed to edit caption: {}", s);
        }
    }
    Ok(())
}

async fn safe_edit_caption_with_json_fallback(
    bot: &Bot,
    chat_id: ChatId,
    message_id: MessageId,
    caption: String,
    custom_kb: serde_json::Value,
    fallback_kb: InlineKeyboardMarkup,
) -> ResponseResult<()> {
    let payload = serde_json::json!({
        "chat_id": chat_id.0,
        "message_id": message_id.0,
        "caption": caption,
        "parse_mode": "HTML",
        "reply_markup": custom_kb
    });

    let endpoint = format!("{}bot{}/editMessageCaption", bot.api_url(), bot.token());
    let mut edited = false;
    if let Ok(resp) = bot.client().post(&endpoint).json(&payload).send().await {
        if let Ok(json) = resp.json::<serde_json::Value>().await {
            if json.get("ok").and_then(|v| v.as_bool()) == Some(true) {
                edited = true;
            } else {
                let desc = json.get("description").and_then(|v| v.as_str()).unwrap_or("");
                if desc.contains("message is not modified") {
                    return Ok(());
                }
                tracing::warn!("Telegram rejected editMessageCaption with custom emoji: {}", desc);
            }
        }
    }

    if !edited {
        safe_edit_caption(bot, chat_id, message_id, caption, fallback_kb).await?;
    }

    Ok(())
}

