async fn handle_vitamin(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    target: String,
) -> ResponseResult<()> {
    let user = msg.from.as_ref();
    let user_id = user.map(|u| u.id.0).unwrap_or(0);

    let username = user.and_then(|u| u.username.clone());
    let first_name = user
        .map(|u| u.first_name.clone())
        .unwrap_or_else(|| "Trainer".to_string());

    // Ensure user row exists with defaults
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let query = target.trim();
    if !msg.chat.is_private() {
        let param = if query.is_empty() {
            "vitamin".to_string()
        } else {
            format!("vitamin_{}", query.replace(' ', "_"))
        };
        let kb = build_dm_redirect_kb(&param, "Give in DM");
        bot.send_message(msg.chat.id, "Give vitamin in DMs")
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    if is_user_in_battle(user_id).await {
        bot.send_message(msg.chat.id, "You can't use vitamins while battling")
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    if query.is_empty() {
        bot.send_message(msg.chat.id, "Format: /vitamin &lt;pokemon name&gt;")
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let rows = match fetch_matching_owned_pokemons(&pool, user_id, query, &pokedex).await {
        Ok(r) => r,
        Err(e) => {
            tracing::warn!("Database error fetching pokemon for vitamin: {}", e);
            return Ok(());
        }
    };

    if rows.len() == 1 {
        let row = &rows[0];
        let pokemon_db_id: i64 = row.get("id");
        let pokemon_id: i64 = row.get("pokemon_id");
        let nickname: String = row.get("nickname");
        let ev_hp: i32 = row.try_get("ev_hp").unwrap_or(0);
        let ev_atk: i32 = row.try_get("ev_attack").unwrap_or(0);
        let ev_def: i32 = row.try_get("ev_defense").unwrap_or(0);
        let ev_spa: i32 = row.try_get("ev_sp_attack").unwrap_or(0);
        let ev_spd: i32 = row.try_get("ev_sp_defense").unwrap_or(0);
        let ev_spe: i32 = row.try_get("ev_speed").unwrap_or(0);

        let vitamins: i64 = sqlx::query_scalar("SELECT vitamins FROM users WHERE id = ?")
            .bind(user_id as i64)
            .fetch_one(&*pool)
            .await
            .unwrap_or(100);

        let display_name = if !nickname.is_empty() {
            nickname
        } else {
            pokedex.get_pokemon_by_id(pokemon_id as u32).map(|p| p.name.clone()).unwrap_or_else(|| "Pokemon".to_string())
        };

        let text = format_vitamin_screen(&display_name, ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe, vitamins);
        send_vitamin_message(&bot, msg.chat.id, msg.id, pokemon_db_id, 1, &text).await?;
    } else if rows.len() > 1 {
        let (display_option, _) = get_user_display_settings(&pool, user_id).await;
        let (text, keyboard) = format_disambiguation_list(&rows, "Use vitamins on which pokemon?", "vit_sel_", &pokedex, display_option);
        bot.send_message(msg.chat.id, text)
            .parse_mode(ParseMode::Html)
            .reply_markup(keyboard)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
    } else {
        let pokedex_entry = pokedex.get_pokemon_by_name(query);
        if pokedex_entry.is_some() {
            bot.send_message(
                msg.chat.id,
                format!(
                    "You do not have a Pokémon matching '<b>{}</b>'.",
                    escape_html(query)
                ),
            )
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        } else if let Some(suggestion) = find_closest_pokemon_name(query, &pokedex) {
            let text = format!("Did you mean: <b>{}</b>?", escape_html(&suggestion));
            let keyboard = InlineKeyboardMarkup::new(vec![vec![
                InlineKeyboardButton::callback("Yes", format!("sug_vit_{}", suggestion)),
                InlineKeyboardButton::callback("No", "sug_no"),
            ]]);
            bot.send_message(msg.chat.id, text)
                .parse_mode(ParseMode::Html)
                .reply_markup(keyboard)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
        } else {
            bot.send_message(
                msg.chat.id,
                format!(
                    "Pokemon '<b>{}</b>' not found.",
                    escape_html(query)
                ),
            )
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        }
    }

    Ok(())
}

