async fn handle_evolve(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    target: String,
) -> ResponseResult<()> {
    let user = match msg.from.as_ref() {
        Some(u) => u,
        None => return Ok(()),
    };
    let user_id = user.id.0;
    let user_region: String = sqlx::query_scalar("SELECT current_region FROM users WHERE id = ?")
        .bind(user_id as i64)
        .fetch_optional(&*pool)
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| "Kanto".to_string());

    let target_trim = target.trim();
    if target_trim.is_empty() {
        let rows = sqlx::query(
            "SELECT id, pokemon_id, nickname, level FROM pokemons WHERE user_id = ?"
        )
        .bind(user_id as i64)
        .fetch_all(&*pool)
        .await
        .unwrap_or_default();

        let mut ready_list = Vec::new();
        for r in rows {
            let db_id: i64 = r.get("id");
            let pk_id: i64 = r.get("pokemon_id");
            let nick: String = r.get("nickname");
            let lvl: i32 = r.get("level");
            if let Some((_req, target_name, _to_id)) = check_evolution_ready_in_region(pk_id as u32, lvl, Some(&user_region)) {
                let disp_name = if !nick.is_empty() {
                    nick
                } else {
                    pokedex
                        .get_pokemon_by_id(pk_id as u32)
                        .map(|p| p.name.clone())
                        .unwrap_or_else(|| "Pokemon".to_string())
                };
                ready_list.push((db_id, disp_name, target_name));
            }
        }

        if ready_list.is_empty() {
            bot.send_message(msg.chat.id, "None of your Pokémon are currently ready to evolve.")
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            return Ok(());
        }

        if ready_list.len() == 1 {
            let (db_id, disp_name, _to_name) = &ready_list[0];
            let text = format_evolution_ready_message(disp_name);
            let kb = build_evolution_keyboard(*db_id);
            bot.send_message(msg.chat.id, text)
                .parse_mode(ParseMode::Html)
                .reply_markup(kb)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            return Ok(());
        }

        let mut buttons = Vec::new();
        for (db_id, disp_name, to_name) in ready_list {
            buttons.push(vec![InlineKeyboardButton::callback(
                format!("Evolve {} -> {}", disp_name, to_name),
                format!("poke_evolve:{}", db_id),
            )]);
        }
        bot.send_message(msg.chat.id, "Choose a Pokémon to evolve:")
            .reply_markup(InlineKeyboardMarkup::new(buttons))
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let rows = sqlx::query(
        "SELECT id, pokemon_id, nickname, level FROM pokemons WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_all(&*pool)
    .await
    .unwrap_or_default();

    let matched: Vec<_> = rows
        .into_iter()
        .filter(|r| {
            let pk_id: i64 = r.get("pokemon_id");
            let nick: String = r.get("nickname");
            let species_name = pokedex
                .get_pokemon_by_id(pk_id as u32)
                .map(|p| p.name.clone())
                .unwrap_or_default();
            nick.eq_ignore_ascii_case(target_trim)
                || species_name.eq_ignore_ascii_case(target_trim)
                || format!("Chibi {}", species_name).eq_ignore_ascii_case(target_trim)
        })
        .collect();

    if matched.is_empty() {
        bot.send_message(
            msg.chat.id,
            format!("You don't have a Pokémon named '{}'.", target_trim),
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let r = &matched[0];
    let db_id: i64 = r.get("id");
    let pk_id: i64 = r.get("pokemon_id");
    let nick: String = r.get("nickname");
    let lvl: i32 = r.get("level");
    let disp_name = if !nick.is_empty() {
        nick
    } else {
        pokedex
            .get_pokemon_by_id(pk_id as u32)
            .map(|p| p.name.clone())
            .unwrap_or_else(|| "Pokemon".to_string())
    };

    let base_pk_id = crate::evolution::get_base_species_id_for_chibi(pk_id as u32);
    if check_evolution_ready_in_region(pk_id as u32, lvl, Some(&user_region)).is_some() {
        let text = format_evolution_ready_message(&disp_name);
        let kb = build_evolution_keyboard(db_id);
        bot.send_message(msg.chat.id, text)
            .parse_mode(ParseMode::Html)
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
    } else if let Some((req_lvl, target_name, _to_id)) = get_evolution_for_region(base_pk_id, Some(&user_region)) {
        bot.send_message(
            msg.chat.id,
            format!(
                "<b>{}</b> needs to reach Lv. {} to evolve into <b>{}</b> (currently Lv. {}).",
                escape_html(&disp_name),
                req_lvl,
                escape_html(target_name),
                lvl
            ),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
    } else {
        bot.send_message(
            msg.chat.id,
            format!("<b>{}</b> cannot evolve further.", escape_html(&disp_name)),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
    }

    Ok(())
}

