#[derive(Debug, PartialEq, Eq)]
pub struct PokeGiveArgs {
    pub target_query: Option<String>,
    pub god_key: Option<String>,
    pub invalid_pokemon: Option<String>,
    pub force: bool,
}

pub fn get_creation_god_spec_flexible(key: &str) -> Option<&'static crate::halloween::CreationGodSpec> {
    let lower = key.to_lowercase();
    let trimmed = lower.trim();
    if trimmed.contains("giratina") {
        Some(&crate::halloween::CREATION_GOD_GIRATINA)
    } else if trimmed.contains("dialga") {
        Some(&crate::halloween::CREATION_GOD_DIALGA)
    } else if trimmed.contains("palkia") {
        Some(&crate::halloween::CREATION_GOD_PALKIA)
    } else {
        None
    }
}

pub fn parse_pokegive_args(input: &str) -> PokeGiveArgs {
    let mut target_query = None;
    let mut god_key = None;
    let mut invalid_pokemon = None;
    let mut force = false;

    let parts: Vec<&str> = input.split_whitespace().collect();
    for part in parts {
        let p_lower = part.to_lowercase();
        if p_lower == "--force" || p_lower == "-f" || p_lower == "force" {
            force = true;
            continue;
        }

        if let Some(spec) = get_creation_god_spec_flexible(&p_lower) {
            god_key = Some(spec.god_key.to_string());
            continue;
        }

        if part.starts_with('@') || (part.len() >= 6 && part.chars().all(|c| c.is_ascii_digit())) {
            let clean = part.trim_start_matches('@').to_string();
            target_query = Some(clean);
            continue;
        }

        if god_key.is_some() {
            if target_query.is_none() {
                target_query = Some(part.trim_start_matches('@').to_string());
            } else {
                invalid_pokemon = Some(part.to_string());
            }
        } else if target_query.is_some() {
            invalid_pokemon = Some(part.to_string());
        } else {
            invalid_pokemon = Some(part.to_string());
        }
    }

    if god_key.is_some() && target_query.is_none() && invalid_pokemon.is_some() {
        target_query = invalid_pokemon.take().map(|s| s.trim_start_matches('@').to_string());
    }

    PokeGiveArgs {
        target_query,
        god_key,
        invalid_pokemon,
        force,
    }
}

pub async fn execute_pokegive_command(
    pool: &SqlitePool,
    admin_id: u64,
    input: &str,
    reply_target: Option<(u64, Option<String>, String, bool)>,
) -> Result<String, String> {
    if !is_admin(admin_id) {
        return Err("<b>Access Denied:</b> You do not have administrator permissions to use this command.".to_string());
    }

    let args = parse_pokegive_args(input);

    if let Some(inv) = &args.invalid_pokemon {
        return Err(format!(
            "<code>{}</code> is not a Halloween Pokémon. This command only works for Halloween Pokémon (Giratina, Dialga, Palkia).",
            escape_html(inv)
        ));
    }

    let god_key = match args.god_key.as_deref() {
        Some(k) => k,
        None => {
            return Err("<b>Usage:</b> Reply to the winner's message with <code>/pokegive &lt;pokemon&gt;</code> or use <code>/pokegive &lt;username/id&gt; &lt;pokemon&gt;</code>\n\n<i>Note: This command only works for Halloween Pokémon: Giratina, Dialga, Palkia.</i>".to_string());
        }
    };

    let (target_id, target_name) = if let Some(target_query) = &args.target_query {
        let user_opt = find_user_by_username_or_id(pool, target_query)
            .await
            .map_err(|e| format!("Database error: {}", e))?;

        match user_opt {
            Some((id, username_opt, name_str, _)) => {
                let display = username_opt
                    .map(|u| format!("@{}", u))
                    .unwrap_or(name_str);
                (id, display)
            }
            None => {
                return Err(format!("Trainer <code>{}</code> not found.", escape_html(target_query)));
            }
        }
    } else if let Some((reply_id, reply_username, reply_first_name, is_bot)) = reply_target {
        if is_bot {
            return Err("You cannot give Pokémon to a bot.".to_string());
        }

        let _ = sqlx::query(
            "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
             ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
        )
        .bind(reply_id as i64)
        .bind(reply_username.as_deref())
        .bind(&reply_first_name)
        .execute(pool)
        .await;

        let display = reply_username
            .map(|u| format!("@{}", u))
            .unwrap_or(reply_first_name);
        (reply_id, display)
    } else {
        return Err("<b>Usage:</b> Reply to the winner's message with <code>/pokegive &lt;pokemon&gt;</code> or use <code>/pokegive &lt;username/id&gt; &lt;pokemon&gt;</code>\n\n<i>Note: This command only works for Halloween Pokémon: Giratina, Dialga, Palkia.</i>".to_string());
    };

    match crate::halloween::claim_creation_god_for_user(pool, target_id, god_key, &target_name, args.force).await {
        Ok((true, success_msg)) => Ok(success_msg),
        Ok((false, fail_reason)) => Err(fail_reason),
        Err(e) => Err(format!("Database error: {}", e)),
    }
}

