pub fn parse_give_args(input: &str) -> Option<(Option<String>, i64)> {
    let parts: Vec<&str> = input.split_whitespace().collect();
    if parts.is_empty() {
        return None;
    }
    if parts.len() == 1 {
        let amt_clean = parts[0].replace(',', "");
        let amt: i64 = amt_clean.parse().ok()?;
        return Some((None, amt));
    }
    let p0_clean = parts[0].replace(',', "");
    let p1_clean = parts[1].replace(',', "");

    if parts[0].starts_with('@') || p0_clean.parse::<i64>().is_err() {
        let amt: i64 = p1_clean.parse().ok()?;
        let target = parts[0].trim().trim_start_matches('@').to_string();
        return Some((Some(target), amt));
    }

    if parts[1].starts_with('@') || p1_clean.parse::<i64>().is_err() {
        let amt: i64 = p0_clean.parse().ok()?;
        let target = parts[1].trim().trim_start_matches('@').to_string();
        return Some((Some(target), amt));
    }

    let n0: i64 = p0_clean.parse().ok()?;
    let n1: i64 = p1_clean.parse().ok()?;
    if n1 > 1_000_000 && n0 <= 1_000_000 {
        Some((Some(n1.to_string()), n0))
    } else {
        Some((Some(n0.to_string()), n1))
    }
}

pub async fn execute_give_transfer(
    pool: &SqlitePool,
    sender_id: u64,
    target_id: u64,
    amount: i64,
) -> Result<(), &'static str> {
    if sender_id == target_id {
        return Err("You cannot send PokéDollars to yourself.");
    }
    if amount <= 0 {
        return Err("Please specify a valid amount of PokéDollars to give.");
    }

    // Check sender balance
    let sender_bal: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = ?")
        .bind(sender_id as i64)
        .fetch_optional(pool)
        .await
        .ok()
        .flatten()
        .unwrap_or(0);

    if sender_bal < amount {
        return Err("You do not have enough PokéDollars.");
    }

    // Transfer PokéDollars atomically
    let mut tx = match pool.begin().await {
        Ok(t) => t,
        Err(e) => {
            tracing::error!("Failed to begin transaction: {}", e);
            return Err("Failed to process transfer. Try again later.");
        }
    };

    let deduct_res = sqlx::query(
        "UPDATE users SET pokedollars = pokedollars - ? WHERE id = ? AND pokedollars >= ?",
    )
    .bind(amount)
    .bind(sender_id as i64)
    .bind(amount)
    .execute(&mut *tx)
    .await;

    match deduct_res {
        Ok(res) if res.rows_affected() > 0 => {
            let add_res = sqlx::query("UPDATE users SET pokedollars = pokedollars + ? WHERE id = ?")
                .bind(amount)
                .bind(target_id as i64)
                .execute(&mut *tx)
                .await;

            if let Err(e) = add_res {
                tracing::error!("Failed to credit recipient: {}", e);
                let _ = tx.rollback().await;
                return Err("Failed to process transfer. Try again later.");
            }

            if let Err(e) = tx.commit().await {
                tracing::error!("Failed to commit transfer: {}", e);
                return Err("Failed to process transfer. Try again later.");
            }

            Ok(())
        }
        _ => {
            let _ = tx.rollback().await;
            Err("You do not have enough PokéDollars.")
        }
    }
}

async fn handle_give(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    input: String,
) -> ResponseResult<()> {
    let sender_user = match msg.from.as_ref() {
        Some(u) => u,
        None => return Ok(()),
    };
    let sender_id = sender_user.id.0;
    let sender_username = sender_user.username.clone();
    let sender_first_name = sender_user.first_name.clone();

    // Ensure sender exists in DB
    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(sender_id as i64)
    .bind(sender_username)
    .bind(&sender_first_name)
    .execute(&*pool)
    .await;

    let parsed = parse_give_args(&input);
    let (target_query_opt, amount) = match parsed {
        Some((t, a)) => (t, a),
        None => {
            bot.send_message(
                msg.chat.id,
                "Please reply to a user's message with /give <amount> or use /give <user> <amount>.",
            )
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    };

    if amount <= 0 {
        bot.send_message(
            msg.chat.id,
            "Please specify a valid amount of PokéDollars to give.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    // Determine target recipient
    let target_id: u64 = if let Some(target_query) = target_query_opt {
        let user_opt = match find_user_by_username_or_id(&pool, &target_query).await {
            Ok(u) => u,
            Err(e) => {
                tracing::error!("Error finding user: {}", e);
                None
            }
        };
        match user_opt {
            Some((id, _, _, _)) => id,
            None => {
                bot.send_message(msg.chat.id, "User not found.")
                    .reply_parameters(ReplyParameters::new(msg.id))
                    .await?;
                return Ok(());
            }
        }
    } else if let Some(reply) = msg.reply_to_message() {
        let reply_user = match reply.from.as_ref() {
            Some(u) => u,
            None => {
                bot.send_message(
                    msg.chat.id,
                    "Cannot identify the recipient from this replied message.",
                )
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }
        };
        if reply_user.is_bot {
            bot.send_message(msg.chat.id, "You cannot send PokéDollars to a bot.")
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            return Ok(());
        }
        let t_id = reply_user.id.0;
        let _ = sqlx::query(
            "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
             ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
        )
        .bind(t_id as i64)
        .bind(reply_user.username.as_deref())
        .bind(&reply_user.first_name)
        .execute(&*pool)
        .await;
        t_id
    } else {
        bot.send_message(
            msg.chat.id,
            "Please reply to a user's message with /give <amount> or use /give <user> <amount>.",
        )
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    };

    match execute_give_transfer(&pool, sender_id, target_id, amount).await {
        Ok(()) => {
            bot.send_message(msg.chat.id, "Poke dollars sent")
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
        }
        Err(err_msg) => {
            bot.send_message(msg.chat.id, err_msg)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
        }
    }

    Ok(())
}

