pub fn format_trade_confirm_text(
    sender_name: &str,
    s_pk: &TradePokemonInfo,
    target_name: &str,
    t_pk: &TradePokemonInfo,
) -> String {
    let s_name_fmt = format_pokemon_name(&s_pk.nickname);
    let s_is_egg = s_pk.is_hatched || s_pk.nickname.trim().eq_ignore_ascii_case("egg");
    let s_egg_prefix = if s_is_egg {
        format!("{} ", crate::emoji::get_egg_emoji(true))
    } else {
        String::new()
    };
    let s_name_display = if s_pk.is_shiny {
        format!("{}{} <b>{}</b>", SHINY_EMOJI, s_egg_prefix, escape_html(&s_name_fmt))
    } else if s_is_egg {
        format!("{}<b>{}</b>", s_egg_prefix, escape_html(&s_name_fmt))
    } else {
        format!("<b>{}</b>", escape_html(&s_name_fmt))
    };
    let s_table = format_ivev_caption(
        s_pk.iv_hp, s_pk.iv_attack, s_pk.iv_defense, s_pk.iv_sp_attack, s_pk.iv_sp_defense, s_pk.iv_speed,
        s_pk.ev_hp, s_pk.ev_attack, s_pk.ev_defense, s_pk.ev_sp_attack, s_pk.ev_sp_defense, s_pk.ev_speed,
    );

    let t_name_fmt = format_pokemon_name(&t_pk.nickname);
    let t_is_egg = t_pk.is_hatched || t_pk.nickname.trim().eq_ignore_ascii_case("egg");
    let t_egg_prefix = if t_is_egg {
        format!("{} ", crate::emoji::get_egg_emoji(true))
    } else {
        String::new()
    };
    let t_name_display = if t_pk.is_shiny {
        format!("{}{} <b>{}</b>", SHINY_EMOJI, t_egg_prefix, escape_html(&t_name_fmt))
    } else if t_is_egg {
        format!("{}<b>{}</b>", t_egg_prefix, escape_html(&t_name_fmt))
    } else {
        format!("<b>{}</b>", escape_html(&t_name_fmt))
    };
    let t_table = format_ivev_caption(
        t_pk.iv_hp, t_pk.iv_attack, t_pk.iv_defense, t_pk.iv_sp_attack, t_pk.iv_sp_defense, t_pk.iv_speed,
        t_pk.ev_hp, t_pk.ev_attack, t_pk.ev_defense, t_pk.ev_sp_attack, t_pk.ev_sp_defense, t_pk.ev_speed,
    );

    format!(
        "{} wants to trade:\n{} - Lv. {} | Nature: {}\n{}\n\n{} wants to trade:\n{} - Lv. {} | Nature: {}\n{}\n\nBoth players must accept this trade",
        sender_name, s_name_display, s_pk.level, s_pk.nature, s_table,
        target_name, t_name_display, t_pk.level, t_pk.nature, t_table
    )
}

