pub async fn render_move_pokemon_picker(
    pool: &SqlitePool,
    pokedex: &PokedexData,
    user_id: u64,
    item_number: u32,
    move_name: &str,
    is_tutor: bool,
    target_page: usize,
) -> Result<Option<(String, serde_json::Value, InlineKeyboardMarkup)>, sqlx::Error> {
    let rows = sqlx::query(
        "SELECT id, pokemon_id, nickname, level, nature,
                iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed,
                ev_hp, ev_attack, ev_defense, ev_sp_attack, ev_sp_defense, ev_speed,
                is_shiny, is_hatched
         FROM pokemons
         WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_all(pool)
    .await?;

    if rows.is_empty() {
        return Ok(None);
    }

    let mut pokemons: Vec<PokemonDbRecord> = rows
        .into_iter()
        .map(|r| {
            let id: i64 = r.try_get("id").unwrap_or(0);
            let pokemon_id: i64 = r.try_get("pokemon_id").unwrap_or(1);
            let nickname: String = r.try_get("nickname").unwrap_or_else(|_| "Pokemon".to_string());
            let level: i32 = r.try_get("level").unwrap_or(5);
            let nature: String = r.try_get("nature").unwrap_or_else(|_| "Hardy".to_string());
            let iv_hp: i32 = r.try_get("iv_hp").unwrap_or(0);
            let iv_attack: i32 = r.try_get("iv_attack").unwrap_or(0);
            let iv_defense: i32 = r.try_get("iv_defense").unwrap_or(0);
            let iv_sp_attack: i32 = r.try_get("iv_sp_attack").unwrap_or(0);
            let iv_sp_defense: i32 = r.try_get("iv_sp_defense").unwrap_or(0);
            let iv_speed: i32 = r.try_get("iv_speed").unwrap_or(0);
            let ev_hp: i32 = r.try_get("ev_hp").unwrap_or(0);
            let ev_attack: i32 = r.try_get("ev_attack").unwrap_or(0);
            let ev_defense: i32 = r.try_get("ev_defense").unwrap_or(0);
            let ev_sp_attack: i32 = r.try_get("ev_sp_attack").unwrap_or(0);
            let ev_sp_defense: i32 = r.try_get("ev_sp_defense").unwrap_or(0);
            let ev_speed: i32 = r.try_get("ev_speed").unwrap_or(0);
            let is_shiny: i32 = r.try_get("is_shiny").unwrap_or(0);
            let is_hatched: i32 = r.try_get("is_hatched").unwrap_or(0);
            PokemonDbRecord {
                id,
                pokemon_id,
                nickname,
                level,
                nature,
                iv_hp,
                iv_attack,
                iv_defense,
                iv_sp_attack,
                iv_sp_defense,
                iv_speed,
                ev_hp,
                ev_attack,
                ev_defense,
                ev_sp_attack,
                ev_sp_defense,
                ev_speed,
                is_shiny: is_shiny == 1,
                is_hatched: is_hatched == 1,
            }
        })
        .collect();

    let (sort_option, sort_direction) = get_user_sort_settings(pool, user_id).await;
    let (display_option, _) = get_user_display_settings(pool, user_id).await;
    sort_pokemons(&mut pokemons, pokedex, sort_option, sort_direction);

    let total = pokemons.len();
    let page_size = get_user_page_size(pool, user_id).await;
    let total_pages = ((total as f64) / (page_size as f64)).ceil() as usize;
    let total_pages = total_pages.max(1);
    let clamped_page = target_page.clamp(1, total_pages);
    let offset = (clamped_page - 1) * page_size;

    let page_pokemons: Vec<PokemonDbRecord> = pokemons
        .into_iter()
        .skip(offset)
        .take(page_size)
        .collect();

    let mut lines = Vec::new();
    for (i, p) in page_pokemons.iter().enumerate() {
        let formatted_name = format_pokemon_name(&p.nickname);
        let is_egg = p.is_hatched || p.nickname.trim().eq_ignore_ascii_case("egg");
        let is_chibi = crate::evolution::is_chibi_id(p.pokemon_id as u32)
            || p.nickname.to_lowercase().starts_with("chibi ");
        let chibi_prefix = if is_chibi {
            format!("{} ", CHIBI_EMOJI)
        } else {
            String::new()
        };
        let icons = if p.is_shiny {
            if is_egg {
                format!("{}{} {} ", chibi_prefix, SHINY_EMOJI, crate::emoji::get_egg_emoji(true))
            } else {
                format!("{}{} ", chibi_prefix, SHINY_EMOJI)
            }
        } else if is_egg {
            format!("{}{} ", chibi_prefix, crate::emoji::get_egg_emoji(true))
        } else {
            chibi_prefix
        };

        let detail_str = match display_option {
            DisplayOption::None => String::new(),
            DisplayOption::Level => format!(" - Lv.{}", p.level),
            _ => {
                if let Some(d) = format_mypokemon_item_detail(p, pokedex, display_option) {
                    if d.starts_with("Level ") {
                        format!(" - Lv.{}", &d[6..])
                    } else {
                        format!(" - {}", d)
                    }
                } else {
                    String::new()
                }
            }
        };

        lines.push(format!("{}. {}<b>{}</b>{}", i + 1, icons, escape_html(&formatted_name), detail_str));
    }

    let text = format!(
        "Which Pokémon do you want to teach <b>{}</b>?\n\n{}\n\nPage: {}/{}\nSort: {} {} | Display: {}",
        escape_html(move_name),
        lines.join("\n"),
        clamped_page,
        total_pages,
        sort_option.display_name(),
        sort_direction.arrow(),
        display_option.display_name(),
    );

    let page_len = page_pokemons.len();
    let pk_prefix = if is_tutor { "tut_pk" } else { "tm_pk" };
    let use_prefix = if is_tutor { "tut_use" } else { "tm_use" };
    let card_prefix = if is_tutor { "tut_card" } else { "tm_card" };

    let mut full_kb_rows: Vec<Vec<InlineKeyboardButton>> = Vec::new();
    let mut full_json_rows: Vec<Vec<serde_json::Value>> = Vec::new();

    let all_indices: Vec<usize> = (1..=page_len).collect();
    for chunk in all_indices.chunks(5) {
        let mut row_btns = Vec::new();
        let mut row_json = Vec::new();
        for &idx in chunk {
            let cb = format!("{}:{}:{}", pk_prefix, item_number, page_pokemons[idx - 1].id);
            row_btns.push(InlineKeyboardButton::callback(format!("{}", idx), cb.clone()));
            row_json.push(serde_json::json!({
                "text": format!("{}", idx),
                "callback_data": cb
            }));
        }
        full_kb_rows.push(row_btns);
        full_json_rows.push(row_json);
    }

    let mut row_nav_btns = Vec::new();
    let mut row_nav_json = Vec::new();

    if clamped_page > 1 {
        let prev_cb = format!("{}:{}:{}", use_prefix, item_number, clamped_page - 1);
        row_nav_btns.push(InlineKeyboardButton::callback("←", prev_cb.clone()));
        row_nav_json.push(serde_json::json!({
            "text": " ",
            "callback_data": prev_cb,
            "icon_custom_emoji_id": LEFT_ARROW_CUSTOM_EMOJI_ID
        }));
    }

    row_nav_btns.push(InlineKeyboardButton::callback(format!("{}/{}", clamped_page, total_pages), "noop"));
    row_nav_json.push(serde_json::json!({
        "text": format!("{}/{}", clamped_page, total_pages),
        "callback_data": "noop"
    }));

    if clamped_page < total_pages {
        let next_cb = format!("{}:{}:{}", use_prefix, item_number, clamped_page + 1);
        row_nav_btns.push(InlineKeyboardButton::callback("→", next_cb.clone()));
        row_nav_json.push(serde_json::json!({
            "text": " ",
            "callback_data": next_cb,
            "icon_custom_emoji_id": RIGHT_ARROW_CUSTOM_EMOJI_ID
        }));
    }

    full_kb_rows.push(row_nav_btns);
    full_json_rows.push(row_nav_json);

    let mut row_jump_btns = Vec::new();
    let mut row_jump_json = Vec::new();

    if clamped_page > 5 {
        let minus_5 = clamped_page.saturating_sub(5).max(1);
        let cb = format!("{}:{}:{}", use_prefix, item_number, minus_5);
        row_jump_btns.push(InlineKeyboardButton::callback("5 ←", cb.clone()));
        row_jump_json.push(serde_json::json!({
            "text": "5 ",
            "callback_data": cb,
            "icon_custom_emoji_id": LEFT_ARROW_CUSTOM_EMOJI_ID
        }));
    }

    if clamped_page + 5 <= total_pages || (clamped_page == 1 && total_pages > 5) {
        let plus_5 = (clamped_page + 5).min(total_pages);
        let cb = format!("{}:{}:{}", use_prefix, item_number, plus_5);
        row_jump_btns.push(InlineKeyboardButton::callback("→ 5", cb.clone()));
        row_jump_json.push(serde_json::json!({
            "text": " 5",
            "callback_data": cb,
            "icon_custom_emoji_id": RIGHT_ARROW_CUSTOM_EMOJI_ID
        }));
    }

    if !row_jump_btns.is_empty() {
        full_kb_rows.push(row_jump_btns);
        full_json_rows.push(row_jump_json);
    }

    let back_cb = format!("{}:{}", card_prefix, item_number);
    let row_back_btns = vec![InlineKeyboardButton::callback("Back", back_cb.clone())];
    let row_back_json = vec![serde_json::json!({
        "text": "Back",
        "callback_data": back_cb
    })];

    full_kb_rows.push(row_back_btns);
    full_json_rows.push(row_back_json);

    let fallback_kb = InlineKeyboardMarkup::new(full_kb_rows);
    let custom_kb = serde_json::json!({
        "inline_keyboard": full_json_rows
    });

    Ok(Some((text, custom_kb, fallback_kb)))
}

async fn handle_tutor(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    query: String,
) -> ResponseResult<()> {
    let user = match msg.from.as_ref() {
        Some(u) => u,
        None => return Ok(()),
    };
    let user_id = user.id.0;
    let username = user.username.clone();
    let first_name = user.first_name.clone();

    let _ = sqlx::query(
        "INSERT INTO users (id, username, first_name) VALUES (?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET username = excluded.username, first_name = excluded.first_name",
    )
    .bind(user_id as i64)
    .bind(username)
    .bind(&first_name)
    .execute(&*pool)
    .await;

    let trimmed = query.trim();
    if trimmed.is_empty() {
        let tutors = get_user_owned_tutors(&pool, user_id).await;
        let total_pages = if tutors.is_empty() { 1 } else { (tutors.len() + TUTORS_PAGE_SIZE - 1) / TUTORS_PAGE_SIZE };
        let page_items = if tutors.len() > TUTORS_PAGE_SIZE { &tutors[..TUTORS_PAGE_SIZE] } else { &tutors[..] };
        let text = format_myinventory_tutors_page(page_items, 1, total_pages);
        send_myinventory_tutors_message(&bot, msg.chat.id, msg.id, &text, 1, total_pages).await?;
        return Ok(());
    }

    // Try lookup by number or name (e.g. "3", "TUTOR3", "Double Edge")
    let tutor_opt = if let Ok(num) = trimmed.trim_start_matches(|c: char| !c.is_numeric()).parse::<u32>() {
        get_tutor_by_number(num)
    } else {
        get_tutor_by_name(trimmed)
    };

    if let Some(tutor) = tutor_opt {
        let owned_qty: i64 = sqlx::query_scalar(
            "SELECT quantity FROM user_tutors WHERE user_id = ? AND tutor_number = ?"
        )
        .bind(user_id as i64)
        .bind(tutor.number as i64)
        .fetch_optional(&*pool)
        .await
        .unwrap_or(None)
        .unwrap_or(0);

        let (text, kb) = format_tutor_card(tutor, owned_qty);

        bot.send_message(msg.chat.id, text)
            .parse_mode(ParseMode::Html)
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
    } else {
        bot.send_message(
            msg.chat.id,
            format!("Move Tutor '<b>{}</b>' not found.", escape_html(trimmed)),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
    }

    Ok(())
}

