async fn handle_teach(
    bot: Bot,
    msg: Message,
    pool: Arc<SqlitePool>,
    pokedex: Arc<PokedexData>,
    args: String,
) -> ResponseResult<()> {
    let user = match msg.from.as_ref() {
        Some(u) => u,
        None => return Ok(()),
    };
    let user_id = user.id.0;

    let trimmed = args.trim();
    if trimmed.is_empty() {
        bot.send_message(
            msg.chat.id,
            "Format: /teach &lt;pokemon&gt; &lt;tm or tutor&gt;\nExample: /teach 1 TM45 or /teach 1 TUTOR3",
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let tokens: Vec<&str> = trimmed.split_whitespace().collect();
    if tokens.len() < 2 {
        bot.send_message(
            msg.chat.id,
            "Format: /teach &lt;pokemon&gt; &lt;tm or tutor&gt;\nExample: /teach 1 TM45 or /teach 1 TUTOR3",
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    let mut split_idx = 1;
    for i in (1..tokens.len()).rev() {
        let cand = tokens[i..].join(" ");
        let cand_clean = cand.to_lowercase().replace('#', "");
        if get_tm_by_name(&cand).is_some()
            || get_tutor_by_name(&cand).is_some()
            || cand_clean.parse::<u32>().ok().and_then(get_tm_by_number).is_some()
            || cand_clean.parse::<u32>().ok().and_then(get_tutor_by_number).is_some()
            || (cand_clean.starts_with("tm") && cand_clean.trim_start_matches("tm").trim().parse::<u32>().ok().and_then(get_tm_by_number).is_some())
            || (cand_clean.starts_with("tutor") && cand_clean.trim_start_matches("tutor").trim().parse::<u32>().ok().and_then(get_tutor_by_number).is_some())
        {
            split_idx = i;
            break;
        }
    }

    let pkmn_query = tokens[..split_idx].join(" ");
    let move_query = tokens[split_idx..].join(" ");

    let matching = match fetch_matching_owned_pokemons(&pool, user_id, &pkmn_query, &pokedex).await {
        Ok(m) => m,
        Err(e) => {
            tracing::warn!("Error fetching owned pokemons for teach: {}", e);
            return Ok(());
        }
    };

    if matching.is_empty() {
        bot.send_message(
            msg.chat.id,
            format!("You do not have a Pokémon matching '<b>{}</b>'.", escape_html(&pkmn_query)),
        )
        .parse_mode(ParseMode::Html)
        .reply_parameters(ReplyParameters::new(msg.id))
        .await?;
        return Ok(());
    }

    if matching.len() > 1 {
        let (display_option, _) = get_user_display_settings(&pool, user_id).await;
        let (text, kb) = format_disambiguation_list(&matching, "Teach move to which Pokémon?", "card_info_", &pokedex, display_option);
        bot.send_message(msg.chat.id, text)
            .parse_mode(ParseMode::Html)
            .reply_markup(kb)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
        return Ok(());
    }

    let pkmn_row = &matching[0];
    let db_id: i64 = pkmn_row.get("id");
    let species_id: i64 = pkmn_row.get("pokemon_id");
    let nickname: String = pkmn_row.get("nickname");
    let display_name = if !nickname.is_empty() {
        nickname
    } else {
        pokedex.get_pokemon_by_id(species_id as u32)
            .map(|p| p.name.clone())
            .unwrap_or_else(|| "Pokemon".to_string())
    };

    let m_clean = move_query.to_lowercase().replace('#', "");
    enum TeachTarget {
        Tm(&'static ShopTm),
        Tutor(&'static TutorMove),
    }

    let teach_item = if m_clean.starts_with("tutor") {
        let num_str = m_clean.trim_start_matches("tutor").trim();
        if let Ok(n) = num_str.parse::<u32>() {
            get_tutor_by_number(n).map(TeachTarget::Tutor)
        } else {
            get_tutor_by_name(&move_query).map(TeachTarget::Tutor)
        }
    } else if m_clean.starts_with("tm") {
        let num_str = m_clean.trim_start_matches("tm").trim();
        if let Ok(n) = num_str.parse::<u32>() {
            get_tm_by_number(n).map(TeachTarget::Tm)
        } else {
            get_tm_by_name(&move_query).map(TeachTarget::Tm)
        }
    } else if let Ok(n) = m_clean.parse::<u32>() {
        if let Some(tm) = get_tm_by_number(n) {
            Some(TeachTarget::Tm(tm))
        } else {
            get_tutor_by_number(n).map(TeachTarget::Tutor)
        }
    } else {
        let tm_cand = get_tm_by_name(&move_query);
        let tut_cand = get_tutor_by_name(&move_query);
        match (tm_cand, tut_cand) {
            (Some(tm), Some(tut)) => {
                let tm_owned: bool = sqlx::query_scalar(
                    "SELECT EXISTS(SELECT 1 FROM user_tms WHERE user_id = ? AND tm_number = ? AND quantity > 0)"
                )
                .bind(user_id as i64)
                .bind(tm.number as i64)
                .fetch_one(&*pool)
                .await
                .unwrap_or(false);

                if tm_owned {
                    Some(TeachTarget::Tm(tm))
                } else {
                    Some(TeachTarget::Tutor(tut))
                }
            }
            (Some(tm), None) => Some(TeachTarget::Tm(tm)),
            (None, Some(tut)) => Some(TeachTarget::Tutor(tut)),
            (None, None) => None,
        }
    };

    let target = match teach_item {
        Some(t) => t,
        None => {
            bot.send_message(
                msg.chat.id,
                format!("Move, TM, or Tutor '<b>{}</b>' not found.", escape_html(&move_query)),
            )
            .parse_mode(ParseMode::Html)
            .reply_parameters(ReplyParameters::new(msg.id))
            .await?;
            return Ok(());
        }
    };

    match target {
        TeachTarget::Tm(tm) => {
            let owned_qty: i64 = sqlx::query_scalar(
                "SELECT quantity FROM user_tms WHERE user_id = ? AND tm_number = ?"
            )
            .bind(user_id as i64)
            .bind(tm.number as i64)
            .fetch_optional(&*pool)
            .await
            .unwrap_or(None)
            .unwrap_or(0);

            if owned_qty <= 0 {
                bot.send_message(
                    msg.chat.id,
                    format!("You do not own <b>TM #{} ({})</b> in your bag!", tm.number, escape_html(tm.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            if !pokedex.can_learn_tm(species_id as u32, tm.name) {
                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> cannot learn <b>TM #{} ({})</b>!", escape_html(&display_name), tm.number, escape_html(tm.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            let move_row = sqlx::query(
                "SELECT move_1, move_2, move_3, move_4, relearn_moves FROM pokemons WHERE id = ?"
            )
            .bind(db_id)
            .fetch_one(&*pool)
            .await;

            let mr = match move_row {
                Ok(r) => r,
                Err(_) => return Ok(()),
            };

            let m1: Option<String> = mr.get("move_1");
            let m2: Option<String> = mr.get("move_2");
            let m3: Option<String> = mr.get("move_3");
            let m4: Option<String> = mr.get("move_4");

            let current_moves = [&m1, &m2, &m3, &m4];
            if current_moves.iter().any(|m| m.as_deref().map(|s| s.eq_ignore_ascii_case(tm.name)).unwrap_or(false)) {
                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> already knows <b>{}</b>!", escape_html(&display_name), escape_html(tm.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            let empty_slot = if m1.is_none() || m1.as_deref() == Some("") {
                Some(1)
            } else if m2.is_none() || m2.as_deref() == Some("") {
                Some(2)
            } else if m3.is_none() || m3.as_deref() == Some("") {
                Some(3)
            } else if m4.is_none() || m4.as_deref() == Some("") {
                Some(4)
            } else {
                None
            };

            if let Some(slot) = empty_slot {
                let col = format!("move_{}", slot);
                let update_sql = format!("UPDATE pokemons SET {} = ? WHERE id = ?", col);
                let _ = sqlx::query(&update_sql)
                    .bind(tm.name)
                    .bind(db_id)
                    .execute(&*pool)
                    .await;

                let _ = sqlx::query(
                    "UPDATE user_tms SET quantity = quantity - 1 WHERE user_id = ? AND tm_number = ?"
                )
                .bind(user_id as i64)
                .bind(tm.number as i64)
                .execute(&*pool)
                .await;

                let _ = sqlx::query(
                    "DELETE FROM user_tms WHERE user_id = ? AND tm_number = ? AND quantity <= 0"
                )
                .bind(user_id as i64)
                .bind(tm.number as i64)
                .execute(&*pool)
                .await;

                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> learned <b>{}</b> via TM #{}!", escape_html(&display_name), escape_html(tm.name), tm.number),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            } else {
                let m1 = current_moves[0].as_deref().unwrap_or("Move 1");
                let m2 = current_moves[1].as_deref().unwrap_or("Move 2");
                let m3 = current_moves[2].as_deref().unwrap_or("Move 3");
                let m4 = current_moves[3].as_deref().unwrap_or("Move 4");
                let buttons = vec![
                    vec![
                        InlineKeyboardButton::callback(format!("1. {}", m1), format!("tm_fgt:{}:1:{}", db_id, tm.number)),
                        InlineKeyboardButton::callback(format!("2. {}", m2), format!("tm_fgt:{}:2:{}", db_id, tm.number)),
                    ],
                    vec![
                        InlineKeyboardButton::callback(format!("3. {}", m3), format!("tm_fgt:{}:3:{}", db_id, tm.number)),
                        InlineKeyboardButton::callback(format!("4. {}", m4), format!("tm_fgt:{}:4:{}", db_id, tm.number)),
                    ],
                    vec![
                        InlineKeyboardButton::callback("Cancel", format!("card_info_{}_{}", species_id, db_id)),
                    ],
                ];

                bot.send_message(
                    msg.chat.id,
                    format!(
                        "<b>{}</b> wants to learn <b>{}</b> via TM #{}, but already knows 4 moves!\n\nSelect a move to forget:",
                        escape_html(&display_name), escape_html(tm.name), tm.number
                    ),
                )
                .parse_mode(ParseMode::Html)
                .reply_markup(InlineKeyboardMarkup::new(buttons))
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            }
        }
        TeachTarget::Tutor(tutor) => {
            let owned_qty: i64 = sqlx::query_scalar(
                "SELECT quantity FROM user_tutors WHERE user_id = ? AND tutor_number = ?"
            )
            .bind(user_id as i64)
            .bind(tutor.number as i64)
            .fetch_optional(&*pool)
            .await
            .unwrap_or(None)
            .unwrap_or(0);

            if owned_qty <= 0 {
                bot.send_message(
                    msg.chat.id,
                    format!("You do not own <b>Tutor #{} ({})</b> in your bag!", tutor.number, escape_html(tutor.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            if !pokedex.can_learn_tutor(species_id as u32, tutor.name) {
                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> cannot learn <b>Tutor #{} ({})</b>!", escape_html(&display_name), tutor.number, escape_html(tutor.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            let move_row = sqlx::query(
                "SELECT move_1, move_2, move_3, move_4, relearn_moves FROM pokemons WHERE id = ?"
            )
            .bind(db_id)
            .fetch_one(&*pool)
            .await;

            let mr = match move_row {
                Ok(r) => r,
                Err(_) => return Ok(()),
            };

            let m1: Option<String> = mr.get("move_1");
            let m2: Option<String> = mr.get("move_2");
            let m3: Option<String> = mr.get("move_3");
            let m4: Option<String> = mr.get("move_4");

            let current_moves = [&m1, &m2, &m3, &m4];
            if current_moves.iter().any(|m| m.as_deref().map(|s| s.eq_ignore_ascii_case(tutor.name)).unwrap_or(false)) {
                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> already knows <b>{}</b>!", escape_html(&display_name), escape_html(tutor.name)),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
                return Ok(());
            }

            let empty_slot = if m1.is_none() || m1.as_deref() == Some("") {
                Some(1)
            } else if m2.is_none() || m2.as_deref() == Some("") {
                Some(2)
            } else if m3.is_none() || m3.as_deref() == Some("") {
                Some(3)
            } else if m4.is_none() || m4.as_deref() == Some("") {
                Some(4)
            } else {
                None
            };

            if let Some(slot) = empty_slot {
                let col = format!("move_{}", slot);
                let update_sql = format!("UPDATE pokemons SET {} = ? WHERE id = ?", col);
                let _ = sqlx::query(&update_sql)
                    .bind(tutor.name)
                    .bind(db_id)
                    .execute(&*pool)
                    .await;

                let _ = sqlx::query(
                    "UPDATE user_tutors SET quantity = quantity - 1 WHERE user_id = ? AND tutor_number = ?"
                )
                .bind(user_id as i64)
                .bind(tutor.number as i64)
                .execute(&*pool)
                .await;

                let _ = sqlx::query(
                    "DELETE FROM user_tutors WHERE user_id = ? AND tutor_number = ? AND quantity <= 0"
                )
                .bind(user_id as i64)
                .bind(tutor.number as i64)
                .execute(&*pool)
                .await;

                bot.send_message(
                    msg.chat.id,
                    format!("<b>{}</b> learned <b>{}</b> via Move Tutor #{}!", escape_html(&display_name), escape_html(tutor.name), tutor.number),
                )
                .parse_mode(ParseMode::Html)
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            } else {
                let m1 = current_moves[0].as_deref().unwrap_or("Move 1");
                let m2 = current_moves[1].as_deref().unwrap_or("Move 2");
                let m3 = current_moves[2].as_deref().unwrap_or("Move 3");
                let m4 = current_moves[3].as_deref().unwrap_or("Move 4");
                let buttons = vec![
                    vec![
                        InlineKeyboardButton::callback(format!("1. {}", m1), format!("tut_fgt:{}:1:{}", db_id, tutor.number)),
                        InlineKeyboardButton::callback(format!("2. {}", m2), format!("tut_fgt:{}:2:{}", db_id, tutor.number)),
                    ],
                    vec![
                        InlineKeyboardButton::callback(format!("3. {}", m3), format!("tut_fgt:{}:3:{}", db_id, tutor.number)),
                        InlineKeyboardButton::callback(format!("4. {}", m4), format!("tut_fgt:{}:4:{}", db_id, tutor.number)),
                    ],
                    vec![
                        InlineKeyboardButton::callback("Cancel", format!("card_info_{}_{}", species_id, db_id)),
                    ],
                ];

                bot.send_message(
                    msg.chat.id,
                    format!(
                        "<b>{}</b> wants to learn <b>{}</b> via Move Tutor #{}, but already knows 4 moves!\n\nSelect a move to forget:",
                        escape_html(&display_name), escape_html(tutor.name), tutor.number
                    ),
                )
                .parse_mode(ParseMode::Html)
                .reply_markup(InlineKeyboardMarkup::new(buttons))
                .reply_parameters(ReplyParameters::new(msg.id))
                .await?;
            }
        }
    }

    Ok(())
}

async fn parse_player_battle_pokemon(
    player_row: &SqliteRow,
    pokedex: &PokedexData,
    pool: &SqlitePool,
) -> Option<BattlePokemon> {
    let p_db_id: i64 = player_row.get("id");
    let p_pokemon_id: i64 = player_row.get("pokemon_id");
    let p_nickname: String = player_row.get("nickname");
    let p_level: i32 = player_row.get("level");
    let p_nature: String = player_row.get("nature");
    let p_iv_hp: i32 = player_row.get("iv_hp");
    let p_iv_atk: i32 = player_row.get("iv_attack");
    let p_iv_def: i32 = player_row.get("iv_defense");
    let p_iv_spa: i32 = player_row.get("iv_sp_attack");
    let p_iv_spd: i32 = player_row.get("iv_sp_defense");
    let p_iv_spe: i32 = player_row.get("iv_speed");
    let p_ev_hp: i32 = player_row.try_get("ev_hp").unwrap_or(0);
    let p_ev_atk: i32 = player_row.try_get("ev_attack").unwrap_or(0);
    let p_ev_def: i32 = player_row.try_get("ev_defense").unwrap_or(0);
    let p_ev_spa: i32 = player_row.try_get("ev_sp_attack").unwrap_or(0);
    let p_ev_spd: i32 = player_row.try_get("ev_sp_defense").unwrap_or(0);
    let p_ev_spe: i32 = player_row.try_get("ev_speed").unwrap_or(0);

    let m1: Option<String> = player_row.get("move_1");
    let m2: Option<String> = player_row.get("move_2");
    let m3: Option<String> = player_row.get("move_3");
    let m4: Option<String> = player_row.get("move_4");

    let player_entry = pokedex.get_pokemon_by_id(p_pokemon_id as u32)?;
    let player_max_hp = calc_hp(player_entry.stats.hp, p_iv_hp, p_ev_hp, p_level);

    let mut player_moves: Vec<MoveDetail> = Vec::new();
    for m_name in [m1.as_deref(), m2.as_deref(), m3.as_deref(), m4.as_deref()].into_iter().flatten() {
        if let Some(detail) = pokedex.get_move(m_name) {
            player_moves.push(detail.clone());
        }
    }
    if player_moves.is_empty() {
        let learned = pokedex.get_level_up_moves(p_pokemon_id as u32, p_level as u32);
        player_moves = learned.into_iter().cloned().collect();
        if player_moves.is_empty() {
            player_moves.push(MoveDetail {
                name: "Tackle".to_string(),
                t: "Normal".to_string(),
                c: "Physical".to_string(),
                p: Some(40),
                a: Some(100),
                pp: Some(35),
                d: "A physical attack in which the user charges and slams into the target with its whole body.".to_string(),
            });
        }
        let sm1 = player_moves.get(0).map(|m| m.name.clone());
        let sm2 = player_moves.get(1).map(|m| m.name.clone());
        let sm3 = player_moves.get(2).map(|m| m.name.clone());
        let sm4 = player_moves.get(3).map(|m| m.name.clone());
        let _ = sqlx::query("UPDATE pokemons SET move_1 = ?, move_2 = ?, move_3 = ?, move_4 = ? WHERE id = ?")
            .bind(sm1).bind(sm2).bind(sm3).bind(sm4).bind(p_db_id).execute(pool).await;
    }

    Some(BattlePokemon {
        db_id: Some(p_db_id),
        id: p_pokemon_id as u32,
        name: player_entry.name.clone(),
        nickname: p_nickname,
        level: p_level as u32,
        types: player_entry.types.clone(),
        nature: p_nature,
        base_stats: player_entry.stats.clone(),
        iv_hp: p_iv_hp,
        iv_atk: p_iv_atk,
        iv_def: p_iv_def,
        iv_spa: p_iv_spa,
        iv_spd: p_iv_spd,
        iv_spe: p_iv_spe,
        ev_hp: p_ev_hp,
        ev_atk: p_ev_atk,
        ev_def: p_ev_def,
        ev_spa: p_ev_spa,
        ev_spd: p_ev_spd,
        ev_spe: p_ev_spe,
        max_hp: player_max_hp,
        current_hp: player_max_hp,
        moves: player_moves,
        is_shiny: false,
        catch_rate: 0,
        base_experience: 0,
        is_burned: false,
    })
}

