pub fn get_available_mega_forms(pkmn: &BattlePokemon, pokedex: &PokedexData) -> Vec<String> {
    let lower_name = pkmn.name.to_lowercase();
    if lower_name.contains("-mega") || lower_name.contains("-primal") {
        return Vec::new();
    }
    let base_entry = pokedex.get_pokemon_by_id(pkmn.id).or_else(|| pokedex.get_pokemon_by_name(&pkmn.name));
    let Some(entry) = base_entry else {
        return Vec::new();
    };
    let base_slug = entry.name.to_lowercase().replace(' ', "-");
    let mut megas = Vec::new();
    for evo in &entry.evolution {
        let evo_lower = evo.to_lowercase();
        if (evo_lower.contains("-mega") || evo_lower.contains("-primal")) && evo_lower.starts_with(&base_slug) {
            if pokedex.get_pokemon_by_name(&evo_lower).is_some() && !megas.contains(&evo_lower) {
                megas.push(evo_lower);
            }
        }
    }
    if megas.is_empty() {
        for suffix in &["-mega", "-mega-x", "-mega-y", "-primal"] {
            let candidate = format!("{}{}", base_slug, suffix);
            if pokedex.get_pokemon_by_name(&candidate).is_some() && !megas.contains(&candidate) {
                megas.push(candidate);
            }
        }
    }
    megas
}

pub fn determine_challenge_faster_trainer_order(
    c_spe: i32,
    o_spe: i32,
    challenger_id: u64,
    opponent_id: u64,
    tie_breaker_challenger_wins: bool,
) -> u64 {
    if c_spe > o_spe {
        challenger_id
    } else if o_spe > c_spe {
        opponent_id
    } else if tie_breaker_challenger_wins {
        challenger_id
    } else {
        opponent_id
    }
}

pub fn determine_challenge_faster_trainer(btl: &ChallengeBattle, challenger_id: u64, opponent_id: u64) -> u64 {
    let c_spe = btl.challenger_active.get_effective_spe_against(&btl.opponent_active);
    let o_spe = btl.opponent_active.get_effective_spe_against(&btl.challenger_active);
    determine_challenge_faster_trainer_order(
        c_spe,
        o_spe,
        challenger_id,
        opponent_id,
        rand::thread_rng().gen_bool(0.5),
    )
}

#[derive(Debug, Clone)]
pub struct ActiveChallenge {
    pub challenge_id: String,
    pub chat_id: ChatId,
    pub message_id: MessageId,
    pub challenger_id: u64,
    pub challenger_name: String,
    pub opponent_id: Option<u64>,
    pub opponent_name: String,
    pub challenger_ready: bool,
    pub opponent_ready: bool,
    pub settings: ChallengeSettings,
    pub menu_state: ChallengeMenuState,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub battle: Option<ChallengeBattle>,
}

pub type ChallengeSessions = Arc<tokio::sync::RwLock<HashMap<String, ActiveChallenge>>>;

pub static CHALLENGES: tokio::sync::OnceCell<ChallengeSessions> = tokio::sync::OnceCell::const_new();

pub fn get_challenges() -> ChallengeSessions {
    CHALLENGES.get().cloned().unwrap_or_else(|| {
        Arc::new(tokio::sync::RwLock::new(HashMap::new()))
    })
}

pub async fn is_user_in_challenge(challenges: &ChallengeSessions, user_id: u64) -> bool {
    let now = chrono::Utc::now();
    let c = challenges.read().await;
    c.values().any(|ch| {
        (ch.challenger_id == user_id || ch.opponent_id == Some(user_id))
            && (now - ch.created_at).num_seconds() < 90
            && (ch.battle.is_some() || !(ch.challenger_ready && ch.opponent_ready))
    })
}

pub async fn load_user_challenge_settings(
    pool: &SqlitePool,
    user_id: u64,
) -> ChallengeSettings {
    let row = sqlx::query(
        "SELECT max_pokemon, switch_pokemon, min_legendaries, max_legendaries,
                min_level, max_level, form_changes, status_effects,
                sandbox_mode, random_mode
         FROM user_challenge_settings
         WHERE user_id = ?"
    )
    .bind(user_id as i64)
    .fetch_optional(pool)
    .await
    .unwrap_or(None);

    match row {
        Some(r) => {
            let max_pokemon: i64 = r.try_get("max_pokemon").unwrap_or(6);
            let switch_pokemon: i64 = r.try_get("switch_pokemon").unwrap_or(1);
            let min_legendaries: i64 = r.try_get("min_legendaries").unwrap_or(0);
            let max_legendaries: i64 = r.try_get("max_legendaries").unwrap_or(6);
            let min_level: i64 = r.try_get("min_level").unwrap_or(1);
            let max_level: i64 = r.try_get("max_level").unwrap_or(100);
            let form_changes: i64 = r.try_get("form_changes").unwrap_or(1);
            let status_effects: i64 = r.try_get("status_effects").unwrap_or(1);
            let sandbox_mode: i64 = r.try_get("sandbox_mode").unwrap_or(0);
            let random_mode: i64 = r.try_get("random_mode").unwrap_or(0);

            ChallengeSettings {
                max_pokemon: max_pokemon as u32,
                switch_pokemon: switch_pokemon != 0,
                min_legendaries: min_legendaries as u32,
                max_legendaries: max_legendaries as u32,
                min_level: min_level as u32,
                max_level: max_level as u32,
                form_changes: form_changes != 0,
                status_effects: status_effects != 0,
                sandbox_mode: sandbox_mode != 0,
                random_mode: random_mode != 0,
            }
        }
        None => ChallengeSettings::default(),
    }
}

pub async fn save_user_challenge_settings(
    pool: &SqlitePool,
    user_id: u64,
    settings: &ChallengeSettings,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "INSERT INTO user_challenge_settings (
            user_id, max_pokemon, switch_pokemon, min_legendaries, max_legendaries,
            min_level, max_level, form_changes, status_effects, sandbox_mode, random_mode, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        ON CONFLICT(user_id) DO UPDATE SET
            max_pokemon = excluded.max_pokemon,
            switch_pokemon = excluded.switch_pokemon,
            min_legendaries = excluded.min_legendaries,
            max_legendaries = excluded.max_legendaries,
            min_level = excluded.min_level,
            max_level = excluded.max_level,
            form_changes = excluded.form_changes,
            status_effects = excluded.status_effects,
            sandbox_mode = excluded.sandbox_mode,
            random_mode = excluded.random_mode,
            updated_at = datetime('now')"
    )
    .bind(user_id as i64)
    .bind(settings.max_pokemon as i64)
    .bind(if settings.switch_pokemon { 1i64 } else { 0i64 })
    .bind(settings.min_legendaries as i64)
    .bind(settings.max_legendaries as i64)
    .bind(settings.min_level as i64)
    .bind(settings.max_level as i64)
    .bind(if settings.form_changes { 1i64 } else { 0i64 })
    .bind(if settings.status_effects { 1i64 } else { 0i64 })
    .bind(if settings.sandbox_mode { 1i64 } else { 0i64 })
    .bind(if settings.random_mode { 1i64 } else { 0i64 })
    .execute(pool)
    .await?;

    Ok(())
}

pub async fn get_user_challenge_team(
    pool: &SqlitePool,
    user_id: u64,
) -> Vec<(i64, u32, i32, String)> {
    let active_team_num = get_user_active_team(pool, user_id).await;
    let team_rows = sqlx::query(
        "SELECT p.id, p.pokemon_id, p.level, p.nickname
         FROM user_teams t
         JOIN pokemons p ON t.pokemon_db_id = p.id
         WHERE t.user_id = ? AND t.team_num = ?
         ORDER BY t.slot ASC"
    )
    .bind(user_id as i64)
    .bind(active_team_num as i64)
    .fetch_all(pool)
    .await
    .unwrap_or_default();

    if !team_rows.is_empty() {
        return team_rows
            .into_iter()
            .map(|r| {
                let id: i64 = r.get("id");
                let pokemon_id: i64 = r.get("pokemon_id");
                let level: i32 = r.get("level");
                let nickname: String = r.get("nickname");
                (id, pokemon_id as u32, level, nickname)
            })
            .collect();
    }

    let default_rows = sqlx::query(
        "SELECT id, pokemon_id, level, nickname FROM pokemons WHERE user_id = ? ORDER BY id ASC LIMIT 6"
    )
    .bind(user_id as i64)
    .fetch_all(pool)
    .await
    .unwrap_or_default();

    default_rows
        .into_iter()
        .map(|r| {
            let id: i64 = r.get("id");
            let pokemon_id: i64 = r.get("pokemon_id");
            let level: i32 = r.get("level");
            let nickname: String = r.get("nickname");
            (id, pokemon_id as u32, level, nickname)
        })
        .collect()
}

pub fn validate_team_for_challenge(
    team: &[(i64, u32, i32, String)],
    pokedex: &PokedexData,
    settings: &ChallengeSettings,
) -> Result<(), String> {
    if team.is_empty() {
        return Err("You don't have any Pokémon to battle with.".to_string());
    }

    if settings.random_mode {
        return Ok(());
    }

    if team.len() > settings.max_pokemon as usize {
        return Err(format!(
            "Your team has {} Pokémon, but the max allowed is {}.",
            team.len(),
            settings.max_pokemon
        ));
    }

    for (_id, _p_id, level, name) in team {
        if (*level as u32) < settings.min_level {
            let formatted_name = format_pokemon_name(name);
            return Err(format!(
                "{} is level {}, but minimum level is {}.",
                formatted_name,
                level,
                settings.min_level
            ));
        }
        if (*level as u32) > settings.max_level {
            let formatted_name = format_pokemon_name(name);
            return Err(format!(
                "{} is level {}, but maximum level is {}.",
                formatted_name,
                level,
                settings.max_level
            ));
        }
    }

    let mut legendaries = 0;
    for (_id, p_id, _level, _name) in team {
        if let Some(entry) = pokedex.get_pokemon_by_id(*p_id) {
            if entry.is_legendary == Some(true) || entry.is_mythical == Some(true) {
                legendaries += 1;
            }
        }
    }

    if legendaries < settings.min_legendaries {
        return Err(format!(
            "Your team has {} legendary Pokémon, but at least {} are required.",
            legendaries,
            settings.min_legendaries
        ));
    }

    if legendaries > settings.max_legendaries {
        return Err(format!(
            "Your team has {} legendary Pokémon, but at most {} are allowed.",
            legendaries,
            settings.max_legendaries
        ));
    }

    Ok(())
}

pub fn format_challenge_user_link(user_id: Option<u64>, name: &str) -> String {
    if name.starts_with("<a href=") {
        return name.to_string();
    }
    let id = user_id.unwrap_or(0);
    format!(r#"<a href="tg://user?id={}">{}</a>"#, id, escape_html(name))
}

pub fn format_challenge_screen<M: Into<ChallengeMenuState>>(
    challenger_name: &str,
    opponent_name: &str,
    challenger_ready: bool,
    opponent_ready: bool,
    settings: &ChallengeSettings,
    menu_state: M,
) -> String {
    let menu_state = menu_state.into();
    let c_link = if challenger_name.starts_with("<a href=") {
        challenger_name.to_string()
    } else {
        format_challenge_user_link(None, challenger_name)
    };
    let o_link = if opponent_name.starts_with("<a href=") {
        opponent_name.to_string()
    } else {
        format_challenge_user_link(None, opponent_name)
    };

    let mut parts = Vec::new();
    parts.push(format!("{} has challenged {} to a battle", c_link, o_link));

    let non_default = settings.formatted_non_default_lines();
    if !non_default.is_empty() {
        parts.push(non_default.join("\n"));
    }

    let c_ready = if challenger_ready { "is ready" } else { "is not ready" };
    let o_ready = if opponent_ready { "is ready" } else { "is not ready" };
    parts.push(format!("{} {}\n{} {}", c_link, c_ready, o_link, o_ready));

    match menu_state {
        ChallengeMenuState::Main => {}
        ChallengeMenuState::Settings => {
            parts.push("Use /settingsinfo to view the meanings of the different settings".to_string());
        }
        ChallengeMenuState::PickMaxPokemon => {
            parts.push("Choose the max number of pokemon each trainer can have on their team".to_string());
        }
        ChallengeMenuState::PickMinLegendaries => {
            parts.push("Choose the min number of legendary pokemon each trainer must have on their team".to_string());
        }
        ChallengeMenuState::PickMaxLegendaries => {
            parts.push("Choose the max number of legendary pokemon each trainer can have on their team".to_string());
        }
        ChallengeMenuState::PickMinLevelRange | ChallengeMenuState::PickMinLevelExact(_, _) => {
            parts.push("Choose the min level every pokemon on each trainer's team must have".to_string());
        }
        ChallengeMenuState::PickMaxLevelRange | ChallengeMenuState::PickMaxLevelExact(_, _) => {
            parts.push("Choose the max level every pokemon on each trainer's team must have".to_string());
        }
    }

    parts.join("\n\n")
}

pub fn format_settingsinfo_text() -> String {
    let mut lines = Vec::new();
    lines.push("Battle settings info -".to_string());
    lines.push("• <b>Max Pokemon</b>: max number of pokemon you can have in your team".to_string());
    lines.push("• <b>Min Legendaries</b>: min number of legendary pokemon you can have in your team".to_string());
    lines.push("• <b>Max Legendaries</b>: max number of legendary pokemon you can have in your team".to_string());
    lines.push("• <b>Min Level</b>: every pokemon in your team must be greater than or equal to this min level. Default: 1".to_string());
    lines.push("• <b>Max Level</b>: every pokemon in your team must be less than or equal to this max level. Default: 100".to_string());
    lines.push("• <b>Switch Pokemon</b>: whether you are allowed to switch pokemon during the battle (if not allowed, you can switch out pokemon only if they fainted)".to_string());
    lines.push("• <b>Form Changes</b>: whether you are allowed to use a <i>Key Item</i> to change a pokemon's form".to_string());
    lines.push("• <b>Sandbox Mode</b>: if enabled, pokemon will NOT gain any EXP or EVs (but trainers may still gain wins/losses and poke dollars)".to_string());
    lines.push("• <b>Random Mode</b>: if enabled, all trainer teams will be randomized when the battle starts".to_string());
    lines.join("\n")
}

