            let owner_id: u64 = owner_str.parse().unwrap_or(0);

            if user_id != owner_id {
                let _ = bot
                    .answer_callback_query(q.id.clone())
                    .text("This is not your settings menu!")
                    .show_alert(true)
                    .await;
                return Ok(());
            }

            let (opt, dir) = get_user_sort_settings(&pool, owner_id).await;
            let new_dir = dir.toggle();
            let _ = set_user_sort_direction(&pool, owner_id, new_dir).await;
            let text = format_sort_text(opt, new_dir);
            let kb = build_sort_keyboard(owner_id, opt, new_dir);
            safe_edit_text(&bot, chat_id, message_id, text, kb).await?;
            let _ = bot.answer_callback_query(q.id.clone()).await;
