    #[test]
    fn test_pokedex_level_up_moves_match_pokedex_json() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");
        for (slug, m) in &pokedex.moves {
            assert!(
                !m.c.eq_ignore_ascii_case("status"),
                "Move {} has category status and should not exist in bot",
                slug
            );
        }

        // Verify that 0-power status moves are completely excluded while damaging & fixed-damage moves are retained
        assert!(!pokedex.moves.contains_key("recover"), "Recover (status) should be removed");
        assert!(!pokedex.moves.contains_key("harden"), "Harden (status) should be removed");
        assert!(!pokedex.moves.contains_key("confuse-ray"), "Confuse Ray (status) should be removed");
        assert!(!pokedex.moves.contains_key("growl"), "Growl (status) should be removed");
        assert!(pokedex.moves.contains_key("night-shade"), "Night Shade (fixed-damage) must be retained");
        assert!(pokedex.moves.contains_key("psywave"), "Psywave (fixed-damage) must be retained");

        // Bulbasaur at level 5 damaging moves: Tackle (Supertackle), Vine Whip (Growl has 0 power and is excluded)
        let bulbasaur_moves = pokedex.get_level_up_moves(1, 5);
        assert_eq!(bulbasaur_moves.len(), 2, "Bulbasaur at lvl 5 should have 2 damaging moves");
        assert_eq!(bulbasaur_moves[0].name, "Supertackle");
        assert_eq!(bulbasaur_moves[1].name, "Vine Whip");

        // Charmander at level 5 damaging moves: Scratch, Ember (Growl has 0 power and is excluded)
        let charmander_moves = pokedex.get_level_up_moves(4, 5);
        assert_eq!(charmander_moves.len(), 2, "Charmander at lvl 5 should have 2 damaging moves");
        assert_eq!(charmander_moves[0].name, "Scratch");
        assert_eq!(charmander_moves[1].name, "Ember");

        // Staryu (ID 120) at level 5 damaging moves: Tackle (Supertackle), Water Gun (Harden has 0 power and is excluded)
        let staryu_moves = pokedex.get_level_up_moves(120, 5);
        assert_eq!(staryu_moves.len(), 2, "Staryu at lvl 5 should have 2 damaging moves");
        assert_eq!(staryu_moves[0].name, "Supertackle");
        assert_eq!(staryu_moves[1].name, "Water Gun");

        // Staryu between level 5 and 20 properly learns only damaging level-up moves from pokedex.json:
        // Rapid Spin (12), Psywave (13), Bubble Beam (18), Swift (20)
        // Confuse Ray (8) and Minimize (16) are 0-power status moves and are excluded!
        let staryu_between = pokedex.get_moves_learned_between_levels(120, 5, 20);
        let between_names: Vec<&str> = staryu_between.iter().map(|m| m.name.as_str()).collect();
        assert_eq!(
            between_names,
            vec!["Rapid Spin", "Psywave", "Bubble Beam", "Swift"]
        );
    }

