    #[test]
    fn test_hunt_level_70_high_power_moves() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Charizard at Lv 70 (e.g. wild encounter in hunt) gets high-power moves
        let charizard_moves = pokedex.get_level_up_moves(6, 70);
        assert_eq!(charizard_moves.len(), 4, "Charizard at Lv 70 should have 4 moves");
        for m in &charizard_moves {
            let p = m.p.unwrap_or(0);
            assert!(p >= 80, "Charizard Lv 70 move {} power ({}) should be >= 80", m.name, p);
        }

        // Metagross (ID 376) at Lv 70 gets Hammer Arm (100) and 90-power moves
        let metagross_moves = pokedex.get_level_up_moves(376, 70);
        assert_eq!(metagross_moves.len(), 4, "Metagross at Lv 70 should have 4 moves");
        for m in &metagross_moves {
            let p = m.p.unwrap_or(0);
            assert!(p >= 80, "Metagross Lv 70 move {} power ({}) should be >= 80", m.name, p);
        }
        let meta_names: Vec<&str> = metagross_moves.iter().map(|m| m.name.as_str()).collect();
        assert!(meta_names.contains(&"Hammer Arm"), "Metagross should have Hammer Arm (100 power)");

        // Arcanine (ID 59) at Lv 70 inherits high-power moves (Burn Up 130, Flare Blitz 120, etc.)
        let arcanine_moves = pokedex.get_level_up_moves(59, 70);
        assert_eq!(arcanine_moves.len(), 4, "Arcanine at Lv 70 should have 4 moves");
        for m in &arcanine_moves {
            let p = m.p.unwrap_or(0);
            assert!(p >= 80, "Arcanine Lv 70 move {} power ({}) should be >= 80", m.name, p);
        }
    }

