    #[test]
    fn test_candy_level_up_growlithe_only_fills_remaining_slot() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Growlithe (ID 58) at level 23 has 3 moves: Ember, Bite, Flame Wheel (1 slot left)
        let mut current_moves = [
            Some("Ember".to_string()),
            Some("Bite".to_string()),
            Some("Flame Wheel".to_string()),
            None,
        ];

        let moves_between = pokedex.get_moves_learned_between_levels(58, 23, 33);
        assert!(!moves_between.is_empty(), "Growlithe between 23 and 33 should have moves in learnset");

        let known_names: Vec<String> = current_moves.iter().flatten().map(|s| s.to_lowercase()).collect();
        let unlearned_moves: Vec<&MoveDetail> = moves_between
            .into_iter()
            .filter(|m| !known_names.contains(&m.name.to_lowercase()))
            .collect();

        assert!(unlearned_moves.len() >= 2, "There are multiple unlearned moves between 23 and 33");

        let mut learned_automatically = Vec::new();
        let mut prompt_move: Option<&MoveDetail> = None;

        for m in unlearned_moves {
            if let Some(empty_idx) = current_moves.iter().position(|slot| slot.as_ref().map(|s| s.trim().is_empty()).unwrap_or(true)) {
                current_moves[empty_idx] = Some(m.name.clone());
                learned_automatically.push(m.name.clone());
            } else {
                if let Some(best) = prompt_move {
                    let best_p = best.p.unwrap_or(0);
                    let new_p = m.p.unwrap_or(0);
                    if new_p >= best_p {
                        prompt_move = Some(m);
                    }
                } else {
                    prompt_move = Some(m);
                }
            }
        }

        // Critical assertions matching user requirement:
        // Growlithe only had 1 empty slot, so ONLY 1 move can be learned automatically!
        assert_eq!(learned_automatically.len(), 1, "Must only learn 1 move automatically since only 1 slot was left");
        assert_eq!(current_moves[0], Some("Ember".to_string()), "Existing move 1 must not be overwritten");
        assert_eq!(current_moves[1], Some("Bite".to_string()), "Existing move 2 must not be overwritten");
        assert_eq!(current_moves[2], Some("Flame Wheel".to_string()), "Existing move 3 must not be overwritten");
        assert_eq!(current_moves[3], Some(learned_automatically[0].clone()), "Slot 4 must be filled with the single learned move");

        // The remaining moves trigger prompt_move instead of overwriting
        assert!(prompt_move.is_some(), "Must prompt for subsequent moves that did not fit in empty slots");
    }

