    #[tokio::test]
    async fn test_starter_cannot_be_released() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query("CREATE TABLE pokemons (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, nickname TEXT, is_starter INTEGER);").execute(&pool).await.unwrap();

        // Insert starter (id = 1)
        sqlx::query("INSERT INTO pokemons (user_id, nickname, is_starter) VALUES (100, 'Charmander', 1);").execute(&pool).await.unwrap();
        // Insert caught pokemon (id = 2)
        sqlx::query("INSERT INTO pokemons (user_id, nickname, is_starter) VALUES (100, 'Seel', 0);").execute(&pool).await.unwrap();

        // Check starter logic for charmander
        let starter_row = sqlx::query("SELECT id FROM pokemons WHERE user_id = ? ORDER BY id ASC LIMIT 1")
            .bind(100i64)
            .fetch_optional(&pool)
            .await
            .unwrap();
        let starter_db_id = starter_row.map(|r| r.get::<i64, _>("id"));
        assert_eq!(starter_db_id, Some(1));

        // Releasing id = 1 should be blocked because it's starter
        let row_starter = sqlx::query("SELECT is_starter FROM pokemons WHERE id = 1 AND user_id = 100")
            .fetch_one(&pool)
            .await
            .unwrap();
        let is_starter = row_starter.get::<i32, _>("is_starter") == 1 || starter_db_id == Some(1);
        assert!(is_starter, "Starter should be identified as starter");

        // Releasing id = 2 (Seel) is allowed
        let row_caught = sqlx::query("SELECT is_starter FROM pokemons WHERE id = 2 AND user_id = 100")
            .fetch_one(&pool)
            .await
            .unwrap();
        let is_seel_starter = row_caught.get::<i32, _>("is_starter") == 1 || starter_db_id == Some(2);
        assert!(!is_seel_starter, "Caught Pokémon should not be identified as starter");
    }

