    #[tokio::test]
    async fn test_format_disambiguation_list() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE pokemons (id INTEGER PRIMARY KEY AUTOINCREMENT, nickname TEXT, nature TEXT);"
        )
        .execute(&pool)
        .await
        .unwrap();

        for i in 1..=6 {
            sqlx::query("INSERT INTO pokemons (nickname, nature) VALUES (?, ?);")
                .bind(format!("Pikachu {}", i))
                .bind("Hardy")
                .execute(&pool)
                .await
                .unwrap();
        }

        let rows = sqlx::query("SELECT id, nickname, nature FROM pokemons ORDER BY id ASC")
            .fetch_all(&pool)
            .await
            .unwrap();

        let pokedex = PokedexData::default();
        let (text, keyboard) = format_disambiguation_list(&rows, "Check stats of which pokemon?", "sel_stats_", &pokedex, DisplayOption::Nature);
        assert!(text.contains("1. Pikachu 1 - Hardy"));
        assert!(text.contains("6. Pikachu 6 - Hardy"));
        assert!(text.contains("Check stats of which pokemon?"));

        // Test DisplayOption::None
        let (text_none, _) = format_disambiguation_list(&rows, "Check stats of which pokemon?", "sel_stats_", &pokedex, DisplayOption::None);
        assert!(text_none.contains("1. Pikachu 1\n"));
        assert!(!text_none.contains("1. Pikachu 1 -"));

        // Test DisplayOption::Level
        let (text_lvl, _) = format_disambiguation_list(&rows, "Check stats of which pokemon?", "sel_stats_", &pokedex, DisplayOption::Level);
        assert!(text_lvl.contains("1. Pikachu 1 - Level 5"));

        // 6 items in chunks of 4 -> 2 rows (row 1 has 4 buttons, row 2 has 2 buttons)
        assert_eq!(keyboard.inline_keyboard.len(), 2);
        assert_eq!(keyboard.inline_keyboard[0].len(), 4);
        assert_eq!(keyboard.inline_keyboard[0][0].text, "1");
        assert_eq!(keyboard.inline_keyboard[0][3].text, "4");
        assert_eq!(keyboard.inline_keyboard[1][0].text, "5");
        assert_eq!(keyboard.inline_keyboard[1][1].text, "6");
    }

    #[tokio::test]
    async fn test_disambiguation_sort_and_display_integration() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                sort_option INTEGER NOT NULL DEFAULT 4,
                sort_direction TEXT NOT NULL DEFAULT 'Descending',
                display_option INTEGER NOT NULL DEFAULT 5,
                show_numbering INTEGER NOT NULL DEFAULT 1,
                page_size INTEGER NOT NULL DEFAULT 20
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 5,
                nature TEXT NOT NULL,
                experience INTEGER NOT NULL DEFAULT 135,
                is_starter INTEGER NOT NULL DEFAULT 0,
                is_shiny INTEGER NOT NULL DEFAULT 0,
                is_hatched INTEGER NOT NULL DEFAULT 0,
                iv_hp INTEGER NOT NULL DEFAULT 0,
                iv_attack INTEGER NOT NULL DEFAULT 0,
                iv_defense INTEGER NOT NULL DEFAULT 0,
                iv_sp_attack INTEGER NOT NULL DEFAULT 0,
                iv_sp_defense INTEGER NOT NULL DEFAULT 0,
                iv_speed INTEGER NOT NULL DEFAULT 0,
                ev_hp INTEGER NOT NULL DEFAULT 0,
                ev_attack INTEGER NOT NULL DEFAULT 0,
                ev_defense INTEGER NOT NULL DEFAULT 0,
                ev_sp_attack INTEGER NOT NULL DEFAULT 0,
                ev_sp_defense INTEGER NOT NULL DEFAULT 0,
                ev_speed INTEGER NOT NULL DEFAULT 0,
                boosted_ivs TEXT NOT NULL DEFAULT ''
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // User 200 with Sort: IvPoints Descending, Display: IvPoints
        sqlx::query(
            "INSERT INTO users (id, sort_option, sort_direction, display_option) VALUES (200, 4, 'Descending', 3);"
        )
        .execute(&pool)
        .await
        .unwrap();

        // Inteleon 1: id=1, level=50, IVs=10 (total 60)
        sqlx::query(
            "INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature, iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed)
             VALUES (1, 200, 818, 'Inteleon', 50, 'Docile', 10, 10, 10, 10, 10, 10);"
        )
        .execute(&pool)
        .await
        .unwrap();

        // Inteleon 2: id=2, level=30, IVs=31 (total 186)
        sqlx::query(
            "INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature, iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed)
             VALUES (2, 200, 818, 'Inteleon', 30, 'Modest', 31, 31, 31, 31, 31, 31);"
        )
        .execute(&pool)
        .await
        .unwrap();

        // Inteleon 3: id=3, level=70, IVs=20 (total 120)
        sqlx::query(
            "INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature, iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed)
             VALUES (3, 200, 818, 'Inteleon', 70, 'Quiet', 20, 20, 20, 20, 20, 20);"
        )
        .execute(&pool)
        .await
        .unwrap();

        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Test 1: Fetch matching pokemons respects user's sort (IV Points Descending)
        let rows = fetch_matching_owned_pokemons(&pool, 200, "Inteleon", &pokedex).await.unwrap();
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0].get::<i64, _>("id"), 2); // 186 IV
        assert_eq!(rows[1].get::<i64, _>("id"), 3); // 120 IV
        assert_eq!(rows[2].get::<i64, _>("id"), 1); // 60 IV

        let (display_option, _) = get_user_display_settings(&pool, 200).await;
        assert_eq!(display_option, DisplayOption::IvPoints);

        let (text, keyboard) = format_disambiguation_list(&rows, "Nickname which pokemon?", "sel_nick_", &pokedex, display_option);
        assert!(text.contains("1. Inteleon - 186 IV"));
        assert!(text.contains("2. Inteleon - 120 IV"));
        assert!(text.contains("3. Inteleon - 60 IV"));
        assert!(text.contains("Nickname which pokemon?"));

        // Verify button mappings match sorted IDs
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref d) = keyboard.inline_keyboard[0][0].kind {
            assert_eq!(d, "sel_nick_2");
        } else {
            panic!("Expected callback data");
        }
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref d) = keyboard.inline_keyboard[0][1].kind {
            assert_eq!(d, "sel_nick_3");
        } else {
            panic!("Expected callback data");
        }
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref d) = keyboard.inline_keyboard[0][2].kind {
            assert_eq!(d, "sel_nick_1");
        } else {
            panic!("Expected callback data");
        }

        // Test 2: Change sort to Level Ascending, display to Level
        sqlx::query("UPDATE users SET sort_option = 3, sort_direction = 'Ascending', display_option = 2 WHERE id = 200;")
            .execute(&pool)
            .await
            .unwrap();

        let rows_lvl = fetch_matching_owned_pokemons(&pool, 200, "Inteleon", &pokedex).await.unwrap();
        assert_eq!(rows_lvl[0].get::<i64, _>("id"), 2); // Level 30
        assert_eq!(rows_lvl[1].get::<i64, _>("id"), 1); // Level 50
        assert_eq!(rows_lvl[2].get::<i64, _>("id"), 3); // Level 70

        let (disp_lvl, _) = get_user_display_settings(&pool, 200).await;
        let (text_lvl, _) = format_disambiguation_list(&rows_lvl, "Check stats of which pokemon?", "sel_stats_", &pokedex, disp_lvl);
        assert!(text_lvl.contains("1. Inteleon - Level 30"));
        assert!(text_lvl.contains("2. Inteleon - Level 50"));
        assert!(text_lvl.contains("3. Inteleon - Level 70"));

        // Test 3: DisplayOption::None
        let (text_none, _) = format_disambiguation_list(&rows_lvl, "Release which pokemon?", "sel_rel_", &pokedex, DisplayOption::None);
        assert!(text_none.contains("1. Inteleon\n"));
        assert!(!text_none.contains("1. Inteleon -"));
    }

    #[test]
    fn test_format_travel_message() {
        // When only Kanto is unlocked (default)
        let msg_kanto_only = format_travel_message("Kanto", "Kanto");
        assert_eq!(
            msg_kanto_only,
            "Which region would you like to travel to?\n\n1. Kanto\n\nRank up to unlock more regions\n\nCurrent region: <b>Kanto</b>"
        );

        // When Johto is unlocked after rank up
        let msg_both = format_travel_message("Kanto", "Kanto,Johto");
        assert_eq!(
            msg_both,
            "Which region would you like to travel to?\n\n1. Kanto\n2. Johto\n\nRank up to unlock more regions\n\nCurrent region: <b>Kanto</b>"
        );
        let msg_in_johto = format_travel_message("Johto", "Kanto,Johto");
        assert_eq!(
            msg_in_johto,
            "Which region would you like to travel to?\n\n1. Kanto\n2. Johto\n\nRank up to unlock more regions\n\nCurrent region: <b>Johto</b>"
        );
    }

    #[test]
    fn test_travel_keyboard() {
        // When only Kanto is unlocked (default) -> only button 1, no Johto button!
        let kb_default = travel_keyboard("Kanto");
        assert_eq!(kb_default.inline_keyboard.len(), 1);
        assert_eq!(kb_default.inline_keyboard[0].len(), 1);
        assert_eq!(kb_default.inline_keyboard[0][0].text, "1");
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref data) = kb_default.inline_keyboard[0][0].kind {
            assert_eq!(data, "travel_1");
        } else {
            panic!("Expected CallbackData");
        }

        // When Johto is unlocked after rank up -> both buttons 1 and 2
        let kb_both = travel_keyboard("Kanto,Johto");
        assert_eq!(kb_both.inline_keyboard.len(), 1);
        assert_eq!(kb_both.inline_keyboard[0].len(), 2);
        assert_eq!(kb_both.inline_keyboard[0][0].text, "1");
        assert_eq!(kb_both.inline_keyboard[0][1].text, "2");
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref data) = kb_both.inline_keyboard[0][0].kind {
            assert_eq!(data, "travel_1");
        } else {
            panic!("Expected CallbackData");
        }
        if let teloxide::types::InlineKeyboardButtonKind::CallbackData(ref data) = kb_both.inline_keyboard[0][1].kind {
            assert_eq!(data, "travel_2");
        } else {
            panic!("Expected CallbackData");
        }

        // When all 9 regions are unlocked -> 3 rows of 3 buttons
        let all_csv = get_unlocked_regions_csv_for_level(8);
        let kb_all = travel_keyboard(&all_csv);
        assert_eq!(kb_all.inline_keyboard.len(), 3);
        assert_eq!(kb_all.inline_keyboard[0].len(), 3);
        assert_eq!(kb_all.inline_keyboard[1].len(), 3);
        assert_eq!(kb_all.inline_keyboard[2].len(), 3);
    }

    #[test]
    fn test_all_9_regions_level_unlocks() {
        assert_eq!(ALL_REGIONS.len(), 9);
        assert_eq!(ALL_REGIONS[0].name, "Kanto");
        assert_eq!(ALL_REGIONS[0].required_level, 0);
        assert_eq!(ALL_REGIONS[1].name, "Johto");
        assert_eq!(ALL_REGIONS[1].required_level, 1);
        assert_eq!(ALL_REGIONS[2].name, "Hoenn");
        assert_eq!(ALL_REGIONS[2].required_level, 2);
        assert_eq!(ALL_REGIONS[3].name, "Sinnoh");
        assert_eq!(ALL_REGIONS[3].required_level, 3);
        assert_eq!(ALL_REGIONS[4].name, "Unova");
        assert_eq!(ALL_REGIONS[4].required_level, 4);
        assert_eq!(ALL_REGIONS[5].name, "Kalos");
        assert_eq!(ALL_REGIONS[5].required_level, 5);
        assert_eq!(ALL_REGIONS[6].name, "Alola");
        assert_eq!(ALL_REGIONS[6].required_level, 6);
        assert_eq!(ALL_REGIONS[7].name, "Galar");
        assert_eq!(ALL_REGIONS[7].required_level, 7);
        assert_eq!(ALL_REGIONS[8].name, "Paldea");
        assert_eq!(ALL_REGIONS[8].required_level, 8);

        // Level 0: only Kanto
        assert_eq!(get_unlocked_regions_for_level(0), vec!["Kanto"]);
        // Level 1: Kanto and Johto
        assert_eq!(get_unlocked_regions_for_level(1), vec!["Kanto", "Johto"]);
        // Level 8+: all 9 regions
        assert_eq!(get_unlocked_regions_for_level(8).len(), 9);
        assert_eq!(get_unlocked_regions_for_level(10).len(), 9);

        // find_region by id and by name
        assert_eq!(find_region("1").unwrap().name, "Kanto");
        assert_eq!(find_region("kanto").unwrap().id, 1);
        assert_eq!(find_region("3").unwrap().name, "Hoenn");
        assert_eq!(find_region("hoenn").unwrap().id, 3);
        assert_eq!(find_region("9").unwrap().name, "Paldea");
        assert_eq!(find_region("paldea").unwrap().id, 9);
        assert!(find_region("unknown").is_none());
    }

    #[tokio::test]
    async fn test_travel_database_and_unlock_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                starter_id INTEGER,
                current_region TEXT NOT NULL DEFAULT 'Kanto',
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto'
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 1. Insert user with defaults
        sqlx::query(
            "INSERT INTO users (id, username, first_name) VALUES (123, 'Ash', 'Ash Ketchum');"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 2. Verify default region is Kanto and only Kanto is unlocked
        let row = sqlx::query("SELECT current_region, unlocked_regions FROM users WHERE id = 123")
            .fetch_one(&pool)
            .await
            .unwrap();
        let current_region: String = row.get("current_region");
        let unlocked_regions: String = row.get("unlocked_regions");
        assert_eq!(current_region, "Kanto");
        assert_eq!(unlocked_regions, "Kanto");

        // Message and keyboard only show Kanto by default
        let msg = format_travel_message(&current_region, &unlocked_regions);
        assert!(msg.contains("1. Kanto"));
        assert!(!msg.contains("2. Johto"));
        let kb = travel_keyboard(&unlocked_regions);
        assert_eq!(kb.inline_keyboard[0].len(), 1);

        // 3. User tries to travel to Kanto (already in Kanto)
        assert_eq!(current_region, "Kanto");

        // 4. User tries to travel to Johto (locked by default)
        let is_johto_unlocked = unlocked_regions
            .split(',')
            .any(|r| r.trim().eq_ignore_ascii_case("Johto"));
        assert!(!is_johto_unlocked, "Johto should be locked by default");

        // 5. User unlocks Johto by ranking up
        sqlx::query("UPDATE users SET unlocked_regions = 'Kanto,Johto' WHERE id = 123")
            .execute(&pool)
            .await
            .unwrap();

        let updated_row = sqlx::query("SELECT unlocked_regions FROM users WHERE id = 123")
            .fetch_one(&pool)
            .await
            .unwrap();
        let new_unlocked: String = updated_row.get("unlocked_regions");
        let can_travel_johto = new_unlocked
            .split(',')
            .any(|r| r.trim().eq_ignore_ascii_case("Johto"));
        assert!(can_travel_johto, "Johto should now be unlocked");

        // 6. User travels to Johto
        sqlx::query("UPDATE users SET current_region = 'Johto' WHERE id = 123")
            .execute(&pool)
            .await
            .unwrap();

        let traveled_row = sqlx::query("SELECT current_region FROM users WHERE id = 123")
            .fetch_one(&pool)
            .await
            .unwrap();
        let new_current: String = traveled_row.get("current_region");
        assert_eq!(new_current, "Johto");

        // 7. Travel message and keyboard update properly with both regions
        let msg_after = format_travel_message(&new_current, &new_unlocked);
        assert!(msg_after.contains("1. Kanto"));
        assert!(msg_after.contains("2. Johto"));
        assert!(msg_after.contains("Current region: <b>Johto</b>"));
        let kb_after = travel_keyboard(&new_unlocked);
        assert_eq!(kb_after.inline_keyboard[0].len(), 2);
    }

    #[tokio::test]
    async fn test_rank_10_unlocks_all_9_regions_in_travel() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                starter_id INTEGER,
                current_region TEXT NOT NULL DEFAULT 'Kanto',
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto',
                trainer_level INTEGER NOT NULL DEFAULT 10
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "INSERT INTO users (id, username, first_name, trainer_level) VALUES (999, 'Shivam', 'Shivam', 10);"
        )
        .execute(&pool)
        .await
        .unwrap();

        let user_row = sqlx::query("SELECT current_region, unlocked_regions, trainer_level FROM users WHERE id = 999")
            .fetch_one(&pool)
            .await
            .unwrap();
        let ur: String = user_row.get("unlocked_regions");
        let t_lvl: i32 = user_row.get("trainer_level");
        let level_csv = get_unlocked_regions_csv_for_level(t_lvl as u32);
        let mut set: Vec<String> = ur.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
        for reg in level_csv.split(',') {
            if !set.iter().any(|r| r.eq_ignore_ascii_case(reg)) {
                set.push(reg.to_string());
            }
        }
        let final_ur = set.join(",");
        assert_eq!(final_ur.split(',').count(), 9);

        let msg = format_travel_message("Kanto", &final_ur);
        assert!(msg.contains("1. Kanto"));
        assert!(msg.contains("2. Johto"));
        assert!(msg.contains("3. Hoenn"));
        assert!(msg.contains("4. Sinnoh"));
        assert!(msg.contains("5. Unova"));
        assert!(msg.contains("6. Kalos"));
        assert!(msg.contains("7. Alola"));
        assert!(msg.contains("8. Galar"));
        assert!(msg.contains("9. Paldea"));

        let kb = travel_keyboard(&final_ur);
        assert_eq!(kb.inline_keyboard.len(), 3);
        assert_eq!(kb.inline_keyboard[0].len(), 3);
        assert_eq!(kb.inline_keyboard[1].len(), 3);
        assert_eq!(kb.inline_keyboard[2].len(), 3);
    }

