    #[test]
    fn test_xp_progression_max_one_million() {
        // Total cumulative sum to reach Rank 10 must be exactly 1,000,000
        let total_sum: i32 = (0..10).map(req_exp_for_rank).sum();
        assert_eq!(total_sum, 1_000_000);

        assert_eq!(cumulative_exp_for_rank(0), 0);
        assert_eq!(cumulative_exp_for_rank(1), 50_000);
        assert_eq!(cumulative_exp_for_rank(2), 110_000);
        assert_eq!(cumulative_exp_for_rank(10), 1_000_000);
        assert_eq!(cumulative_exp_for_rank(11), 1_110_000);
        assert_eq!(cumulative_exp_for_rank(MAX_TRAINER_LEVEL), MAX_TRAINER_EXP);

        assert_eq!(get_total_cumulative_exp(0, 0), 0);
        assert_eq!(get_total_cumulative_exp(0, 25_000), 25_000);
        assert_eq!(get_total_cumulative_exp(1, 10_000), 60_000);
        assert_eq!(get_total_cumulative_exp(10, 0), 1_000_000);
        assert_eq!(get_total_cumulative_exp(10, 50_000), 1_050_000);
        assert_eq!(get_total_cumulative_exp(MAX_TRAINER_LEVEL, 0), MAX_TRAINER_EXP);
        assert_eq!(get_total_cumulative_exp(MAX_TRAINER_LEVEL, 50_000), MAX_TRAINER_EXP);
    }

