    #[tokio::test]
    async fn test_add_trainer_exp_single_level_up() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                trainer_level INTEGER NOT NULL DEFAULT 0,
                trainer_exp INTEGER NOT NULL DEFAULT 0,
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto'
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, trainer_level, trainer_exp, unlocked_regions) VALUES (123, 0, 0, 'Kanto');")
            .execute(&pool)
            .await
            .unwrap();

        // Rank 0 requires 50,000 EXP. Add 60,000 EXP.
        let res = add_trainer_exp(&pool, 123, 60_000).await.unwrap();
        assert_eq!(res.old_rank, 0);
        assert_eq!(res.new_rank, 1);
        assert!(res.leveled_up);
        assert_eq!(res.current_exp, 10_000); // 60,000 - 50,000 = 10,000 rollover!
        assert_eq!(res.total_cumulative_exp, 60_000);
        assert_eq!(res.newly_unlocked_regions, vec!["Johto"]);

        let row = sqlx::query("SELECT trainer_level, trainer_exp, unlocked_regions FROM users WHERE id = 123")
            .fetch_one(&pool)
            .await
            .unwrap();
        let lvl: i32 = row.get("trainer_level");
        let exp: i32 = row.get("trainer_exp");
        let reg: String = row.get("unlocked_regions");
        assert_eq!(lvl, 1);
        assert_eq!(exp, 10_000);
        assert!(reg.contains("Johto"));
    }

    #[tokio::test]
    async fn test_add_trainer_exp_multi_level_up_and_cap() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                trainer_level INTEGER NOT NULL DEFAULT 0,
                trainer_exp INTEGER NOT NULL DEFAULT 0,
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto'
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, trainer_level, trainer_exp, unlocked_regions) VALUES (456, 0, 0, 'Kanto');")
            .execute(&pool)
            .await
            .unwrap();

        // Add 2,000,000 EXP (1,000,000 gets to rank 10, then 990,000 gets 9 more ranks -> rank 19 with 10k left)
        let res = add_trainer_exp(&pool, 456, 2_000_000).await.unwrap();
        assert_eq!(res.old_rank, 0);
        assert_eq!(res.new_rank, 19);
        assert!(res.leveled_up);
        assert_eq!(res.total_cumulative_exp, 2_000_000);
        assert_eq!(res.current_exp, 10_000);
        assert_eq!(res.newly_unlocked_regions.len(), 8); // Johto through Paldea

        // Test capping at MAX_TRAINER_LEVEL
        sqlx::query("INSERT INTO users (id, trainer_level, trainer_exp, unlocked_regions) VALUES (789, 9999999, 100000, 'Kanto');")
            .execute(&pool)
            .await
            .unwrap();
        let res_cap = add_trainer_exp(&pool, 789, 50_000).await.unwrap();
        assert_eq!(res_cap.old_rank, 9_999_999);
        assert_eq!(res_cap.new_rank, MAX_TRAINER_LEVEL);
        assert_eq!(res_cap.current_exp, 0);
        assert_eq!(res_cap.total_cumulative_exp, MAX_TRAINER_EXP);
    }

