    #[test]
    fn test_select_wild_pokemon_and_ev_yield() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");
        let magmar = pokedex.get_pokemon_by_id(126).expect("Magmar should exist");
        assert_eq!(magmar.name, "magmar");
        assert_eq!(magmar.region.as_deref(), Some("Kanto"));
        assert_eq!(magmar.ev_yield.as_deref(), Some("2 Sp.Atk"));
        assert_eq!(magmar.is_legendary, Some(false));
        assert_eq!(magmar.is_mythical, Some(false));
        assert_eq!(format_ev_yield_text(magmar), "Yields: +2 Sp. Attack");

        let bulbasaur = pokedex.get_pokemon_by_id(1).expect("Bulbasaur should exist");
        assert_eq!(format_ev_yield_text(bulbasaur), "Yields: +1 Sp. Attack");

        let ivysaur = pokedex.get_pokemon_by_id(2).expect("Ivysaur should exist");
        assert_eq!(format_ev_yield_text(ivysaur), "Yields: +1 Sp. Attack, +1 Sp. Defense");

        // Test wild encounter selection for Kanto
        let (wild, _is_shiny) = pokedex.select_wild_pokemon("Kanto").expect("Wild Pokemon in Kanto should be found");
        assert!(wild.id <= 151, "Kanto wild Pokemon must be gen 1 (1..=151), got {}", wild.id);

        // Test native region checks
        assert!(is_pokemon_native_to_region(magmar, "Kanto"));
        assert!(!is_pokemon_native_to_region(magmar, "Johto"));

        let cyndaquil = pokedex.get_pokemon_by_id(155).expect("Cyndaquil should exist");
        assert!(is_pokemon_native_to_region(cyndaquil, "Johto"));
        assert!(!is_pokemon_native_to_region(cyndaquil, "Kanto"));

        let treecko = pokedex.get_pokemon_by_id(252).expect("Treecko should exist");
        assert!(is_pokemon_native_to_region(treecko, "Hoenn"));
        assert!(!is_pokemon_native_to_region(treecko, "Kanto"));

        // Forms must not spawn in Kanto
        if let Some(galar_meowth) = pokedex.get_pokemon_by_name("meowth-galar") {
            assert!(!is_pokemon_native_to_region(galar_meowth, "Kanto"));
            assert!(is_pokemon_native_to_region(galar_meowth, "Galar"));
        }
        if let Some(mega_char) = pokedex.get_pokemon_by_name("charizard-mega-x") {
            assert!(!is_pokemon_native_to_region(mega_char, "Kanto"));
            assert!(!is_pokemon_native_to_region(mega_char, "Kalos"));
        }
    }

    #[test]
    fn test_spawn_rate_tiers_and_exclusions() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Non-legendary (Normal pool)
        let magmar = pokedex.get_pokemon_by_id(126).unwrap();
        assert_eq!(get_pokemon_spawn_tier(magmar), Some(SpawnTier::NonLegendary));

        let pidgey = pokedex.get_pokemon_by_id(16).unwrap();
        assert_eq!(get_pokemon_spawn_tier(pidgey), Some(SpawnTier::NonLegendary));

        // Pseudo-legendary (Normal pool)
        let dratini = pokedex.get_pokemon_by_id(147).unwrap();
        let dragonite = pokedex.get_pokemon_by_id(149).unwrap();
        let tyranitar = pokedex.get_pokemon_by_id(248).unwrap();
        let garchomp = pokedex.get_pokemon_by_id(445).unwrap();
        let metagross = pokedex.get_pokemon_by_id(376).unwrap();
        let dragapult = pokedex.get_pokemon_by_id(887).unwrap();
        let baxcalibur = pokedex.get_pokemon_by_id(998).unwrap();

        assert_eq!(get_pokemon_spawn_tier(dratini), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(dragonite), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(tyranitar), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(garchomp), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(metagross), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(dragapult), Some(SpawnTier::PseudoLegendary));
        assert_eq!(get_pokemon_spawn_tier(baxcalibur), Some(SpawnTier::PseudoLegendary));

        // Legendary / Mythical / Beast / Paradox (Very rare: 1%)
        let mewtwo = pokedex.get_pokemon_by_id(150).unwrap();
        let rayquaza = pokedex.get_pokemon_by_id(384).unwrap();
        let nihilego = pokedex.get_pokemon_by_id(793).unwrap(); // Ultra Beast
        let great_tusk = pokedex.get_pokemon_by_id(984).unwrap(); // Paradox

        assert_eq!(get_pokemon_spawn_tier(mewtwo), Some(SpawnTier::LegendarySpecial));
        assert_eq!(get_pokemon_spawn_tier(rayquaza), Some(SpawnTier::LegendarySpecial));
        assert_eq!(get_pokemon_spawn_tier(nihilego), Some(SpawnTier::LegendarySpecial));
        assert_eq!(get_pokemon_spawn_tier(great_tusk), Some(SpawnTier::LegendarySpecial));

        // Battle-only / event forms must be disallowed
        if let Some(mega) = pokedex.get_pokemon_by_name("charizard-mega-y") {
            assert_eq!(get_pokemon_spawn_tier(mega), None);
        }
        if let Some(gmax) = pokedex.get_pokemon_by_name("venusaur-gmax") {
            assert_eq!(get_pokemon_spawn_tier(gmax), None);
        }
        if let Some(cap) = pokedex.get_pokemon_by_name("pikachu-original-cap") {
            assert_eq!(get_pokemon_spawn_tier(cap), None);
        }
    }

    #[test]
    fn test_wild_pokemon_spawn_distribution_statistical() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        let mut non_leg_count = 0;
        let mut pseudo_leg_count = 0;
        let mut leg_special_count = 0;
        let mut shiny_count = 0;

        let total_iterations = 10_000;
        for _ in 0..total_iterations {
            let (wild, is_shiny) = pokedex.select_wild_pokemon("Kanto").expect("Should select wild Pokemon");
            if is_shiny {
                shiny_count += 1;
            }

            match get_pokemon_spawn_tier(wild) {
                Some(SpawnTier::NonLegendary) => non_leg_count += 1,
                Some(SpawnTier::PseudoLegendary) => pseudo_leg_count += 1,
                Some(SpawnTier::LegendarySpecial) => leg_special_count += 1,
                None => panic!("Spawned disallowed form: {}", wild.name),
            }
        }

        // 1. Legendary should spawn very rarely (~1%, acceptable bounds 0.4%..=2.0% in 10k trials)
        assert!(
            leg_special_count >= 40 && leg_special_count <= 200,
            "Expected ~1% (40..=200) legendary spawns, got {}",
            leg_special_count
        );

        // 2. Normal pool (non-legendary + pseudo-legendary) should be ~99% (> 9800)
        assert!(
            non_leg_count + pseudo_leg_count >= 9800,
            "Expected >= 9800 normal spawns, got {}",
            non_leg_count + pseudo_leg_count
        );

        // 3. Pseudo-legendaries spawn at normal frequency (in Kanto, Dratini line is 3/146 normal species = ~2%)
        // Nowhere near the broken 27% (which would be ~2700)
        assert!(
            pseudo_leg_count >= 50 && pseudo_leg_count <= 400,
            "Expected normal pseudo-legendary distribution (50..=400), got {}",
            pseudo_leg_count
        );

        // 4. Non-legendaries are the vast majority of normal spawns (~97%)
        assert!(
            non_leg_count >= 9400,
            "Expected >= 9400 non-legendary spawns, got {}",
            non_leg_count
        );

        // 5. Shiny rate remains authentic rare (1 in 4096)
        assert!(
            shiny_count <= 25,
            "Shinies should remain authentic rare (1 in 4096), got {}",
            shiny_count
        );
    }

    #[test]
    fn test_hunt_caption_format() {
        let wild_name = "rapidash";
        let level = 63;

        // Not caught, regular
        let caption = format_hunt_caption(wild_name, level, false, false);
        assert_eq!(caption, "A wild <b>Rapidash</b> (Lv. 63) has appeared!");

        // Already caught, regular -> displays the star emoji with id 5258185631355378853
        let caught_caption = format_hunt_caption(wild_name, level, false, true);
        assert_eq!(
            caught_caption,
            "A wild <b>Rapidash</b> (Lv. 63) has appeared! <tg-emoji emoji-id=\"5258185631355378853\">⭐</tg-emoji>"
        );

        // Not caught, shiny
        let shiny_caption = format_hunt_caption(wild_name, level, true, false);
        assert_eq!(
            shiny_caption,
            "A wild <tg-emoji emoji-id=\"5251676977785483690\">✨</tg-emoji> <b>Rapidash</b> (Lv. 63) has appeared!"
        );

        // Already caught, shiny
        let shiny_caught_caption = format_hunt_caption(wild_name, level, true, true);
        assert_eq!(
            shiny_caught_caption,
            "A wild <tg-emoji emoji-id=\"5251676977785483690\">✨</tg-emoji> <b>Rapidash</b> (Lv. 63) has appeared! <tg-emoji emoji-id=\"5258185631355378853\">⭐</tg-emoji>"
        );
    }

    #[tokio::test]
    async fn test_hunt_already_caught_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        let user_id: i64 = 42;
        let rapidash_id: i64 = 78;

        // 1. Initially, user has not caught Rapidash
        let exists: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM pokemons WHERE user_id = ? AND pokemon_id = ?)"
        )
        .bind(user_id)
        .bind(rapidash_id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(!exists);

        let caption_uncaught = format_hunt_caption("rapidash", 63, false, exists);
        assert_eq!(caption_uncaught, "A wild <b>Rapidash</b> (Lv. 63) has appeared!");

        // 2. User catches Rapidash
        sqlx::query("INSERT INTO pokemons (user_id, pokemon_id, nickname) VALUES (?, ?, 'Rapidash')")
            .bind(user_id)
            .bind(rapidash_id)
            .execute(&pool)
            .await
            .unwrap();

        let exists_after: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM pokemons WHERE user_id = ? AND pokemon_id = ?)"
        )
        .bind(user_id)
        .bind(rapidash_id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(exists_after);

        let caption_caught = format_hunt_caption("rapidash", 63, false, exists_after);
        assert_eq!(
            caption_caught,
            "A wild <b>Rapidash</b> (Lv. 63) has appeared! <tg-emoji emoji-id=\"5258185631355378853\">⭐</tg-emoji>"
        );
    }

    #[test]
    fn test_evolution_stage_classification() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Base forms
        for id in [1, 4, 7, 19, 129, 147, 172] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::Base, "Failed for ID {}", id);
        }

        // Middle forms (Stage 2 in 3-stage chain)
        for id in [2, 5, 8, 25, 148] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::Middle, "Failed for ID {}", id);
        }

        // Final 3-stage forms (Charizard, etc.)
        for id in [3, 6, 9, 26, 149] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::Final3, "Failed for ID {}", id);
        }

        // Final 2-stage forms (Raticate, Gyarados, Arcanine)
        for id in [20, 59, 130] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::Final2, "Failed for ID {}", id);
        }

        // Single stage
        for id in [115, 128, 131, 214] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::SingleStage, "Failed for ID {}", id);
        }

        // Legendary / Mythical / Beast / Paradox
        for id in [150, 384, 793, 984] {
            let pkmn = pokedex.get_pokemon_by_id(id).unwrap();
            assert_eq!(get_pokemon_evolution_stage(pkmn), EvolutionStage::Legendary, "Failed for ID {}", id);
        }

        // Regional forms
        if let Some(rattata_alola) = pokedex.get_pokemon_by_name("rattata-alola") {
            assert_eq!(get_pokemon_evolution_stage(rattata_alola), EvolutionStage::Base);
        }
        if let Some(raticate_alola) = pokedex.get_pokemon_by_name("raticate-alola") {
            assert_eq!(get_pokemon_evolution_stage(raticate_alola), EvolutionStage::Final2);
        }
        if let Some(sliggoo_hisui) = pokedex.get_pokemon_by_name("sliggoo-hisui") {
            assert_eq!(get_pokemon_evolution_stage(sliggoo_hisui), EvolutionStage::Middle);
        }
        if let Some(goodra_hisui) = pokedex.get_pokemon_by_name("goodra-hisui") {
            assert_eq!(get_pokemon_evolution_stage(goodra_hisui), EvolutionStage::Final3);
        }
    }

    #[test]
    fn test_wild_pokemon_level_bounds() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        let charmander = pokedex.get_pokemon_by_id(4).unwrap();
        let charmeleon = pokedex.get_pokemon_by_id(5).unwrap();
        let charizard = pokedex.get_pokemon_by_id(6).unwrap();
        let raticate = pokedex.get_pokemon_by_id(20).unwrap();
        let lapras = pokedex.get_pokemon_by_id(131).unwrap();
        let mewtwo = pokedex.get_pokemon_by_id(150).unwrap();

        // 1. Base form: 1..=30
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(charmander, 80);
            assert!((1..=30).contains(&lvl), "Base form level {} outside 1..=30", lvl);
        }

        // 2. Middle form: 15..=40
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(charmeleon, 80);
            assert!((15..=40).contains(&lvl), "Middle form level {} outside 15..=40", lvl);
        }

        // 3. Final 3-stage form (Charizard): 30..=80
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(charizard, 80);
            assert!((30..=80).contains(&lvl), "Charizard level {} outside 30..=80", lvl);
        }

        // 4. Final 2-stage form: 25..=75
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(raticate, 80);
            assert!((25..=75).contains(&lvl), "Raticate level {} outside 25..=75", lvl);
        }

        // 5. Single stage: 25..=70
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(lapras, 80);
            assert!((25..=70).contains(&lvl), "Lapras level {} outside 25..=70", lvl);
        }

        // 6. Legendary: 50..=80
        for _ in 0..100 {
            let lvl = generate_wild_pokemon_level(mewtwo, 80);
            assert!((50..=80).contains(&lvl), "Mewtwo level {} outside 50..=80", lvl);
        }

        // 7. Strict upper bound: NO pokemon must ever exceed level 80
        for p in pokedex.pokemon.values().take(100) {
            for _ in 0..10 {
                let lvl = generate_wild_pokemon_level(p, 80);
                assert!(lvl <= 80, "Pokemon {} spawned above level 80: {}", p.name, lvl);
                assert!(lvl >= 1, "Pokemon {} spawned below level 1: {}", p.name, lvl);
            }
        }
    }

    #[test]
    fn test_wild_pokemon_level_scales_with_player_level() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        let charmander = pokedex.get_pokemon_by_id(4).unwrap();
        let charmeleon = pokedex.get_pokemon_by_id(5).unwrap();
        let charizard = pokedex.get_pokemon_by_id(6).unwrap();
        let mewtwo = pokedex.get_pokemon_by_id(150).unwrap();

        // 1. Low level player (Level 5 starter):
        // All pokemon (Base, Middle, Final, Legendary) must spawn at low levels (1..=8)
        for _ in 0..100 {
            let lvl_base = generate_wild_pokemon_level(charmander, 5);
            assert!((1..=8).contains(&lvl_base), "Base lvl {} outside 1..=8 for player lvl 5", lvl_base);

            let lvl_mid = generate_wild_pokemon_level(charmeleon, 5);
            assert!((1..=8).contains(&lvl_mid), "Middle lvl {} outside 1..=8 for player lvl 5", lvl_mid);

            let lvl_final = generate_wild_pokemon_level(charizard, 5);
            assert!((1..=8).contains(&lvl_final), "Charizard lvl {} outside 1..=8 for player lvl 5", lvl_final);

            let lvl_legendary = generate_wild_pokemon_level(mewtwo, 5);
            assert!((1..=8).contains(&lvl_legendary), "Mewtwo lvl {} outside 1..=8 for player lvl 5", lvl_legendary);
        }

        // 2. Mid level player (Level 25):
        for _ in 0..100 {
            let lvl_base = generate_wild_pokemon_level(charmander, 25);
            assert!((1..=28).contains(&lvl_base), "Base lvl {} outside 1..=28 for player lvl 25", lvl_base);

            let lvl_final = generate_wild_pokemon_level(charizard, 25);
            assert!((22..=28).contains(&lvl_final), "Charizard lvl {} outside 22..=28 for player lvl 25", lvl_final);
        }

        // 3. High level player (Level 80):
        // Spans all levels lower to higher!
        for _ in 0..100 {
            let lvl_base = generate_wild_pokemon_level(charmander, 80);
            assert!((1..=30).contains(&lvl_base));

            let lvl_final = generate_wild_pokemon_level(charizard, 80);
            assert!((30..=80).contains(&lvl_final));
        }
    }

    #[test]
    fn test_format_hp_bar() {
        // 100% full
        let bar_full = format_hp_bar(38, 38, 10, 12345);
        assert_eq!(bar_full, "<code>██████████</code>");

        // 50% full
        let bar_half = format_hp_bar(19, 38, 10, 12345);
        assert_eq!(bar_half, "<code>█████░░░░░</code>");

        // 0% HP
        let bar_empty = format_hp_bar(0, 38, 10, 12345);
        assert_eq!(bar_empty, "<code>░░░░░░░░░░</code>");

        // Living with 1 HP
        let bar_min = format_hp_bar(1, 380, 10, 12345);
        assert_eq!(bar_min, "<code>█░░░░░░░░░</code>");
    }

    #[test]
    fn test_battle_type_effectiveness() {
        // Super effective
        assert_eq!(get_single_type_effectiveness("water", "fire"), 2.0);
        assert_eq!(get_single_type_effectiveness("electric", "water"), 2.0);

        // Dual typing: Ice vs Dragon / Flying -> 2.0 * 2.0 = 4.0
        let def_dragon_flying = vec!["dragon".to_string(), "flying".to_string()];
        assert_eq!(get_type_effectiveness("ice", &def_dragon_flying), 4.0);

        // Resisted
        assert_eq!(get_single_type_effectiveness("fire", "water"), 0.5);

        // Immunity: Ground vs Flying = 0.0
        assert_eq!(get_type_effectiveness("ground", &def_dragon_flying), 0.0);
        assert_eq!(get_single_type_effectiveness("normal", "ghost"), 0.0);
    }

