    #[test]
    fn test_build_battle_keyboard_structure() {
        let moves = vec![
            MoveDetail { name: "Slam".to_string(), t: "Normal".to_string(), c: "Physical".to_string(), p: Some(80), a: Some(75), pp: Some(20), d: String::new() },
            MoveDetail { name: "Aqua Tail".to_string(), t: "Water".to_string(), c: "Physical".to_string(), p: Some(90), a: Some(90), pp: Some(10), d: String::new() },
            MoveDetail { name: "Dragon Rush".to_string(), t: "Dragon".to_string(), c: "Physical".to_string(), p: Some(100), a: Some(75), pp: Some(10), d: String::new() },
            MoveDetail { name: "Outrage".to_string(), t: "Dragon".to_string(), c: "Physical".to_string(), p: Some(120), a: Some(100), pp: Some(10), d: String::new() },
        ];

        let kb = build_battle_keyboard(12345, &moves);
        assert_eq!(kb.inline_keyboard.len(), 3); // 2 rows of moves + 1 row of actions

        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> Option<&str> {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(data) => Some(data.as_str()),
                _ => None,
            }
        }

        // Row 1: Slam, Aqua Tail
        assert_eq!(kb.inline_keyboard[0][0].text, "Slam");
        assert_eq!(get_cb(&kb.inline_keyboard[0][0]), Some("btl_mv:12345:0"));
        assert_eq!(kb.inline_keyboard[0][1].text, "Aqua Tail");
        assert_eq!(get_cb(&kb.inline_keyboard[0][1]), Some("btl_mv:12345:1"));

        // Row 2: Dragon Rush, Outrage
        assert_eq!(kb.inline_keyboard[1][0].text, "Dragon Rush");
        assert_eq!(get_cb(&kb.inline_keyboard[1][0]), Some("btl_mv:12345:2"));
        assert_eq!(kb.inline_keyboard[1][1].text, "Outrage");
        assert_eq!(get_cb(&kb.inline_keyboard[1][1]), Some("btl_mv:12345:3"));

        // Row 3: Poke Ball, Run, Pokemons
        assert_eq!(kb.inline_keyboard[2][0].text, "Poke Ball");
        assert_eq!(get_cb(&kb.inline_keyboard[2][0]), Some("btl_ball:12345"));
        assert_eq!(kb.inline_keyboard[2][1].text, "Run");
        assert_eq!(get_cb(&kb.inline_keyboard[2][1]), Some("btl_run:12345"));
        assert_eq!(kb.inline_keyboard[2][2].text, "Pokemons");
        assert_eq!(get_cb(&kb.inline_keyboard[2][2]), Some("btl_team:12345"));
    }

