    #[test]
    fn test_gym_and_wild_move_transition_and_screen_header_discipline() {
        // Player attacks: Kyogre using Ancient Power
        let p_log = format_action_log("Kyogre", "Ancient Power", 98, false, 1.0, false);
        // Opponent attacks: Gym Leader Sabrina's Kadabra using Future Sight
        let w_log = format_action_log("Gym Leader Sabrina's Kadabra", "Future Sight", 160, false, 1.0, true);

        // 1. Gym Battle Intermediate Transition must show Player's damage and Opponent attacking
        let gym_transition = format!("{}\n\nGym Leader Sabrina's Kadabra is attacking...", p_log);
        assert!(gym_transition.contains("Kyogre used <b>Ancient Power</b>."));
        assert!(gym_transition.contains("Deal 98 damage."));
        assert!(gym_transition.ends_with("Gym Leader Sabrina's Kadabra is attacking..."));
        assert!(!gym_transition.contains("Future Sight"));
        assert!(!gym_transition.contains("Kyogre is attacking..."));

        // 2. Gym Battle Main Screen Header MUST ONLY contain Gym Leader's attack (NO player damage indicator)
        let header = w_log.clone();
        assert!(header.contains("Gym Leader Sabrina's Kadabra used <b>Future Sight</b>."));
        assert!(header.contains("Deal 160 damage."));
        assert!(!header.contains("Ancient Power"));
        assert!(!header.contains("Kyogre"));

        // 3. Hunt Battle Intermediate Transition must show Player's damage and Wild attacking
        let wild_transition = format!("{}\n\nKadabra is attacking...", p_log);
        assert!(wild_transition.contains("Kyogre used <b>Ancient Power</b>."));
        assert!(wild_transition.ends_with("Kadabra is attacking..."));
        assert!(!wild_transition.contains("Future Sight"));
    }

    #[test]
    fn test_battle_speed_comparison_logic() {
        // Charmander (base 65 spe) vs Snorlax (base 30 spe)
        let player_spe = calc_stat(65, 31, 0, 20, 1.0).0;
        let wild_spe = calc_stat(30, 15, 0, 20, 1.0).0;
        assert!(player_spe > wild_spe);

        // Slowpoke (base 15 spe) vs Jolteon (base 130 spe)
        let slow_player_spe = calc_stat(15, 0, 0, 20, 1.0).0;
        let fast_wild_spe = calc_stat(130, 31, 0, 20, 1.0).0;
        assert!(fast_wild_spe > slow_player_spe);
    }

    #[test]
    fn test_determine_wild_battle_turn_order() {
        // Player faster
        assert!(determine_wild_battle_turn_order(100, 50, false));
        assert!(determine_wild_battle_turn_order(100, 50, true));

        // Wild faster
        assert!(!determine_wild_battle_turn_order(50, 100, false));
        assert!(!determine_wild_battle_turn_order(50, 100, true));

        // Speed tie
        assert!(determine_wild_battle_turn_order(100, 100, true));
        assert!(!determine_wild_battle_turn_order(100, 100, false));
    }

    #[test]
    fn test_shedinja_hp_and_stat_calculations() {
        // Shedinja with base HP 1 must always have exactly 1 HP regardless of IVs, EVs, or Level
        assert_eq!(calc_hp(1, 31, 252, 100), 1);
        assert_eq!(calc_hp(1, 0, 0, 1), 1);

        // Regular Pokemon calculates standard HP formula
        assert_eq!(calc_hp(100, 31, 252, 100), 404);
        assert_eq!(calc_hp(100, 31, 0, 100), 341);
    }

    #[test]
    fn test_ev_impact_on_speed_and_turn_order() {
        // Two Pokemon with identical base 100 speed, level 50, Hardy nature, 31 IV
        // One has 0 Speed EVs, the other has 252 Speed EVs
        let spe_0_ev = calc_stat(100, 31, 0, 50, 1.0).0;
        let spe_252_ev = calc_stat(100, 31, 252, 50, 1.0).0;

        assert_eq!(spe_0_ev, 120);
        assert_eq!(spe_252_ev, 152);
        assert!(spe_252_ev > spe_0_ev);

        // Turn order with EVs: the 252 EV Pokemon outspeeds the 0 EV Pokemon
        assert!(determine_wild_battle_turn_order(spe_252_ev, spe_0_ev, false));
        assert!(!determine_wild_battle_turn_order(spe_0_ev, spe_252_ev, true));
    }

    #[test]
    fn test_ev_impact_on_damage_calculation() {
        let base_stats = BaseStats { hp: 80, attack: 100, defense: 80, special_attack: 100, special_defense: 80, speed: 100 };
        let tackle = MoveDetail {
            name: "Tackle".to_string(),
            t: "Normal".to_string(),
            c: "Physical".to_string(),
            p: Some(40),
            a: Some(100),
            pp: Some(35),
            d: String::new(),
        };

        let attacker_0_ev = BattlePokemon {
            db_id: None, id: 1, name: "Mon".to_string(), nickname: "Mon".to_string(),
            level: 50, types: vec!["Normal".to_string()], nature: "Hardy".to_string(),
            base_stats: base_stats.clone(),
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 140, current_hp: 140, moves: vec![tackle.clone()], is_shiny: false,
            catch_rate: 45, base_experience: 100, is_burned: false,
        };

        let attacker_252_ev = BattlePokemon {
            db_id: None, id: 1, name: "Mon".to_string(), nickname: "Mon".to_string(),
            level: 50, types: vec!["Normal".to_string()], nature: "Hardy".to_string(),
            base_stats: base_stats.clone(),
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 252, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 140, current_hp: 140, moves: vec![tackle.clone()], is_shiny: false,
            catch_rate: 45, base_experience: 100, is_burned: false,
        };

        let defender_0_ev = BattlePokemon {
            db_id: None, id: 2, name: "Def".to_string(), nickname: "Def".to_string(),
            level: 50, types: vec!["Normal".to_string()], nature: "Hardy".to_string(),
            base_stats: base_stats.clone(),
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 140, current_hp: 140, moves: vec![], is_shiny: false,
            catch_rate: 45, base_experience: 100, is_burned: false,
        };

        let defender_252_ev = BattlePokemon {
            db_id: None, id: 2, name: "Def".to_string(), nickname: "Def".to_string(),
            level: 50, types: vec!["Normal".to_string()], nature: "Hardy".to_string(),
            base_stats: base_stats.clone(),
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 252, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 140, current_hp: 140, moves: vec![], is_shiny: false,
            catch_rate: 45, base_experience: 100, is_burned: false,
        };

        // 252 Atk EV deals strictly more damage than 0 Atk EV (fixed roll 100)
        let (dmg_0_atk, _, _) = calculate_authentic_damage_exact(&attacker_0_ev, &tackle, &defender_0_ev, Some(false), Some(100));
        let (dmg_252_atk, _, _) = calculate_authentic_damage_exact(&attacker_252_ev, &tackle, &defender_0_ev, Some(false), Some(100));
        assert!(dmg_252_atk > dmg_0_atk, "Expected 252 Atk EV damage ({}) > 0 Atk EV damage ({})", dmg_252_atk, dmg_0_atk);

        // 252 Def EV takes strictly less damage than 0 Def EV (fixed roll 100)
        let (dmg_against_252_def, _, _) = calculate_authentic_damage_exact(&attacker_0_ev, &tackle, &defender_252_ev, Some(false), Some(100));
        assert!(dmg_0_atk > dmg_against_252_def, "Expected damage against 0 Def ({}) > damage against 252 Def ({})", dmg_0_atk, dmg_against_252_def);
    }

    #[test]
    fn test_battle_switch_turn_logic_fainted_vs_non_fainted() {
        // When Pokémon has fainted (HP == 0), switching brings in the replacement
        // without the wild Pokémon taking an attack turn.
        let fainted_hp = 0;
        let was_fainted = fainted_hp == 0;
        assert!(was_fainted);

        // When Pokémon has NOT fainted (HP > 0), switching uses the player's turn
        // and the wild Pokémon gets the turn to attack the incoming Pokémon.
        let active_hp = 120;
        let was_active = active_hp > 0;
        assert!(was_active);

        // Even if incoming Pokémon has vastly higher speed than the wild Pokémon,
        // switching without fainting still cedes the turn to the wild Pokémon.
        let incoming_spe = calc_stat(130, 31, 252, 50, 1.1).0; // Very fast
        let wild_spe = calc_stat(30, 0, 0, 20, 1.0).0;         // Very slow
        assert!(incoming_spe > wild_spe);

        // Wild Pokémon gets the turn and inflicts damage on the switched-in Pokémon
        let incoming_hp = 150;
        let wild_attack_dmg = 35;
        let incoming_hp_after_turn = (incoming_hp - wild_attack_dmg).max(0);
        assert_eq!(incoming_hp_after_turn, 115);
    }

