    #[tokio::test]
    async fn test_consumed_encounters_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE consumed_encounters (
                chat_id INTEGER NOT NULL,
                message_id INTEGER NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (chat_id, message_id)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        let chat_id: i64 = 123456789;
        let message_id: i32 = 999;

        // 1. Initial check: encounter is not consumed
        let exists: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM consumed_encounters WHERE chat_id = ? AND message_id = ?)"
        )
        .bind(chat_id)
        .bind(message_id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(!exists);

        // 2. Mark as consumed when battle starts
        sqlx::query("INSERT OR IGNORE INTO consumed_encounters (chat_id, message_id) VALUES (?, ?)")
            .bind(chat_id)
            .bind(message_id)
            .execute(&pool)
            .await
            .unwrap();

        // 3. Subsequent check: encounter is now consumed
        let exists_after: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM consumed_encounters WHERE chat_id = ? AND message_id = ?)"
        )
        .bind(chat_id)
        .bind(message_id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(exists_after);
    }

    #[tokio::test]
    async fn test_active_hunts_and_old_hunt_invalidation_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE consumed_encounters (
                chat_id INTEGER NOT NULL,
                message_id INTEGER NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (chat_id, message_id)
            );
            CREATE TABLE active_hunts (
                user_id INTEGER PRIMARY KEY,
                chat_id INTEGER NOT NULL,
                message_id INTEGER NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        let user_id: i64 = 77777;
        let chat_id: i64 = 12345;
        let msg_1: i64 = 101;
        let msg_2: i64 = 102;

        // 1. User performs first hunt (msg_1)
        sqlx::query("INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, ?, ?)")
            .bind(user_id)
            .bind(chat_id)
            .bind(msg_1)
            .execute(&pool)
            .await
            .unwrap();

        // Verify msg_1 is active and not consumed
        let is_msg1_active: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM active_hunts WHERE user_id = ? AND chat_id = ? AND message_id = ?)"
        )
        .bind(user_id)
        .bind(chat_id)
        .bind(msg_1)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(is_msg1_active);

        // 2. User performs second hunt (msg_2): look up previous hunt, mark it consumed, update active_hunts
        let prev_hunt = sqlx::query(
            "SELECT chat_id, message_id FROM active_hunts WHERE user_id = ?"
        )
        .bind(user_id)
        .fetch_optional(&pool)
        .await
        .unwrap();

        assert!(prev_hunt.is_some());

        if let Some(row) = prev_hunt {
            let old_chat: i64 = row.get("chat_id");
            let old_msg: i64 = row.get("message_id");
            assert_eq!(old_chat, chat_id);
            assert_eq!(old_msg, msg_1);

            sqlx::query("INSERT OR IGNORE INTO consumed_encounters (chat_id, message_id) VALUES (?, ?)")
                .bind(old_chat)
                .bind(old_msg)
                .execute(&pool)
                .await
                .unwrap();
        }

        sqlx::query(
            "INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, ?, ?)
             ON CONFLICT(user_id) DO UPDATE SET chat_id = excluded.chat_id, message_id = excluded.message_id"
        )
        .bind(user_id)
        .bind(chat_id)
        .bind(msg_2)
        .execute(&pool)
        .await
        .unwrap();

        // 3. Verify old hunt (msg_1) is now in consumed_encounters and NOT active
        let is_msg1_consumed: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM consumed_encounters WHERE chat_id = ? AND message_id = ?)"
        )
        .bind(chat_id)
        .bind(msg_1)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(is_msg1_consumed, "Old hunt must be consumed");

        let is_msg1_still_active: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM active_hunts WHERE user_id = ? AND chat_id = ? AND message_id = ?)"
        )
        .bind(user_id)
        .bind(chat_id)
        .bind(msg_1)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(!is_msg1_still_active, "Old hunt must not be active");

        // 4. Verify new hunt (msg_2) is active and NOT consumed
        let is_msg2_consumed: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM consumed_encounters WHERE chat_id = ? AND message_id = ?)"
        )
        .bind(chat_id)
        .bind(msg_2)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(!is_msg2_consumed, "New hunt must not be consumed");

        let is_msg2_active: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM active_hunts WHERE user_id = ? AND chat_id = ? AND message_id = ?)"
        )
        .bind(user_id)
        .bind(chat_id)
        .bind(msg_2)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert!(is_msg2_active, "New hunt must be active");
    }

