    #[test]
    fn test_calculate_catch_result_shake_stages() {
        // Test controlled rolls for break free at 1 star, 2 stars, 3 stars, and caught
        // For a = 50, p = (50/255)^0.25 ≈ 0.665
        let catch_rate = 50;
        let hp = 100;

        // Roll 0 fails (>= p) -> BrokeFree(1)
        let res1 = calculate_catch_result_with_rolls(catch_rate, hp, hp, "regular", 1.0, [0.99, 0.0, 0.0, 0.0]);
        assert_eq!(res1, CatchResult::BrokeFree(1));

        // Roll 0 succeeds, Roll 1 fails -> BrokeFree(2)
        let res2 = calculate_catch_result_with_rolls(catch_rate, hp, hp, "regular", 1.0, [0.1, 0.99, 0.0, 0.0]);
        assert_eq!(res2, CatchResult::BrokeFree(2));

        // Roll 0 & 1 succeed, Roll 2 fails -> BrokeFree(3)
        let res3 = calculate_catch_result_with_rolls(catch_rate, hp, hp, "regular", 1.0, [0.1, 0.1, 0.99, 0.0]);
        assert_eq!(res3, CatchResult::BrokeFree(3));

        // Roll 0, 1, 2 succeed, Roll 3 fails -> BrokeFree(3)
        let res4 = calculate_catch_result_with_rolls(catch_rate, hp, hp, "regular", 1.0, [0.1, 0.1, 0.1, 0.99]);
        assert_eq!(res4, CatchResult::BrokeFree(3));

        // All succeed -> Caught
        let res5 = calculate_catch_result_with_rolls(catch_rate, hp, hp, "regular", 1.0, [0.1, 0.1, 0.1, 0.1]);
        assert_eq!(res5, CatchResult::Caught);
    }

