    #[test]
    fn test_is_valid_nickname() {
        assert!(is_valid_nickname("Pikachu"));
        assert!(is_valid_nickname("Charizard99"));
        assert!(is_valid_nickname("A1B2C3"));
        assert!(is_valid_nickname("a"));
        assert!(is_valid_nickname("12345"));

        // Invalid: spaces in middle
        assert!(!is_valid_nickname("Pikachu 1"));
        assert!(!is_valid_nickname("Sparky The Dog"));
        // Invalid: symbols
        assert!(!is_valid_nickname("Pika-chu"));
        assert!(!is_valid_nickname("Sparky!"));
        assert!(!is_valid_nickname("Cat@123"));
        assert!(!is_valid_nickname("Poke_mon"));
        assert!(!is_valid_nickname("⭐"));
        // Invalid: empty or whitespace
        assert!(!is_valid_nickname(""));
        assert!(!is_valid_nickname("   "));
        // Invalid: too long (>20 chars)
        assert!(!is_valid_nickname("abcdefghijklmnopqrstuvwxyz"));
    }

