    #[tokio::test]
    async fn test_clear_user_stuck_states() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();

        sqlx::query(
            "CREATE TABLE user_safari (
                user_id INTEGER PRIMARY KEY,
                is_active INTEGER NOT NULL DEFAULT 1,
                balls_remaining INTEGER NOT NULL DEFAULT 30
            );"
        ).execute(&pool).await.unwrap();

        sqlx::query(
            "CREATE TABLE user_evtrain (
                user_id INTEGER PRIMARY KEY,
                is_active INTEGER NOT NULL DEFAULT 1
            );"
        ).execute(&pool).await.unwrap();

        sqlx::query(
            "CREATE TABLE active_hunts (
                user_id INTEGER PRIMARY KEY,
                chat_id INTEGER NOT NULL,
                message_id INTEGER NOT NULL
            );"
        ).execute(&pool).await.unwrap();

        let user_id = 99999u64;

        sqlx::query("INSERT INTO user_safari (user_id, is_active, balls_remaining) VALUES (?, 1, 30)")
            .bind(user_id as i64)
            .execute(&pool)
            .await
            .unwrap();

        sqlx::query("INSERT INTO user_evtrain (user_id, is_active) VALUES (?, 1)")
            .bind(user_id as i64)
            .execute(&pool)
            .await
            .unwrap();

        sqlx::query("INSERT INTO active_hunts (user_id, chat_id, message_id) VALUES (?, 100, 200)")
            .bind(user_id as i64)
            .execute(&pool)
            .await
            .unwrap();

        let battles: BattleSessions = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let challenges: ChallengeSessions = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let trades: TradeSessions = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let pending_nicknames: PendingNicknames = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let working_teams: WorkingTeams = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let pending_team_actions: PendingTeamActions = Arc::new(tokio::sync::RwLock::new(HashMap::new()));
        let card_sessions: CardSessions = Arc::new(tokio::sync::RwLock::new(HashMap::new()));

        let dummy_pokemon = BattlePokemon {
            db_id: Some(1),
            id: 25,
            name: "Pikachu".to_string(),
            nickname: "Pikachu".to_string(),
            level: 25,
            types: vec!["electric".to_string()],
            nature: "Hardy".to_string(),
            base_stats: BaseStats {
                hp: 35,
                attack: 55,
                defense: 40,
                special_attack: 50,
                special_defense: 50,
                speed: 90,
            },
            iv_hp: 15,
            iv_atk: 15,
            iv_def: 15,
            iv_spa: 15,
            iv_spd: 15,
            iv_spe: 15,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            max_hp: 100,
            current_hp: 100,
            moves: vec![],
            is_shiny: false,
            catch_rate: 190,
            base_experience: 112,
            is_burned: false,
        };

        battles.write().await.insert(user_id, ActiveBattle {
            owner_id: user_id,
            chat_id: ChatId(123),
            message_id: MessageId(456),
            trainer_name: "Trainer".to_string(),
            player_pokemon: dummy_pokemon.clone(),
            wild_pokemon: dummy_pokemon,
            turn_count: 0,
            last_action: "None".to_string(),
            fainted_pokemon_ids: Vec::new(),
            fainted_team_indices: Vec::new(),
            team_hp: HashMap::new(),
            is_evtrain: false,
            gym_info: None,
            last_activity: chrono::Utc::now(),
        });

        pending_nicknames.write().await.insert(user_id, PendingNickname {
            pokemon_db_id: 1,
            prompt_message_id: 123,
            original_name: "Pikachu".to_string(),
        });

        working_teams.write().await.insert(user_id, vec![1, 2, 3]);

        pending_team_actions.write().await.insert(user_id, PendingTeamAction {
            editor_message_id: 123,
            chat_id: 456,
        });

        clear_user_stuck_states(
            &pool,
            user_id,
            &battles,
            &challenges,
            &trades,
            &pending_nicknames,
            &working_teams,
            &pending_team_actions,
            &card_sessions,
        ).await;

        assert!(!battles.read().await.contains_key(&user_id));
        assert!(!pending_nicknames.read().await.contains_key(&user_id));
        assert!(!working_teams.read().await.contains_key(&user_id));
        assert!(!pending_team_actions.read().await.contains_key(&user_id));

        let safari_active: (i32, i32) = sqlx::query_as("SELECT is_active, balls_remaining FROM user_safari WHERE user_id = ?")
            .bind(user_id as i64)
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(safari_active, (0, 0));

        let evtrain_active: i32 = sqlx::query_scalar("SELECT is_active FROM user_evtrain WHERE user_id = ?")
            .bind(user_id as i64)
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(evtrain_active, 0);

        let active_hunt: Option<i64> = sqlx::query_scalar("SELECT user_id FROM active_hunts WHERE user_id = ?")
            .bind(user_id as i64)
            .fetch_optional(&pool)
            .await
            .unwrap();
        assert!(active_hunt.is_none());
    }

    #[test]
    fn test_format_mypokemon_text() {
        let items = vec![
            MyPokemonItem {
                nickname: "Magnemite".to_string(),
                nature: "Quirky".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: false,
                detail: None,
            },
            MyPokemonItem {
                nickname: "Weedle".to_string(),
                nature: "Relaxed".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: false,
                detail: None,
            },
            MyPokemonItem {
                nickname: "Charizard".to_string(),
                nature: "Adamant".to_string(),
                is_shiny: true,
                is_hatched: false,
                is_chibi: false,
                detail: None,
            },
        ];

        let text = format_mypokemon_text(
            &items,
            1,
            20,
            754,
            SortOption::IvPoints,
            SortDirection::Descending,
            DisplayOption::Nature,
            true,
        );
        let expected = concat!(
            "1. <b>Magnemite</b> - Quirky\n",
            "2. <b>Weedle</b> - Relaxed\n",
            "3. <tg-emoji emoji-id=\"5251676977785483690\">✨</tg-emoji> <b>Charizard</b> - Adamant\n\n",
            "Total Pokemon: 754\n",
            "/sort by: IV points ↓\n",
            "/display: Nature\n",
            "/pagesize: 20"
        );
        assert_eq!(text, expected);

        // Page 2 indexing
        let page2_text = format_mypokemon_text(
            &items,
            2,
            20,
            754,
            SortOption::IvPoints,
            SortDirection::Descending,
            DisplayOption::Nature,
            true,
        );
        assert!(page2_text.starts_with("21. <b>Magnemite</b> - Quirky\n22. <b>Weedle</b> - Relaxed"));
    }

    #[test]
    fn test_build_mypokemon_keyboard_single_page() {
        let kb = build_mypokemon_keyboard(12345, 1, 1);
        assert_eq!(kb.inline_keyboard.len(), 1);
        assert_eq!(kb.inline_keyboard[0].len(), 3);
        assert_eq!(kb.inline_keyboard[0][0].text, "←");
        assert_eq!(kb.inline_keyboard[0][1].text, "1/1");
        assert_eq!(kb.inline_keyboard[0][2].text, "→");

        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> Option<&str> {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(data) => Some(data.as_str()),
                _ => None,
            }
        }
        assert_eq!(get_cb(&kb.inline_keyboard[0][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[0][1]), Some("noop"));
        assert_eq!(get_cb(&kb.inline_keyboard[0][2]), Some("mypkmn:12345:1"));
    }

    #[test]
    fn test_build_mypokemon_keyboard_multi_page() {
        let kb = build_mypokemon_keyboard(12345, 1, 38);
        assert_eq!(kb.inline_keyboard.len(), 5);

        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> Option<&str> {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(data) => Some(data.as_str()),
                _ => None,
            }
        }

        // Row 1: [ ← ] [ 1/38 ] [ → ]
        assert_eq!(kb.inline_keyboard[0][0].text, "←");
        assert_eq!(kb.inline_keyboard[0][1].text, "1/38");
        assert_eq!(kb.inline_keyboard[0][2].text, "→");
        assert_eq!(get_cb(&kb.inline_keyboard[0][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[0][1]), Some("noop"));
        assert_eq!(get_cb(&kb.inline_keyboard[0][2]), Some("mypkmn:12345:2"));

        // Row 2: [ (-5) ← ] [ → (+5) ]
        assert_eq!(kb.inline_keyboard[1][0].text, "(-5) ←");
        assert_eq!(kb.inline_keyboard[1][1].text, "→ (+5)");
        assert_eq!(get_cb(&kb.inline_keyboard[1][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[1][1]), Some("mypkmn:12345:6"));

        // Row 3: [ (-10) ← ] [ → (+10) ]
        assert_eq!(kb.inline_keyboard[2][0].text, "(-10) ←");
        assert_eq!(kb.inline_keyboard[2][1].text, "→ (+10)");
        assert_eq!(get_cb(&kb.inline_keyboard[2][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[2][1]), Some("mypkmn:12345:11"));

        // Row 4: [ (-20) ← ] [ → (+20) ]
        assert_eq!(kb.inline_keyboard[3][0].text, "(-20) ←");
        assert_eq!(kb.inline_keyboard[3][1].text, "→ (+20)");
        assert_eq!(get_cb(&kb.inline_keyboard[3][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[3][1]), Some("mypkmn:12345:21"));

        // Row 5: [ (-30) ← ] [ → (+30) ]
        assert_eq!(kb.inline_keyboard[4][0].text, "(-30) ←");
        assert_eq!(kb.inline_keyboard[4][1].text, "→ (+30)");
        assert_eq!(get_cb(&kb.inline_keyboard[4][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb.inline_keyboard[4][1]), Some("mypkmn:12345:31"));

        // When user has 14 pages (from screenshot): only ±5 and ±10 should appear (3 rows total)
        let kb_14 = build_mypokemon_keyboard(12345, 1, 14);
        assert_eq!(kb_14.inline_keyboard.len(), 3);
        assert_eq!(kb_14.inline_keyboard[0][1].text, "1/14");
        assert_eq!(kb_14.inline_keyboard[1][0].text, "(-5) ←");
        assert_eq!(kb_14.inline_keyboard[2][0].text, "(-10) ←");

        // From mid-range page 25
        let kb_mid = build_mypokemon_keyboard(12345, 25, 38);
        assert_eq!(kb_mid.inline_keyboard[0][1].text, "25/38");
        assert_eq!(get_cb(&kb_mid.inline_keyboard[0][0]), Some("mypkmn:12345:24"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[0][2]), Some("mypkmn:12345:26"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[1][0]), Some("mypkmn:12345:20"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[1][1]), Some("mypkmn:12345:30"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[2][0]), Some("mypkmn:12345:15"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[2][1]), Some("mypkmn:12345:35"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[3][0]), Some("mypkmn:12345:5"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[3][1]), Some("mypkmn:12345:38"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[4][0]), Some("mypkmn:12345:1"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[4][1]), Some("mypkmn:12345:38"));
    }

