    #[test]
    fn test_sort_pokemon_logic() {
        let pokedex = PokedexData::default();
        let mut list = vec![
            PokemonDbRecord {
                id: 1,
                pokemon_id: 25,
                nickname: "Pikachu".to_string(),
                level: 50,
                nature: "Hardy".to_string(),
                iv_hp: 10, iv_attack: 10, iv_defense: 10, iv_sp_attack: 10, iv_sp_defense: 10, iv_speed: 10,
                ev_hp: 0, ev_attack: 0, ev_defense: 0, ev_sp_attack: 0, ev_sp_defense: 0, ev_speed: 0,
                is_shiny: false,
                is_hatched: false,
            },
            PokemonDbRecord {
                id: 2,
                pokemon_id: 1,
                nickname: "Bulbasaur".to_string(),
                level: 10,
                nature: "Bold".to_string(),
                iv_hp: 31, iv_attack: 31, iv_defense: 31, iv_sp_attack: 31, iv_sp_defense: 31, iv_speed: 31,
                ev_hp: 0, ev_attack: 0, ev_defense: 0, ev_sp_attack: 0, ev_sp_defense: 0, ev_speed: 0,
                is_shiny: false,
                is_hatched: false,
            },
        ];

        // Sort by IV points descending -> Bulbasaur (total 186) should be first
        sort_pokemons(&mut list, &pokedex, SortOption::IvPoints, SortDirection::Descending);
        assert_eq!(list[0].nickname, "Bulbasaur");
        assert_eq!(list[1].nickname, "Pikachu");

        // Sort by Level descending -> Pikachu (50) should be first
        sort_pokemons(&mut list, &pokedex, SortOption::Level, SortDirection::Descending);
        assert_eq!(list[0].nickname, "Pikachu");
        assert_eq!(list[1].nickname, "Bulbasaur");

        // Sort by Level ascending -> Bulbasaur (10) should be first
        sort_pokemons(&mut list, &pokedex, SortOption::Level, SortDirection::Ascending);
        assert_eq!(list[0].nickname, "Bulbasaur");
        assert_eq!(list[1].nickname, "Pikachu");
    }

