    #[test]
    fn test_build_mypokemon_keyboard_json_arrows() {
        let json = build_mypokemon_keyboard_json(12345, 1, 38);
        let rows = json["inline_keyboard"].as_array().unwrap();
        assert_eq!(rows.len(), 5);

        // Row 1 left button has custom left arrow
        assert_eq!(rows[0][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows[0][0]["callback_data"], "mypkmn:12345:1");

        // Row 1 middle button is page counter
        assert_eq!(rows[0][1]["text"], "1/38");
        assert_eq!(rows[0][1]["callback_data"], "noop");

        // Row 1 right button has custom right arrow
        assert_eq!(rows[0][2]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows[0][2]["callback_data"], "mypkmn:12345:2");

        // Jump rows have custom arrows
        assert_eq!(rows[1][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows[1][0]["text"], "(-5)");
        assert_eq!(rows[1][1]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows[1][1]["text"], "(+5)");

        // 14 pages should only have 3 rows (Row 0: 1/14, Row 1: ±5, Row 2: ±10)
        let json_14 = build_mypokemon_keyboard_json(12345, 1, 14);
        let rows_14 = json_14["inline_keyboard"].as_array().unwrap();
        assert_eq!(rows_14.len(), 3);
        assert_eq!(rows_14[1][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows_14[1][1]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows_14[2][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows_14[2][1]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);

        // Single page should only have 1 row
        let json_single = build_mypokemon_keyboard_json(12345, 1, 1);
        let rows_single = json_single["inline_keyboard"].as_array().unwrap();
        assert_eq!(rows_single.len(), 1);
        assert_eq!(rows_single[0][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows_single[0][2]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);
    }

