    #[test]
    fn test_format_pokedex_charmander_spec() {
        let mut evs = HashMap::new();
        evs.insert("Speed".to_string(), 1);

        let charmander = PokemonEntry {
            id: 4,
            name: "charmander".to_string(),
            types: vec!["Fire".to_string()],
            stats: BaseStats {
                hp: 39,
                attack: 52,
                defense: 43,
                special_attack: 60,
                special_defense: 50,
                speed: 65,
            },
            catch_rate: Some(45),
            ev_yields: evs,
            ..Default::default()
        };

        let about = format_pokedex_about_caption(&charmander);
        let expected_about = format!(
            "Pokedex No. 4\nName: Charmander\nTypes: [{}]\nCatch probability: Low\nGrowth rate: Medium Slow\nRegions found: [Kanto, Johto, Kalos, Galar, Paldea]",
            format_type_with_emoji("Fire")
        );
        assert_eq!(about, expected_about);

        let pidgey = PokemonEntry {
            id: 16,
            name: "pidgey".to_string(),
            types: vec!["Normal".to_string(), "Flying".to_string()],
            ..Default::default()
        };
        let pidgey_about = format_pokedex_about_caption(&pidgey);
        assert!(pidgey_about.contains(&format!(
            "Types: [{} / {}]",
            format_type_with_emoji("Normal"),
            format_type_with_emoji("Flying")
        )));

        let stats = format_pokedex_stats_caption(&charmander);
        assert_eq!(
            stats,
            "<b>HP:</b> 39\n<b>Attack:</b> 52\n<b>Defense:</b> 43\n<b>Sp. Attack:</b> 60\n<b>Sp. Defense:</b> 50\n<b>Speed:</b> 65"
        );

        let evs_text = format_pokedex_ev_caption(&charmander);
        assert_eq!(evs_text, "Speed: +1");
    }

