    #[test]
    fn test_build_pokedexall_keyboard() {
        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> Option<&str> {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(data) => Some(data.as_str()),
                _ => None,
            }
        }

        // Single page (total_pages = 1) has only 1 row
        let kb_single = build_pokedexall_keyboard(12345, 1, 1);
        assert_eq!(kb_single.inline_keyboard.len(), 1);
        assert_eq!(get_cb(&kb_single.inline_keyboard[0][0]), Some("pdxa:12345:1"));
        assert_eq!(kb_single.inline_keyboard[0][1].text, "1/1");
        assert_eq!(get_cb(&kb_single.inline_keyboard[0][1]), Some("noop"));
        assert_eq!(get_cb(&kb_single.inline_keyboard[0][2]), Some("pdxa:12345:1"));

        // Multi page (total_pages = 48, current_page = 1) has 5 rows
        let kb = build_pokedexall_keyboard(12345, 1, 48);
        assert_eq!(kb.inline_keyboard.len(), 5);

        // Row 1: ←, 1/48, →
        assert_eq!(get_cb(&kb.inline_keyboard[0][0]), Some("pdxa:12345:1"));
        assert_eq!(kb.inline_keyboard[0][1].text, "1/48");
        assert_eq!(get_cb(&kb.inline_keyboard[0][2]), Some("pdxa:12345:2"));

        // Row 2: (-5) ←, → (+5)
        assert_eq!(kb.inline_keyboard[1][0].text, "(-5) ←");
        assert_eq!(get_cb(&kb.inline_keyboard[1][0]), Some("pdxa:12345:1"));
        assert_eq!(kb.inline_keyboard[1][1].text, "→ (+5)");
        assert_eq!(get_cb(&kb.inline_keyboard[1][1]), Some("pdxa:12345:6"));

        // Row 3: (-10) ←, → (+10)
        assert_eq!(kb.inline_keyboard[2][0].text, "(-10) ←");
        assert_eq!(get_cb(&kb.inline_keyboard[2][0]), Some("pdxa:12345:1"));
        assert_eq!(kb.inline_keyboard[2][1].text, "→ (+10)");
        assert_eq!(get_cb(&kb.inline_keyboard[2][1]), Some("pdxa:12345:11"));

        // Row 4: (-20) ←, → (+20)
        assert_eq!(kb.inline_keyboard[3][0].text, "(-20) ←");
        assert_eq!(get_cb(&kb.inline_keyboard[3][0]), Some("pdxa:12345:1"));
        assert_eq!(kb.inline_keyboard[3][1].text, "→ (+20)");
        assert_eq!(get_cb(&kb.inline_keyboard[3][1]), Some("pdxa:12345:21"));

        // Row 5: (-30) ←, → (+30)
        assert_eq!(kb.inline_keyboard[4][0].text, "(-30) ←");
        assert_eq!(get_cb(&kb.inline_keyboard[4][0]), Some("pdxa:12345:1"));
        assert_eq!(kb.inline_keyboard[4][1].text, "→ (+30)");
        assert_eq!(get_cb(&kb.inline_keyboard[4][1]), Some("pdxa:12345:31"));

        // Middle page jumps: current_page = 25
        let kb_mid = build_pokedexall_keyboard(12345, 25, 48);
        assert_eq!(get_cb(&kb_mid.inline_keyboard[0][0]), Some("pdxa:12345:24"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[0][2]), Some("pdxa:12345:26"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[1][0]), Some("pdxa:12345:20"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[1][1]), Some("pdxa:12345:30"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[2][0]), Some("pdxa:12345:15"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[2][1]), Some("pdxa:12345:35"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[3][0]), Some("pdxa:12345:5"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[3][1]), Some("pdxa:12345:45"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[4][0]), Some("pdxa:12345:1"));
        assert_eq!(get_cb(&kb_mid.inline_keyboard[4][1]), Some("pdxa:12345:48"));
    }

