    #[test]
    fn test_check_move_miss_mechanic() {
        // Moves with None or 0 accuracy (never miss moves like Swift, Aerial Ace, Aura Sphere)
        let swift = MoveDetail { name: "Swift".to_string(), t: "Normal".to_string(), c: "Special".to_string(), p: Some(60), a: None, pp: Some(20), d: String::new() };
        assert!(!check_move_miss_with_roll(&swift, 0));
        assert!(!check_move_miss_with_roll(&swift, 99));

        let aura_sphere = MoveDetail { name: "Aura Sphere".to_string(), t: "Fighting".to_string(), c: "Special".to_string(), p: Some(80), a: Some(0), pp: Some(20), d: String::new() };
        assert!(!check_move_miss_with_roll(&aura_sphere, 99));

        // Accuracy >= 100 lands 100% of the time (never misses)
        let tackle = MoveDetail { name: "Tackle".to_string(), t: "Normal".to_string(), c: "Physical".to_string(), p: Some(40), a: Some(100), pp: Some(35), d: String::new() };
        for roll in 0..100 {
            assert!(!check_move_miss_with_roll(&tackle, roll));
        }

        // Accuracy < 100 has a (100 - Accuracy)% chance to miss
        // Hydro Pump with 80 acc has 20% miss chance: hits on 1..=80 (80%), misses on 81..=100 (20%)
        let hydro_pump = MoveDetail { name: "Hydro Pump".to_string(), t: "Water".to_string(), c: "Special".to_string(), p: Some(110), a: Some(80), pp: Some(5), d: String::new() };
        assert!(!check_move_miss_with_roll(&hydro_pump, 80)); // lands (80th hitting roll)
        assert!(check_move_miss_with_roll(&hydro_pump, 81));  // misses (first of the 20 missing rolls)
        assert!(check_move_miss_with_roll(&hydro_pump, 100)); // misses

        // Blizzard with 70 acc: hits on 1..=70 (70%), misses on 71..=100 (30%)
        let blizzard = MoveDetail { name: "Blizzard".to_string(), t: "Ice".to_string(), c: "Special".to_string(), p: Some(110), a: Some(70), pp: Some(5), d: String::new() };
        assert!(!check_move_miss_with_roll(&blizzard, 70)); // lands (70th hitting roll)
        assert!(check_move_miss_with_roll(&blizzard, 71));  // misses (first of the 30 missing rolls)
    }

    #[test]
    fn test_authentic_damage_burn_reduction() {
        let mut physical_attacker = BattlePokemon {
            db_id: None,
            id: 68,
            name: "Machamp".to_string(),
            nickname: "Machamp".to_string(),
            level: 50,
            types: vec!["Fighting".to_string()],
            nature: "Adamant".to_string(),
            base_stats: BaseStats { hp: 90, attack: 130, defense: 80, special_attack: 65, special_defense: 85, speed: 55 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 252, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 165,
            current_hp: 165,
            moves: vec![],
            is_shiny: false,
            catch_rate: 45,
            base_experience: 227,
            is_burned: false,
        };

        let target = BattlePokemon {
            db_id: None,
            id: 143,
            name: "Snorlax".to_string(),
            nickname: "Snorlax".to_string(),
            level: 50,
            types: vec!["Normal".to_string()],
            nature: "Hardy".to_string(),
            base_stats: BaseStats { hp: 160, attack: 110, defense: 65, special_attack: 65, special_defense: 110, speed: 30 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 235,
            current_hp: 235,
            moves: vec![],
            is_shiny: false,
            catch_rate: 25,
            base_experience: 189,
            is_burned: false,
        };

        let close_combat = MoveDetail { name: "Close Combat".to_string(), t: "Fighting".to_string(), c: "Physical".to_string(), p: Some(120), a: Some(100), pp: Some(5), d: String::new() };
        let focus_blast = MoveDetail { name: "Focus Blast".to_string(), t: "Fighting".to_string(), c: "Special".to_string(), p: Some(120), a: Some(70), pp: Some(5), d: String::new() };

        // Unburned physical damage
        let (unburned_dmg, _, _) = calculate_authentic_damage_exact(&physical_attacker, &close_combat, &target, Some(false), Some(100));

        // Burned physical damage (halved by 0.5x)
        physical_attacker.is_burned = true;
        let (burned_dmg, _, _) = calculate_authentic_damage_exact(&physical_attacker, &close_combat, &target, Some(false), Some(100));
        assert_eq!(burned_dmg, unburned_dmg / 2);

        // Special attack is NOT reduced by burn
        physical_attacker.is_burned = false;
        let (unburned_sp_dmg, _, _) = calculate_authentic_damage_exact(&physical_attacker, &focus_blast, &target, Some(false), Some(100));
        physical_attacker.is_burned = true;
        let (burned_sp_dmg, _, _) = calculate_authentic_damage_exact(&physical_attacker, &focus_blast, &target, Some(false), Some(100));
        assert_eq!(burned_sp_dmg, unburned_sp_dmg);
    }

    #[test]
    fn test_defender_hp_overkill_cap() {
        let calculated_dmg = 842;
        let defender_current_hp = 45;

        // Defender HP overkill cap
        let actual_dmg = calculated_dmg.min(defender_current_hp);
        assert_eq!(actual_dmg, 45);

        // Zero-floor HP clamping
        let new_hp = (defender_current_hp - actual_dmg).max(0);
        assert_eq!(new_hp, 0);
    }

