    #[test]
    fn test_calculate_vitamin_application_limits() {
        // Normal 1x use (+10 EVs, 1 vitamin)
        let res1 = calculate_vitamin_application(0, 0, 100, 1).expect("ok");
        assert_eq!(res1, VitaminResult { ev_gain: 10, vitamins_used: 1 });

        // Normal 5x use (+50 EVs, 5 vitamins)
        let res5 = calculate_vitamin_application(0, 0, 100, 5).expect("ok");
        assert_eq!(res5, VitaminResult { ev_gain: 50, vitamins_used: 5 });

        // Normal 10x use (+100 EVs, 10 vitamins)
        let res10 = calculate_vitamin_application(0, 0, 100, 10).expect("ok");
        assert_eq!(res10, VitaminResult { ev_gain: 100, vitamins_used: 10 });

        // Cap at 252 (stat at 250, wants 5x -> only needs 2 EVs -> 1 vitamin)
        let res_cap = calculate_vitamin_application(250, 250, 10, 5).expect("ok");
        assert_eq!(res_cap, VitaminResult { ev_gain: 2, vitamins_used: 1 });

        // Stat already at 252
        let err_stat = calculate_vitamin_application(252, 252, 10, 1);
        assert!(err_stat.is_err());

        // Total cap at 510 (total at 505, stat at 0, wants 5x -> only 5 EVs -> 1 vitamin)
        let res_tot_cap = calculate_vitamin_application(0, 505, 10, 5).expect("ok");
        assert_eq!(res_tot_cap, VitaminResult { ev_gain: 5, vitamins_used: 1 });

        // Total already at 510
        let err_tot = calculate_vitamin_application(0, 510, 10, 1);
        assert!(err_tot.is_err());

        // No vitamins
        let err_vit = calculate_vitamin_application(0, 0, 0, 1);
        assert!(err_vit.is_err());
    }

