    #[tokio::test]
    async fn test_candy_move_learning_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                candies INTEGER NOT NULL DEFAULT 100
            );
            CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 19,
                experience INTEGER NOT NULL DEFAULT 6859,
                move_1 TEXT,
                move_2 TEXT,
                move_3 TEXT,
                move_4 TEXT
            );"
        ).execute(&pool).await.unwrap();

        sqlx::query("INSERT INTO users (id, candies) VALUES (1, 20)").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, move_1) VALUES (10, 1, 102, 'Exeggcute', 19, 'Barrage')").execute(&pool).await.unwrap();

        // Check initial state
        let candies: i64 = sqlx::query_scalar("SELECT candies FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        assert_eq!(candies, 20);

        // Apply 1 candy -> Lv. 20
        let res = calculate_candy_application(19, candies, 1).unwrap();
        assert_eq!(res.new_level, 20);
        sqlx::query("UPDATE users SET candies = candies - ? WHERE id = 1").bind(res.candies_used).execute(&pool).await.unwrap();
        sqlx::query("UPDATE pokemons SET level = ? WHERE id = 10").bind(res.new_level).execute(&pool).await.unwrap();

        // Empty slot 2 gets Confusion
        sqlx::query("UPDATE pokemons SET move_2 = 'Confusion' WHERE id = 10").execute(&pool).await.unwrap();

        let lvl: i32 = sqlx::query_scalar("SELECT level FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        let m2: Option<String> = sqlx::query_scalar("SELECT move_2 FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        let rem_candies: i64 = sqlx::query_scalar("SELECT candies FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();

        assert_eq!(lvl, 20);
        assert_eq!(m2, Some("Confusion".to_string()));
        assert_eq!(rem_candies, 19);

        // Fill remaining slots
        sqlx::query("UPDATE pokemons SET move_3 = 'Solar Beam', move_4 = 'Psychic' WHERE id = 10").execute(&pool).await.unwrap();

        // Forget slot 1 ('Barrage') and teach 'Giga Drain'
        sqlx::query("UPDATE pokemons SET move_1 = 'Giga Drain' WHERE id = 10").execute(&pool).await.unwrap();
        let m1_updated: Option<String> = sqlx::query_scalar("SELECT move_1 FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        assert_eq!(m1_updated, Some("Giga Drain".to_string()));
    }

