    #[test]
    fn test_calculate_boost_application_limits_and_rules() {
        // Valid boost (+1 IV, -1 Boost)
        let res = calculate_boost_application("atk", 29, "", 5);
        assert_eq!(res, Ok(BoostResult { iv_gain: 1, boosts_used: 1 }));

        // Rejection: same stat cannot be boosted twice
        let res_repeat = calculate_boost_application("atk", 30, "atk", 4);
        assert_eq!(res_repeat, Err("This IV stat has already been boosted!"));

        let res_repeat_multi = calculate_boost_application("def", 15, "hp,def", 4);
        assert_eq!(res_repeat_multi, Err("This IV stat has already been boosted!"));

        // Rejection: stat already at max (31 IV)
        let res_max = calculate_boost_application("spe", 31, "", 5);
        assert_eq!(res_max, Err("This IV stat is already at max (31 IV)!"));

        // Rejection: zero boosts in inventory
        let res_zero = calculate_boost_application("hp", 17, "", 0);
        assert_eq!(res_zero, Err("You don't have enough Boosts!"));
    }

    #[tokio::test]
    async fn test_boost_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                boosts INTEGER NOT NULL DEFAULT 10
            );
            CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                iv_hp INTEGER NOT NULL,
                iv_attack INTEGER NOT NULL,
                iv_defense INTEGER NOT NULL,
                iv_sp_attack INTEGER NOT NULL,
                iv_sp_defense INTEGER NOT NULL,
                iv_speed INTEGER NOT NULL,
                boosted_ivs TEXT NOT NULL DEFAULT ''
            );"
        ).execute(&pool).await.unwrap();

        sqlx::query("INSERT INTO users (id, boosts) VALUES (1, 10)").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, iv_hp, iv_attack, iv_defense, iv_sp_attack, iv_sp_defense, iv_speed)
                     VALUES (10, 1, 470, 'Leafeon', 17, 29, 15, 2, 13, 27)").execute(&pool).await.unwrap();

        // Check initial state
        let boosts: i64 = sqlx::query_scalar("SELECT boosts FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        assert_eq!(boosts, 10);
        let boosted_ivs: String = sqlx::query_scalar("SELECT boosted_ivs FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        assert_eq!(boosted_ivs, "");

        // Boost Attack
        let res = calculate_boost_application("atk", 29, &boosted_ivs, boosts).unwrap();
        assert_eq!(res, BoostResult { iv_gain: 1, boosts_used: 1 });
        let new_boosts = boosts - res.boosts_used;
        let new_boosted_ivs = "atk".to_string();
        sqlx::query("UPDATE users SET boosts = ? WHERE id = 1").bind(new_boosts).execute(&pool).await.unwrap();
        sqlx::query("UPDATE pokemons SET iv_attack = iv_attack + ?, boosted_ivs = ? WHERE id = 10")
            .bind(res.iv_gain)
            .bind(&new_boosted_ivs)
            .execute(&pool).await.unwrap();

        // Verify updated values
        let updated_boosts: i64 = sqlx::query_scalar("SELECT boosts FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        let updated_atk: i32 = sqlx::query_scalar("SELECT iv_attack FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        let updated_boosted_ivs: String = sqlx::query_scalar("SELECT boosted_ivs FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        assert_eq!(updated_boosts, 9);
        assert_eq!(updated_atk, 30);
        assert_eq!(updated_boosted_ivs, "atk");

        // Attempting to boost Attack again fails
        let res_fail = calculate_boost_application("atk", updated_atk, &updated_boosted_ivs, updated_boosts);
        assert_eq!(res_fail, Err("This IV stat has already been boosted!"));

        // Boosting HP succeeds
        let res_hp = calculate_boost_application("hp", 17, &updated_boosted_ivs, updated_boosts).unwrap();
        assert_eq!(res_hp, BoostResult { iv_gain: 1, boosts_used: 1 });
        let new_boosted_ivs_hp = format!("{},hp", updated_boosted_ivs);
        sqlx::query("UPDATE users SET boosts = boosts - 1 WHERE id = 1").execute(&pool).await.unwrap();
        sqlx::query("UPDATE pokemons SET iv_hp = iv_hp + ?, boosted_ivs = ? WHERE id = 10")
            .bind(res_hp.iv_gain)
            .bind(&new_boosted_ivs_hp)
            .execute(&pool).await.unwrap();

        let final_boosts: i64 = sqlx::query_scalar("SELECT boosts FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        let final_hp: i32 = sqlx::query_scalar("SELECT iv_hp FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        let final_boosted_ivs: String = sqlx::query_scalar("SELECT boosted_ivs FROM pokemons WHERE id = 10").fetch_one(&pool).await.unwrap();
        assert_eq!(final_boosts, 8);
        assert_eq!(final_hp, 18);
        assert_eq!(final_boosted_ivs, "atk,hp");
    }

    #[test]
    fn test_parse_pokestore_and_buy_commands() {
        let cmd = Command::parse("/pokestore", "bot").unwrap();
        assert!(matches!(cmd, Command::PokeStore));

        assert!(Command::parse("/store", "bot").is_err());
        assert!(Command::parse("/mart", "bot").is_err());
        assert!(Command::parse("/shop", "bot").is_err());

        let cmd_buy_plain = Command::parse("/buy", "bot").unwrap();
        match cmd_buy_plain {
            Command::Buy(q) => assert_eq!(q, ""),
            _ => panic!("Expected Command::Buy"),
        }

        let cmd_buy_item = Command::parse("/buy pokeball 10", "bot").unwrap();
        match cmd_buy_item {
            Command::Buy(q) => assert_eq!(q, "pokeball 10"),
            _ => panic!("Expected Command::Buy"),
        }

        let cmd_buy_tm = Command::parse("/buy tm 45", "bot").unwrap();
        match cmd_buy_tm {
            Command::Buy(q) => assert_eq!(q, "tm 45"),
            _ => panic!("Expected Command::Buy"),
        }
    }

    #[test]
    fn test_parse_buy_input_targets() {
        assert_eq!(parse_buy_input("regular ball 10").unwrap(), (BuyItemTarget::RegularBall, 10));
        assert_eq!(parse_buy_input("pokeball 5").unwrap(), (BuyItemTarget::RegularBall, 5));
        assert_eq!(parse_buy_input("great ball 3").unwrap(), (BuyItemTarget::GreatBall, 3));
        assert_eq!(parse_buy_input("ultra ball").unwrap(), (BuyItemTarget::UltraBall, 1));
        assert_eq!(parse_buy_input("repeat ball 2").unwrap(), (BuyItemTarget::RepeatBall, 2));
        assert_eq!(parse_buy_input("nest ball 4").unwrap(), (BuyItemTarget::NestBall, 4));
        assert_eq!(parse_buy_input("dusk ball 6").unwrap(), (BuyItemTarget::DuskBall, 6));
        assert_eq!(parse_buy_input("omni ring").unwrap(), (BuyItemTarget::OmniRing, 1));
        assert_eq!(parse_buy_input("egg incubator 2").unwrap(), (BuyItemTarget::EggIncubator, 2));
        assert_eq!(parse_buy_input("rare candy 20").unwrap(), (BuyItemTarget::RareCandy, 20));
        assert_eq!(parse_buy_input("berry 15").unwrap(), (BuyItemTarget::Berry, 15));
        assert_eq!(parse_buy_input("vitamin 15").unwrap(), (BuyItemTarget::Vitamin, 15));
        assert_eq!(parse_buy_input("boost 3").unwrap(), (BuyItemTarget::Boost, 3));
        assert_eq!(parse_buy_input("tm 45").unwrap(), (BuyItemTarget::Tm(45), 1));
        assert_eq!(parse_buy_input("tm#46 2").unwrap(), (BuyItemTarget::Tm(46), 2));
        assert_eq!(parse_buy_input("tm219").unwrap(), (BuyItemTarget::Tm(219), 1));

        // Invalid cases
        assert_eq!(format_buy_usage(), "Usage: /buy <item> [amount]");
        assert_eq!(parse_buy_input("").unwrap_err(), "Usage: /buy <item> [amount]");
        assert!(parse_buy_input("null candy 1").is_err());
        assert!(parse_buy_input("regular ball -5").is_err());
        assert!(parse_buy_input("regular ball 0").is_err());
        assert!(parse_buy_input("invalid item xyz").is_err());
    }

