    #[tokio::test]
    async fn test_pokestore_database_and_purchase_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();

        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                pokedollars INTEGER NOT NULL DEFAULT 10000,
                ball_regular INTEGER NOT NULL DEFAULT 100,
                ball_great INTEGER NOT NULL DEFAULT 50,
                ball_ultra INTEGER NOT NULL DEFAULT 30,
                ball_repeat INTEGER NOT NULL DEFAULT 20,
                ball_master INTEGER NOT NULL DEFAULT 5,
                ball_dusk INTEGER NOT NULL DEFAULT 20,
                ball_nest INTEGER NOT NULL DEFAULT 0,
                omni_ring INTEGER NOT NULL DEFAULT 0,
                egg_incubator INTEGER NOT NULL DEFAULT 0,
                null_candies INTEGER NOT NULL DEFAULT 0,
                candies INTEGER NOT NULL DEFAULT 100,
                vitamins INTEGER NOT NULL DEFAULT 100,
                berries INTEGER NOT NULL DEFAULT 100,
                boosts INTEGER NOT NULL DEFAULT 10
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE user_tm_shop (
                user_id INTEGER PRIMARY KEY,
                tm_1 INTEGER NOT NULL,
                tm_2 INTEGER NOT NULL,
                tm_3 INTEGER NOT NULL,
                tm_4 INTEGER NOT NULL,
                tm_5 INTEGER NOT NULL,
                expires_at INTEGER NOT NULL
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE user_tms (
                user_id INTEGER NOT NULL,
                tm_number INTEGER NOT NULL,
                move_name TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, tm_number)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, username, first_name, pokedollars) VALUES (1, 'ash', 'Ash', 10000)")
            .execute(&pool)
            .await
            .unwrap();

        // 1. Initial TM shop creation seeds default 5 TMs
        let (tms, refresh_str) = get_or_create_user_tm_shop(&pool, 1).await.unwrap();
        assert_eq!(tms.len(), 5);
        assert_eq!(tms[0].number, 45);
        assert_eq!(tms[1].number, 46);
        assert_eq!(tms[2].number, 95);
        assert_eq!(tms[3].number, 219);
        assert_eq!(tms[4].number, 54);
        assert_eq!(refresh_str, "3 days");

        // 2. Buy TM46 (Avalanche) costs 2,000 💵
        let (bought_tm, bal_after_tm) = buy_tm(&pool, 1, 46).await.unwrap();
        assert_eq!(bought_tm.number, 46);
        assert_eq!(bal_after_tm, 8000);
        let tm_qty: i64 = sqlx::query_scalar("SELECT quantity FROM user_tms WHERE user_id = 1 AND tm_number = 46")
            .fetch_one(&pool).await.unwrap();
        assert_eq!(tm_qty, 1);

        // 3. Refresh TM shop costs 2,000 💵
        let (refreshed_tms, ref_str, bal_after_ref) = refresh_user_tm_shop(&pool, 1).await.unwrap();
        assert_eq!(refreshed_tms.len(), 5);
        assert_eq!(ref_str, "3 days");
        assert_eq!(bal_after_ref, 6000);

        // 4. Quick buy items: 10x Nest Ball (15 * 10 = 150)
        let res_nest = execute_buy_command(&pool, 1, "nest ball 10").await.unwrap();
        assert!(res_nest.starts_with("Purchased "));
        assert!(!res_nest.contains("✅"));
        assert!(!res_nest.contains("New Balance"));
        assert!(res_nest.contains("10x Nest Ball"));
        assert!(res_nest.contains("150 💵"));
        let nest_qty: i64 = sqlx::query_scalar("SELECT ball_nest FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        assert_eq!(nest_qty, 10);
        assert_eq!(get_user_pokedollars(&pool, 1).await, 5850);

        // 5. Quick buy Omni Ring (5,000 💵)
        let res_omni = execute_buy_command(&pool, 1, "omni ring").await.unwrap();
        assert!(res_omni.contains("1x Omni Ring"));
        assert!(res_omni.contains("5,000 💵"));
        let omni_count: i64 = sqlx::query_scalar("SELECT omni_ring FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        assert_eq!(omni_count, 1);
        assert_eq!(get_user_pokedollars(&pool, 1).await, 850);

        // 6. Buying Egg Incubator (5,000 💵) with insufficient balance fails
        let fail_incubator = execute_buy_command(&pool, 1, "egg incubator").await;
        assert!(fail_incubator.is_err());
        assert!(fail_incubator.unwrap_err().contains("You need <b>5,000 💵</b>"));

        // 7. Buying 1x Boost (500 💵) succeeds
        let res_boost = execute_buy_command(&pool, 1, "boost 1").await.unwrap();
        assert!(res_boost.contains("1x Boost"));
        assert_eq!(get_user_pokedollars(&pool, 1).await, 350);
        let boosts_count: i64 = sqlx::query_scalar("SELECT boosts FROM users WHERE id = 1").fetch_one(&pool).await.unwrap();
        assert_eq!(boosts_count, 11);
    }

