    #[test]
    fn test_format_myinventory_screens() {
        // 1. Main screen
        let main_owned = format_myinventory_main(1, 1, 161);
        assert!(main_owned.contains("<b>Your Inventory:</b>"));
        assert!(main_owned.contains(crate::emoji::INVENTORY_CUSTOM_EMOJI_ID));
        assert!(main_owned.contains(crate::emoji::OMNI_RING_CUSTOM_EMOJI_ID));
        assert!(main_owned.contains(crate::emoji::INCUBATOR_CUSTOM_EMOJI_ID));
        assert!(main_owned.contains("<u>Omni Ring</u> : Owned"));
        assert!(main_owned.contains("<u>Egg Incubator</u> : Owned"));
        assert!(main_owned.contains("<u>PokéDollars</u> : 161"));

        let main_not_owned = format_myinventory_main(0, 0, 5000);
        assert!(main_not_owned.contains("<u>Omni Ring</u> : Not Owned"));
        assert!(main_not_owned.contains("<u>Egg Incubator</u> : Not Owned"));
        assert!(main_not_owned.contains("<u>PokéDollars</u> : 5,000"));

        // 2. Pokéballs screen
        let balls_screen = format_myinventory_balls(100, 50, 30, 20, 10, 15, 2);
        assert!(balls_screen.contains("<b>Your Pokéballs:</b>"));
        assert!(balls_screen.contains("Regular Ball : 100"));
        assert!(balls_screen.contains("Great Ball : 50"));
        assert!(balls_screen.contains("Ultra Ball : 30"));
        assert!(balls_screen.contains("Repeat Ball : 20"));
        assert!(balls_screen.contains("Nest Ball : 10"));
        assert!(balls_screen.contains("Dusk Ball : 15"));
        assert!(balls_screen.contains("Master Ball : 2"));

        // 3. TMs screen (empty and populated)
        let tms_empty = format_myinventory_tms(&[]);
        assert!(tms_empty.contains("You do not own any Technical Machines (TMs) yet."));

        let tms_populated = format_myinventory_tms(&[(45, "Venoshock".to_string(), 2), (46, "Avalanche".to_string(), 1)]);
        assert!(tms_populated.contains("<b>Your Technical Machines:</b>"));
        assert!(tms_populated.contains("• <u>TM #45</u> : Venoshock (x2)"));
        assert!(tms_populated.contains("• <u>TM #46</u> : Avalanche (x1)"));

        // 4. Key items
        let key_items = format_myinventory_key_items(1, 0);
        assert!(key_items.contains("<b>Your Key Items:</b>"));
        assert!(key_items.contains("<u>Omni Ring</u> : Owned"));
        assert!(key_items.contains("<u>Egg Incubator</u> : Not Owned"));

        // 5. Eggs & Incubator & Tutors
        assert!(format_myinventory_eggs().contains("You currently do not have any Pokémon Eggs."));
        assert!(format_myinventory_incubator(1).contains("<u>Egg Incubator</u> : Owned"));
        let tutors_empty = format_myinventory_tutors(&[]);
        assert!(tutors_empty.contains("Move Tutors will be available"));
        assert!(tutors_empty.contains("5393113918744847961"));
        let tutors_populated = format_myinventory_tutors(&[(3, "Double Edge".to_string(), 1), (5, "Fire Punch".to_string(), 2)]);
        assert!(tutors_populated.contains("5393113918744847961"));
        assert!(tutors_populated.contains("• /TUTOR3 - Double Edge"));
        assert!(tutors_populated.contains("• /TUTOR5 - Fire Punch (x2)"));
    }

