    #[test]
    fn test_key_items_page_formatting_and_keyboards() {
        let items_p1 = vec![
            ("Alakazite".to_string(), 1),
            ("Barbaracite".to_string(), 1),
            ("Blastoisinite".to_string(), 1),
            ("Blazikenite".to_string(), 1),
            ("Charizardite X".to_string(), 1),
            ("Glalitite".to_string(), 1),
            ("Gyaradosite".to_string(), 1),
            ("Houndoominite".to_string(), 1),
            ("Lucarionite".to_string(), 1),
            ("Metagrossite".to_string(), 1),
            ("Swampertite".to_string(), 1),
            ("Venusaurite".to_string(), 1),
        ];
        let p1_text = format_myinventory_key_items_page(&items_p1, 1, 2);
        assert!(p1_text.contains("<b>Key Items: (Page 1/2)</b>"));
        assert!(p1_text.contains("• "));
        assert!(p1_text.contains("Alakazite: 1"));
        assert!(p1_text.contains("Charizardite X: 1"));
        assert!(p1_text.contains("Venusaurite: 1"));

        let items_p2 = vec![
            ("Red Orb".to_string(), 1),
            ("Rare Candy".to_string(), 56),
            ("Berry".to_string(), 52),
            ("Vitamin".to_string(), 145),
            ("Boost".to_string(), 10),
        ];
        let p2_text = format_myinventory_key_items_page(&items_p2, 2, 2);
        assert!(p2_text.contains("<b>Key Items: (Page 2/2)</b>"));
        assert!(p2_text.contains("Red Orb: 1"));
        assert!(p2_text.contains("Rare Candy: 56"));
        assert!(p2_text.contains("Berry: 52"));
        assert!(p2_text.contains("Vitamin: 145"));
        assert!(p2_text.contains("Boost: 10"));
        assert!(!p2_text.contains("Pd:"));

        // Keyboards
        let kb1 = build_myinventory_key_items_kb(1, 2);
        assert_eq!(kb1.inline_keyboard[0][0].text, "1/2");
        assert_eq!(kb1.inline_keyboard[0][1].text, "➡️ Next");
        assert_eq!(kb1.inline_keyboard[1][0].text, "Back");

        let kb1_json = build_myinventory_key_items_kb_json(1, 2);
        assert_eq!(kb1_json["inline_keyboard"][0][0]["text"], "1/2");
        assert_eq!(kb1_json["inline_keyboard"][0][1]["text"], "Next");
        assert_eq!(kb1_json["inline_keyboard"][0][1]["icon_custom_emoji_id"], RIGHT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(kb1_json["inline_keyboard"][1][0]["text"], "Back");

        let kb2 = build_myinventory_key_items_kb(2, 2);
        assert_eq!(kb2.inline_keyboard[0][0].text, "⬅️ Prev");
        assert_eq!(kb2.inline_keyboard[0][1].text, "2/2");
        assert_eq!(kb2.inline_keyboard[1][0].text, "Back");

        let kb2_json = build_myinventory_key_items_kb_json(2, 2);
        assert_eq!(kb2_json["inline_keyboard"][0][0]["text"], "Prev");
        assert_eq!(kb2_json["inline_keyboard"][0][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(kb2_json["inline_keyboard"][0][1]["text"], "2/2");
        assert_eq!(kb2_json["inline_keyboard"][1][0]["text"], "Back");
    }

    #[test]
    fn test_is_valid_key_item() {
        // Valid key items
        assert!(is_valid_key_item("Alakazite"));
        assert!(is_valid_key_item("Charizardite X"));
        assert!(is_valid_key_item("Lucarionite"));
        assert!(is_valid_key_item("Metagrossite"));
        assert!(is_valid_key_item("Red Orb"));
        assert!(is_valid_key_item("Blue Orb"));
        assert!(is_valid_key_item("Dragonium Z"));
        assert!(is_valid_key_item("Omni Ring"));

        // Invalid: balls, eggs, plates, memories, drives, held items, evolution stones, incubator
        assert!(!is_valid_key_item("Egg Incubator"));
        assert!(!is_valid_key_item("Chibiball"));
        assert!(!is_valid_key_item("Lucky Egg"));
        assert!(!is_valid_key_item("Mystery Egg"));
        assert!(!is_valid_key_item("Griseous Core"));
        assert!(!is_valid_key_item("Meadow Plate"));
        assert!(!is_valid_key_item("Flame Plate"));
        assert!(!is_valid_key_item("Fire Memory"));
        assert!(!is_valid_key_item("Burn Drive"));
        assert!(!is_valid_key_item("Adamant Crystal"));
        assert!(!is_valid_key_item("Lustrous Globe"));
        assert!(!is_valid_key_item("Leftovers"));
        assert!(!is_valid_key_item("Rusted Shield"));
        assert!(!is_valid_key_item("Rusted Sword"));
        assert!(!is_valid_key_item("Fire Stone"));
        assert!(!is_valid_key_item("Water Stone"));
    }

    #[tokio::test]
    async fn test_myinventory_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                omni_ring INTEGER NOT NULL DEFAULT 0,
                egg_incubator INTEGER NOT NULL DEFAULT 0,
                pokedollars INTEGER NOT NULL DEFAULT 0,
                ball_regular INTEGER NOT NULL DEFAULT 100,
                ball_great INTEGER NOT NULL DEFAULT 50,
                ball_ultra INTEGER NOT NULL DEFAULT 30,
                ball_repeat INTEGER NOT NULL DEFAULT 20,
                ball_nest INTEGER NOT NULL DEFAULT 0,
                ball_dusk INTEGER NOT NULL DEFAULT 20,
                ball_master INTEGER NOT NULL DEFAULT 5,
                candies INTEGER NOT NULL DEFAULT 100,
                berries INTEGER NOT NULL DEFAULT 100,
                vitamins INTEGER NOT NULL DEFAULT 100,
                boosts INTEGER NOT NULL DEFAULT 10
            );
            CREATE TABLE user_tms (
                user_id INTEGER NOT NULL,
                tm_number INTEGER NOT NULL,
                move_name TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, tm_number)
            );
            CREATE TABLE user_key_items (
                user_id INTEGER NOT NULL,
                item_name TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, item_name)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "INSERT INTO users (id, omni_ring, egg_incubator, pokedollars, ball_nest)
             VALUES (1, 1, 1, 161, 10);"
        )
        .execute(&pool)
        .await
        .unwrap();

        let (omni, inc, bal) = get_user_inventory_summary(&pool, 1).await;
        assert_eq!(omni, 1);
        assert_eq!(inc, 1);
        assert_eq!(bal, 161);

        let balls = get_user_pokeballs(&pool, 1).await;
        assert_eq!(balls.0, 100);
        assert_eq!(balls.4, 10);

        sqlx::query("INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (1, 45, 'Venoshock', 2);")
            .execute(&pool)
            .await
            .unwrap();
        let tms = get_user_owned_tms(&pool, 1).await;
        assert_eq!(tms.len(), 1);
        assert_eq!(tms[0].0, 45);
        assert_eq!(tms[0].1, "Venoshock");
        assert_eq!(tms[0].2, 2);

        // Test key items fetching and auto-seeding
        let key_items = get_user_all_key_items(&pool, 1).await;
        assert_eq!(key_items.len(), 17);
        assert_eq!(key_items[0].0, "Alakazite");
        assert_eq!(key_items[0].1, 1);
        assert_eq!(key_items[11].0, "Venusaurite");
        assert_eq!(key_items[11].1, 1);
        assert_eq!(key_items[12].0, "Red Orb");
        assert_eq!(key_items[12].1, 1);
        assert_eq!(key_items[13].0, "Rare Candy");
        assert_eq!(key_items[14].0, "Berry");
        assert_eq!(key_items[15].0, "Vitamin");
        assert_eq!(key_items[16].0, "Boost");
    }

    #[tokio::test]
    async fn test_agive_admin_flow() {
        std::env::set_var("ADMIN_IDS", "999,8404111906");

        // 1. is_admin tests
        assert!(is_admin(999));
        assert!(is_admin(8404111906));
        assert!(!is_admin(12345));

        // 2. parse_agive_input tests
        assert!(parse_agive_input("").is_err());
        assert!(parse_agive_input("ash").is_err());
        assert!(parse_agive_input("ash -100").is_err());
        assert!(parse_agive_input("ash 0").is_err());
        assert!(parse_agive_input("ash abc").is_err());
        assert_eq!(parse_agive_input("ash 500").unwrap(), ("ash".to_string(), 500));
        assert_eq!(parse_agive_input("@ash 1,000").unwrap(), ("ash".to_string(), 1000));
        assert_eq!(parse_agive_input("8404111906 50000").unwrap(), ("8404111906".to_string(), 50000));

        // 3. Command parse
        assert!(matches!(Command::parse("/agive @ash 500", "bot").unwrap(), Command::AGive(_)));

        // 4. Database execution
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT NOT NULL,
                pokedollars INTEGER NOT NULL DEFAULT 100
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, username, first_name, pokedollars) VALUES (1, 'ashketchum', 'Ash', 100);")
            .execute(&pool)
            .await
            .unwrap();

        // Non-admin call fails
        let non_admin_res = execute_agive_command(&pool, 12345, "ashketchum 500").await;
        assert!(non_admin_res.is_err());
        assert!(non_admin_res.unwrap_err().contains("Access Denied"));

        // Admin call for non-existent user fails
        let missing_user_res = execute_agive_command(&pool, 999, "misty 500").await;
        assert!(missing_user_res.is_err());
        assert!(missing_user_res.unwrap_err().contains("was not found"));

        // Admin call by username succeeds
        let success_uname = execute_agive_command(&pool, 999, "@AshKetchum 5,000").await.unwrap();
        assert!(success_uname.contains("PokéDollars Granted!"));
        assert!(success_uname.contains("5,000 💵"));
        assert!(success_uname.contains("@ashketchum"));
        assert!(success_uname.contains("5,100 💵"));

        let bal1 = get_user_pokedollars(&pool, 1).await;
        assert_eq!(bal1, 5100);

        // Admin call by user id succeeds
        let success_id = execute_agive_command(&pool, 999, "1 400").await.unwrap();
        assert!(success_id.contains("400 💵"));
        assert!(success_id.contains("5,500 💵"));

        let bal2 = get_user_pokedollars(&pool, 1).await;
        assert_eq!(bal2, 5500);
    }

    #[tokio::test]
    async fn test_pokegive_admin_flow() {
        std::env::set_var("ADMIN_IDS", "999,8404111906");

        // 1. parse_pokegive_args tests
        assert_eq!(
            parse_pokegive_args(""),
            PokeGiveArgs {
                target_query: None,
                god_key: None,
                invalid_pokemon: None,
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("giratina"),
            PokeGiveArgs {
                target_query: None,
                god_key: Some("giratina".to_string()),
                invalid_pokemon: None,
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("dialga --force"),
            PokeGiveArgs {
                target_query: None,
                god_key: Some("dialga".to_string()),
                invalid_pokemon: None,
                force: true
            }
        );
        assert_eq!(
            parse_pokegive_args("@ash giratina"),
            PokeGiveArgs {
                target_query: Some("ash".to_string()),
                god_key: Some("giratina".to_string()),
                invalid_pokemon: None,
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("palkia @ash"),
            PokeGiveArgs {
                target_query: Some("ash".to_string()),
                god_key: Some("palkia".to_string()),
                invalid_pokemon: None,
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("ash dialga"),
            PokeGiveArgs {
                target_query: Some("ash".to_string()),
                god_key: Some("dialga".to_string()),
                invalid_pokemon: None,
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("pikachu"),
            PokeGiveArgs {
                target_query: None,
                god_key: None,
                invalid_pokemon: Some("pikachu".to_string()),
                force: false
            }
        );
        assert_eq!(
            parse_pokegive_args("@ash charizard"),
            PokeGiveArgs {
                target_query: Some("ash".to_string()),
                god_key: None,
                invalid_pokemon: Some("charizard".to_string()),
                force: false
            }
        );

        // 2. Command parse tests
        assert!(matches!(Command::parse("/pokegive giratina", "bot").unwrap(), Command::PokeGive(_)));
        assert!(matches!(Command::parse("/pokegive @ash dialga", "bot").unwrap(), Command::PokeGive(_)));

        // 3. Database execution
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        crate::halloween::init_halloween_tables(&pool).await.unwrap();

        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT NOT NULL,
                pokedollars INTEGER NOT NULL DEFAULT 100,
                halloween_candies INTEGER NOT NULL DEFAULT 0,
                halloween_void_shards INTEGER NOT NULL DEFAULT 0,
                halloween_total_candies_earned INTEGER NOT NULL DEFAULT 0,
                halloween_total_shards_earned INTEGER NOT NULL DEFAULT 0,
                halloween_cauldron_spins INTEGER NOT NULL DEFAULT 0,
                halloween_megastone_bought TEXT,
                halloween_catch_rate_voucher_expires REAL
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 5,
                nature TEXT NOT NULL,
                iv_hp INTEGER NOT NULL,
                iv_attack INTEGER NOT NULL,
                iv_defense INTEGER NOT NULL,
                iv_sp_attack INTEGER NOT NULL,
                iv_sp_defense INTEGER NOT NULL,
                iv_speed INTEGER NOT NULL,
                ev_hp INTEGER NOT NULL DEFAULT 0,
                ev_attack INTEGER NOT NULL DEFAULT 0,
                ev_defense INTEGER NOT NULL DEFAULT 0,
                ev_sp_attack INTEGER NOT NULL DEFAULT 0,
                ev_sp_defense INTEGER NOT NULL DEFAULT 0,
                ev_speed INTEGER NOT NULL DEFAULT 0,
                experience INTEGER NOT NULL DEFAULT 135,
                move_1 TEXT,
                move_2 TEXT,
                move_3 TEXT,
                move_4 TEXT,
                is_starter INTEGER NOT NULL DEFAULT 0,
                is_shiny INTEGER NOT NULL DEFAULT 0,
                is_hatched INTEGER NOT NULL DEFAULT 0,
                boosted_ivs TEXT NOT NULL DEFAULT '',
                relearn_moves TEXT NOT NULL DEFAULT '',
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, username, first_name) VALUES (1, 'ashketchum', 'Ash');")
            .execute(&pool)
            .await
            .unwrap();

        // Non-admin call fails
        let non_admin = execute_pokegive_command(&pool, 12345, "giratina", None).await;
        assert!(non_admin.is_err());
        assert!(non_admin.unwrap_err().contains("Access Denied"));

        // Invalid pokemon fails
        let invalid_pk = execute_pokegive_command(&pool, 999, "pikachu", None).await;
        assert!(invalid_pk.is_err());
        assert!(invalid_pk.unwrap_err().contains("not a Halloween Pokémon"));

        // No recipient and no reply fails
        let no_target = execute_pokegive_command(&pool, 999, "giratina", None).await;
        assert!(no_target.is_err());
        assert!(no_target.unwrap_err().contains("Usage:"));

        // Giving to a bot fails
        let bot_target = execute_pokegive_command(&pool, 999, "giratina", Some((2, Some("mybot".to_string()), "Bot".to_string(), true))).await;
        assert!(bot_target.is_err());
        assert!(bot_target.unwrap_err().contains("cannot give Pokémon to a bot"));

        // Admin awards Giratina via replied message to winner!
        let success_reply = execute_pokegive_command(
            &pool,
            999,
            "giratina",
            Some((1, Some("ashketchum".to_string()), "Ash".to_string(), false)),
        )
        .await
        .unwrap();
        assert!(success_reply.contains("Giratina"));
        assert!(success_reply.contains("successfully awarded to"));

        // Verify Pokémon in DB
        let row = sqlx::query("SELECT pokemon_id, nickname, level, is_shiny, iv_hp FROM pokemons WHERE user_id = 1")
            .fetch_one(&pool)
            .await
            .unwrap();
        let pid: i64 = row.try_get("pokemon_id").unwrap();
        let nick: String = row.try_get("nickname").unwrap();
        let lvl: i32 = row.try_get("level").unwrap();
        let shiny: i32 = row.try_get("is_shiny").unwrap();
        let iv_hp: i32 = row.try_get("iv_hp").unwrap();

        assert_eq!(pid, 10007); // Origin Form
        assert!(nick.contains("Giratina"));
        assert_eq!(lvl, 100);
        assert_eq!(shiny, 1);
        assert_eq!(iv_hp, 31);

        // Attempting to give Giratina again without force should fail (1-of-1 rule)
        let dup_attempt = execute_pokegive_command(
            &pool,
            999,
            "giratina",
            Some((2, Some("misty".to_string()), "Misty".to_string(), false)),
        )
        .await;
        assert!(dup_attempt.is_err());
        assert!(dup_attempt.unwrap_err().contains("already been claimed"));

        // Giving Dialga by username to @ashketchum
        let dialga_res = execute_pokegive_command(&pool, 999, "@ashketchum dialga", None)
            .await
            .unwrap();
        assert!(dialga_res.contains("Dialga"));

        // Giving Palkia with --force
        let palkia_res = execute_pokegive_command(&pool, 999, "palkia 1 --force", None)
            .await
            .unwrap();
        assert!(palkia_res.contains("Palkia"));
    }

