    #[test]
    fn test_tm_and_tutor_separation_learnsets() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Bulbasaur (ID 1) can learn Venoshock via TM (TM45 in TM_CATALOG), but Venoshock is NOT a Move Tutor
        assert!(pokedex.can_learn_tm(1, "venoshock"));
        assert!(!pokedex.can_learn_tutor(1, "venoshock"));

        // Verify get_tm_moves and get_tutor_moves strictly separate learn methods:
        // Every move in get_tm_moves has m == "machine", and get_tutor_moves has m == "tutor"
        let tm_moves = pokedex.get_tm_moves(1);
        let tutor_moves = pokedex.get_tutor_moves(1);

        assert!(!tm_moves.is_empty());
        assert!(!tutor_moves.is_empty());

        // Venoshock is a TM move for Bulbasaur, never a tutor move
        assert!(tm_moves.iter().any(|m| m.name.eq_ignore_ascii_case("venoshock")));
        assert!(!tutor_moves.iter().any(|m| m.name.eq_ignore_ascii_case("venoshock")));

        // Verify TM_CATALOG has all 229 TMs with sequential numbering 1..=229
        assert_eq!(TM_CATALOG.len(), 229);
        for (idx, tm) in TM_CATALOG.iter().enumerate() {
            assert_eq!(tm.number as usize, idx + 1);
        }
    }

