    #[test]
    fn test_evolution_table_and_requirements() {
        // Bulbasaur (1) -> Ivysaur (2) at Lv. 16
        assert_eq!(get_static_evolution(1), Some((16, "Ivysaur", 2)));
        assert_eq!(check_evolution_ready(1, 15), None);
        assert_eq!(check_evolution_ready(1, 16), Some((16, "Ivysaur", 2)));
        assert_eq!(check_evolution_ready(1, 20), Some((16, "Ivysaur", 2)));

        // Ivysaur (2) -> Venusaur (3) at Lv. 32
        assert_eq!(get_static_evolution(2), Some((32, "Venusaur", 3)));
        assert_eq!(check_evolution_ready(2, 31), None);
        assert_eq!(check_evolution_ready(2, 32), Some((32, "Venusaur", 3)));

        // Venusaur (3) cannot evolve further
        assert_eq!(get_static_evolution(3), None);
        assert_eq!(check_evolution_ready(3, 100), None);

        // Charmander (4) -> Charmeleon (5) at Lv. 16
        assert_eq!(check_evolution_ready(4, 16), Some((16, "Charmeleon", 5)));
        // Charmeleon (5) -> Charizard (6) at Lv. 36
        assert_eq!(check_evolution_ready(5, 36), Some((36, "Charizard", 6)));
        assert_eq!(check_evolution_ready(6, 100), None);

        // Regional form: Alolan Rattata (10091) -> Alolan Raticate (10092) at Lv. 20
        assert_eq!(check_evolution_ready(10091, 19), None);
        assert_eq!(check_evolution_ready(10091, 20), Some((20, "Raticate-Alola", 10092)));
    }

