    #[tokio::test]
    async fn test_database_evolution_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                pokemon_obtained INTEGER NOT NULL DEFAULT 0,
                pokemon_seen INTEGER NOT NULL DEFAULT 0
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id) VALUES (1);").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level) VALUES (10, 1, 1, 'Bulbasaur', 16);")
            .execute(&pool)
            .await
            .unwrap();

        // Check ready to evolve
        let evo = check_evolution_ready(1, 16);
        assert_eq!(evo, Some((16, "Ivysaur", 2)));

        let (_req, target_name, target_id) = evo.unwrap();
        sqlx::query("UPDATE pokemons SET pokemon_id = ?, nickname = ? WHERE id = 10")
            .bind(target_id as i64)
            .bind(target_name)
            .execute(&pool)
            .await
            .unwrap();

        let updated_row = sqlx::query("SELECT pokemon_id, nickname FROM pokemons WHERE id = 10")
            .fetch_one(&pool)
            .await
            .unwrap();
        let new_pid: i64 = updated_row.get("pokemon_id");
        let new_nick: String = updated_row.get("nickname");
        assert_eq!(new_pid, 2);
        assert_eq!(new_nick, "Ivysaur");
    }

    #[test]
    fn test_candy_evolution_prompt_triggers_only_once_at_req_lvl() {
        // Charmander (ID 4) evolves into Charmeleon at Lv. 16
        let evo = check_evolution_ready(4, 16);
        assert!(evo.is_some());
        let (req_lvl, _, _) = evo.unwrap();

        // Leveling from 15 to 16: triggers evolution message
        let triggers_15_to_16 = 15 < req_lvl as i32 && 16 >= req_lvl as i32;
        assert!(triggers_15_to_16, "Must trigger when reaching evolution level 16");

        // Subsequent leveling from 16 to 17: does NOT trigger again
        let triggers_16_to_17 = 16 < req_lvl as i32 && 17 >= req_lvl as i32;
        assert!(!triggers_16_to_17, "Must not re-trigger when leveling past 16 without evolving");

        // Subsequent multi-candy leveling from 17 to 20: does NOT trigger again
        let triggers_17_to_20 = 17 < req_lvl as i32 && 20 >= req_lvl as i32;
        assert!(!triggers_17_to_20, "Must not re-trigger when leveling past 16 without evolving");

        // But user can still evolve any time via check_evolution_ready
        assert!(check_evolution_ready(4, 20).is_some(), "Pokemon remains able to evolve at any time");
    }

