    #[test]
    fn test_pokemon_growth_rate_and_exp_calculations() {
        // Bulbapedia standard test points:
        // Medium Slow at Lv 5: 1.2*125 - 15*25 + 100*5 - 140 = 150 - 375 + 500 - 140 = 135
        let ms_lv5 = calculate_pokemon_exp_at_level("Medium Slow", 5);
        assert_eq!(ms_lv5, 135);

        // Medium Fast at Lv 5: 5^3 = 125
        let mf_lv5 = calculate_pokemon_exp_at_level("Medium Fast", 5);
        assert_eq!(mf_lv5, 125);

        // Medium Fast at Lv 10: 10^3 = 1000
        let mf_lv10 = calculate_pokemon_exp_at_level("Medium Fast", 10);
        assert_eq!(mf_lv10, 1000);

        // Slow at Lv 5: 5 * 125 / 4 = 156
        let s_lv5 = calculate_pokemon_exp_at_level("Slow", 5);
        assert_eq!(s_lv5, 156);

        // Fast at Lv 5: 4 * 125 / 5 = 100
        let f_lv5 = calculate_pokemon_exp_at_level("Fast", 5);
        assert_eq!(f_lv5, 100);

        // Level 100 cap test
        let (_eff_exp, to_next, bar) = calculate_pokemon_exp_details("Medium Slow", 100, 1_059_860);
        assert_eq!(to_next, 0);
        assert_eq!(bar, "EXP <code>█████████</code>");
    }

