    #[test]
    fn test_no_status_moves_in_level_up_and_relearn() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Verify loaded moves contains 0 status moves with 0 power
        for m in pokedex.moves.values() {
            assert!(!m.c.eq_ignore_ascii_case("status"), "Found status move in pokedex: {}", m.name);
            assert!(m.p.unwrap_or(0) > 0, "Found 0 or null power move in pokedex: {}", m.name);
        }

        // Test level-up moves for several Pokemon known to have status moves
        for pkmn_id in [1, 4, 7, 25, 58, 120] {
            let moves = pokedex.get_level_up_moves(pkmn_id, 50);
            for m in &moves {
                assert!(!m.c.eq_ignore_ascii_case("status"), "Status move {} returned for ID {}", m.name, pkmn_id);
                assert!(m.p.unwrap_or(0) > 0, "Zero-power move {} returned for ID {}", m.name, pkmn_id);
            }

            let between_moves = pokedex.get_moves_learned_between_levels(pkmn_id, 1, 50);
            for m in &between_moves {
                assert!(!m.c.eq_ignore_ascii_case("status"), "Status move {} learned between levels for ID {}", m.name, pkmn_id);
                assert!(m.p.unwrap_or(0) > 0, "Zero-power move {} learned between levels for ID {}", m.name, pkmn_id);
            }

            let relearn = pokedex.get_relearnable_moves(pkmn_id, 50, &[], "");
            for m in &relearn {
                assert!(!m.c.eq_ignore_ascii_case("status"), "Status move {} in relearn for ID {}", m.name, pkmn_id);
                assert!(m.p.unwrap_or(0) > 0, "Zero-power move {} in relearn for ID {}", m.name, pkmn_id);
            }
        }
    }

