    #[test]
    fn test_parse_myteam_command() {
        let cmd = Command::parse("/myteam", "ozone_pokemon_bot").unwrap();
        match cmd {
            Command::MyTeam(target) => assert_eq!(target, ""),
            _ => panic!("Expected MyTeam"),
        }

        let cmd2 = Command::parse("/myteam 6", "ozone_pokemon_bot").unwrap();
        match cmd2 {
            Command::MyTeam(target) => assert_eq!(target, "6"),
            _ => panic!("Expected MyTeam 6"),
        }

        let cmd3 = Command::parse("/myteam edit", "ozone_pokemon_bot").unwrap();
        match cmd3 {
            Command::MyTeam(target) => assert_eq!(target, "edit"),
            _ => panic!("Expected MyTeam edit"),
        }

        assert!(Command::parse("/team edit", "ozone_pokemon_bot").is_err());
    }

    #[tokio::test]
    async fn test_user_teams_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();

        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                active_team INTEGER NOT NULL DEFAULT 1
            );
            CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL
            );
            CREATE TABLE user_teams (
                user_id INTEGER NOT NULL,
                team_num INTEGER NOT NULL,
                slot INTEGER NOT NULL,
                pokemon_db_id INTEGER NOT NULL,
                PRIMARY KEY (user_id, team_num, slot)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query("INSERT INTO users (id, active_team) VALUES (1001, 1)").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname) VALUES (1, 1001, 25, 'Pikachu')").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname) VALUES (2, 1001, 6, 'Charizard')").execute(&pool).await.unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname) VALUES (3, 1001, 9, 'Blastoise')").execute(&pool).await.unwrap();

        // Initial active team should be 1
        let active = get_user_active_team(&pool, 1001).await;
        assert_eq!(active, 1);

        // Initial Team 1 should be empty
        let initial_ids = get_team_pokemon_ids(&pool, 1001, 1).await.unwrap();
        assert!(initial_ids.is_empty());

        // Save Team 1 with Pikachu and Charizard
        save_team_pokemon_ids(&pool, 1001, 1, &[1, 2]).await.unwrap();
        let team1_ids = get_team_pokemon_ids(&pool, 1001, 1).await.unwrap();
        assert_eq!(team1_ids, vec![1, 2]);

        // Save Team 6 with Blastoise and Pikachu
        save_team_pokemon_ids(&pool, 1001, 6, &[3, 1]).await.unwrap();
        assert_eq!(get_user_active_team(&pool, 1001).await, 6);
        let team6_ids = get_team_pokemon_ids(&pool, 1001, 6).await.unwrap();
        assert_eq!(team6_ids, vec![3, 1]);

        // Switch active team to 2
        set_user_active_team(&pool, 1001, 2).await.unwrap();
        assert_eq!(get_user_active_team(&pool, 1001).await, 2);

        // Releasing Pikachu (id 1) removes it from user_teams
        sqlx::query("DELETE FROM user_teams WHERE pokemon_db_id = ?").bind(1).execute(&pool).await.unwrap();
        let team6_after = get_team_pokemon_ids(&pool, 1001, 6).await.unwrap();
        assert_eq!(team6_after, vec![3]);
    }

    #[test]
    fn test_build_team_add_pokemon_text_and_keyboard_layout() {
        let mut candidates = Vec::new();
        for i in 1..=10 {
            candidates.push(PokemonDbRecord {
                id: i,
                pokemon_id: 81,
                nickname: format!("Pkmn{}", i),
                level: 20,
                nature: "Quirky".to_string(),
                iv_hp: 10, iv_attack: 10, iv_defense: 10, iv_sp_attack: 10, iv_sp_defense: 10, iv_speed: 10,
                ev_hp: 0, ev_attack: 0, ev_defense: 0, ev_sp_attack: 0, ev_sp_defense: 0, ev_speed: 0,
                is_shiny: false,
                is_hatched: false,
            });
        }

        let text_full = build_team_add_pokemon_text(&candidates, true);
        assert!(text_full.starts_with("Your team is full. Select a Pokemon to bring in, then choose who it replaces:\n\n"));
        assert!(text_full.contains("1. <b>Pkmn1</b> - Quirky"));
        assert!(text_full.contains("10. <b>Pkmn10</b> - Quirky"));

        let text_not_full = build_team_add_pokemon_text(&candidates, false);
        assert!(text_not_full.starts_with("Select a Pokemon to bring into your team:\n\n"));

        let kb_json = build_team_add_keyboard_json(12345, &candidates, 1, 75);
        let rows = kb_json.get("inline_keyboard").unwrap().as_array().unwrap();
        // 10 candidates: row 0 has 4, row 1 has 4, row 2 has 2, row 3 has nav (3), row 4 has back (1)
        assert_eq!(rows.len(), 5);
        assert_eq!(rows[0].as_array().unwrap().len(), 4);
        assert_eq!(rows[0][0]["text"], "1");
        assert_eq!(rows[0][3]["text"], "4");
        assert_eq!(rows[1].as_array().unwrap().len(), 4);
        assert_eq!(rows[1][0]["text"], "5");
        assert_eq!(rows[1][3]["text"], "8");
        assert_eq!(rows[2].as_array().unwrap().len(), 2);
        assert_eq!(rows[2][0]["text"], "9");
        assert_eq!(rows[2][1]["text"], "10");
        assert_eq!(rows[3].as_array().unwrap().len(), 3);
        assert_eq!(rows[3][1]["text"], "1/75");
        assert_eq!(rows[4].as_array().unwrap().len(), 1);
        assert_eq!(rows[4][0]["text"], "Back");
    }

