    #[test]
    fn test_gym_command_and_keyboard() {
        use teloxide::utils::command::BotCommands;
        let c1 = Command::parse("/gym", "test_bot");
        assert!(c1.is_err(), "/gym was removed in favor of /gyms");
        let c2 = Command::parse("/gyms", "test_bot").expect("Should parse /gyms");
        assert!(matches!(c2, Command::Gyms));

        assert_eq!(GYM_MAIN_CAPTION, "Which region's gyms would you like to challenge?");

        let kb = build_gym_keyboard();
        assert_eq!(kb.inline_keyboard.len(), 2);
        assert_eq!(kb.inline_keyboard[0].len(), 2);
        assert_eq!(kb.inline_keyboard[1].len(), 2);

        assert_eq!(kb.inline_keyboard[0][0].text, "Kanto");
        assert_eq!(kb.inline_keyboard[0][1].text, "Johto");
        assert_eq!(kb.inline_keyboard[1][0].text, "Hoenn");
        assert_eq!(kb.inline_keyboard[1][1].text, "Sinnoh");

        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> &str {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(d) => d.as_str(),
                _ => "",
            }
        }
        assert_eq!(get_cb(&kb.inline_keyboard[0][0]), "gym_reg:kanto");
        assert_eq!(get_cb(&kb.inline_keyboard[0][1]), "gym_reg:johto");
        assert_eq!(get_cb(&kb.inline_keyboard[1][0]), "gym_reg:hoenn");
        assert_eq!(get_cb(&kb.inline_keyboard[1][1]), "gym_reg:sinnoh");

        // Cities & Caption Tests
        assert_eq!(KANTO_GYM_CITIES.len(), 8);
        assert_eq!(JOHTO_GYM_CITIES.len(), 8);
        assert_eq!(HOENN_GYM_CITIES.len(), 8);
        assert_eq!(SINNOH_GYM_CITIES.len(), 8);

        let kanto_cap_0 = format_gym_cities_caption("Kanto", 0);
        assert!(kanto_cap_0.contains("<blockquote>Which Gym will you step into? Choose your battlefield!</blockquote>"));
        assert!(kanto_cap_0.contains("• Pewter City [ Current ]"));
        assert!(kanto_cap_0.contains(&format!("• Cerulean City {}", crate::emoji::get_locked_gym_emoji(true))));
        assert!(kanto_cap_0.contains(&format!("• Viridian City {}", crate::emoji::get_locked_gym_emoji(true))));

        let kanto_cap_1 = format_gym_cities_caption("Kanto", 1);
        assert!(kanto_cap_1.contains(&format!("• Pewter City {}", crate::emoji::get_conquered_emoji(true))));
        assert!(kanto_cap_1.contains("• Cerulean City [ Current ]"));
        assert!(kanto_cap_1.contains(&format!("• Vermilion City {}", crate::emoji::get_locked_gym_emoji(true))));

        let cities_kb = build_gym_cities_keyboard("kanto");
        assert_eq!(cities_kb.inline_keyboard.len(), 3);
        assert_eq!(cities_kb.inline_keyboard[0].len(), 4);
        assert_eq!(cities_kb.inline_keyboard[1].len(), 4);
        assert_eq!(cities_kb.inline_keyboard[2].len(), 1);
        assert_eq!(cities_kb.inline_keyboard[0][0].text, "1");
        assert_eq!(get_cb(&cities_kb.inline_keyboard[0][0]), "gym_city:kanto:1");
        assert_eq!(cities_kb.inline_keyboard[1][3].text, "8");
        assert_eq!(get_cb(&cities_kb.inline_keyboard[1][3]), "gym_city:kanto:8");
        assert_eq!(cities_kb.inline_keyboard[2][0].text, "Back");
        assert_eq!(get_cb(&cities_kb.inline_keyboard[2][0]), "gym_main");

        let cities_kb_json = build_gym_cities_keyboard_json("kanto");
        let rows = cities_kb_json["inline_keyboard"].as_array().unwrap();
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[2][0]["text"], "Back");
        assert_eq!(rows[2][0]["icon_custom_emoji_id"], LEFT_ARROW_CUSTOM_EMOJI_ID);
        assert_eq!(rows[2][0]["callback_data"], "gym_main");

        // Gym Leader Detail Tests
        let brock = get_gym_leader("kanto", 1).expect("Brock should exist");
        assert_eq!(brock.name, "Brock");
        assert_eq!(brock.poke_type, "Rock");
        assert_eq!(brock.fee, 200);
        assert_eq!(brock.badge, "Boulder Badge");

        let brock_caption = format_gym_leader_caption(&brock);
        assert!(brock_caption.contains("<blockquote><u>Gym Leader Brock:</u>"));
        assert!(brock_caption.contains("My Pokémon are as hard as rock"));
        assert!(brock_caption.contains("<b>Gym Type:</b> <code>Rock</code>"));
        assert!(brock_caption.contains("<b>Challenge Fee:</b> <code>200</code> PokéDollars 💵"));
        assert!(brock_caption.contains("Are you sure you want to challenge <code>Pewter City Gym</code> ?"));

        let leader_kb = build_gym_leader_keyboard("kanto", 1);
        assert_eq!(leader_kb.inline_keyboard.len(), 2);
        assert_eq!(leader_kb.inline_keyboard[0].len(), 2);
        assert_eq!(leader_kb.inline_keyboard[1].len(), 2);
        assert_eq!(leader_kb.inline_keyboard[0][0].text, "Rewards");
        assert_eq!(leader_kb.inline_keyboard[0][1].text, "Rules");
        assert_eq!(leader_kb.inline_keyboard[1][0].text, "Battle");
        assert_eq!(leader_kb.inline_keyboard[1][1].text, "Back");

        // Verify that all 32 cities across Kanto, Johto, Hoenn, and Sinnoh have leader artwork files,
        // anime signature pokemon, level 100 stats, 186 IVs (all 31), and 510 EVs
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");
        for region in &["kanto", "johto", "hoenn", "sinnoh"] {
            for num in 1..=8 {
                let leader = get_gym_leader(region, num).expect("Leader should exist");
                let photo_path = get_gym_photo_path(leader.city);
                assert!(
                    std::path::Path::new(&photo_path).exists(),
                    "Photo path {} for {} must exist",
                    photo_path,
                    leader.city
                );
                assert_ne!(
                    photo_path, "assets/gym.jpg",
                    "Leader {} in {} should have specific leader artwork, not default gym.jpg",
                    leader.name, leader.city
                );

                assert!(!leader.signature_pokemon.is_empty());
                assert!(leader.signature_pokemon_id > 0);

                let pkmn = create_gym_leader_battle_pokemon(&leader, &pokedex)
                    .unwrap_or_else(|| panic!("Failed to create battle pokemon for {}'s {}", leader.name, leader.signature_pokemon));
                assert_eq!(pkmn.level, 100);
                assert_eq!(pkmn.id, leader.signature_pokemon_id);

                // Exact 186 IVs (31 in all 6 stats)
                let total_ivs = pkmn.iv_hp + pkmn.iv_atk + pkmn.iv_def + pkmn.iv_spa + pkmn.iv_spd + pkmn.iv_spe;
                assert_eq!(total_ivs, 186, "Leader {}'s {} must have exactly 186 total IVs", leader.name, leader.signature_pokemon);
                assert_eq!(pkmn.iv_hp, 31);
                assert_eq!(pkmn.iv_atk, 31);
                assert_eq!(pkmn.iv_def, 31);
                assert_eq!(pkmn.iv_spa, 31);
                assert_eq!(pkmn.iv_spd, 31);
                assert_eq!(pkmn.iv_spe, 31);

                // Exact 510 EVs
                let total_evs = pkmn.ev_hp + pkmn.ev_atk + pkmn.ev_def + pkmn.ev_spa + pkmn.ev_spd + pkmn.ev_spe;
                assert_eq!(total_evs, 510, "Leader {}'s {} must have exactly 510 total EVs", leader.name, leader.signature_pokemon);

                // Moves and HP
                assert!(!pkmn.moves.is_empty(), "Leader {} must have damaging moves", leader.name);
                assert!(pkmn.moves.len() <= 4);
                assert_eq!(pkmn.current_hp, pkmn.max_hp);
                assert!(pkmn.max_hp > 0);

                // Verify 6v6 team has exactly 6 pokemon
                assert_eq!(leader.team_pokemon_ids.len(), 6, "Leader {} must have 6 pokemon IDs", leader.name);
                let leader_team = create_gym_leader_team(&leader, &pokedex);
                assert_eq!(leader_team.len(), 6, "Leader {} must have 6 battle pokemon", leader.name);
                for team_pkmn in &leader_team {
                    assert_eq!(team_pkmn.level, 100);
                    let ivs = team_pkmn.iv_hp + team_pkmn.iv_atk + team_pkmn.iv_def + team_pkmn.iv_spa + team_pkmn.iv_spd + team_pkmn.iv_spe;
                    assert_eq!(ivs, 186);
                    let evs = team_pkmn.ev_hp + team_pkmn.ev_atk + team_pkmn.ev_def + team_pkmn.ev_spa + team_pkmn.ev_spd + team_pkmn.ev_spe;
                    assert_eq!(evs, 510);
                }
            }
        }

        // Test Gym Battle Screen and Keyboard formatting
        let brock_battle_pkmn = create_gym_leader_battle_pokemon(&brock, &pokedex).unwrap();
        let player_test_pkmn = BattlePokemon {
            db_id: Some(1),
            id: 25,
            name: "Pikachu".to_string(),
            nickname: "Pikachu".to_string(),
            level: 50,
            types: vec!["Electric".to_string()],
            nature: "Hardy".to_string(),
            base_stats: BaseStats { hp: 35, attack: 55, defense: 40, special_attack: 50, special_defense: 50, speed: 90 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 252, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 252,
            max_hp: 110,
            current_hp: 110,
            moves: vec![
                MoveDetail {
                    name: "Thunderbolt".to_string(),
                    t: "Electric".to_string(),
                    c: "Special".to_string(),
                    p: Some(90),
                    a: Some(100),
                    pp: Some(15),
                    d: "A strong electric attack.".to_string(),
                }
            ],
            is_shiny: false,
            catch_rate: 190,
            base_experience: 112,
            is_burned: false,
        };

        let gym_screen = format_gym_battle_screen(
            "Battle begins",
            brock.name,
            &brock_battle_pkmn,
            &player_test_pkmn,
            "Ash",
            12345,
        );
        assert!(gym_screen.contains("Gym Leader Brock's <b>Onix</b>"));
        assert!(gym_screen.contains("Lv. 100"));
        assert!(gym_screen.contains("Current turn: <a href=\"tg://user?id=12345\">Ash</a>"));
        assert!(gym_screen.contains("Thunderbolt"));

        let leader_action_header = format_action_log("Gym Leader Brock's Onix", "Stone Edge", 163, true, 1.0, true);
        let turn_screen = format_gym_battle_screen(
            &leader_action_header,
            brock.name,
            &brock_battle_pkmn,
            &player_test_pkmn,
            "Ash",
            12345,
        );
        assert!(turn_screen.contains("Gym Leader Brock's Onix used <b>Stone Edge</b>"));
        assert!(!turn_screen.contains("Ancient Power"));

        let gym_kb = build_gym_battle_keyboard(12345, &player_test_pkmn.moves);
        assert_eq!(gym_kb.inline_keyboard.len(), 2);
        assert_eq!(gym_kb.inline_keyboard[0][0].text, "Thunderbolt");
        assert_eq!(gym_kb.inline_keyboard[1][0].text, "Run");
        assert_eq!(get_cb(&gym_kb.inline_keyboard[1][0]), "btl_run:12345");
        assert_eq!(gym_kb.inline_keyboard[1][1].text, "Pokemons");
        assert_eq!(get_cb(&gym_kb.inline_keyboard[1][1]), "btl_team:12345");
    }

