    #[test]
    fn test_build_battle_keyboard_opts_omits_pokeball_in_evtrain() {
        let moves = vec![
            MoveDetail { name: "Tackle".to_string(), t: "Normal".to_string(), c: "Physical".to_string(), p: Some(40), a: Some(100), pp: Some(35), d: String::new() },
        ];
        let kb_ev = build_battle_keyboard_opts(12345, &moves, true);
        fn get_cb(btn: &teloxide::types::InlineKeyboardButton) -> Option<&str> {
            match &btn.kind {
                teloxide::types::InlineKeyboardButtonKind::CallbackData(data) => Some(data.as_str()),
                _ => None,
            }
        }
        // Last row must NOT have Poke Ball button
        let last_row = kb_ev.inline_keyboard.last().unwrap();
        assert_eq!(last_row.len(), 2);
        assert_eq!(last_row[0].text, "Run");
        assert_eq!(get_cb(&last_row[0]), Some("btl_run:12345"));
        assert_eq!(last_row[1].text, "Pokemons");
        assert_eq!(get_cb(&last_row[1]), Some("btl_team:12345"));
        for row in &kb_ev.inline_keyboard {
            for btn in row {
                assert_ne!(btn.text, "Poke Ball");
                if let Some(cb) = get_cb(btn) {
                    assert!(!cb.starts_with("btl_ball:"));
                }
            }
        }

        // Normal battle keyboard MUST have Poke Ball
        let kb_normal = build_battle_keyboard_opts(12345, &moves, false);
        let normal_last_row = kb_normal.inline_keyboard.last().unwrap();
        assert_eq!(normal_last_row.len(), 3);
        assert_eq!(normal_last_row[0].text, "Poke Ball");
    }

