    #[test]
    fn test_parse_give_args() {
        // Single amount (e.g. in reply: "/give 1778")
        let res1 = parse_give_args("1778");
        assert_eq!(res1, Some((None, 1778)));

        let res1_comma = parse_give_args("1,778");
        assert_eq!(res1_comma, Some((None, 1778)));

        // Target then amount: "/give @shivam 1778"
        let res2 = parse_give_args("@shivam 1778");
        assert_eq!(res2, Some((Some("shivam".to_string()), 1778)));

        // Amount then target: "/give 1778 @shivam"
        let res3 = parse_give_args("1778 @shivam");
        assert_eq!(res3, Some((Some("shivam".to_string()), 1778)));

        // Target numeric ID then amount: "/give 987654 500"
        let res4 = parse_give_args("987654 500");
        assert_eq!(res4, Some((Some("987654".to_string()), 500)));

        // Amount then target numeric ID: "/give 500 12345678"
        let res5 = parse_give_args("500 12345678");
        assert_eq!(res5, Some((Some("12345678".to_string()), 500)));

        // Invalid empty
        assert_eq!(parse_give_args(""), None);
    }

