    #[tokio::test]
    async fn test_give_database_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT NOT NULL,
                pokedollars INTEGER NOT NULL DEFAULT 100
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // Sender (id: 1001) has 2000 PokéDollars
        // Receiver (id: 1002) has 100 PokéDollars
        sqlx::query("INSERT INTO users (id, username, first_name, pokedollars) VALUES (1001, 'sender', 'Sender', 2000);")
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query("INSERT INTO users (id, username, first_name, pokedollars) VALUES (1002, 'receiver', 'Receiver', 100);")
            .execute(&pool)
            .await
            .unwrap();

        // 1. Cannot send to self
        let self_res = execute_give_transfer(&pool, 1001, 1001, 500).await;
        assert_eq!(self_res, Err("You cannot send PokéDollars to yourself."));

        // 2. Zero or negative amount
        let zero_res = execute_give_transfer(&pool, 1001, 1002, 0).await;
        assert_eq!(zero_res, Err("Please specify a valid amount of PokéDollars to give."));
        let neg_res = execute_give_transfer(&pool, 1001, 1002, -100).await;
        assert_eq!(neg_res, Err("Please specify a valid amount of PokéDollars to give."));

        // 3. Insufficient balance (trying to send 5000 when balance is 2000)
        let poor_res = execute_give_transfer(&pool, 1001, 1002, 5000).await;
        assert_eq!(poor_res, Err("You do not have enough PokéDollars."));

        // 4. Successful transfer of 1778 (as in screenshot)
        let ok_res = execute_give_transfer(&pool, 1001, 1002, 1778).await;
        assert_eq!(ok_res, Ok(()));

        // Verify balances
        let sender_bal: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = 1001")
            .fetch_one(&pool)
            .await
            .unwrap();
        let receiver_bal: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = 1002")
            .fetch_one(&pool)
            .await
            .unwrap();

        assert_eq!(sender_bal, 2000 - 1778); // 222
        assert_eq!(receiver_bal, 100 + 1778); // 1878
    }

    #[test]
    fn test_distribute_iv_sum_bounds_and_total() {
        let mut rng = rand::thread_rng();
        for target in [0, 10, 50, 90, 100, 110, 120, 150, 169, 170, 186] {
            for _ in 0..50 {
                let (hp, atk, def, spa, spd, spe) = distribute_iv_sum(target, 0, 31, &mut rng);
                assert!((0..=31).contains(&hp));
                assert!((0..=31).contains(&atk));
                assert!((0..=31).contains(&def));
                assert!((0..=31).contains(&spa));
                assert!((0..=31).contains(&spd));
                assert!((0..=31).contains(&spe));
                let sum = hp + atk + def + spa + spd + spe;
                assert_eq!(sum, target, "Sum {} didn't match target {}", sum, target);
            }
        }
    }

    #[test]
    fn test_hunt_iv_distribution_statistical() {
        let mut rng = rand::thread_rng();
        let mut c_0_100 = 0;
        let mut c_101_120 = 0;
        let mut c_121_150 = 0;
        let mut c_151_169 = 0;
        let mut c_170_186 = 0;

        let total_samples = 10_000;
        for _ in 0..total_samples {
            let (hp, atk, def, spa, spd, spe) = generate_wild_hunt_ivs_with_rng(None, false, &mut rng);
            assert!((0..=31).contains(&hp));
            assert!((0..=31).contains(&atk));
            assert!((0..=31).contains(&def));
            assert!((0..=31).contains(&spa));
            assert!((0..=31).contains(&spd));
            assert!((0..=31).contains(&spe));

            let total = hp + atk + def + spa + spd + spe;
            match total {
                0..=100 => c_0_100 += 1,
                101..=120 => c_101_120 += 1,
                121..=150 => c_121_150 += 1,
                151..=169 => c_151_169 += 1,
                170..=186 => c_170_186 += 1,
                _ => panic!("Total IV {} out of valid range 0..=186", total),
            }
        }

        let p_0_100 = (c_0_100 as f64 / total_samples as f64) * 100.0;
        let p_101_120 = (c_101_120 as f64 / total_samples as f64) * 100.0;
        let p_121_150 = (c_121_150 as f64 / total_samples as f64) * 100.0;
        let p_151_169 = (c_151_169 as f64 / total_samples as f64) * 100.0;
        let p_170_186 = (c_170_186 as f64 / total_samples as f64) * 100.0;

        // Hunt: 0-100: ~28.0%, 101-120: ~50.0%, 121-150: ~21.5%, 151-169: ~0.5%, 170-186: ~0.00001%
        assert!((25.0..=31.0).contains(&p_0_100), "0-100 actual: {}%", p_0_100);
        assert!((47.0..=53.0).contains(&p_101_120), "101-120 actual: {}%", p_101_120);
        assert!((19.0..=24.0).contains(&p_121_150), "121-150 actual: {}%", p_121_150);
        assert!(p_151_169 <= 1.5, "151-169 actual: {}%", p_151_169);
        assert!(p_170_186 <= 0.05, "170-186 actual: {}%", p_170_186);
    }

    #[test]
    fn test_safari_iv_distribution_statistical() {
        let mut rng = rand::thread_rng();
        let mut c_0_100 = 0;
        let mut c_101_120 = 0;
        let mut c_121_150 = 0;
        let mut c_151_169 = 0;
        let mut c_170_186 = 0;

        let total_samples = 10_000;
        for _ in 0..total_samples {
            let (hp, atk, def, spa, spd, spe) = generate_safari_ivs_with_rng(None, false, &mut rng);
            assert!((0..=31).contains(&hp));
            assert!((0..=31).contains(&atk));
            assert!((0..=31).contains(&def));
            assert!((0..=31).contains(&spa));
            assert!((0..=31).contains(&spd));
            assert!((0..=31).contains(&spe));

            let total = hp + atk + def + spa + spd + spe;
            match total {
                0..=100 => c_0_100 += 1,
                101..=120 => c_101_120 += 1,
                121..=150 => c_121_150 += 1,
                151..=169 => c_151_169 += 1,
                170..=186 => c_170_186 += 1,
                _ => panic!("Total IV {} out of valid range 0..=186", total),
            }
        }

        // Safari: 0-100: 0% strictly guaranteed
        assert_eq!(c_0_100, 0, "Safari must NEVER generate total IV <= 100!");

        let p_101_120 = (c_101_120 as f64 / total_samples as f64) * 100.0;
        let p_121_150 = (c_121_150 as f64 / total_samples as f64) * 100.0;
        let p_151_169 = (c_151_169 as f64 / total_samples as f64) * 100.0;
        let p_170_186 = (c_170_186 as f64 / total_samples as f64) * 100.0;

        // Safari: 101-120: ~69.44%, 121-150: ~29.86%, 151-169: ~0.69%, 170-186: ~0.000014%
        assert!((66.0..=73.0).contains(&p_101_120), "Safari 101-120 actual: {}%", p_101_120);
        assert!((27.0..=33.0).contains(&p_121_150), "Safari 121-150 actual: {}%", p_121_150);
        assert!(p_151_169 <= 2.0, "Safari 151-169 actual: {}%", p_151_169);
        assert!(p_170_186 <= 0.05, "Safari 170-186 actual: {}%", p_170_186);
    }

    #[test]
    fn test_hunt_floors_and_shiny_guarantee() {
        let mut rng = rand::thread_rng();

        // 1. Shiny guarantee: at least one 31 IV
        for _ in 0..100 {
            let (hp, atk, def, spa, spd, spe) = generate_wild_hunt_ivs_with_rng(None, true, &mut rng);
            let ivs = [hp, atk, def, spa, spd, spe];
            assert!(ivs.contains(&31), "Shiny must have at least one 31 IV, got {:?}", ivs);

            let (s_hp, s_atk, s_def, s_spa, s_spd, s_spe) = generate_safari_ivs_with_rng(None, true, &mut rng);
            let s_ivs = [s_hp, s_atk, s_def, s_spa, s_spd, s_spe];
            assert!(s_ivs.contains(&31), "Safari Shiny must have at least one 31 IV, got {:?}", s_ivs);
        }

        // 2. Tier helpers
        assert_eq!(get_iv_tier(50), "0-100");
        assert_eq!(get_iv_tier(100), "0-100");
        assert_eq!(get_iv_tier(101), "101-120");
        assert_eq!(get_iv_tier(120), "101-120");
        assert_eq!(get_iv_tier(121), "121-150");
        assert_eq!(get_iv_tier(150), "121-150");
        assert_eq!(get_iv_tier(151), "151-169");
        assert_eq!(get_iv_tier(169), "151-169");
        assert_eq!(get_iv_tier(170), "170-186");
        assert_eq!(get_iv_tier(186), "170-186");
    }

