    #[test]
    fn test_challenge_settings_cycling_and_toggling() {
        let mut s = ChallengeSettings::default();

        // Max pokemon cycle: 6 -> 1 -> 2 -> ... -> 6
        assert_eq!(s.max_pokemon, 6);
        s.cycle_or_toggle("max_pokemon");
        assert_eq!(s.max_pokemon, 1);
        s.cycle_or_toggle("max_pokemon");
        assert_eq!(s.max_pokemon, 2);

        // Switch pokemon toggle: true -> false -> true
        assert!(s.switch_pokemon);
        s.cycle_or_toggle("switch_pokemon");
        assert!(!s.switch_pokemon);
        s.cycle_or_toggle("switch_pokemon");
        assert!(s.switch_pokemon);

        // Min legendaries cycle: 0 -> 1 -> 2 -> 3 -> 6 -> 0
        assert_eq!(s.min_legendaries, 0);
        s.cycle_or_toggle("min_legendaries");
        assert_eq!(s.min_legendaries, 1);
        s.cycle_or_toggle("min_legendaries");
        assert_eq!(s.min_legendaries, 2);

        // Max legendaries cycle: 6 -> 0 -> 1 -> 2 -> 3 -> 6
        assert_eq!(s.max_legendaries, 6);
        s.cycle_or_toggle("max_legendaries");
        assert_eq!(s.max_legendaries, 0);

        // Min level cycle: 1 -> 5 -> 25 -> 50 -> 100 -> 1
        assert_eq!(s.min_level, 1);
        s.cycle_or_toggle("min_level");
        assert_eq!(s.min_level, 5);
        s.cycle_or_toggle("min_level");
        assert_eq!(s.min_level, 25);
        s.cycle_or_toggle("min_level");
        assert_eq!(s.min_level, 50);
        s.cycle_or_toggle("min_level");
        assert_eq!(s.min_level, 100);
        s.cycle_or_toggle("min_level");
        assert_eq!(s.min_level, 1);

        // Max level cycle: 100 -> 50 -> 25 -> 5 -> 100
        assert_eq!(s.max_level, 100);
        s.cycle_or_toggle("max_level");
        assert_eq!(s.max_level, 50);
        s.cycle_or_toggle("max_level");
        assert_eq!(s.max_level, 25);

        // Form changes toggle
        assert!(s.form_changes);
        s.cycle_or_toggle("form_changes");
        assert!(!s.form_changes);

        // Sandbox mode toggle
        assert!(!s.sandbox_mode);
        s.cycle_or_toggle("sandbox_mode");
        assert!(s.sandbox_mode);

        // Random mode toggle
        assert!(!s.random_mode);
        s.cycle_or_toggle("random_mode");
        assert!(s.random_mode);
    }

