    #[tokio::test]
    async fn test_user_challenge_settings_db_flow() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE user_challenge_settings (
                user_id INTEGER PRIMARY KEY,
                max_pokemon INTEGER NOT NULL DEFAULT 6,
                switch_pokemon INTEGER NOT NULL DEFAULT 1,
                min_legendaries INTEGER NOT NULL DEFAULT 0,
                max_legendaries INTEGER NOT NULL DEFAULT 6,
                min_level INTEGER NOT NULL DEFAULT 1,
                max_level INTEGER NOT NULL DEFAULT 100,
                form_changes INTEGER NOT NULL DEFAULT 1,
                status_effects INTEGER NOT NULL DEFAULT 1,
                sandbox_mode INTEGER NOT NULL DEFAULT 0,
                random_mode INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT (datetime('now'))
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // Non-existent user gets default settings
        let loaded = load_user_challenge_settings(&pool, 999).await;
        assert_eq!(loaded, ChallengeSettings::default());

        // Modify and save
        let mut custom = ChallengeSettings::default();
        custom.min_level = 100;
        custom.sandbox_mode = true;
        custom.switch_pokemon = false;
        let save_res = save_user_challenge_settings(&pool, 999, &custom).await;
        assert!(save_res.is_ok());

        // Re-load and verify
        let reloaded = load_user_challenge_settings(&pool, 999).await;
        assert_eq!(reloaded.min_level, 100);
        assert!(reloaded.sandbox_mode);
        assert!(!reloaded.switch_pokemon);
    }

