    #[test]
    fn test_challenge_speed_logistics_and_round_turn_order() {
        let ch_id = 100u64;
        let opp_id = 200u64;

        // Challenger faster
        assert_eq!(determine_challenge_faster_trainer_order(150, 100, ch_id, opp_id, false), ch_id);
        // Opponent faster
        assert_eq!(determine_challenge_faster_trainer_order(80, 120, ch_id, opp_id, false), opp_id);
        // Speed tie with 50/50 roll flag
        assert_eq!(determine_challenge_faster_trainer_order(100, 100, ch_id, opp_id, true), ch_id);
        assert_eq!(determine_challenge_faster_trainer_order(100, 100, ch_id, opp_id, false), opp_id);

        let fast_pkmn = BattlePokemon {
            id: 25,
            db_id: Some(1),
            name: "pikachu".to_string(),
            nickname: "FastPika".to_string(),
            level: 50,
            nature: "Jolly".to_string(),
            types: vec!["Electric".to_string()],
            base_stats: BaseStats { hp: 35, attack: 55, defense: 40, special_attack: 50, special_defense: 50, speed: 90 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 0, ev_spd: 0, ev_spe: 252,
            max_hp: 110, current_hp: 110,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 190,
            base_experience: 112,
            is_burned: false,
        };

        let slow_pkmn = BattlePokemon {
            id: 143,
            db_id: Some(2),
            name: "snorlax".to_string(),
            nickname: "Chonky".to_string(),
            level: 50,
            nature: "Brave".to_string(),
            types: vec!["Normal".to_string()],
            base_stats: BaseStats { hp: 160, attack: 110, defense: 65, special_attack: 65, special_defense: 110, speed: 30 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 252, ev_atk: 252, ev_def: 4, ev_spa: 0, ev_spd: 0, ev_spe: 0,
            max_hp: 267, current_hp: 267,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 25,
            base_experience: 189,
            is_burned: false,
        };

        assert!(fast_pkmn.get_spe() > slow_pkmn.get_spe());

        let mut btl = ChallengeBattle {
            current_turn: ch_id,
            turn_count: 0,
            last_action: "Battle begins".to_string(),
            challenger_active: fast_pkmn.clone(),
            challenger_team: vec![fast_pkmn.clone()],
            challenger_fainted_ids: Vec::new(),
            challenger_fainted_indices: Vec::new(),
            challenger_team_hp: HashMap::new(),
            opponent_active: slow_pkmn.clone(),
            opponent_team: vec![slow_pkmn.clone()],
            opponent_fainted_ids: Vec::new(),
            opponent_fainted_indices: Vec::new(),
            opponent_team_hp: HashMap::new(),
            awaiting_faint_switch: None,
            round_first_acted: None,
            challenger_mega_used: false,
            opponent_mega_used: false,
        };

        // Faster trainer is challenger
        assert_eq!(determine_challenge_faster_trainer(&btl, ch_id, opp_id), ch_id);

        // Turn round execution simulation:
        // Round 1 start:
        btl.current_turn = determine_challenge_faster_trainer(&btl, ch_id, opp_id);
        assert_eq!(btl.current_turn, ch_id);
        assert_eq!(btl.round_first_acted, None);

        // Challenger attacks (Action 1):
        btl.round_first_acted = Some(ch_id);
        btl.current_turn = opp_id;
        btl.turn_count += 1;

        // Opponent attacks (Action 2 - round complete):
        assert!(btl.round_first_acted.is_some());
        btl.round_first_acted = None;
        btl.current_turn = determine_challenge_faster_trainer(&btl, ch_id, opp_id);
        btl.turn_count += 1;

        // Round 2 should start again with the faster trainer (challenger)!
        assert_eq!(btl.current_turn, ch_id);
        assert_eq!(btl.round_first_acted, None);

        // Faint switch test:
        let super_fast_pkmn = BattlePokemon {
            id: 101,
            db_id: Some(3),
            name: "electrode".to_string(),
            nickname: "Speedy".to_string(),
            level: 50,
            nature: "Timid".to_string(),
            types: vec!["Electric".to_string()],
            base_stats: BaseStats { hp: 60, attack: 50, defense: 70, special_attack: 80, special_defense: 80, speed: 150 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 252, ev_spd: 4, ev_spe: 252,
            max_hp: 135, current_hp: 135,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 60,
            base_experience: 172,
            is_burned: false,
        };

        // Opponent faint switches to Electrode
        btl.opponent_active = super_fast_pkmn;
        btl.awaiting_faint_switch = None;
        btl.round_first_acted = None;
        btl.current_turn = determine_challenge_faster_trainer(&btl, ch_id, opp_id);

        // Electrode is faster, so opponent MUST get the first turn!
        assert_eq!(btl.current_turn, opp_id);

        // Opponent faint switches to slow Snorlax instead:
        btl.opponent_active = slow_pkmn.clone();
        btl.current_turn = determine_challenge_faster_trainer(&btl, ch_id, opp_id);

        // Snorlax is slower, so Challenger (Pikachu) MUST get the first turn!
        assert_eq!(btl.current_turn, ch_id);
    }

    #[test]
    fn test_challenge_defeat_message_and_prize_calculation() {
        // 1. Prize money tests according to player team size (15 PD per pokemon)
        // 1v1 => 15 PD
        assert_eq!(calculate_challenge_prize_pd(1, 1, false), 15);
        // 2v2 => 30 PD
        assert_eq!(calculate_challenge_prize_pd(2, 2, false), 30);
        // 3v3 => 45 PD
        assert_eq!(calculate_challenge_prize_pd(3, 3, false), 45);
        // 4v4 => 60 PD
        assert_eq!(calculate_challenge_prize_pd(4, 4, false), 60);
        // 5v5 => 75 PD
        assert_eq!(calculate_challenge_prize_pd(5, 5, false), 75);
        // 6v6 => 90 PD ("full team 6v6 grant 90 pd thats it")
        assert_eq!(calculate_challenge_prize_pd(6, 6, false), 90);

        // Mismatched team sizes: prize is based on smaller team
        // 1 vs 6 => 15 PD ("for example 1st player have 1 pokemon, 2nd pokemon have 6 pokemon, winner will get 15pd thats it")
        assert_eq!(calculate_challenge_prize_pd(1, 6, false), 15);
        // 6 vs 1 => 15 PD
        assert_eq!(calculate_challenge_prize_pd(6, 1, false), 15);
        // 2 vs 5 => 30 PD
        assert_eq!(calculate_challenge_prize_pd(2, 5, false), 30);
        // 3 vs 6 => 45 PD
        assert_eq!(calculate_challenge_prize_pd(3, 6, false), 45);

        // Sandbox mode gives 0 PD
        assert_eq!(calculate_challenge_prize_pd(6, 6, true), 0);
        assert_eq!(calculate_challenge_prize_pd(1, 1, true), 0);

        // 2. Defeat message format matches exact user prompt:
        // Dragonite used Outrage.
        // Charmeleon fainted.
        // 
        // Shivam has defeated None.
        // +90 💵
        let move_log = "Dragonite used Outrage.";
        let msg = format_challenge_defeat_screen(move_log, "Charmeleon", "Shivam", 12345, "None", 0, 90);
        assert_eq!(
            msg,
            "Dragonite used Outrage.\n\nCharmeleon fainted.\n\n<a href=\"tg://user?id=12345\">Shivam</a> has defeated <a href=\"tg://user?id=0\">None</a>.\n+90 💵"
        );

        // Test with 15 PD (1v1 or 1v6)
        let msg_15 = format_challenge_defeat_screen("Pikachu used Thunderbolt.", "Squirtle", "Ash", 100, "Gary", 200, 15);
        assert_eq!(
            msg_15,
            "Pikachu used Thunderbolt.\n\nSquirtle fainted.\n\n<a href=\"tg://user?id=100\">Ash</a> has defeated <a href=\"tg://user?id=200\">Gary</a>.\n+15 💵"
        );

        // Test with sandbox (0 PD, no prize line)
        let msg_sandbox = format_challenge_defeat_screen("Mewtwo used Psychic.", "Gengar", "Red", 300, "Blue", 400, 0);
        assert_eq!(
            msg_sandbox,
            "Mewtwo used Psychic.\n\nGengar fainted.\n\n<a href=\"tg://user?id=300\">Red</a> has defeated <a href=\"tg://user?id=400\">Blue</a>."
        );
    }

    #[tokio::test]
    async fn test_challenge_random_mode_and_team_validation() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE user_teams (
                user_id INTEGER NOT NULL,
                team_num INTEGER NOT NULL,
                slot INTEGER NOT NULL,
                pokemon_db_id INTEGER NOT NULL,
                PRIMARY KEY (user_id, team_num, slot)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 50,
                nature TEXT NOT NULL DEFAULT 'Hardy',
                experience INTEGER NOT NULL DEFAULT 0,
                iv_hp INTEGER NOT NULL DEFAULT 15,
                iv_attack INTEGER NOT NULL DEFAULT 15,
                iv_defense INTEGER NOT NULL DEFAULT 15,
                iv_sp_attack INTEGER NOT NULL DEFAULT 15,
                iv_sp_defense INTEGER NOT NULL DEFAULT 15,
                iv_speed INTEGER NOT NULL DEFAULT 15,
                ev_hp INTEGER NOT NULL DEFAULT 0,
                ev_attack INTEGER NOT NULL DEFAULT 0,
                ev_defense INTEGER NOT NULL DEFAULT 0,
                ev_sp_attack INTEGER NOT NULL DEFAULT 0,
                ev_sp_defense INTEGER NOT NULL DEFAULT 0,
                ev_speed INTEGER NOT NULL DEFAULT 0,
                move_1 TEXT,
                move_2 TEXT,
                move_3 TEXT,
                move_4 TEXT
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        let pokedex = PokedexData::load_from_file("./pokedex.json").unwrap_or_default();

        let mut settings = ChallengeSettings::default();
        settings.min_legendaries = 6;

        let team = vec![
            (1, 25, 50, "Pikachu".to_string()),
            (2, 4, 50, "Charmander".to_string()),
        ];

        // Without random mode: fails because 0 legendaries < 6 required
        let res = validate_team_for_challenge(&team, &pokedex, &settings);
        assert!(res.is_err());
        assert_eq!(
            res.unwrap_err(),
            "Your team has 0 legendary Pokémon, but at least 6 are required."
        );

        // With random mode: passes because pokemons are drawn randomly from collection!
        settings.random_mode = true;
        let res_random = validate_team_for_challenge(&team, &pokedex, &settings);
        assert!(res_random.is_ok());

        // Empty team still returns error
        let empty_team: Vec<(i64, u32, i32, String)> = Vec::new();
        let res_empty = validate_team_for_challenge(&empty_team, &pokedex, &settings);
        assert!(res_empty.is_err());

        // Test load_user_challenge_battle_team in random mode from user collection
        let user_id = 88888u64;
        for i in 1..=5 {
            sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature) VALUES (?, ?, ?, ?, 50, 'Hardy')")
                .bind(i as i64)
                .bind(user_id as i64)
                .bind(25) // Pikachu
                .bind(format!("Poke{}", i))
                .execute(&pool)
                .await
                .unwrap();
        }

        // Initially, user only has level 50 pokemons
        let mut lvl_50_settings = ChallengeSettings::default();
        lvl_50_settings.random_mode = true;
        lvl_50_settings.min_level = 50;
        lvl_50_settings.max_level = 50;
        let loaded = load_user_challenge_battle_team(&pool, user_id, &pokedex, &lvl_50_settings).await;
        assert_eq!(loaded.len(), 5);
        assert_eq!(loaded[0].level, 50);

        // Test trained level filtering: when min_level = 100, max_level = 100
        settings.min_level = 100;
        settings.max_level = 100;
        settings.min_legendaries = 0;
        // User has NO level 100 pokemons yet: validate_user_random_challenge_eligible must return Err
        let res_eligible_err = validate_user_random_challenge_eligible(&pool, user_id, &pokedex, &settings).await;
        assert!(res_eligible_err.is_err());
        assert_eq!(res_eligible_err.unwrap_err(), "You have no level 100 Pokémon in your collection.");

        // And load_user_challenge_battle_team must return empty (untrained level 50 pokemons will NOT be loaded!)
        let loaded_empty = load_user_challenge_battle_team(&pool, user_id, &pokedex, &settings).await;
        assert_eq!(loaded_empty.len(), 0, "Untrained pokemons must never be loaded into a level 100 battle");

        // Now train/add a genuine level 100 Charizard for the user
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature) VALUES (999, ?, 6, 'Charizard', 100, 'Timid')")
            .bind(user_id as i64)
            .execute(&pool)
            .await
            .unwrap();

        // Now eligible check passes!
        let res_eligible_ok = validate_user_random_challenge_eligible(&pool, user_id, &pokedex, &settings).await;
        assert!(res_eligible_ok.is_ok());

        // And ONLY the genuine level 100 Pokemon is loaded, preserving its genuine level and stats
        let loaded_100 = load_user_challenge_battle_team(&pool, user_id, &pokedex, &settings).await;
        assert_eq!(loaded_100.len(), 1);
        assert_eq!(loaded_100[0].id, 6);
        assert_eq!(loaded_100[0].level, 100);

        // Test legendary filtering: add Mewtwo (id 150, legendary, lv 70) and Pikachu (id 25, lv 70)
        let mewtwo_user = 99999u64;
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature) VALUES (101, ?, 150, 'Mewtwo', 70, 'Modest')")
            .bind(mewtwo_user as i64)
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query("INSERT INTO pokemons (id, user_id, pokemon_id, nickname, level, nature) VALUES (102, ?, 25, 'Pikachu', 70, 'Hardy')")
            .bind(mewtwo_user as i64)
            .execute(&pool)
            .await
            .unwrap();

        // 1. max_legendaries = 0: must exclude Mewtwo
        let mut non_leg_settings = ChallengeSettings::default();
        non_leg_settings.random_mode = true;
        non_leg_settings.max_legendaries = 0;
        non_leg_settings.max_pokemon = 6;
        non_leg_settings.min_level = 1;
        non_leg_settings.max_level = 100;
        let loaded_non_leg = load_user_challenge_battle_team(&pool, mewtwo_user, &pokedex, &non_leg_settings).await;
        assert_eq!(loaded_non_leg.len(), 1);
        assert_eq!(loaded_non_leg[0].id, 25);

        // 2. min_legendaries = 1: must include Mewtwo
        let mut leg_settings = ChallengeSettings::default();
        leg_settings.random_mode = true;
        leg_settings.min_legendaries = 1;
        leg_settings.max_legendaries = 2;
        leg_settings.max_pokemon = 2;
        leg_settings.min_level = 1;
        leg_settings.max_level = 100;
        let loaded_leg = load_user_challenge_battle_team(&pool, mewtwo_user, &pokedex, &leg_settings).await;
        assert_eq!(loaded_leg.len(), 2);
        assert!(loaded_leg.iter().any(|p| p.id == 150));
        assert!(loaded_leg.iter().any(|p| p.id == 25));
    }

    #[test]
    fn test_challenge_mega_evolution_mechanics() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").unwrap_or_default();

        let mut charizard = BattlePokemon {
            id: 6,
            db_id: Some(1),
            name: "charizard".to_string(),
            nickname: "Charizard".to_string(),
            level: 100,
            nature: "Jolly".to_string(),
            types: vec!["Fire".to_string(), "Flying".to_string()],
            base_stats: BaseStats { hp: 78, attack: 84, defense: 78, special_attack: 109, special_defense: 85, speed: 100 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 252, ev_def: 4, ev_spa: 0, ev_spd: 0, ev_spe: 252,
            max_hp: 297, current_hp: 297,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 45,
            base_experience: 240,
            is_burned: false,
        };

        // Available megas for base Charizard
        let megas = get_available_mega_forms(&charizard, &pokedex);
        assert_eq!(megas.len(), 2);
        assert!(megas.contains(&"charizard-mega-x".to_string()));
        assert!(megas.contains(&"charizard-mega-y".to_string()));

        // Transform into Charizard Mega X
        let mega_entry = pokedex.get_pokemon_by_name("charizard-mega-x").unwrap();
        charizard.id = mega_entry.id;
        charizard.name = mega_entry.name.clone();
        charizard.types = mega_entry.types.clone();
        charizard.base_stats = mega_entry.stats.clone();
        charizard.max_hp = calc_hp(mega_entry.stats.hp, charizard.iv_hp, charizard.ev_hp, charizard.level as i32);
        charizard.current_hp = charizard.max_hp;

        assert_eq!(charizard.name, "charizard-mega-x");
        assert_eq!(charizard.types, vec!["fire", "dragon"]);
        assert_eq!(charizard.base_stats.attack, 130);

        // Once transformed, get_available_mega_forms must return empty!
        let megas_after = get_available_mega_forms(&charizard, &pokedex);
        assert!(megas_after.is_empty(), "Transformed Mega Pokémon cannot mega evolve again");

        // Venusaur test
        let venusaur = BattlePokemon {
            id: 3,
            db_id: Some(2),
            name: "venusaur".to_string(),
            nickname: "Venusaur".to_string(),
            level: 50,
            nature: "Modest".to_string(),
            types: vec!["Grass".to_string(), "Poison".to_string()],
            base_stats: BaseStats { hp: 80, attack: 82, defense: 83, special_attack: 100, special_defense: 100, speed: 80 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 252, ev_spd: 0, ev_spe: 252,
            max_hp: 155, current_hp: 155,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 45,
            base_experience: 236,
            is_burned: false,
        };
        let v_megas = get_available_mega_forms(&venusaur, &pokedex);
        assert_eq!(v_megas, vec!["venusaur-mega"]);

        // Kyogre primal test
        let kyogre = BattlePokemon {
            id: 382,
            db_id: Some(3),
            name: "kyogre".to_string(),
            nickname: "Kyogre".to_string(),
            level: 70,
            nature: "Timid".to_string(),
            types: vec!["Water".to_string()],
            base_stats: BaseStats { hp: 100, attack: 100, defense: 90, special_attack: 150, special_defense: 140, speed: 90 },
            iv_hp: 31, iv_atk: 31, iv_def: 31, iv_spa: 31, iv_spd: 31, iv_spe: 31,
            ev_hp: 0, ev_atk: 0, ev_def: 0, ev_spa: 252, ev_spd: 0, ev_spe: 252,
            max_hp: 242, current_hp: 242,
            moves: Vec::new(),
            is_shiny: false,
            catch_rate: 3,
            base_experience: 335,
            is_burned: false,
        };
        let k_megas = get_available_mega_forms(&kyogre, &pokedex);
        assert_eq!(k_megas, vec!["kyogre-primal"]);
    }

    #[test]
    fn test_mypokemon_egg_emoji_formatting() {
        let items = vec![
            MyPokemonItem {
                nickname: "Charizard".to_string(),
                nature: "Hardy".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: false,
                detail: Some("Lv.36".to_string()),
            },
            MyPokemonItem {
                nickname: "Riolu".to_string(),
                nature: "Jolly".to_string(),
                is_shiny: false,
                is_hatched: true,
                is_chibi: false,
                detail: Some("Lv.5".to_string()),
            },
            MyPokemonItem {
                nickname: "Togepi".to_string(),
                nature: "Modest".to_string(),
                is_shiny: true,
                is_hatched: true,
                is_chibi: false,
                detail: Some("Lv.1".to_string()),
            },
            MyPokemonItem {
                nickname: "Egg".to_string(),
                nature: "Hardy".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: false,
                detail: Some("Lv.1".to_string()),
            },
        ];

        let text = format_mypokemon_text(
            &items,
            1,
            20,
            4,
            SortOption::OrderCaught,
            SortDirection::Ascending,
            DisplayOption::Level,
            true,
        );
        let egg_emoji = crate::emoji::get_egg_emoji(true);
        assert!(egg_emoji.contains("5199761466105818538"));

        // Item 1: Normal
        assert!(text.contains("1. <b>Charizard</b> - Lv.36"));
        // Item 2: Hatched -> egg emoji in front of pokemon name
        assert!(text.contains(&format!("2. {} <b>Riolu</b> - Lv.5", egg_emoji)));
        // Item 3: Shiny + Hatched -> shiny emoji, egg emoji in front of pokemon name
        assert!(text.contains(&format!("3. {} {} <b>Togepi</b> - Lv.1", SHINY_EMOJI, egg_emoji)));
        // Item 4: Egg nickname (unhatched egg) -> egg emoji in front
        assert!(text.contains(&format!("4. {} <b>Egg</b> - Lv.1", egg_emoji)));
    }

    #[test]
    fn test_mypokemon_chibi_emoji_formatting() {
        let items = vec![
            MyPokemonItem {
                nickname: "Charmander".to_string(),
                nature: "Hardy".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: true,
                detail: Some("Lv.5".to_string()),
            },
            MyPokemonItem {
                nickname: "Charmander".to_string(),
                nature: "Jolly".to_string(),
                is_shiny: true,
                is_hatched: false,
                is_chibi: true,
                detail: Some("Lv.5".to_string()),
            },
            MyPokemonItem {
                nickname: "Riolu".to_string(),
                nature: "Adamant".to_string(),
                is_shiny: false,
                is_hatched: true,
                is_chibi: true,
                detail: Some("Lv.1".to_string()),
            },
            MyPokemonItem {
                nickname: "Chibi Pikachu".to_string(),
                nature: "Timid".to_string(),
                is_shiny: false,
                is_hatched: false,
                is_chibi: false,
                detail: Some("Lv.10".to_string()),
            },
        ];

        let text = format_mypokemon_text(
            &items,
            1,
            20,
            4,
            SortOption::OrderCaught,
            SortDirection::Ascending,
            DisplayOption::Level,
            true,
        );
        let chibi_emoji = crate::emoji::get_chibi_emoji(true);
        let egg_emoji = crate::emoji::get_egg_emoji(true);

        // Item 1: Normal Chibi -> chibi emoji in front
        assert!(text.contains(&format!("1. {} <b>Charmander</b> - Lv.5", chibi_emoji)));
        // Item 2: Shiny Chibi -> chibi emoji, shiny emoji in front of pokemon name
        assert!(text.contains(&format!("2. {} {} <b>Charmander</b> - Lv.5", chibi_emoji, SHINY_EMOJI)));
        // Item 3: Hatched Chibi -> chibi emoji, egg emoji in front of pokemon name
        assert!(text.contains(&format!("3. {} {} <b>Riolu</b> - Lv.1", chibi_emoji, egg_emoji)));
        // Item 4: Chibi nickname -> detected as chibi, chibi emoji in front
        assert!(text.contains(&format!("4. {} <b>Chibi Pikachu</b> - Lv.10", chibi_emoji)));
    }

