    #[tokio::test]
    async fn test_fetch_matching_owned_pokemons_shiny_filtering() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();
        sqlx::query(
            "CREATE TABLE pokemons (
                id INTEGER PRIMARY KEY,
                user_id INTEGER NOT NULL,
                pokemon_id INTEGER NOT NULL,
                nickname TEXT NOT NULL,
                level INTEGER NOT NULL DEFAULT 5,
                nature TEXT NOT NULL,
                experience INTEGER NOT NULL DEFAULT 135,
                is_starter INTEGER NOT NULL DEFAULT 0,
                is_shiny INTEGER NOT NULL DEFAULT 0,
                is_hatched INTEGER NOT NULL DEFAULT 0,
                iv_hp INTEGER NOT NULL DEFAULT 0,
                iv_attack INTEGER NOT NULL DEFAULT 0,
                iv_defense INTEGER NOT NULL DEFAULT 0,
                iv_sp_attack INTEGER NOT NULL DEFAULT 0,
                iv_sp_defense INTEGER NOT NULL DEFAULT 0,
                iv_speed INTEGER NOT NULL DEFAULT 0,
                ev_hp INTEGER NOT NULL DEFAULT 0,
                ev_attack INTEGER NOT NULL DEFAULT 0,
                ev_defense INTEGER NOT NULL DEFAULT 0,
                ev_sp_attack INTEGER NOT NULL DEFAULT 0,
                ev_sp_defense INTEGER NOT NULL DEFAULT 0,
                ev_speed INTEGER NOT NULL DEFAULT 0,
                boosted_ivs TEXT NOT NULL DEFAULT ''
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 1 Normal Charizard
        sqlx::query(
            "INSERT INTO pokemons (id, user_id, pokemon_id, nickname, nature, is_shiny) VALUES (1, 100, 6, 'Charizard', 'Adamant', 0)"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 1 Shiny Charizard
        sqlx::query(
            "INSERT INTO pokemons (id, user_id, pokemon_id, nickname, nature, is_shiny) VALUES (2, 100, 6, 'Charizard', 'Jolly', 1)"
        )
        .execute(&pool)
        .await
        .unwrap();

        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // Normal query should return both Charizards
        let all = fetch_matching_owned_pokemons(&pool, 100, "Charizard", &pokedex).await.unwrap();
        assert_eq!(all.len(), 2);

        // Shiny query should return only the shiny Charizard
        let shinies = fetch_matching_owned_pokemons(&pool, 100, "shiny Charizard", &pokedex).await.unwrap();
        assert_eq!(shinies.len(), 1);
        assert_eq!(shinies[0].get::<i64, _>("id"), 2);
        assert_eq!(shinies[0].get::<i32, _>("is_shiny"), 1);

        // Shiny numeric query
        let shinies_by_id = fetch_matching_owned_pokemons(&pool, 100, "shiny 6", &pokedex).await.unwrap();
        assert_eq!(shinies_by_id.len(), 1);
        assert_eq!(shinies_by_id[0].get::<i64, _>("id"), 2);
    }

    #[test]
    fn test_chibi_id_mapping_and_artwork_resolution() {
        use crate::evolution::{is_chibi_id, get_base_species_id_for_chibi, get_chibi_id_for_base};

        // Chibi ID checks
        assert!(is_chibi_id(20001));
        assert!(is_chibi_id(20004));
        assert!(is_chibi_id(20010));
        assert!(is_chibi_id(31020));
        assert!(!is_chibi_id(1));
        assert!(!is_chibi_id(4));
        assert!(!is_chibi_id(6));
        assert!(!is_chibi_id(1025));

        // Base ID resolutions
        assert_eq!(get_base_species_id_for_chibi(20001), 1);
        assert_eq!(get_base_species_id_for_chibi(20004), 4);
        assert_eq!(get_base_species_id_for_chibi(20010), 7);
        assert_eq!(get_base_species_id_for_chibi(20011), 8);
        assert_eq!(get_base_species_id_for_chibi(20012), 9);
        assert_eq!(get_base_species_id_for_chibi(20310), 310);
        assert_eq!(get_base_species_id_for_chibi(31020), 652); // Chesnaught
        assert_eq!(get_base_species_id_for_chibi(31025), 656); // Froakie
        assert_eq!(get_base_species_id_for_chibi(4), 4);

        // Chibi ID for base
        assert_eq!(get_chibi_id_for_base(1), 20001);
        assert_eq!(get_chibi_id_for_base(4), 20004);
        assert_eq!(get_chibi_id_for_base(7), 20010);
        assert_eq!(get_chibi_id_for_base(8), 20011);
        assert_eq!(get_chibi_id_for_base(9), 20012);
        assert_eq!(get_chibi_id_for_base(652), 31020);

        // Chibi artwork is ONLY for Chibi Pokemon
        assert_eq!(get_pokemon_artwork_path(20004, false), "assets/chibi_assets/Charmander.jpg");
        assert_eq!(get_pokemon_artwork_path(20006, false), "assets/chibi_assets/Charizard.jpg");
        assert_eq!(get_pokemon_artwork_path(20001, false), "assets/chibi_assets/bulbasaur.jpg");
        assert_eq!(get_pokemon_artwork_path(20010, false), "assets/chibi_assets/Squirtle.jpg");
        assert_eq!(get_pokemon_artwork_path(20359, false), "assets/chibi_assets/Absol.jpg");
        assert_eq!(get_pokemon_artwork_path(20280, false), "assets/chibi_assets/Ralts.jpg");
        assert_eq!(get_pokemon_artwork_path(30001, false), "assets/chibi_assets/Deoxys (attack forme).jpg");
        assert_eq!(get_pokemon_artwork_path(30007, false), "assets/chibi_assets/Giratina (origin forme).jpg");
        assert_eq!(get_pokemon_artwork_path(30034, false), "assets/chibi_assets/Charizard-mega-x.jpg");
        assert_eq!(get_pokemon_artwork_path(30120, false), "assets/chibi_assets/Zygarde (complete forme).jpg");

        // Normal Pokemon MUST NEVER use chibi assets!
        assert_eq!(get_pokemon_artwork_path(4, false), "assets/pokemon/4.png");
        assert_eq!(get_pokemon_artwork_path(6, false), "assets/pokemon/6.png");
        assert_eq!(get_pokemon_artwork_path(1, false), "assets/pokemon/1.png");
        assert_eq!(get_pokemon_artwork_path(7, false), "assets/pokemon/7.png");
        assert_eq!(get_pokemon_artwork_path(359, false), "assets/pokemon/359.png");
    }

    #[test]
    fn test_chibi_evolution_progression() {
        use crate::evolution::{check_evolution_ready, get_pre_evolution};

        // Chibi Charmander (20004) -> Chibi Charmeleon (20005) at Lv 16
        assert_eq!(check_evolution_ready(20004, 15), None);
        assert_eq!(check_evolution_ready(20004, 16), Some((16, "Charmeleon", 20005)));

        // Chibi Charmeleon (20005) -> Chibi Charizard (20006) at Lv 36
        assert_eq!(check_evolution_ready(20005, 35), None);
        assert_eq!(check_evolution_ready(20005, 36), Some((36, "Charizard", 20006)));

        // Chibi Bulbasaur (20001) -> Chibi Ivysaur (20002) at Lv 16
        assert_eq!(check_evolution_ready(20001, 16), Some((16, "Ivysaur", 20002)));

        // Chibi Squirtle (20010) -> Chibi Wartortle (20011) at Lv 16
        assert_eq!(check_evolution_ready(20010, 16), Some((16, "Wartortle", 20011)));

        // Pre-evolution of Chibi Charizard (20006) -> Chibi Charmeleon (20005)
        assert_eq!(get_pre_evolution(20006), Some(20005));
        assert_eq!(get_pre_evolution(20005), Some(20004));

        // Normal Pokemon must evolve into normal Pokemon (NOT Chibi!)
        assert_eq!(check_evolution_ready(4, 16), Some((16, "Charmeleon", 5)));
        assert_eq!(check_evolution_ready(5, 36), Some((36, "Charizard", 6)));
        assert_eq!(get_pre_evolution(6), Some(5));
    }

    #[test]
    fn test_chibi_pokedex_lookup() {
        let pokedex = PokedexData::load_from_file("./pokedex.json").expect("Failed to load pokedex.json");

        // get_pokemon_by_id with Chibi ID returns correct base species
        let charmander = pokedex.get_pokemon_by_id(20004).expect("Charmander entry");
        assert_eq!(charmander.name.to_lowercase(), "charmander");
        assert_eq!(charmander.stats.hp, 39);

        let charizard = pokedex.get_pokemon_by_id(20006).expect("Charizard entry");
        assert_eq!(charizard.name.to_lowercase(), "charizard");

        let squirtle = pokedex.get_pokemon_by_id(20010).expect("Squirtle entry");
        assert_eq!(squirtle.name.to_lowercase(), "squirtle");

        // get_pokemon_by_name with "chibi " prefix
        let chibi_char = pokedex.get_pokemon_by_name("chibi charmander").expect("Chibi charmander lookup");
        assert_eq!(chibi_char.id, 4);

        let chibi_pikachu = pokedex.get_pokemon_by_name("Chibi Pikachu").expect("Chibi pikachu lookup");
        assert_eq!(chibi_pikachu.id, 25);
    }

