    #[test]
    fn test_giratina_abilities() {
        let base_stats = BaseStats {
            hp: 150,
            attack: 100,
            defense: 120,
            special_attack: 100,
            special_defense: 120,
            speed: 90,
        };
        let giratina = BattlePokemon {
            db_id: Some(1),
            id: 487,
            name: "Giratina".to_string(),
            nickname: String::new(),
            types: vec!["Ghost".to_string(), "Dragon".to_string()],
            level: 50,
            max_hp: 210,
            current_hp: 210,
            nature: "Impish".to_string(),
            iv_hp: 31,
            iv_atk: 31,
            iv_def: 31,
            iv_spa: 31,
            iv_spd: 31,
            iv_spe: 31,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            moves: vec![],
            base_stats,
            is_shiny: false,
            catch_rate: 3,
            base_experience: 300,
            is_burned: false,
        };
        assert!(giratina.is_giratina());

        let neutral_pkmn = BattlePokemon {
            db_id: Some(2),
            id: 25,
            name: "Pikachu".to_string(),
            nickname: String::new(),
            types: vec!["Electric".to_string()],
            level: 50,
            max_hp: 100,
            current_hp: 100,
            nature: "Hardy".to_string(),
            iv_hp: 31,
            iv_atk: 31,
            iv_def: 31,
            iv_spa: 31,
            iv_spd: 31,
            iv_spe: 31,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            moves: vec![],
            base_stats: BaseStats {
                hp: 35,
                attack: 55,
                defense: 40,
                special_attack: 50,
                special_defense: 50,
                speed: 90,
            },
            is_shiny: false,
            catch_rate: 190,
            base_experience: 112,
            is_burned: false,
        };

        // Shadow Realm check:
        let swift = MoveDetail {
            name: "Swift".to_string(),
            t: "Normal".to_string(),
            c: "Special".to_string(),
            p: Some(60),
            a: None,
            pp: Some(20),
            d: String::new(),
        };
        // When targeting Giratina and shadow_realm_miss is true, it misses into Shadow Realm
        assert!(check_move_miss_against_with_roll(&swift, &giratina, 50, true));
        // When targeting Giratina and shadow_realm_miss is false, Swift lands (never misses)
        assert!(!check_move_miss_against_with_roll(&swift, &giratina, 50, false));
        // Neutral Pokemon never triggers Shadow Realm miss
        assert!(!check_move_miss_against_with_roll(&swift, &neutral_pkmn, 50, true));

        // Anti-Matter Dominion: incoming damage is reduced by 50%
        let dragon_claw = MoveDetail {
            name: "Dragon Claw".to_string(),
            t: "Dragon".to_string(),
            c: "Physical".to_string(),
            p: Some(80),
            a: Some(100),
            pp: Some(15),
            d: String::new(),
        };
        let (dmg_vs_giratina, _, _) = calculate_authentic_damage_exact(&neutral_pkmn, &dragon_claw, &giratina, Some(false), Some(100));
        let mut non_god_target = giratina.clone();
        non_god_target.id = 9999;
        non_god_target.name = "CustomDragon".to_string();
        let (dmg_vs_normal, _, _) = calculate_authentic_damage_exact(&neutral_pkmn, &dragon_claw, &non_god_target, Some(false), Some(100));
        assert!(dmg_vs_giratina <= (dmg_vs_normal / 2) + 1);

        // Fixed damage moves against Giratina: Dragon Rage (40 fixed damage -> halved to 20)
        let dragon_rage = MoveDetail {
            name: "Dragon Rage".to_string(),
            t: "Dragon".to_string(),
            c: "Special".to_string(),
            p: None,
            a: Some(100),
            pp: Some(10),
            d: String::new(),
        };
        let (rage_dmg, _, _) = calculate_authentic_damage_exact(&neutral_pkmn, &dragon_rage, &giratina, Some(false), Some(100));
        assert_eq!(rage_dmg, 20);
    }

    #[test]
    fn test_dialga_abilities() {
        let base_stats = BaseStats {
            hp: 100,
            attack: 120,
            defense: 120,
            special_attack: 150,
            special_defense: 100,
            speed: 90,
        };
        let dialga = BattlePokemon {
            db_id: Some(3),
            id: 483,
            name: "Dialga".to_string(),
            nickname: String::new(),
            types: vec!["Steel".to_string(), "Dragon".to_string()],
            level: 50,
            max_hp: 175,
            current_hp: 175,
            nature: "Modest".to_string(),
            iv_hp: 31,
            iv_atk: 31,
            iv_def: 31,
            iv_spa: 31,
            iv_spd: 31,
            iv_spe: 31,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            moves: vec![],
            base_stats,
            is_shiny: false,
            catch_rate: 3,
            base_experience: 300,
            is_burned: false,
        };
        assert!(dialga.is_dialga());

        let mut normal_same_stats = dialga.clone();
        normal_same_stats.id = 9998;
        normal_same_stats.name = "CustomDragon".to_string();

        // Time Acceleration: Dialga's own speed is +50%
        let normal_spe = normal_same_stats.get_spe();
        let dialga_spe = dialga.get_spe();
        assert_eq!(dialga_spe, ((normal_spe as f64) * 1.5).round() as i32);

        // Time Stop: Opponent speed is reduced by 50% when facing Dialga
        let opp_effective_spe = normal_same_stats.get_effective_spe_against(&dialga);
        assert_eq!(opp_effective_spe, ((normal_spe as f64) * 0.5).round() as i32);

        // Dialga vs Dialga: no time stop penalty applied to fellow Dialga
        let dialga_vs_dialga_spe = dialga.get_effective_spe_against(&dialga);
        assert_eq!(dialga_vs_dialga_spe, dialga_spe);
    }

    #[test]
    fn test_palkia_abilities() {
        let base_stats = BaseStats {
            hp: 90,
            attack: 120,
            defense: 100,
            special_attack: 150,
            special_defense: 120,
            speed: 100,
        };
        let palkia = BattlePokemon {
            db_id: Some(4),
            id: 484,
            name: "Palkia".to_string(),
            nickname: String::new(),
            types: vec!["Water".to_string(), "Dragon".to_string()],
            level: 50,
            max_hp: 165,
            current_hp: 165,
            nature: "Modest".to_string(),
            iv_hp: 31,
            iv_atk: 31,
            iv_def: 31,
            iv_spa: 31,
            iv_spd: 31,
            iv_spe: 31,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            moves: vec![],
            base_stats,
            is_shiny: false,
            catch_rate: 3,
            base_experience: 300,
            is_burned: false,
        };
        assert!(palkia.is_palkia());

        let mut normal_same_stats = palkia.clone();
        normal_same_stats.id = 9997;
        normal_same_stats.name = "CustomWaterDragon".to_string();

        let steel_defender = BattlePokemon {
            db_id: Some(5),
            id: 304,
            name: "Aron".to_string(),
            nickname: String::new(),
            types: vec!["Steel".to_string(), "Rock".to_string()],
            level: 50,
            max_hp: 120,
            current_hp: 120,
            nature: "Hardy".to_string(),
            iv_hp: 31,
            iv_atk: 31,
            iv_def: 31,
            iv_spa: 31,
            iv_spd: 31,
            iv_spe: 31,
            ev_hp: 0,
            ev_atk: 0,
            ev_def: 0,
            ev_spa: 0,
            ev_spd: 0,
            ev_spe: 0,
            moves: vec![],
            base_stats: BaseStats {
                hp: 50,
                attack: 70,
                defense: 100,
                special_attack: 40,
                special_defense: 40,
                speed: 30,
            },
            is_shiny: false,
            catch_rate: 180,
            base_experience: 66,
            is_burned: false,
        };

        // Dragon Pulse is Dragon type -> normally resisted by Steel (0.5x effectiveness)
        let dragon_pulse = MoveDetail {
            name: "Dragon Pulse".to_string(),
            t: "Dragon".to_string(),
            c: "Special".to_string(),
            p: Some(85),
            a: Some(100),
            pp: Some(10),
            d: String::new(),
        };

        // Normal Pokemon deals reduced damage to Steel
        let (normal_dmg, _, normal_eff) = calculate_authentic_damage_exact(&normal_same_stats, &dragon_pulse, &steel_defender, Some(false), Some(100));
        assert_eq!(normal_eff, 0.5);

        // Palkia Spatial Distortion: ignores resistance, treats it as 1.5x effectiveness!
        // Plus Dimensional Rift: 1.5x damage multiplier
        let (palkia_dmg, _, palkia_eff) = calculate_authentic_damage_exact(&palkia, &dragon_pulse, &steel_defender, Some(false), Some(100));
        assert_eq!(palkia_eff, 1.5);
        assert!(palkia_dmg > normal_dmg * 2);
    }

    #[test]
    fn test_referrals_command_and_formatting() {
        let cmd = Command::parse("/referrals", "bot").expect("Should parse /referrals");
        assert!(matches!(cmd, Command::Referrals));

        let initial_text = format_referrals_message(0, 1, None);
        let expected_text = "Total referrals: 0\n\nSend the link below to new players and receive a bonus of 100 💵 for every invited player that reaches <b>Rank 3</b>\n\nAlso:\n• After every 3 invites, you will receive a mix of different poke balls\n• After every 7 invites, you will receive a TM 💿 and 1000 💵\n• After every 12 invites, you will receive 1 Master Ball and 1 Key Item\n\n<i>Waiting to reach Rank 3: 1</i>";
        assert_eq!(initial_text, expected_text);

        let gen_text = format_referrals_message(2, 5, Some("https://t.me/ozone_pokemon_bot?start=ref_12345678"));
        assert!(gen_text.contains("Total referrals: 2"));
        assert!(gen_text.contains("<code>https://t.me/ozone_pokemon_bot?start=ref_12345678</code>"));
        assert!(gen_text.contains("<i>Waiting to reach Rank 3: 5</i>"));

        let initial_kb = build_referrals_initial_kb(12345678);
        assert_eq!(initial_kb.inline_keyboard.len(), 1);
        assert_eq!(initial_kb.inline_keyboard[0][0].text, "Generate my link");

        let gen_kb = build_referrals_generated_kb(12345678, "https://t.me/ozone_pokemon_bot?start=ref_12345678");
        assert_eq!(gen_kb.inline_keyboard.len(), 2);
        assert_eq!(gen_kb.inline_keyboard[0][0].text, "Share link");
        assert_eq!(gen_kb.inline_keyboard[1][0].text, "Refresh");
    }

    #[tokio::test]
    async fn test_referral_registration_eligibility() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();

        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                starter_id INTEGER,
                pokedollars INTEGER NOT NULL DEFAULT 0,
                ball_regular INTEGER NOT NULL DEFAULT 50,
                ball_great INTEGER NOT NULL DEFAULT 50,
                ball_ultra INTEGER NOT NULL DEFAULT 30,
                ball_repeat INTEGER NOT NULL DEFAULT 20,
                ball_master INTEGER NOT NULL DEFAULT 5,
                ball_dusk INTEGER NOT NULL DEFAULT 20,
                trainer_level INTEGER NOT NULL DEFAULT 0,
                trainer_exp INTEGER NOT NULL DEFAULT 0,
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto'
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE referrals (
                referrer_id INTEGER NOT NULL,
                referred_id INTEGER NOT NULL PRIMARY KEY,
                referred_username TEXT,
                referred_first_name TEXT,
                status TEXT NOT NULL DEFAULT 'completed',
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 1. Insert referrer into users
        sqlx::query("INSERT INTO users (id, username, first_name, starter_id) VALUES (1001, 'ash', 'Ash', 25)")
            .execute(&pool)
            .await
            .unwrap();

        // 2. Self-referral rejected
        let self_res = register_referral_if_eligible(&pool, 1001, 1001, Some("ash"), "Ash").await;
        assert!(!self_res);

        // 3. Referrer doesn't exist rejected
        let non_exist_res = register_referral_if_eligible(&pool, 2001, 9999, Some("brock"), "Brock").await;
        assert!(!non_exist_res);

        // 4. Existing player with starter rejected
        sqlx::query("INSERT INTO users (id, username, first_name, starter_id) VALUES (2002, 'misty', 'Misty', 7)")
            .execute(&pool)
            .await
            .unwrap();
        let existing_res = register_referral_if_eligible(&pool, 2002, 1001, Some("misty"), "Misty").await;
        assert!(!existing_res);

        // 5. Eligible new player accepted
        let new_res = register_referral_if_eligible(&pool, 2003, 1001, Some("gary"), "Gary").await;
        assert!(new_res);

        // Check pending status in database
        let status: String = sqlx::query_scalar("SELECT status FROM referrals WHERE referred_id = 2003")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(status, "pending");

        // 6. Duplicate referral for already referred user rejected
        let dup_res = register_referral_if_eligible(&pool, 2003, 1001, Some("gary"), "Gary").await;
        assert!(!dup_res);
    }

    #[tokio::test]
    async fn test_referral_rank_up_milestones_and_rewards() {
        let pool = SqlitePool::connect("sqlite::memory:").await.unwrap();

        sqlx::query(
            "CREATE TABLE users (
                id INTEGER PRIMARY KEY,
                username TEXT,
                first_name TEXT,
                starter_id INTEGER,
                pokedollars INTEGER NOT NULL DEFAULT 0,
                ball_regular INTEGER NOT NULL DEFAULT 50,
                ball_great INTEGER NOT NULL DEFAULT 50,
                ball_ultra INTEGER NOT NULL DEFAULT 30,
                ball_repeat INTEGER NOT NULL DEFAULT 20,
                ball_master INTEGER NOT NULL DEFAULT 5,
                ball_dusk INTEGER NOT NULL DEFAULT 20,
                trainer_level INTEGER NOT NULL DEFAULT 0,
                trainer_exp INTEGER NOT NULL DEFAULT 0,
                unlocked_regions TEXT NOT NULL DEFAULT 'Kanto'
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE referrals (
                referrer_id INTEGER NOT NULL,
                referred_id INTEGER NOT NULL PRIMARY KEY,
                referred_username TEXT,
                referred_first_name TEXT,
                status TEXT NOT NULL DEFAULT 'completed',
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE user_tms (
                user_id INTEGER NOT NULL,
                tm_number INTEGER NOT NULL,
                move_name TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, tm_number)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        sqlx::query(
            "CREATE TABLE user_key_items (
                user_id INTEGER NOT NULL,
                item_name TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, item_name)
            );"
        )
        .execute(&pool)
        .await
        .unwrap();

        // 1. Create referrer (ID 100) with 1000 pokedollars
        sqlx::query("INSERT INTO users (id, username, first_name, starter_id, pokedollars) VALUES (100, 'referrer', 'Ref', 1, 1000)")
            .execute(&pool)
            .await
            .unwrap();

        // 2. Create referred user 101, pending
        sqlx::query("INSERT INTO users (id, username, first_name, starter_id, trainer_level, trainer_exp) VALUES (101, 'friend1', 'Friend 1', 4, 0, 0)")
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query("INSERT INTO referrals (referrer_id, referred_id, referred_username, referred_first_name, status) VALUES (100, 101, 'friend1', 'Friend 1', 'pending')")
            .execute(&pool)
            .await
            .unwrap();

        // Level up user 101 to Rank 3 via add_trainer_exp (Rank 0->1=50k, 1->2=75k, 2->3=100k -> 250,000 exp needed)
        let exp_res = add_trainer_exp(&pool, 101, 300_000).await.unwrap();
        assert!(exp_res.new_rank >= 3);

        // Check that referral is completed
        let status: String = sqlx::query_scalar("SELECT status FROM referrals WHERE referred_id = 101")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(status, "completed");

        // Referrer should receive 100 PokeDollars (1000 + 100 = 1100)
        let ref_pd: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = 100")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(ref_pd, 1100);

        // 3. Test Milestone 3 invites: mix of poke balls
        // Add invite 2 and invite 3
        sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, 102, 'completed')")
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, 103, 'pending')")
            .execute(&pool)
            .await
            .unwrap();

        let initial_great: i64 = sqlx::query_scalar("SELECT ball_great FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        process_referral_rank_up(&pool, 103).await.unwrap();

        let new_great: i64 = sqlx::query_scalar("SELECT ball_great FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        assert_eq!(new_great, initial_great + 15, "Milestone at 3 completed invites should award 15 Great Balls");

        // 4. Test Milestone 7 invites: TM and 1000 PokeDollars
        for i in 104..=106 {
            sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, ?, 'completed')")
                .bind(i)
                .execute(&pool)
                .await
                .unwrap();
        }
        sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, 107, 'pending')")
            .execute(&pool)
            .await
            .unwrap();

        let pd_before_7: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        process_referral_rank_up(&pool, 107).await.unwrap();
        let pd_after_7: i64 = sqlx::query_scalar("SELECT pokedollars FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        // 100 regular bonus + 1000 milestone bonus = 1100
        assert_eq!(pd_after_7, pd_before_7 + 1100);

        let tms_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM user_tms WHERE user_id = 100")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(tms_count, 1, "Milestone at 7 completed invites should award a TM");

        // 5. Test Milestone 12 invites: Master Ball and Key Item
        for i in 108..=111 {
            sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, ?, 'completed')")
                .bind(i)
                .execute(&pool)
                .await
                .unwrap();
        }
        sqlx::query("INSERT INTO referrals (referrer_id, referred_id, status) VALUES (100, 112, 'pending')")
            .execute(&pool)
            .await
            .unwrap();

        let mb_before: i64 = sqlx::query_scalar("SELECT ball_master FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        process_referral_rank_up(&pool, 112).await.unwrap();
        let mb_after: i64 = sqlx::query_scalar("SELECT ball_master FROM users WHERE id = 100").fetch_one(&pool).await.unwrap();
        assert_eq!(mb_after, mb_before + 1, "Milestone at 12 completed invites should award 1 Master Ball");

        let key_item_count: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM user_key_items WHERE user_id = 100")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(key_item_count, 1, "Milestone at 12 completed invites should award 1 Key Item");
    }

